INSERT INTO `tbl_all_synset` VALUES (7682,NULL,'खण्डमोदकः, खण्डः, उपला, शुक्तोपला, शर्करा, सिताखण्डः, दृढगात्रिका','माक्षीककृता शर्करा।:सः खण्डमोदकान् अत्ति।','noun'),(36512,'','स्वेदबिन्दुः','स्वेदस्य कणः।; \"तस्य ललाटात् स्वेदबिन्दवः गलन्ति।\"','noun'),(36513,'','चातुर्मासः','आषाढशुक्लैकादश्याः आरभ्य कार्तिकशुक्लैकादशीं यावत् चतुर्णां मासानां समयः।; \"चातुर्मासे जनाः धार्मिकानि व्रतानि आचरन्ति।\"','noun'),(36514,'','चातुर्यम्','चतुरस्य अवस्था भावः गुणः वा।; \"तेन चातुर्येण उत्तरम् उक्तम्।\"','noun'),(36510,'','घर्घरः','कफस्य कारणात् श्वसनसमये कण्ठे जायमानः अव्यक्तः ध्वनिः।; \"घर्घरस्य कारणात् रात्रौ निद्रा न अभवत्।\"','noun'),(36511,'','निम्बबीजम्, अरिष्टबीजम्, हिङ्गुनिर्यासबीजम्, सर्वतोभद्रबीजम्, मालकबीजम्, पिचुमर्दबीजम्, अर्कपादपबीजम्, वरत्वचबीजम्, कैटर्यबीजम्, छर्दिघ्नबीजम्, प्रभद्रबीजम्, पारिभद्रकबीजम्, काकफलबीजम्, विशीर्णपर्णबीजम्, यवनेष्टबीजम्, पीतसारकबीजम्, कीकटबीजम्','निम्बवृक्षस्य बीजम्।; \"निम्बबीजस्य चूर्णं कीटनाशकरूपेण उपयुज्यते।\"','noun'),(36508,'','मिष्टान्नम्','कस्मिन्नपि वस्तुनि मधुरसम् उत्पादयितुम् उपयुज्यमानः पदार्थः।; \"गुडशर्कराखर्जुरादयानि मिष्टान्नानि सन्ति।\"','noun'),(36509,'','गोल्फक्रीडकः, गोल्फक्रीडिका','गोल्फ इति क्रीडाप्रकारः यः क्रीडति।; \"शर्मिला-निकोलटमहोदया भारतस्य एका उत्कृष्टा गोल्फक्रीडिका अस्ति।\"','noun'),(36506,'','धैर्यता, परिधारणा, स्थैर्य, गन्धनम्','धीरतापूर्वकं कार्यसम्पादनम्।; \"क्रीडकानां धैर्यतां दर्शकाः प्राशंसन्।\"','noun'),(36505,'','माता, देवी','एकः आदरसूचकः शब्दः यः कामपि पूज्याम् आदरणीयां वा स्त्रियं देवीं वा सम्बोधयितुं प्रयुज्यते।; \"मातुः पार्वत्याः इदं मन्दिरम्।\"','noun'),(36504,'','माता, आर्या, देवी','कापि पूज्या आदरणीया वा स्त्री।; \"मातः भवती अत्र उपविशतु।\"','noun'),(36503,'','महाविनाशः','भूरि विनाशः।; \"महाविनाशात् रक्षणस्य सर्वे उपायाः विफलाः जाताः।\"','noun'),(36502,'','समप्रोटानः','तत् तत्वम् यस्य परमाणुसङ्ख्या समाना अस्ति किन्तु यस्य परमाणुभारः भिन्नः अस्ति।; \"समप्रोटानानां परमाणुभारे असमानतायाः कारणं तेषां केन्द्रे स्थितानां कणिकानां सङ्ख्या अस्ति।\"','noun'),(36501,'','गुरुः, तीर्थम्','धर्मग्रन्थानुसारेण येन तत्त्वं साक्षात्कृतम् तादृशः पुरुषः यः आध्यात्मिकं ज्ञानं ददाति तथा च यः साधनां कर्तुं पथदर्शकः अस्ति।; \"गुरोः अभिज्ञानं कथं भवेत् इति जनानां मनसि सर्वदा एव प्रश्नः भवति।\"','noun'),(36500,'','राजपत्रम्','राज्ञा प्रेषितम् आज्ञापत्रम्।; \"राज्ञा सर्वेभ्यः गणनायकेभ्यः राजपत्रं प्रेषितम्।\"','noun'),(36498,'','गृहव्ययः','गृहार्थे परिवारार्थे वा कृतः व्ययः।; \"अर्थोत्सर्गस्य कारणात् गृहव्ययः वर्धितः।\"','noun'),(36499,'','चिन्तावेश्म','तत् स्थानं यत्र राजानः परामर्शं कुर्वन्ति स्म।; \"युद्धात् पूर्वं सर्वैः गणनायकैः चिन्तावेश्मनि संमील्य योजना निर्मिता।\"','noun'),(36495,'','प्रकाशिन्','यस्मिन् प्रकाशः वर्तते।; \"सूर्यसदृशाः नैकाः तारकाः प्रकाशिनाः खगोलियाः पिण्डाः सन्ति।\"','adjective'),(36496,'','मूढ','यः उन्मत्तसदृशं आचरति।; \"एषः मूढः प्रायः न कदापि परिवर्तयेत्।\"','adjective'),(36487,'','राजकचौरी','आलूकचणकमुद्गदध्यादिभिः व्यञ्जनैः पूरिता एका कचौरी या रसपूर्णा अस्ति।; \"पूजायाः राजकचौरी सम्यक् भवति।\"','noun'),(36490,'','चञ्चल, अपस्यु, इर्य, इषिर, उत्साहिन्, उदार, विचर्षणि, सक्रिय, सचेष्ट','यः अतीव चपलः अस्ति।; \"चञ्चलानां बालकानां पालनं कठिनं भवति।\"','adjective'),(36491,'','महार्घ','यस्य मूल्यं वर्धितम्।; \"सर्वाणि वस्तूनि महार्घाणि भवन्ति।\"','adjective'),(36492,'','शीघ्र','यः त्वरया भवति।; \"दुबई-देशस्य नैकैः कारणैः प्रगतिः शीघ्रा जाता।\"','adjective'),(36480,'','स्पष्ट','यद् सम्यक्तया श्रूयते।; \"दूरध्वन्या स्पष्टः ध्वनिः न श्रूयते।\"','adjective'),(36482,'','सफरमासम्','हिजरी संवत्सरस्य द्वितीयः मासः।; \"सफरमासे अहम् अत्र न भविष्यामि।\"','noun'),(36483,'','अन्तरम्','य़ात्राकाले निश्चितरूपेण क्रान्तः अध्वा।; \"पञ्चाशतमैलपरिमाणं यावत् अन्तरं तैः आक्रान्तम्।\"','noun'),(36494,'','उत्कट, पागल','यः कमपि कार्यं प्रति यावान् अनुरक्तः आसक्तः लीनः येन सः अन्यस्मिन् कार्ये न प्रवर्तते।; \"अधुना निर्वाचनस्य कारणात् उत्कटाः नेतारः ग्रामे ग्रामे अटन्ति।\"','adjective'),(36493,'','दीपवृक्षः','प्रायः छदस्य शोभार्थे काचादिभिः निर्मितम् उपकरणं यस्मिन् दीपादयः प्रकाशन्ते।; \"विश्रामगृहस्य प्रत्येकस्मिन् प्रकोष्ठे दीपवृक्षाः सन्ति।\"','noun'),(36440,'','प्रकारः, रूपम्','कस्यापि कार्यस्य नियता व्यवस्थिता वा पद्धतिः।; \"अस्मिन् कुले विवाहस्य अयमेव प्रकारः प्रचलितः।\"','noun'),(36444,'','बुद्धिजीवी','यः बुद्ध्या एव जीविकायाः उपार्जनं करोति।; \"विधिज्ञः मन्त्र्यादयः बुद्धिजीविनः एव भ्रष्टं समाजं परिवर्तयितुं शक्नुवन्ति।\"','noun'),(36486,'','दध्यापूपः','तैलघृतादिषु भर्जितं कुसूलपिष्टस्य व्यञ्जनं यद् निमिज्य खाद्यते।; \"तस्मै दध्यापूपम् अतीव रोचते।\"','noun'),(36484,'','गोलकम्','आलुककुसूलादीन् पेशित्वा पिण्डीकृत्वा भर्जितः एकः व्यञ्जनविशेषः।; \"तिक्तिकया सह आलुकस्य गोलकस्य रुचिः वर्धते।\"','noun'),(36485,'','गोलकम्','अङ्गारस्य रक्षया निर्मितः पिण्डः।; \"तेन गोलकं प्रज्वाल्य तमाखुपत्रम् उपभुज्यते।\"','noun'),(36478,'','निरभ्र, स्वच्छ, अच्छ','यद् मेघादिभिः आच्छादितं नास्ति।; \"प्रभातस्य अपेक्षया सायङ्काले आकाशं निरभ्रं भवति।\"','adjective'),(36479,'','स्वच्छ, अच्छ, विमल','यस्य सम्पादनम् अनुचितं नियमविरुद्धं वा नास्ति।; \"स्वच्छः व्यवहारः एव सम्यक् वर्तते।\"','adjective'),(36472,'','सुलिखित','यद् सम्यक्तया लिखितम्।; \"सुलिखितानि अक्षराणि एव पठतु।\"','adjective'),(36475,'','लम्बगोल','यद् लम्बाकारकं वर्तुलम्।; \"मम समीपे बहूनि लम्बगोलानि मौक्तिकानि सन्ति।\"','adjective'),(36476,'','राज्ञी','स्वस्य वर्गे सर्वोत्तमं मत्वा स्त्रीरूपेण साकारितम् वस्तु।; \"दार्जीलिङ्गजलपाईगुड़ी इत्येतयोः मध्ये प्रचलित लघु लोहपथगामिनी पर्वतानां राज्ञी अस्ति।\"','noun'),(36410,'','दूरसञ्चारमन्त्री','सः मन्त्री यस्य अधिकारे दूरसञ्चारमन्त्रालयम् अस्ति।; \"दूरसञ्चारमन्त्रिणः एका नूतना योजना उद्घोषिता।\"','noun'),(36414,'','ऐम्बेस्डरयानम्','यानप्रकारः।; \"टाटा मोटर्स इति नाम्ना उद्योगसंस्था ऐम्बेस्डरयानं निर्माति।\"','noun'),(36417,'','अवगतिः','वितर्कीकरणस्य कार्यम्।; \"अधुना जनाः वास्तवात् अवगत्या कार्यं कुर्वन्ति।\"','noun'),(36423,'','आवेगः, वेगः','आवेशितस्य अवस्था।; \"अनेन यन्त्रेण प्रकाशः विद्युतीये आवेगे परिवर्त्यते।\"','noun'),(36424,'','विद्योतः','रूपित्रादिभ्यः यन्त्रेभ्यः निर्गतः प्रकाशः।; \"प्रखरेण विद्योतेन नेत्रे निमीलतः।\"','noun'),(36428,'','अन्टार्कटिका-महाद्वीपः','पृथिव्याः दक्षिणध्रुवे वर्तमानः महाद्वीपः यत्र अतीव शैत्यं वर्तते तथा च त्रयोदशसहस्त्रं फुटपरिमाणं यावत् हिमं वर्तते।; \"अन्टार्कटिका-महाद्वीपः आस्ट्रेलियादेशात् द्विगुणितः अस्ति।\"','noun'),(36429,'','तारका','चित्रपटदूरदर्शनकार्यक्रमादीनां वर्गीकरणार्थे समीक्षकैः उपयुक्तं प्रतीकम्।; \"उपहारगृहाणां वर्गीकरणे प्रायः एकतः पञ्चमं यावत् तारकाः उपयुज्यन्ते।\"','noun'),(36471,'','पाठक','अर्थम् विहाय यः रटति।; \"वेदपुराणां पाठकः अहङ्कारेण ग्रस्तः भवति।\"','adjective'),(36469,'','वर्ज्यवर्णः','काव्येषु रसबाधकाः वर्णाः।; \"शृङ्गाररसे ट ठ ड इत्यादयः वर्ज्यवर्णाः सन्ति।\"','noun'),(36470,'','अधिकारीगणः, अधिकारीवर्गः','अधिकारिणां समूहः।; \"अस्य कार्यक्रमस्य सर्वा अनुयोगाधीनता अधिकारीगणस्य अस्ति।\"','noun'),(36468,'','तिक्तम्','वैद्यकशास्त्रे वर्तमानेषु षड्रसेषु एकः।; \"कस्मै अपि तिक्तं न रोचते।\"','noun'),(36467,'','जहाजीखड्गः','प्राचीनकालीनः खड्गप्रकारः।; \"अस्मिन् सङ्ग्रहालये जहाजीखड्गः वर्तते।\"','noun'),(36464,'','निलीन','यः निलीयते।; \"तेन भयात् निलीनाः बालकाः दृष्टाः।\"','adjective'),(36465,'','नाविकः','नौकायां वर्तमानः कर्मकरः।; \"नाविकेन यात्रिणः सहाय्यं कृतम्।\"','noun'),(36466,'','नौयात्री','यः नौकया यात्रां करोति।; \"नौयात्री नौकायां स्थित्वा समुद्रं पश्यति।\"','noun'),(36453,'','झमझमाकृत्य','झमिति अव्यक्तं शब्दं कृत्वा।; \"बहिः झमझमाकृत्य वर्षा भवति।\"','adverb'),(36455,'','झञ्झमित','यः झमिति अव्यक्तं शब्दं करोति।; \"प्रातःकालस्य झञ्झमितया वर्षया वायुमण्डलं सुखकरं जातम्।\"','adjective'),(36463,'','अस्पष्ट','यद् दर्शनपथात् दूरे अस्ति।; \"अस्पष्टानां दृश्यानां स्मृतिः अवशिष्टा अस्ति।\"','adjective'),(36446,'','क्रूजयानम्','जले भ्रमयितुं प्रयुक्तं यानं नौका वा।; \"गोवाप्रदेशे बृहद् क्रूजयानं दृश्यते।\"','noun'),(36445,'','नारिकेलजलम्','नारिकेलस्य जलम्।; \"नारिकेलजलं लाभदायकम् अस्ति अतः प्रत्येकस्मिन् ऋतौ तद् पातुं शक्यते।\"','noun'),(36436,'','पुलिनः, पुलिनम्','कस्यापि सागरादीनां तटे वर्तमानः वालुकामयः प्रदेशः।; \"सायङ्काले जुहूग्रामस्य पुलिने बहवः जनाः सन्ति।\"','noun'),(36437,'','प्रियालुः','कोलजातीयं ग्रथियुक्तं फलम्।; \"तस्मै प्रियालुः अतीव रोचते।\"','noun'),(36438,'','प्रियालुः','वृक्षविशेषः यस्य ग्रन्थिसदृशानि फलानि सन्ति।; \"तेन प्रियालोः उद्यानं रक्षितम्।\"','noun'),(36439,'','पर्वतीयस्थानम्','समीपस्थात् समतलभागात् उन्नतं पर्वते वर्तमानं नगरं ग्रामं वा।; \"पर्वतीयस्थाने ग्रीष्मे काले अधिकाः जनाः भवन्ति।\"','noun'),(36430,'','वातानुकूलनम्','सा प्रणालिः या वायोः शुष्कत्वं शीतत्वञ्च सन्तुलयति।; \"वातानुकूलनस्य कृते प्रयुक्ते यन्त्रे प्रायः एकं वायुशीतकं तथा च एकं वायुतापकं यन्त्रम् अस्ति।\"','noun'),(36431,'','विस्फोटः, स्फोटः','अन्तर्निहितस्य अग्नेः उष्णातायाः वा क्वथनात् उद्गमनस्य क्रिया।; \"ज्वालामुखेः विस्फोटात् भूरि हानिः जाता।\"','noun'),(36432,'','विमान-परिचारिका','सा स्त्री या विमानद्वारा यात्रिणां स्वागतं करोति तथा च तान् सहाय्यं करोति।; \"प्रत्येकस्याः विमान-परिचारिकायाः परिधानं नियतं वर्तते।\"','noun'),(36390,'','वामपथः','यः सिद्धान्तः जनकल्याणाय विभिन्नस्य स्तरस्य सामाजिकं राजकीयं आर्थिकं वा परिवर्तनस्य समर्थनं करोति।; \"ते वामपथस्य समर्थकाः सन्ति।\"','noun'),(36391,'','वामपन्थी','जनकल्याणार्थं निर्मितस्य विभिन्नस्य स्तरस्य सामाजिकराजनैतिकार्थिकपरिवर्तनस्य समर्थनं यः करोति।; \"वामपन्थिनः अपि अस्मिन् सम्मेलने भागम् अवहन्।\"','noun'),(36392,'','क्षयित, ह्रासित','यद् ह्रसते।; \"अंशकस्य क्षयितेन मूल्येन हानिः जाता।\"','adjective'),(36400,'','जनप्रतिनिधिः','जनानां प्रतिनिधिः।; \"इदानींतने काले जनप्रतिनिधयः एव जनैः सह कपटेन व्यवहरन्ति।\"','noun'),(36403,'','जलसंसाधनमन्त्री','यस्य अधिकारे जलसंसाधनमन्त्रालयः अस्ति।; \"अद्य अस्माकं ग्रामे जलसंसाधनमन्त्री आगमिष्यति।\"','noun'),(36407,'','राष्ट्रव्यापिन्, देशव्यापिन्','सम्पूर्णं राष्ट्रं येन व्याप्तम् अस्ति।; \"भ्रष्टाचारस्य विरुद्धं राष्ट्रव्यापिनः अभियानस्य आवश्यकता अस्ति।\"','adjective'),(36408,'','रासलानुफनगरम्','लिबियादेशस्य एकं नगरम्।; \"गद्दाफीसमर्थितया सेनया रासलानुफनगरं स्वाधिकारे कृतम्।\"','noun'),(36409,'','बिनजवादप्रान्तम्','लिबियादेशस्य प्रान्तम्।; \"रमेशः बिनजवादप्रान्ते निवसति।\"','noun'),(36332,'','मेगावाटपरिमाणम्','ऊर्जायाः परिमाणम्।; \"अनया विद्युद्योजनया 16340मेगावाटपरिमाणं यावत् विद्युत् उत्पद्यते।\"','noun'),(36333,'','कार्ययोजना','कार्यस्य योजना।; \"अस्माभिः कार्ययोजनायाः अनुसारेण एव कार्यं कर्तव्यम्।\"','noun'),(36334,'','योजना, पर्यालोचना','कार्यादीनां प्राक् कृतं तस्य कार्यस्य अमूर्तं मूर्तं वा लघुरूपम्।; \"पूर्वम् अस्माभिः कार्यस्य योजना निर्मितव्या।\"','noun'),(36336,'','खनिजतैलमन्त्रालयः','खनिजतैलसम्बन्धिकार्याणां मन्त्रालयः।; \"खनिजतैलमन्त्रालये विविधाः क्षेपाः भवन्ति।\"','noun'),(36337,'','खनिजतैलमन्त्रालयः','खनिजतैलमन्त्रिणः कार्यालयः।; \"अद्य रमेशः खनिजतैलमन्त्रालये गतः।\"','noun'),(36338,'','ऊर्जामन्त्री','सः मन्त्री यस्य कार्यक्षेत्रम् ऊर्जा-मन्त्रालयः अस्ति।; \"अमेरिकादेशस्य ऊर्जामन्त्री भारतदेशम् आगच्छत्।\"','noun'),(36339,'','थ्रीमाइल-आईलैण्डक्षेत्रम्','अमेरिकादेशस्य पेन्सिलवेनियाप्रदेशस्य क्षेत्रम्।; \"थ्रीमाइल-आईलैण्डक्षेत्रे परमाणुविस्फोटः जातः।\"','noun'),(36340,'','पेन्सिलवेनियाप्रदेशः','अमेरिकादेशे वर्तमानः प्रदेशः।; \"रमेशः पेन्सिलवेनियाप्रदेशे निवसति।\"','noun'),(36342,'','गामाकिरणः','केभ्यश्चित् पदार्थेभ्यः निर्गतः किरणप्रकारः।; \"क्षकिरणस्य तरङ्गदैर्घ्यं गामाकिरणानाम् अपेक्षया दीर्घं भवति।\"','noun'),(36343,'','सामरिक','युद्धस्य युद्धसम्बन्धी वा।; \"भारते सुयोग्यानां सामारिकानां विमानानां निर्मितिः आवश्यकी।\"','adjective'),(36344,'','निम्बूपानीयम्','जले निम्बूकं निष्पीड्य निर्मितः पानार्हद्रव्यविशेषः।; \"ग्रीष्मकाले अहं प्रतिदिनं निम्बूपानीयं पिबामि।\"','noun'),(36345,'','राष्ट्रहितम्, देशहितम्','देशस्य हितम्।; \"अस्माभिः प्रत्येकं कार्यं राष्ट्रहिताय करणीयम्।\"','noun'),(36346,'','उपप्रधानमध्यस्थः','प्रधानमध्यस्थस्य अधीनः सः ग्रामसेवकः यः तस्य अनुपस्थितौ तस्य स्थाने कार्यरतः भवति।; \"उपप्रधानमध्यस्थस्य प्रधानमध्यस्थस्य च मेलनेन अत्र विकासः न भवति।\"','noun'),(36347,'','उपाध्यक्षः','अध्यक्ष इति पदस्य अनन्तरीयः पदाधिकारी यः कार्ये अध्यक्षस्य सहाय्यं करोति।; \"अस्याः संस्थायाः उपाध्यक्षः अद्य न आगमिष्यति।\"','noun'),(36348,'','अलेक्जाण्ड्रियानगरम्','ईजिप्तदेशे वर्तमानम् एकं नगरम्।; \"अस्माकम् एकं मित्रम् अलेक्जाण्ड्रियानगरे निवसति।\"','noun'),(36349,'','जावियानगरम्','लीबियादेशस्य एकं प्रमुखं नगरम्।; \"जावियानगरे विद्रोहिन्यः घटनाः जायमानाः सन्ति।\"','noun'),(36350,'','टाटामोटर्ससंस्था','टाटा-समुदायस्य एका उद्योगसंस्था।; \"रमेशः टाटामोटर्ससंस्थायां कार्यं करोति।\"','noun'),(36351,'','बैङ्क-आफ-इण्डिया','सर्वकारेण सञ्चालितः एकः वित्तकोषः।; \"मम लेखा बैङ्क-आफ-इण्डिया इति वित्तकोषे अस्ति।\"','noun'),(36352,'','हेरातनगरम्','अफगणिस्तानदेशे वर्तमानम् एकं नगरम्।; \"हेरातनगरम् अफगणिस्तानदेशस्य वायव्ये स्थितम् अस्ति।\"','noun'),(36353,'','इन्फोसिससंस्था','सूचना-प्रौद्योगिक-क्षेत्रस्य एका बृहद् उद्योगसंस्था।; \"रामः इन्फोसिससंस्थायां कार्यं करोति।\"','noun'),(36354,'','अविकसित','यद् न विकसितम्।; \"अविकसितेषु क्षेत्रेषु व्यवसायं कर्तुं अतिरिक्ताः सेवाः दीयते।\"','adjective'),(36355,'','अपप्रचारः, कुप्रचारः','अपकीर्तिकरः प्रचारः।; \"अपप्रचारस्य कारणात् गुरुवर्यः नैकवारं विवादस्य विषयः अभवत्।\"','noun'),(36356,'','अधिकृतता','अधिकृतस्य अवस्था भावः वा।; \"अस्य लेख्यपत्रस्य अधिकृतता परीक्षितव्या।\"','noun'),(36357,'','अध्ययनपूर्ण','अध्ययनेन सहितम्।; \"भवान् अस्य पुस्तकस्य अध्ययनपूर्णं विवेचनं करोतु।\"','adjective'),(36358,'','अर्धकुशल, अर्धनिपुण','यः पूर्णः कुशलः नास्ति।; \"अर्धकुशलेभ्यः श्रमिकेभ्यः न्यूनं वेतनं प्राप्यते।\"','adjective'),(36359,'','अर्थबोधनम्','अर्थस्य बोधस्य क्रिया।; \"अस्याः कवितायाः अर्थबोधनं न भवति।\"','noun'),(36360,'','अविभाज्य, अभिन्न','यद् विभाजयितुं न शक्यते।; \"जम्मू-कश्मीर इति भारतस्य अविभाज्यम् अङ्गम् अस्ति।\"','adjective'),(36363,'','चिरोटाः','किक्नसेन गोधूमपिष्टेन च निर्मितं एकं मिष्टान्नं यस्मिन् बहवः स्तराः भवन्ति।; \"अद्य भोजने चिरोटाः अपि आसीत्।\"','noun'),(36364,'','बहिःस्रावि-ग्रन्थिः','सः ग्रन्थिः यस्याः स्रावः विशिष्टाभिः नलिकाभिः कार्यस्थलं प्राप्नोति।; \"अग्न्याशयस्य रसः बहिःस्रावि-ग्रन्थेः स्रवति।\"','noun'),(36365,'','रूप्यकम्','शतपैसाः इति मूल्यस्य धनपत्रं नाणकं वा।; \"माता मह्यं रूप्यकं दत्तवती।\"','noun'),(36366,'','अर्थापूर्तिः','अर्थस्य आपूर्तिः।; \"अयं वित्तकोषः नैकानां संस्थानां कृते अर्थापूर्तिं करोति।\"','noun'),(36367,'','अर्थव्यवहारः','अर्थेन सम्बद्धः व्यवहारः।; \"अस्माभिः भारतदेशस्य अर्थव्यवहारे वाणिज्ये च सामाजिकमूल्यानां प्रधानता भवेत्।\"','noun'),(36368,'','शिलापट्टः, शिलाखण्डः','भवनादीनां निर्माणे उपयुज्यमानः पाषाणस्य खण्डः।; \"इदं मन्दिरं रुचिरप्रस्तरः इति शिलापट्टैः निर्मितम् अस्ति।\"','noun'),(36369,'','अवस्थान्तरम्','एकस्याः अवस्थायाः अन्यस्याम् अवस्थायां प्रवेशनस्य क्रिया।; \"मृत्युः तु केवलम् आत्मनः अवस्थान्तरम् एव।\"','noun'),(36370,'','पार्किन्सनव्याधिः','केन्द्रीयतन्त्रिकातन्त्रस्य एकः विकारः यस्मिन् कम्पनं तथा च दुर्बलः पेशीयः समन्वयः भवति।; \"पार्किन्सनव्याधेः उन्नतावस्थायां मनोभ्रमः भवति।\"','noun'),(36372,'','पेशीय','पेश्या सम्बद्धः।; \"पेशीयया शिथिलतया नैके व्याधयः भवन्ति।\"','adjective'),(36373,'','ध्रुवीकरणम्','सा घटना यस्यां प्रकाशस्य अन्यस्य विकिरणस्य वा किरणाः कम्पनस्य दिशम् अभि प्रतिबध्यन्ते।; \"बहुतरङ्गग्राहकेन विद्युच्चुम्बकीयानां तरङ्गाणां ध्रुवीकरणं क्रियते।\"','noun'),(36374,'','ध्रुवीकरणम्','ध्रुवीयतायाः ध्रुवीयतादानस्य वा अवस्था।; \"चुम्बकीयेन उद्दीपनेन मस्तिष्कस्य तन्त्रिकाकोशिकानां ध्रुवीकरणं समाप्य पार्किंसनव्याधेः उपचाराः क्रियन्ते।\"','noun'),(36375,'','उत्सवः','सः शुभावसरः यदा जनाः एकत्रिताः भवन्ति।; \"पितृष्वसा विवाहस्य उत्सवे उपस्थातुम् आगतवती।\"','noun'),(36376,'','कोशिका-स्रावि-ग्रन्थिः','सः ग्रन्थिः यस्याः कोशिकायाः गलनेन स्वस्य अन्तर्भागात् स्रावं निर्माति।; \"त्वचः स्नेहग्रन्थिः एका कोशिका-स्रावि-ग्रन्थिः अस्ति।\"','noun'),(36378,'','निमीलनम्, निमिषनम्','अक्षिसङ्कोचनस्य क्रिया भावः वा।; \"अक्ष्णोः निमीलनम् अक्ष्णोः अनावश्यकानां वस्तूनां प्रवेशं निषेधयति।\"','noun'),(36380,'','योधनम्, द्वन्द्वः','परस्परयोः युद्धस्य क्रिया।; \"द्वयोः देशयोः योधनं प्रजां पीडयति।\"','noun'),(36381,'','उत्तम, अतिश्रेष्ठ','अतीव योग्यः।; \"अयं एकः उत्तमः सङ्गणकः अस्ति यस्मिन् नैकाः नूतनाः विशेषताः सन्ति।\"','adjective'),(36384,'','अपप्रदानम्, लञ्चा, उत्कोचः','अनुचितं कार्यं स्वानुकूलीकरणाय अनुचितरीत्या अल्पमात्रायां प्रदत्तं धनद्रव्यादिकम्।; \"अस्य कार्यस्य कृते सः मह्यम् अपप्रदानं दातुं प्रायतत।\"','noun'),(36389,'','लुप्तप्राय, लोपोन्मुख','यः शीघ्रमेव लुप्यते।; \"जावाद्वीपस्य वने लुप्तप्रायायाः प्रजातेः गण्डस्य द्वौ शावकौ प्राप्तौ।\"','adjective'),(36388,'','चञ्चुप्रवेशः','शनैः शनैः क्रियमाणः प्रवेशः।; \"राजनीतौ चञ्चुप्रवेशं कृत्वा तेन उद्योगस्य आरम्भः कृतः।\"','noun'),(36387,'','तटीय','तटस्य तटेन वा सम्बद्ध।; \"सिन्धुनद्याः तटीया सभ्यता विश्वस्य प्राचीनासु नदीतटीयासु सभ्यतासु एका प्रमुखा सभ्यता आसीत्।\"','adjective'),(36386,'','दुर्गन्धित','यस्य शरीरात् घर्मस्य दुर्गन्धः प्रसरति।; \"दुर्गन्धितस्य पुरुषस्य समीपे मा उपविशतु।\"','adjective'),(36328,'','वायुयन्त्रम्','तद् यन्त्रं यस्मिन् वायुः पूरितः भवति अथवा यस्य यन्त्रस्य उपयोगः वायुं पूरयितुं क्रियते।; \"कारयानस्य वायुयन्त्रे ऊर्णनाभेन तन्तुजालः निर्मितः।\"','noun'),(36385,'','पत्रम्','दीर्घं पर्णम्।; \"पलाण्डोः तृणादीनाञ्च पर्णानां पत्रम् इति आख्या।\"','noun'),(36331,'','क्षमता','कार्यसम्पादनार्थम् आवश्यकं सामर्थ्यम्।; \"कर्मकराणां क्षमतां वर्धयितुम् उद्योगसंस्थया नूतनानां प्रशिक्षणवर्गाणाम् आयोजनं क्रियते।\"','noun'),(36330,'','सीसीपरिमाणम्','यानस्य यन्त्रस्य शक्तिसूचकं परिमाणम्।; \"अस्य यानस्य यन्त्रं 2500सीसीपरिमाणं यावत् अस्ति।\"','noun'),(36327,'','यानकूपः','कस्यापि याने इन्धनार्थे वर्तमानं पात्रम्।; \"अस्य कारयानस्य यानकूपे छिद्रः अभवत्।\"','noun'),(36322,'','शर्मअलशेखनगरम्','ईजिप्तदेशे वर्तमानम् एकं नगरम्।; \"मुबारकः शर्मअलशेखनगरे बद्धः आसीत्।\"','noun'),(36325,'','निर्ज्वर','ज्वररहितः।; \"वैद्येन निर्ज्वरः पुरुषः गृहं प्रेषितः।\"','adjective'),(36326,'','तन्त्रिकाशास्त्रम्','चिकित्साशास्त्रस्य सा शाखा यस्यां तन्त्रिकया सम्बद्धम् अध्ययनं क्रियते।; \"रमेशः तन्त्रिकाशास्त्रस्य ज्ञाता अस्ति।\"','noun'),(36319,'','प्रधानमन्त्रि-कार्यालयः','प्रधानमन्त्रिणः कार्यालयः।; \"अद्य अहं प्रधानमन्त्रि-कार्यालयम् अगच्छत्।\"','noun'),(36321,'','प्रसारमाध्यमकर्मी','यः प्रसारमाध्यमे कार्यं करोति।; \"आरक्षकाः प्रसारमाध्यमकर्मिणः प्राहरन्।\"','noun'),(36318,'','प्रधानमन्त्रिकार्यालयः','प्रधानमन्त्रिणः कार्यालयः।; \"प्रधानमन्त्रिकार्यालयात् एका अधिसूचना आगता।\"','noun'),(36297,'','निकुम्भः','सुन्दोपसुन्दयोः पिता।; \"निकुम्भः एकः प्रतापी राजा आसीत्।\"','noun'),(36304,'','बगदावतः','लोकगायकप्रकाराः।; \"अधुना बगदावताः विरलाः जाताः।\"','noun'),(36306,'','अपरान्तः','यूरोपामेरीकाखण्डे वर्तमानाः देशाः।; \"अधुना अधिकेभ्यः भारतीयेभ्यः अपरान्तस्य सङ्गीतं रोचते।\"','noun'),(36307,'','कटुता','सम्बन्धेषु जातं मतिवैचित्र्यम्।; \"अस्माकं सम्बन्धेषु कटुता नास्ति।\"','noun'),(36308,'','सम्बोधनम्','बोधस्य क्रिया।; \"अद्यतनीयानां नेतॄणां सम्बोधनस्य शब्दाः अर्थरहिताः भवन्ति।\"','noun'),(36310,'','प्रवर्तन-निदेशालयः','प्रवर्तनेन सम्बद्धानां कार्याणां निरीक्षकः निदेशालयः।; \"प्रवर्तन-निदेशालयः मोदीमहोदयस्य पारपत्रस्य अन्वेषणं कुर्वन् अस्ति।\"','noun'),(36316,'','एकौघभूत','अत्यधिकायां मात्रायाम् आगतः।; \"अण्णामहोदयेन जन्तरमन्तर इति स्थाने एकौघभूताः समर्थकाः सम्बोधिताः।\"','adjective'),(36296,'','निकन्दरोगः','योनिरोगविशेषः।; \"शीला निकन्दरोगेण पीडिता।\"','noun'),(36295,'','बन्धुः, बान्धवः','स्नेहयुक्ताः सम्बन्धाः यैः सह सन्ति ते स्वजनाः।; \"रामेण स्वविवाहे बन्धवः एव आहूताः।\"','noun'),(36294,'','कटुतिक्तम्','कटोः तिक्तस्य च समाहारः।; \"मात्रा अद्य कटुतिक्तायाः इन्द्रवारुणिकायाः शाकं निर्मितम्।\"','adjective'),(36288,'',' ',' ; \"\"','noun'),(36289,'','सैन-फ्रांसिस्कोनगरम्','अमेरिकादेशस्य कैलिफोर्नियाराज्ये वर्तमानम् नौकाश्रययुक्तम् एकं नगरम्।; \"अमेरिकादेशस्य औद्योगिककेन्द्रेषु परिवहनकेन्द्रेषु च एकं प्रमुखं सैन-फ्रांसिस्कोनगरम्।\"','noun'),(36290,'','कैलीफोर्नियाराज्यम्, केलीफोर्नियाराज्यम्','प्रशान्तमहासागरस्य तटे स्थितम् अमेरिकादेशे वर्तमानम् एकं राज्यम्।; \"कैलीफोर्नियाराज्यम् अमेरिकादेशस्य तृतीयक्रमाङ्कस्य बृहद् राज्यम् अस्ति।\"','noun'),(36293,'','उद्दीपन','कस्यापि मनुष्यस्य कस्मिंश्चित् कार्ये प्रवर्तनं विशेषतया मनोभावस्य प्रदीपनम्।; \"चुम्बकीयेन उद्दीपनेन मस्तिष्कस्य पार्किन्सन इत्याख्यः व्याधेः उपचारः क्रियते।\"','noun'),(36287,'','सोहरनगरम्','ओमानराष्ट्रस्य एकं विकसितं नगरं यद् प्राचीने काले तस्य राजधानी आसीत्।; \"सोहरनगरं सिन्दबादस्य जन्मस्थानम् अस्ति।\"','noun'),(36286,'','मध्यपूर्वः','तुर्कीदेशात् उत्तरदिशि आफ्रिकां यावत् तथा पूर्वदिशि ईराणं यावत् भूमध्यसागरस्य समीपस्थः प्रदेशः।; \"मध्यपूर्वः पाश्चिमात्यसंस्कृतेः उगमस्थानम् अस्ति।\"','noun'),(36284,'','योगः','ज्योतिःशास्त्रानुसारेण रविचन्द्रयोः स्थितिः तद्विशिष्टः कालः।; \"सप्तविंशतिः योगाः सन्ति।\"','noun'),(36285,'','योगछन्दः','छन्दसः प्रकारः।; \"योगछन्दसि प्रत्येकं चरणं द्वादशे अष्टमे च विश्रामेण यह विंशतिमात्रिकं वर्तते तथा च अस्य अन्ते यगणः भवति।\"','noun'),(36282,'','अभिजनः','तत् नगरं यत्र कस्यापि मूलं निवासस्थानं वर्तते।; \"मम अभिजनः रायपूरनगरम् अस्ति।\"','noun'),(36283,'','समाधिः','आत्मतत्वस्य निरन्तरेण ध्यानेन द्वैतरहिता अवस्था।; \"नैकेभ्यः वर्षेभ्यः तपसा योगिने समाधिः प्राप्ता।\"','noun'),(36276,'','महानगरटेलीफोननिगमलिमिटेडम्','या उद्योगसंस्था अन्तर्जालस्य सेवां प्रददाति।; \"सः महानगरटेलीफोननिगमलिमिटेडे कार्यं करोति।\"','noun'),(36278,'','प्रत्यायनम्','दुःखादीन् प्रदर्शयितुं करुणां प्राप्तुं च प्रजया सम्बन्धितैः अधिकारिणैः कृतस्य अन्यायस्य विरुद्धं घोषणायुक्तं प्रदर्शनम्।; \"उद्योगसंस्थायाः कर्मकरैः अद्य प्रत्यायनं कृतम्।\"','noun'),(36279,'','घातकयोगः','फलज्योतिष्यानुसारेण सः योगः येन मनुष्यस्य मृत्युः सम्भाव्यते।; \"वरस्य कुण्डल्यां घातकयोगः अस्ति अतः भवान् पुत्र्याः विवाहः तेन सह मा करोतु।\"','noun'),(36280,'','वृत्तवाहिनी','सा वाहिनी यस्याः वृत्तं प्रसार्यते।; \"आजतक, ज़ी न्यूज़, जियो न्यूज़, बीबीसी न्यूज़ इत्यादयः वृत्तवाहिन्यः सन्ति।\"','noun'),(36281,'','यानग्रामः','यानानां समूहः।; \"अस्माकं जेटविमानानां तथा कारयानानां यानग्रामः अस्ति।\"','noun'),(36270,'','भारतीयप्रशासनिकसेवा','भारतसर्वकारस्य कार्यपालिकायाः शाखायाः प्रशासनीया सेवा।; \"भारतीयप्रशासनिकसेवायाः परीक्षायाम् अल्पीयाः जनाः उत्तीर्णाः भवन्ति।\"','noun'),(36271,'','भारतीयपुलिससेवा','भारतसर्वकारस्य त्रिषु अखिलभारतीयासु सेवासु एका।; \"भारतीयपुलिससेवायां किरणबेदीमहोदया प्रथमा महिला अधिकारीणी अस्ति।\"','noun'),(36275,'','भारतसञ्चारनिगमलिमिटेडम्','भारतसर्वकारस्य दूरसञ्चारस्य उद्योगसंस्था।; \"भारतसञ्चारनिगमलिमिटेडेन दत्तानां सुविधानां लाभं स्वीकरोतु।\"','noun'),(36267,'','पत्रिका, पदभञ्जिका','कस्यचित् विशिष्टस्य विषयस्य नियतकालिकं पत्रम्।; \"सः वैद्यकीयां पत्रिकाम् इच्छति।\"','noun'),(36268,'','विलुप्तिः','कस्यापि वस्तुनः लोपस्य अवस्था भावः वा।; \"माता पुत्रस्य विलुप्तिः आरक्षकान् असूचयत्।\"','noun'),(36265,'','न्यायपालिका','कस्यापि लोकतन्त्रस्य त्रिषु प्रमुखेषु अङ्गेषु एकं यत् न स्वयं नियमान् निर्माति न तु शासनेन विहितानां नियमानाम् आचरणं नियन्त्रयति।; \"नियमानाम् उल्लङ्घनं ये कुर्वन्ति तान् न्यायपालिका दण्डयति।\"','noun'),(36269,'','अन्तरीयम्','कटेः अधस्तनीयं भागम् आच्छादयितुं धार्यमाणः वस्त्रविशेषः।; \"स्त्रियः अन्तरीयस्य उपयोगः कटेः अधस्तनीयं भागं तथा उपरितनं भागं आच्छादयितुम् अपि कुर्वन्ति।\"','noun'),(36261,'','गोवत्सद्वादशी','अश्विनकृष्णद्वादशी तिथिः यस्यां तिथौ गवादयः पूज्यन्ते।; \"नैकाः महिलाः गोवत्सद्वादश्याम् उपवासं कुर्वन्ति।\"','noun'),(36264,'','कार्यपालिका','भारतस्य जनतन्त्रस्य त्रिषु अङ्गेषु एकं यत् न्यायपालिकाद्वारा तथा व्यवस्थापिकाद्वारा निश्चितानां नियमानां प्ररोचनार्थे उत्तरदायि अस्ति।; \"सङ्घस्य कार्यपालिकायां राष्ट्रपतिः उपराष्ट्रपतिः तथा च राष्ट्रपतेः साहाय्यार्थे परामर्शार्थे च प्रधानमन्त्री तथा च मन्त्रिपरिषद् एते अन्तर्भवन्ति।\"','noun'),(36262,'','बलिप्रतिपदा','कार्तिकशुद्धप्रतिपदा।; \"बलिप्रतिपदायाः दिने बलिः पूज्यते।\"','noun'),(36242,'','वर्गक्रोशकः','क्षेत्रफलमापनस्य परिमाणम्।; \"एकः वर्गक्रोशकः 640 प्रहलं यावत् भवति।\"','noun'),(36245,'','माध्य','परस्परयोः विपरीतयोः दिशोः स्थितयोः द्वयोः बिन्द्वोः सङ्ख्ययोः वा मध्यस्थानम्।; \"यदि कस्यचित् स्थानस्य निम्नतमः तापमानः नवपञ्चशतांशः अस्ति अधिकतमः तापमानः पञ्चाशताधिकैकशतम् अस्ति तर्हि तत्रत्यः माध्यः तापमानः शतांशं यावत् भवति।\"','adjective'),(36246,'','आर्कटिकवृत्तः','पृथिव्याः 66:33 अक्षांशे वर्तमानः वृत्तः यः उत्तरध्रुवस्य समीपे वर्तते।; \"आर्कटिकवृत्ते डिसेम्बरमासस्य 21तमे दिने सूर्यः न उदेति तथा जूनमासस्य 21तमे दिने सूर्यः अस्तं न गच्छति।\"','noun'),(36248,'','वृषणः, वीर्यकोषः','पुरुषस्य शरीरे स्थितयोः द्वयोः जननग्रन्थयोः एकः।; \"वार्यकोषे वीर्यं निर्माति।\"','noun'),(36250,'','अन्यतर','बहुषु कश्चित् एकः।; \"दर्शकेषु अन्यतरः पुरुषः मञ्चम् आगच्छतु।\"','adjective'),(36255,'','इन्टरसर्विसिज-इन्टेलजन्सम्','पाकिस्तानदेशस्य प्रमुखा गुप्तसंस्था।; \"इन्टरसर्विसिज-इन्टेलजन्सस्य स्थापना 1948तमे वर्षे अभवत्।\"','noun'),(36256,'','अननुज्ञप्त','यस्य अनुज्ञप्तिः नास्ति।; \"अपराधिनः गृहात् अननुज्ञप्तानि शस्त्राणि प्राप्तानि।\"','adjective'),(36257,'','अनुज्ञप्त','यस्य अनुज्ञप्तिः अस्ति।; \"श्रेष्ठी अनुज्ञप्तां सूक्ष्मगुलिप्रक्षेपणीं कपाटिकायां स्थापयति।\"','adjective'),(36258,'','सिंहपराक्रमः','महान् पराक्रमः।; \"तेन नवविंशतिप्रकारकाणाम् ओषधीनां पर्णफलनालमूलैः पञ्चशतप्रकारकाणां वर्णानां निर्माणं कृत्वा सिंहपराक्रमः कृतः।\"','noun'),(36239,'','दक्षिण-चीन-सागरः','चीनदेशस्य दक्षिणे भागे स्थितः सागरः यः प्रशान्तमहासागरस्य भागः अस्ति।; \"चीनदेशीयाः भूगर्भशास्त्रज्ञाः दक्षिण-चीन-सागरे तैलस्य वायोः च स्रोतः प्राप्नुवन्।\"','noun'),(36240,'','एड्रियाटिकसागरः','भूमध्यसागरस्य एकः भागः।; \"क्रोएशियादेशस्य दक्षिणः तथा च पश्चिमः तटः एड्रियाटिकसागरेण युनक्ति।\"','noun'),(36241,'','आधारशिला','सः आदिमः शिलाखण्डः यस्योपरि एव अन्यान् शिलाखण्डान् स्थापयित्वा भवनं निर्मीयते।; \"केन्द्रीय-मानव-संसाधन एवं विकास-मंत्री कपिलसिब्बलमहोदयेन भारतीय-प्रौद्योगिक-संस्थानं पटना इत्यस्य आधारशिला स्थापिता।\"','noun'),(36235,'','लोकसाहित्यम्','साधारणेषु जनेषु अथवा लोके प्रचलितं साहित्यम्।; \"लोकसाहित्ये सामान्यैः जनैः सम्बद्धाः विषयाः भवन्ति।\"','noun'),(36237,'','प्रखण्डः','प्रशासनस्य सुविधायै उपमण्डलस्य कृतः विभागः।; \"अस्य उपमण्डलस्य पञ्च प्रखण्डाः सन्ति।\"','noun'),(36238,'','बघेलखण्डक्षेत्रम्','मध्यभारतस्य एकं क्षेत्रं यद् मध्यप्रदेशराज्यस्य ईशान्ये स्थितम् अस्ति।; \"बघेलखण्डक्षेत्रे मध्यप्रदेशराज्यस्य रीवा,सतना इत्यादीनि मण्डलानि उत्तरप्रदेशराज्यस्य सोनभद्रमण्डलं तथा च इलाहबादक्षेत्रस्य प्राच्याः भागाः सन्ति।\"','noun'),(36223,'','विद्यापतिः','कस्याः अपि राजसभायाः महान् विद्वान्।; \"विद्यापतेः परामर्शेन विना राजा कमपि विषयं न निर्णयति।\"','noun'),(36224,'','विद्यापतिः','मिथिलायाः एकः प्रसिद्धः कविः।; \"विद्यापतिः भक्तिपरम्परायाः प्रमुखेषु कविषु एकः।\"','noun'),(36225,'','वाचस्पतिमिश्रः, वाचस्पतिः','महान् विद्वान्।; \"वाचस्पतिमिश्रः मिथिलायाः ब्राह्मणः आसीत्।\"','noun'),(36226,'','उपराजधानी','कस्यापि राज्यस्य राष्ट्रस्य वा राजधानेः अन्यतमं प्रमुखं नगरम्।; \"महाराष्ट्रराज्यस्य उपराजधानी नागपूरनगरम् अस्ति।\"','noun'),(36227,'','क्षतिः, अपचयः, क्षयः, हानिः','कस्यापि भोग्यस्य वस्तुनः भ्रंशनेन नाशनेन वा जायमाना असुविधा।; \"गृहस्य भित्त्यां भवता यद् क्षतिः कृता तस्य अपचितिः भवता एव करणीया।\"','noun'),(36228,'','मूर्तिकला','मूर्तिनिर्माणस्य कला।; \"सारनाथखजुराहोनगरादिषु मूर्तिकलायाः उत्तमाः प्रतिदर्शाः सन्ति।\"','noun'),(36229,'','जागृत','यस्य पूजया इच्छापूर्तिः भवति।; \"पटनानगरे गोरागावानाम्नायाः जागृतायाः देव्याः प्राचीनं मन्दिरम् अस्ति।\"','adjective'),(36230,'','लोकः','विश्वस्य कश्चित् विशिष्टः भागः यस्मिन् विभिन्नाः जीवाः निवसन्ति।; \"जीवलोकः देवलोकः ब्रह्मलोकः मनुष्यलोकः इत्यादयः लोकाः सन्ति।\"','noun'),(36231,'','उच्चमाध्यमिकविद्यालयः','यस्मिन् विद्यालये नवमीकक्षातः द्वादश्यां कक्षां यावत् शिक्षा प्रदीयते।; \"बालकाः समीपस्थम् उच्चमाध्यमिकविद्यालयं पठनार्थं गच्छन्ति।\"','noun'),(36234,'','वार्लीचित्रक्रिया','भारतदेशस्य मुम्बईनगर्याः उत्तरदिशि स्थितेन वार्ली इति जनजात्या क्रियमाणा चित्रक्रिया।; \"वार्लीचित्रक्रिया इति महाराष्ट्रराज्यस्य वार्ली इति जनजात्याः  चित्रणम् अस्ति।\"','noun'),(36233,'','लोकचित्रक्रिया','सा चित्रक्रिया यस्याः विशेषम् अध्ययनं अकृत्वा एव जनाः स्वयम् एव आलेखनं कुर्वन्ति।; \"महाराष्ट्रराज्यस्य वार्ली इति जातेः लोकचित्रकला प्रसिद्धा अस्ति।\"','noun'),(36232,'','प्राथमिक','अन्तिमायाः अवस्थायाः प्राक्।; \"प्राथमिकात् खननात् एव मौर्यकालीनानि नाणकानि, मृत्पात्राणि तथा अन्यानि वस्तूनि च प्राप्तानि।\"','adjective'),(36221,'','स्थलम्','कस्यापि निश्चितं स्थानम्।; \"भवान् अस्मिन् स्थले स्थित्वा नगरं द्रष्टुं शक्नोति।\"','noun'),(36220,'','केन्द्रबिन्दुः','सः बिन्दुः यत्र प्रकाशस्य अन्यविकिरणानां वा किरणानि एकत्रितानि भवन्ति यस्मात् प्रसरन्ति च।; \"उद्भुजस्य तथा च उत्तानस्य दीप्तोपलस्य केन्द्रबिन्दवः भिन्नाः सन्ति।\"','noun'),(36219,'','कलादीर्घः','यस्मिन् स्थाने जनाः कलायाः प्रदर्शनं कुर्वन्ति।; \"कलादीर्घे चित्रकारस्य जतिनदासमहोदयस्य कलायाः प्रदर्शनम् अस्ति।\"','noun'),(36218,'','जलवर्णः','चित्रकैः उपयुज्यमानः सः वर्णविशेषः यस्य उपयोगः जलेन सह एव क्रियते।; \"तेन स्वगृहे जलवर्णेन भित्तिषु सुन्दरं चित्रलेखनं कृतम्।\"','noun'),(36217,'','तैलवर्णः, तैलरङ्गः','सः वर्णः यस्य माध्यमं तैलं भवति।; \"चित्रक्रियायां जलवर्णाः तैलवर्णाः च प्रयुज्यन्ते।\"','noun'),(36214,'','शुद्धिः','अपवित्रं वस्तु पवित्रं कर्तुम् अथवा धर्मच्युताय पुनः धर्मप्रवेशार्थं कृतं धार्मिकं कार्यम्।; \"अस्मिन् आश्रमे आगतानां जनानां शुद्धिः आवश्यकी।\"','noun'),(36206,'','अङ्गम्','यस्मात् शब्दात् प्रत्ययः विधीयते तस्य आदिमः वर्णात् आरभ्य प्रत्ययं यावत् वर्तमानं शब्दस्वरूपम्।; \"बालकः इत्यस्य शब्दस्य अङ्गम् बालक इति।\"','noun'),(36216,'','यात्राभिकरणम्','या संस्था यात्रायाः प्रबन्धं करोति।; \"इदानीं यात्राभिकरणं भिन्नैः प्रस्तावैः जनान् आकर्षयन्ति।\"','noun'),(36215,'','सीताहरणम्','रामसीतयोः वनवासकाले रावणेन सीतायाः कृतं हरणम्।; \"अयोध्यानगरस्य कैश्चित जनैः सीताहरणस्य प्रदर्शनम् अतीवं सुन्दरं कृतम् आसीत्।\"','noun'),(36212,'','भूसंरचनात्मक','भूमेः संरचनया सम्बद्धः।; \"भूसंरचनात्मकेन परिवर्तनेन यमुना नदी स्वस्थानात् विंशतिः किलोमीटर इति यावत् पूर्वम् अचलत्।\"','adjective'),(36211,'','वनरोपणम्','वनस्य रोपणस्य क्रिया।; \"वनरोपणम् अवर्षणात् रक्षणस्य उत्तमः उपायः अस्ति।\"','noun'),(36208,'','टट्टनम्','गृहगोधायाः ध्वनिः।; \"मन्दिरस्य भित्तौ गृहगोधिका टट्टनं करोति।\"','noun'),(36207,'','सामान्य-विज्ञानम्','साधारणमनुष्यजीवने समाजे व्यवहर्तुम् आवश्यकम् वैज्ञानिकं ज्ञानम्।; \"सामान्य-विज्ञाने सः उत्तमान् अङ्कान् अप्राप्नोत्।\"','noun'),(36199,'','आकर्षणम्','यः आकृष्यते।; \"अस्य नगरस्य मुख्यम् आकर्षणम् अत्रत्यं सरोवरं अस्ति।\"','noun'),(36200,'','अभिसृष्ट, आहित','कस्यापि आधिपत्ये दत्तः।; \"सैनिकाः अभिसृष्टात् अपराधिनः सत्यज्ञापनार्थे प्रायतन्त।\"','adjective'),(36201,'','खिलजीवंशः','मध्यकालीनस्य भारतस्य एकः राजवंशः यस्य १२९० तः   १३२० ईसवीसनं पर्यन्तम् यावत् देहल्याम् अधिकारः आसीत्।; \"खिलजीवंशस्य त्रयः शासकाः आसन् - जलालुद्दीनखिलजी, अलाउद्दीनखिलजी तथा च मुबारकखिलजी।\"','noun'),(36205,'','साम, सामोपचारः','सौम्यः उपायः।; \"अस्याः समस्यायाः समाधानं साम्ना अपि कर्तुं शक्यते।\"','noun'),(36183,'','पेयूषम्','सद्यस्तनं घृतं नवनीतं वा।; \"पेयूषेन सह पोलिका अधिका एव स्वादिष्टा भवति।\"','noun'),(36185,'','पृच्छा','कृतधीः वार्ता।; \"तेन मम पृच्छा प्रत्युपेक्षिता।\"','noun'),(36186,'',' ',' ; \"\"','noun'),(36187,'','आततिरहित','आतत्या रहितः।; \"आततिरहितं जीवनं सुखपूर्णं भवति।\"','adjective'),(36190,'','धनुर्विद्या, धनुष्क्रीडा','क्रीडाप्रकारः यस्मिन् धनुषा बाणः प्रक्षिप्य लक्ष्यं विध्यति।; \"धनुर्विद्यायां तेन प्रथमः क्रमाङ्कः प्राप्तः।\"','noun'),(36191,'','टीका, टिप्पणी','कश्चित् विषयः सम्यक् स्पष्टीभवितुं लिखिता सूचना।; \"अस्मिन् ग्रन्थे टीकाः दत्ताः।\"','noun'),(36192,'','अस्मिता','स्वस्य अस्तित्वविषये प्रकर्षेण अभिज्ञानस्य भावः।; \"अस्य आन्दोलनस्य कारणात् अत्रत्यानां जनानाम् अस्मिता जागृता।\"','noun'),(36194,'','विरञ्जकः','यः पदार्थः वस्त्रे स्थितं वर्णं चिह्नं वा दूरीकरोति।; \"आपणे नैके विरञ्जकाः प्राप्यन्ते।\"','noun'),(36195,'','श्रद्धाहीन, श्रद्धारहित','यस्मिन् श्रद्धायाः अभावः वर्तते।; \"श्रद्धाहीने मनुष्ये भगवतः कृपा न भवति।\"','adjective'),(36196,'','विसर्जनम्','देवतापूजनस्य षोडशसु संस्कारेषु अन्तिमः उपचारः यस्मिन् देवतां प्रति निवेदनं क्रियते यद् इदानीं पूजनं समाप्तं कृपया प्रतिष्ठताम्।; \"सत्यनारायणपूजायाः विसर्जनस्य अनन्तरं सर्वैः प्रसादं स्वीकृतम्।\"','noun'),(36197,'','उपचारः','पूजनस्य विधिः।; \"आवाहनमधुपर्कनैवेद्यपरिक्रमावन्दनादयः उपचाराः इति कथ्यन्ते।\"','noun'),(36198,'','सुनामी','भूकम्पेन अथवा ज्वालामुखीविस्फोटेन उत्पन्नाः विनाशकाः समुद्रीयाः तरङ्गाः।; \"सुनामी इति एकं जापानभाषीयः शब्दः यस्य अर्थः अस्ति नौकास्थानकस्थाः तरङ्गाः।\"','noun'),(36182,'','बिन्दुप्रस्फोटः','द्वयोः कर्गजयोः मध्ये स्फोटान् स्थापयित्वा बिन्दुरूपेण निर्मितः एकः प्रस्फोटः यस्योपरि आघातं कृत्वा भञ्जते।; \"सः बिन्दुप्रस्फोटान् भञ्जते।\"','noun'),(36177,'','घर्घरा','मुखप्रक्षालनार्थे आस्ये जलं गृहीत्वा घर्घराशब्देन जलप्रस्रावः।; \"घर्घरा न निर्गलितव्या।\"','noun'),(36178,'','आत्मसमर्थनम्','स्वस्य समर्थनम्।; \"नेता बलपूर्वकम् अखण्डम् आत्मसमर्थनं करोति।\"','noun'),(36179,'','खिलजी','खिलजीवंशस्य पुरुषः।; \"खिलजी तुर्किस्तानदेशात् भारतदेशम् आगतः।\"','noun'),(36181,'','जालस्थाली','धात्वादिभिः निर्मिता जालयुक्ता स्थालिका।; \"दुग्धस्य उपरि जालस्थालीं स्थापयतु।\"','noun'),(36170,'','टोरोन्टोनगरम्, टोरन्टोनगरम्','कनाडादेशस्य एकं बृहद् नगरम्।; \"टोरोन्टोनगरम् ओन्टारियोप्रान्तस्य राजधानी अस्ति।\"','noun'),(36171,'','ओन्टारियोक्षेत्रम्','मध्यकनाडादेशस्य एकं क्षेत्रम्।; \"ओन्टारियोनगरम् एकं समृद्धम् औद्योगिकं क्षेत्रम् अस्ति।\"','noun'),(36163,'','स्पर्शपटलः','कस्मिन्नपि यन्त्रे वर्तमाना सा सुविधा यस्यां यन्त्रे कार्यादिकं कर्तुं नोद्यपिञ्जादिकस्य आवश्यकता न भवति अपि तु स्पर्शमात्रेण एव कार्यं कर्तुं शक्यते।; \"अस्मिन् भ्रमणध्वनौ स्पर्शपटलः अस्ति।\"','noun'),(36174,'','चूर्णम्','कस्यापि पदार्थस्य भग्नावशेषः।; \"शुष्कस्य ग्रासस्य चूर्णं एकत्रीकरोतु।\"','noun'),(36172,'','चारविभागः','यः विभागः प्रायः अपराधसम्बन्धिनीं गूढां वार्तां शोधयति।; \"कनाडादेशस्य चारविभागस्य कार्यालयस्य ध्वंसनस्य योजना आतङ्कवादिभिः निर्मिता।\"','noun'),(36160,'','सामाजिक-जालक-सङ्केतस्थलम्','तद् सङ्केतस्थलं यद् समाजेन सम्बद्धम् अस्ति।; \"फेसबुक इति एकं सामाजिक-जालक-सङ्केतस्थलम् अस्ति।\"','noun'),(36161,'','मेगापिक्सलपरिमाणम्','एकं परिमाणम्।; \"अस्माकं भ्रमणध्वन्यां द्वे मेगापिक्सलपरिमाणस्य चित्रग्राहिणी अस्ति।\"','noun'),(36162,'','प्रतिक्रिया','कस्यापि प्रयोगस्य विषये स्वाभिप्रायकथनम्।; \"अस्य सङ्केतस्थलस्य उपयोगस्य अनन्तरं स्वस्य प्रतिक्रियां सूचयतु।\"','noun'),(36153,'','क्रीडा','रञ्जनार्थे प्रयुक्तानि वस्तुकार्यादीनि यानि क्रीडार्थे उपयुज्यन्ते।; \"मम सङ्गणके नैकाः क्रीडाः उपारोपिताः सन्ति।\"','noun'),(36154,'','क्रीडनम्','क्रीडायाः अवस्था।; \"अस्मिन् भ्रमणध्वन्यां क्रीडनस्यापि अङ्गम् अस्ति।\"','noun'),(36156,'','गीगाहर्ट्जपरिमाणम्','तद् परिमाणं येन विद्युत-चुम्बकीय-तरङ्गान् मीयते।; \"एतत् संसाधनं 1:6 गीगाहर्ट्जपरिमाणस्य अस्ति।\"','noun'),(36157,'','प्रधानसंसाधनाङ्गम्','सङ्गणकस्य एकः भागः।; \"प्रधानसंसाधनाङ्गेन विना सङ्गणकः कार्यं कर्तुं न शक्नोति।\"','noun'),(36158,'','यन्त्रांशः','सङ्गणकप्रणालीं निर्मातुं यान्त्रिकः चुम्बकीयः तथा च विद्युत् अवयवाः।; \"रमेशः यन्त्रांशस्य विषये सम्यक् जानाति।\"','noun'),(36159,'','विपरिवर्तकम्','एकं विद्युत् उपकरणम्।; \"विपरिवर्तकस्य उपयोगः सङ्गणकं दूरध्वन्या योजयितुं क्रियते।\"','noun'),(36149,'','सिक्थवर्तिकायात्रा','जनैः हस्ते प्रकाशितां सिक्थवर्तिकां गृहीत्वा कृता लघुयात्रा।; \"जनैः आतङ्कवादे घातितानां जनानां स्मरणार्थे एका सिक्थवर्तिकायात्रा आरब्धा।\"','noun'),(36150,'','मूलकोशिका','प्रथमा जाता कोशिका।; \"वैज्ञानिकैः मूलकोशिकया विशिष्टा मज्जापेशी विकसिता कृता।\"','noun'),(36148,'','एकल','यस्मिन् एकस्मिन् पक्षे एकः एव क्रीडकः अस्ति।; \"नडालेन एकलायाः स्पर्धायाः अन्तिमे चरणे प्रवेशः कृतः।\"','adjective'),(36152,'','वैग्रन्थः','तत् पुस्तकं यद् सङ्गणकादिषु उपारोपितानि सन्ति।; \"उपारोपिताः नैके वैग्रन्थाः प्राप्यन्ते।\"','noun'),(36151,'','वैशिष्ट्यम्','केषामपि वस्त्वादीनां विशिष्टः गुणः।; \"अस्मिन् भ्रमणध्वन्यां वैशिष्ट्यानि सन्ति।\"','noun'),(36142,'','संसदीय','संसदसम्बन्धी।; \"प्रधानमन्त्री संसदीयायां कार्य-प्रणाल्यां विकासस्य पक्षे अस्ति।\"','adjective'),(36143,'','संयुक्त-राष्ट्र-सुरक्षा-परिषद्','सा सुरक्षापरिषद् या संयुक्तराष्ट्रद्वारा प्रस्थापिता अस्ति।; \"संयुक्त-राष्ट्र-सुरक्षा-परिषदः कार्यं  अन्तर्राष्ट्रीयशान्ति तथा च सुरक्षा इति अस्ति।\"','noun'),(36144,'','पञ्चवार्षिक','पञ्चवर्षैः सम्बद्धः।; \"भारतशासनः नैकाः पञ्चवार्षिकाः योजनाः प्रचालयति।\"','adjective'),(36146,'','विश्वचषकम्','सा क्रीडाप्रतियोगिता या अन्तर्राष्ट्रीयस्तरे नियते काले भवति तथा च यस्यां नैके देशाः भागं गृह्णन्ति।; \"अस्मिन् समये क्रिकेटस्य विश्वचषकं भारतेन जीतम्।\"','noun'),(36147,'','जन्तर-मन्तर','सवाई-जय-सिंह-महोदयेन दिल्लीनगरे निर्मिता वेधशाला या अधुना नूतनरूपे परिणतम् अस्ति।; \"अण्णा-हजारे महोदयेन भ्रष्टाचारविरोधी आन्दोलनं जन्तरमन्तरात् एव आरब्धम्।\"','noun'),(36141,'','भपङ्गवाद्यम्, बोपङ्गवाद्यम्','राजस्थानप्रदेशस्य एकं लोकवाद्यम्।; \"उमर-फारूखमहोदयः भपङ्गवाद्यस्य वादने तथा च गायने कुशलः अस्ति।\"','noun'),(36136,'','कञ्जरी','कञ्जरजातेः स्त्री।; \"अधिकाः कञ्जर्यः वेश्यावृत्तिम् आचरन्ति इति मन्यते।\"','noun'),(36137,'','लङ्गागीतम्','राजस्थानराज्ये रुढम् एकं लोकगीतम्।; \"लङ्गाः जनाः लङ्गागीतस्य गायने कुशलाः भवन्ति।\"','noun'),(36138,'','लङ्गाजातिः','राजस्थानराज्ये वर्तमाना जातिः।; \"लङ्गाजातिः प्रायः बिकानेरजोधपुरनगरादीनां समीपस्थेषु ग्रामेषु प्राप्यते।\"','noun'),(36139,'','माङ्गनयारजातिः, माङ्गणियारजातिः','राजस्थानराज्ये वर्तमाना एका जातिः।; \"मङ्गा इति जातौ माङ्गनयार इति जातौ च समानता वर्तते।\"','noun'),(36140,'','लङ्गा-माङ्गनयारौ, लङ्गा-माङ्गणियारौ','राजस्थानप्रदेशस्य लङ्गा च माङ्गनयारम् इति जाती।; \"लङ्गा-माङ्गनयारयोः सदस्याः लोककलायां निपुणाः सन्ति।\"','noun'),(36110,'','नदवाद्यम्','एकं लोकवाद्ययन्त्रम्।; \"राजस्थानराज्यस्य पारम्पारिकेषु वाद्येषु नदवाद्यस्य विशिष्टं स्थानं वर्तते।\"','noun'),(36111,'','राजघाटम्','देहल्यां यमुनानद्याः पश्चिमे तटे स्थितं स्मारकं यत्र गान्धीमहोदयस्य समाधिः वर्तते।; \"राजघाटम् एकं दर्शनीयं स्थलम् अस्ति।\"','noun'),(36113,'','अनिलचुल्लिः, अनलचुल्लिः','या चुल्लिः अनिलस्य सहाय्येन प्रज्वलति।; \"अनिलचुल्ल्यां स्थापितं दुग्धम् उत्क्वथते।\"','noun'),(36114,'','आत्मकेन्द्रित','यः आत्मनि एव मग्नः भवति।; \"अधुना सः अधिकः एव आत्मकेन्द्रितः जातः।\"','adjective'),(36115,'','आत्मलीन, आत्ममग्न; आत्मरत','जगति जायमानैः अन्यैः कार्यैः सम्बन्धरहितः स्वस्मिन् एव मग्नः।; \"राज्ञा परीक्षिता आत्मलीनस्य साधोः कण्ठे मृतः सर्पः वेष्टितः।\"','adjective'),(36116,'','आत्मगौरवम्','स्वस्य गौरवः।; \"कर्तव्यपालनेन आत्मगौरवं वर्धते।\"','noun'),(36117,'','आत्मविकासः','स्वस्य विकासः।; \"आत्मविकासाय अस्माभिः शिबिरे भागः गृहीतः।\"','noun'),(36118,'','चञ्चापुरुषः','कमपि भाययितुं स्थापितः पुत्तलः।; \"सहाध्यायिनं भाययितुं तेन अस्थिपञ्जरस्य चञ्चापुरुषस्य प्रयोगः कृतः।\"','noun'),(36119,'','हिमार्त','अत्यधिकं शीतलम्।; \"अस्य सरोवरस्य जलं हिमार्तम् अस्ति।\"','adjective'),(36120,'','ग्रन्थयात्रा','कस्यापि मार्गदर्शने कस्यचित् ग्रन्थस्य यात्रा यस्याम् अधिकाः जनाः सम्मिलिताः भवन्ति।; \"साहित्यसम्मेलनस्य दिने ग्रन्थयात्रा आयोजिता।\"','noun'),(36121,'','क्षेत्रम्','ग्रामस्य सीम्नः अभ्यन्तरः भागः।; \"अस्माकं क्षेत्रं हरितम् अस्ति।\"','noun'),(36123,'','प्रतिक्रिया','कस्यचित् वस्तुनः कार्यस्य वा कृते जनैः दत्तम् अवधारणम्।; \"अस्माकं पुस्तकस्य कृते जनेषु सम्यक् प्रतिक्रिया प्राप्यते।\"','noun'),(36124,'','प्रतिसारणम्','व्रणादिषु लेपादीन् लेपितुम् एकं साधनम्।; \"चिकित्सकः व्रणे प्रतिसारणेन लेपं लेपयति।\"','noun'),(36125,'','महाविक्रयमूल्यम्','वस्तूनां महाविक्रयस्य मूल्यं यत् अल्पशः विक्रयस्य अपेक्षया न्यूनं भवति।; \"अहं वस्त्रादीन् महाविक्रयमूल्येन एव क्रीणामि।\"','noun'),(36127,'','आखातीयदेशः','सउदी-अरबबहरीनादीनां षण्णां देशानां समूहः यत्र खनिजतैलम् आधिक्येन प्राप्यते।; \"आखातीयेषु देशेषु जलस्य दुर्भिक्षम् अस्ति।\"','noun'),(36128,'','अनगरम्','तद् क्षेत्रं यस्य विकासः पूर्णतया नगरम् इव न जातः तथापि ग्रामापेक्षया अधिकं विकसितम् अस्ति।; \"मार्गं परितः अनगरस्य निर्माणं कदा भवति इति न ज्ञायते।\"','noun'),(36129,'','अनगरीय','अनगरेण सम्बद्धः।; \"रमेशः अनगरीये क्षेत्रे एकाम् उद्योगसंस्थाम् उद्घाटयितुम् इच्छति।\"','adjective'),(36134,'','युतकम्, अन्तर्युतकम्','शिरसः धार्यमाणः एकः वस्त्रविशेषः यस्य पूर्णः अग्रीमः भागः कड्मलैः युक्तः न भवति।; \"रमेशः कृष्णवर्णीयम् युतकं धृतवान्।\"','noun'),(36135,'','कालबेलियाजातिः','राजस्थानराज्ये वर्तमाना एका जातिः।; \"कालबेलियाजातेः जनाः विभिन्नासु लोककलासु कुशलाः भवन्ति।\"','noun'),(36109,'','जोगिया-सारङ्गी','सारङ्गीविशेषः।; \"राजस्थानराज्यस्य लोकवाद्ययन्त्रेषु जोगिया-सारंगी इति वाद्यस्य विशेषं स्थानं वर्तते।\"','noun'),(36107,'','कमायचावाद्यम्','एकं भारतीयं लोकवाद्ययन्त्रम्।; \"रमेशः कमायचावाद्यम् वादयति।\"','noun'),(36108,'','सिन्धी-सारङ्गी','सारङ्गीविशेषः।; \"राजस्थानराज्यस्य केचन लोककलाकाराः सिन्धी-सारङ्गीं वादयन्ति।\"','noun'),(36106,'','कालबेलिया','राजस्थानराज्ये वर्तमानः एकः नृत्यप्रकारः।; \"कालबेलिया इति व्यालिकानां नृत्यप्रकारः वर्तते।\"','noun'),(36104,'','सिमकार्डम्','भ्रमणध्वन्याम् आवश्यकम् एकं पत्रं यस्य विशिष्टः क्रमाङ्कः अस्ति तथा च यस्य सहाय्येन एव परस्परैः सम्भाषणं कर्तुं शक्यते।; \"मया एकं नूतनं सिमकार्डं क्रेतव्यम्।\"','noun'),(36105,'','नृत्यशैली','नृत्यस्य विशिष्टः प्रकारः।; \"कालबेलिया इति एका नृत्यशैली अस्ति।\"','noun'),(36097,'','नीतिगत','नीत्या सम्बन्धी।; \"रमेशः सर्वदा नीतिगतं कथनम् एव करोति।\"','adjective'),(36098,'','मोटर-वाहन-अधिनियमः','मोटर-वाहनसम्बन्धी अधिनियमः।; \"मोटर-वाहन-अधिनियमे वाहनचालनेन सम्बद्धाः विषयाः अपि उक्ताः।\"','noun'),(36101,'','जीवाणुरोधिन्, जीवाणुरोधक','यः जीवाणूनां प्रभावम् अवरुणद्धि।; \"मधुनि जीवाणुरोधिनः गुणाः सन्ति।\"','adjective'),(36102,'','उपचारगृहम्','चिकित्सासंस्थानविशेषः यत्र पीडितेषु उपचारः क्रियते।; \"शीला दिनद्वयं यावत् उपचारगृहे कक्षीकृता।\"','noun'),(36103,'','प्रतिविषविधिः','यद् विषविधिं नाशयति।; \"अस्माकं सङ्गणके प्रतिविषविधेः विधिः संस्थापितः।\"','adjective'),(36083,'','वृषणिः','पुरुषाणां शुक्रग्रन्थिभिः उत्पन्नः स्रावः।; \"पुरुषेषु लैङ्गिकविशिष्टतायाः विकासार्थम् वृषणिः उत्तरदायकः भवति।\"','noun'),(36084,'','भूवैज्ञानिक','भूविज्ञानेन सम्बद्धः।; \"भूवैज्ञानिकेन सर्वेक्षणेन नैकाः नैसर्गिकाः विपत्तयः परिहर्तुं शक्यन्ते।\"','adjective'),(36086,'','अखिल, निखिल, सम्पूर्ण','एकम् अपि अपरित्यज्य निःशेषेण वा।; \"रामस्य अखिलायाः हानेः क्षतिपूर्तिं कः करिष्यति।\"','adjective'),(36093,'','अङ्कफलकः','विशिष्टाकारकः प्रतिष्ठापितः सः फलकः यस्मिन् वस्त्वादीनां ज्ञापनार्थे संख्या लिखिता भवति।; \"अस्माकं यानस्य अङ्कफलकः भग्नः।\"','noun'),(36094,'','अपहरणम्, अपहारम्','मनुष्यस्य प्राणिनां वा बलात् अपनयनम्।; \"कर्मकरेण एव स्वामिनः पुत्रस्य अपहरणं कृतम्।\"','noun'),(36095,'','दृश्यता, दृश्यत्वम्','दृश्यस्य अवस्था।; \"धूमिकायाः कारणात् दृश्यता ऊनयति।\"','noun'),(36096,'','नियामकः','रिजर्व बैंक इति वित्तकोषस्य एकः उच्चस्तरीयः अधिकारी।; \"नियामकस्य आदेशेन एव धनपत्राणि प्रकाशितानि भवन्ति।\"','noun'),(36082,'','जल-भूवैज्ञानिकः','भूमिगतजलसम्बन्धिनां विषयाणां विशेषज्ञः भूवैज्ञानिकः।; \"भूविज्ञानस्य अध्यापनं कुर्वाणः छात्रः एकः कुशलः जल-भूवैज्ञानिकः भवितुम् अर्हति।\"','noun'),(36081,'','केन्द्रीय-भूमिगत-जल-परिषद्','भूमिगतजलसम्बन्धान् विषयान् निर्णेतुं निर्मिता एका केन्द्रीया परिषद्।; \"रमेशस्य पिता केन्द्रीय-भूमिगत-जल-परिषदः सदस्यः अस्ति।\"','noun'),(36077,'','वायुः','भारतीयदर्शनानुसारेण शरीरे वर्तमानः प्राणस्य मुख्यः आधारः।; \"प्राण-अपान-समान-उदान-व्यानाः इत्येते वायोः पञ्चभेदाः।\"','noun'),(36073,'','किट्टरोधी','यस्मिन् किट्टः न भवति।; \"नित्यं किट्टरोधीनि पात्राणि प्रयोक्तव्यानि।\"','adjective'),(36076,'','पेस्ट्री','क्षोदशर्करादुग्धनवनीतादिभिः आपक्वः एकः पदार्थः।; \"बालकेभ्यः पेस्ट्री रोचते।\"','noun'),(36071,'','पुनर्निवाचनम्','पुनः कृतं निर्वाचनम्।; \"काङ्ग्रेसाध्यक्ष इति पदस्य कृते सोनियागान्धीमहोदयायाः पुनर्निर्वाचनस्य प्रक्रिया आरब्धा।\"','noun'),(36066,'','मासिकम्','प्रत्येकस्मिन् मासे प्रकाश्यमाना पत्रिका।; \"इदं मासिकं ज्योतिःशास्त्रे आधारितम् अस्ति।\"','noun'),(36067,'','नियतकालिकम्','नियते काले प्रकाश्यमाना मासिका त्रैमासिका पत्रिका वा।; \"अस्मिन् वाचनालये विविधप्रकारकाणि नियतकालिकानि सन्ति।\"','noun'),(36068,'','कलशी','लघुः कलशः।; \"तेन कलश्या जलं पूरीतम्।\"','noun'),(36069,'','वर्तिका','भोजनं पाचयितुं वाहनं चालयितुं च आवश्यकम् एकं जीवाश्म ईन्धनम्।; \"इदानीं नगरेषु गृहे गृहे नलिकया वर्तिकां पूरयते।\"','noun'),(36070,'','तेजस्विन्','तेजयुक्तम्।; \"सः स्वस्य तेजस्विभ्यां नेत्राभ्यां शून्ये अपश्यत्।\"','adjective'),(36064,'','वस्त्रासनम्','तद् वस्त्रं यस्मिन् उपविश्यते।; \"गजाननः योगार्थं वस्त्रासनं स्तॄणाति।\"','noun'),(36063,'','विसर्जित','अधिवेशनादीनां कृतं समापनम्।; \"विसर्जितायाः सभायाः श्वः दशवादने प्रारम्भः भविष्यति।\"','adjective'),(36048,'','विदेश-मन्त्रालयः','विदेशसम्बन्धिनां कार्याणां यत्र निरीक्षणं क्रियते अथवा यद् विदेशमन्त्रिणः कार्यालयः वर्तते।; \"विदेश-मन्त्रालयस्य कार्यं सम्यक् प्रचलति।\"','noun'),(36049,'','विदेश-मन्त्रालयः','विदेशमन्त्रिणः कार्यालयः।; \"वयम् अद्य विदेश-मन्त्रालयं गतवन्तः।\"','noun'),(36051,'','रक्षकः, त्राता','काभ्यश्चित् दुर्घटनादिभ्यः यः रक्षति।; \"भारतदेशात् जपानदेशे रक्षकाणां प्रेषणविषये विचारः अस्ति।\"','noun'),(36054,'','मिनामिसोमानगरम्','जापानदेशे वर्तमानम् एकं नगरम्।; \"सुनामी इति नैसर्गिकेन सङ्कटेन मिनामिसोमानगरं ध्वस्तं जातम्।\"','noun'),(36055,'','पर्यावरण-मन्त्रालयः','सः मन्त्रालयः यः पर्यावरणसम्बन्धिनां विषयाणां निरीक्षणं करोति।; \"पर्यावरण-मन्त्रालयेन एका नूतना सूचना कृता।\"','noun'),(36056,'','पर्यावरण-मन्त्रालयः','पर्यावरणमन्त्रिणः कार्यालयः।; \"रामः कार्यार्थं पर्यावरण-मन्त्रालयम् अगच्छत्।\"','noun'),(36060,'','वटपौर्णिमा','ज्येष्ठमासस्य शुक्लपूर्णिमा।; \"वटपौर्णिमायां वटवृक्षं पूजयन्ति।\"','noun'),(36062,'','संवेदनाशून्य','संवेदनारहितः।; \"रक्तप्रवाहस्य अवरोधनेन पादौ संवेदनाशून्यौ भवतः।\"','adjective'),(36045,'','फुकुशिमादायचीक्षेत्रम्','जापानदेशे वर्तमानं तद् स्थानं यत्र परमाणुयन्त्रं स्थापितम् अस्ति।; \"सुरक्षार्थं फुकुशिमादायचीक्षेत्रस्य समिपस्थात् स्थानात् जनाः अन्यस्मिन् स्थाने नीताः।\"','noun'),(36047,'','शीतीकृत','यद् शीतं कृतम्।; \"अस्मिन् यन्त्रे शीतीकृतस्य जलस्य राशिः न्यूनः जातः।\"','adjective'),(36020,'','महाशिवरात्रिः, शिवरात्रिः','माघमासस्य चतुर्दशी।; \"महाशिवरात्र्यां सङ्गमे स्नानं कृत्वा भगवतः शिवस्य पूजनेन सुखं समृद्धिः च लभते।\"','noun'),(36021,'','शिवरात्रिः','प्रत्येकस्य मासस्य कृष्णपक्षस्य चतुर्दशी।; \"अहं शिवरात्रौ उपवासं करोमि।\"','noun'),(36022,'','अविश्वासप्रस्तावः','शासनं पराजेतुं दुर्बलं कर्तुं वा विपक्षेण कदाचित् तत्कालिकैः समर्थकैः वा संसदि रुढ्या स्थापितः प्रस्तावः।; \"विपक्षिणैः शासनस्य पुरतः अविश्वासप्रस्तावः स्थापितः।\"','noun'),(36023,'','विश्वासमतम्','अनुमोदनस्य प्रोत्साहनस्य वा अभिव्यक्तिः।; \"राज्यशासनेन विश्वासमतं जितम्।\"','noun'),(36025,'','क्रयविक्रयः','केषामपि वस्त्वादीनां क्रयणस्य विक्रयणस्य च क्रिया।; \"जनानां मतं प्राप्तुं नेतारः क्रयविक्रयस्य अपि व्यवहारः कुर्वन्ति।\"','noun'),(36029,'','चक्रयानम्','काष्ठलोहादिभिः निर्मिता वर्तुलाकारा आकृतिः या दण्डादिभिः चक्रस्य केन्द्रे बद्धा अस्ति तथा च अक्षं केन्द्रं कृत्वा तस्य परितः भ्रमति यानरथादीन् कर्षति च।; \"बालकाः चक्रयाने हिन्दोलयन्ति।\"','noun'),(36044,'','मण्डलाधिकारिकार्यालयः','मण्डलाधिकारिणः कार्यालयः।; \"अद्य मण्डलाधिकारिकार्यालये भूरिः संनयः अस्ति।\"','noun'),(36033,'','यूको-बैङ्क','भारतदेशे वर्तमानः एकः प्रमुखः वित्तकोषः।; \"यूको-बैन्क इति वित्तकोषस्य कार्यालयः मुम्बईनगर्याम् अस्ति।\"','noun'),(36035,'','अनुत्तरदायित्वम्','उत्तरदायित्वस्य अभावस्य अवस्था भावः वा।; \"समाजे वर्तमानानां समस्यानाम् अकथनेन अनुत्तरदायित्वस्य भावनायाः प्रसारः भवति।\"','noun'),(36030,'','चतहमद्वीपसमूहः','प्रशान्तमहासागरस्य न्यूजीलैण्डक्षेत्रे स्थितं दशानां द्वीपानां समूहस्थानम्।; \"चतहमद्वीपसमूहः इतः चत्वारिंशत् किलोमिटरं यावत् दूरे अस्ति।\"','noun'),(36031,'','इन्डियन-बैङ्क','भारतदेशे वर्तमानः एकः प्रमुखः वित्तकोषः।; \"इन्डियन-बैङ्क इति वित्तकोषे लिपिकस्य पदस्य कृते साङ्गणिकम् आवेदनपत्रम् आहूतम्।\"','noun'),(36010,'','अल्जाइमरम्','वयसा जातः विस्मरणस्य रोगः।; \"अल्जाइमरे पूर्वं मस्तिष्कस्य कापि कोशिका प्रभाविता भवति।\"','noun'),(36012,'','वाटी, वाटः','वलयितं लघु उद्यानम्।; \"नगरात् बहिः अस्माकं वाटी अस्ति।\"','noun'),(36017,'','विलोकनम्, ईक्षणम्','केषुचन क्रियादिषु गुप्तरूपेण पर्यवेक्षणम्।; \"आरक्षकः तस्य चोरस्य विलोकनं कुर्वन् अस्ति।\"','noun'),(35993,'','व्यवहारः','तादृशम् आचरणं यस्मिन् कस्मैचित् कार्यसम्पादने सहाय्यं कृत्वा तत्स्थाने तस्य पुरुषस्य साहाय्येन एव स्वहितसम्पादनम्।; \"तस्मै व्यवहारः न अरोचत।\"','noun'),(36005,'','मधुमेह-विशेषज्ञः','मधुमेहस्य विशेषज्ञः चिकित्सकः।; \"रमेशस्य पिता प्रसिद्धः मधुमेह-विशेषज्ञः अस्ति।\"','noun'),(36007,'','मूत्रनलिका, मूत्रवाहिका','मूत्रं वाहयन्ती नलिका।; \"एकः वैज्ञानिकः मूत्रनलिकायाः ऊत्या निर्माणं दृढतापूर्वकं कथयति।\"','noun'),(36018,'','ऋषि-पञ्चमी','भाद्रपदमासस्य शुक्लपञ्चमी यां उत्सवरूपेण निर्वर्तयन्ति तथा च यस्मिन् दिने ऋषीन् प्रति सौहार्दता प्रकटीक्रियते।; \"पितुः आज्ञया पुत्र्या ऋषि-पञ्चम्याः व्रतम् आचरितम्।\"','noun'),(35992,'','सेना','राज्यस्य शासनस्य वा सशस्त्रः सैनिकानां सः दलः यस्य सहाय्येन एव युद्धं, रक्षणं, शान्तिस्थापनादीनि कार्याणि भवन्ति।; \"अस्माकं राज्यस्य आरक्षकाणां सेना बलिष्ठा अस्ति।\"','noun'),(35988,'','प्रबल','अधिकबलयुक्तः।; \"एषः सङ्घः प्रतियोगितायाः प्रबलः अधिकारी अस्ति।\"','adjective'),(35989,'','मोतीहारीमण्डलम्','बिहारराज्ये वर्तमानम् एकं मण्डलम्।; \"सः मोतीहारीमण्डलस्य कस्यचित् ग्रामस्य निवासी आसीत्।\"','noun'),(35990,'','केन्द्रीय-आरक्षितपुलिसबलम्','भारतसर्वकारस्य गृहमन्त्रालयस्य संरक्षणे कार्यरतम् अर्धसैनिकं सुरक्षाबलम्।; \"राज्येषु केन्द्रशासितप्रदेशेषु च अनुशासनं व्यवस्थां च स्थापयितुं आतङ्कवादं नियन्त्रयितुं च केन्द्रीय-आरक्षितपुलिसबलं सहाय्यं करोति।\"','noun'),(35991,'','विशेषकार्यबलम्','विशिष्टाः समस्याः विशिष्टया पद्धत्या अपाकर्तुं शासनेन स्थापितं विशेषं बलम्।; \"उत्तरप्रदेशे जायामानाम् अपराधस्य वृद्धिं नियन्त्रयितुं विशेषकार्यबलस्य स्थापना कृता।\"','noun'),(35952,'','प्रसूतिकालः','प्रसवस्य कालः।; \"प्रसूतिकाले स्त्री बहु पीडाम् अनुभवति।\"','noun'),(35953,'','प्रबोधनम्','उपदेशादीनां माध्यमेन विशिष्टविषयस्य बोधनस्य क्रिया।; \"सदस्यगणस्य कृते दिनद्वयात्मकः प्रबोधनस्य कार्यक्रमः आयोजितः।\"','noun'),(35954,'','प्रदक्षिणम्, प्रदक्षिणः','मूर्तेः पूजनीयस्य मनुष्यस्य वा परितः दक्षिणभागात् आरभ्य कृतं भ्रमणम्।; \"सः प्रतिदिनं रामस्य मूर्तेः प्रदक्षिणम् करोति।\"','noun'),(35955,'','प्रशंसा-पत्रम्','प्रशंसायुक्तं पत्रम्।; \"स्वाधीनतादिने विभिन्नेषु क्षेत्रेषु उल्लेखनीयं कार्यं यैः कृतं तेभ्यः 35 प्रतिभाशालीनेभ्यः मुख्ये समारोहे मुख्यातिथिः प्रशंसा-पत्रम् ददाति।\"','noun'),(35956,'','प्रवाहपतित','इच्छया विनापि यः परिस्थितिम् अनु आचरति।; \"आधुनिके काले प्रवाहपतिताः जनाः एव सुखिनः भवन्ति।\"','adjective'),(35957,'','उत्कीर्ण-प्रतिमा','धात्वादिषु उत्कीर्णा प्रतिमा।; \"एलोराकन्दरे नैकाः उत्कीर्ण-प्रतिमाः सन्ति।\"','noun'),(35958,'','विभङ्गता','विभङ्गेन प्राप्ता अवस्था।; \"वस्त्रस्य विभङ्गतां दृष्ट्वा सः क्रुद्धः।\"','noun'),(35959,'','कर्करापाकः','कर्करस्य पाषाणं भर्जित्वा कर्करनिर्माणस्य आपाकः।; \"अस्मिन् स्थाने पूर्वम् एकः कर्करापाकः आसीत्।\"','noun'),(35960,'','वाच्यम्','व्याकरणशास्त्रे कर्तुः कर्मणः भावस्य वा क्रियापदेन सम्बन्धानुसारेण वाक्यरचना।; \"रामः आम्रं खादति इत्यस्य वाक्यस्य वाच्यं कर्तृवाच्यम् अस्ति।\"','noun'),(35961,'','काजूतकम्','काजूतकवृक्षस्य फलस्य बीजम्।; \"सः काजूतकं छित्वा खादति।\"','noun'),(35918,'','प्रकाशनम्','कस्यापि वस्तुनः विक्रयणार्थे सार्वजनिकप्रदर्शनार्थे वा वितरणस्य क्रिया।; \"सः स्वस्य तृतीयस्य पुस्तकस्य प्रकाशनं कर्तुं दिल्लीं गतः।\"','noun'),(35919,'','विमोचनम्','पशुनः बन्धनात् मुक्तता।; \"वाहनात् पशुनः विमोचनात् अनन्तरं तेभ्यः जलं दातव्यम्।\"','noun'),(35920,'','विमोचनम्','नियन्त्रणसीमादिभ्यः दूरीकरणम्।; \"अर्जुनस्य धनुषः बाणस्य विमोचनं शत्रूणां मनसि भयम् उत्पादयति।\"','noun'),(35921,'','शाकाहारिन्','अन्नफलादिभिः युक्तः।; \"अस्मिन् उपहारगृहे केवलं शाकाहारी भोजनं प्राप्यते।\"','adjective'),(35927,'','शुष्क, परिजीर्ण, परिम्लान','सत्वहीनः।; \"भगवते शुष्कं पुष्पं न अर्पणीयम्।\"','adjective'),(35930,'','कतरदेशः','एकः अरबस्तानीयः देशः।; \"कतरदेशः 1971 तमे वर्षे स्वतन्त्रः अभवत्।\"','noun'),(35931,'','केपवर्डेदेशः','अमेरिकादेशस्य उत्तरदिशि वर्तमानः देशः।; \"महेशः केपवर्डेदेशे कार्यरतः अस्ति।\"','noun'),(35933,'','अस्थिरोगतज्ज्ञः','सः चिकित्सकः यः अस्थिसम्बन्धिनां व्याधीनां निवारणे तज्ज्ञः अस्ति।; \"वैद्यः सिंहमहोदयः एकः प्रसिद्धः अस्थिरोगतज्ज्ञः अस्ति।\"','noun'),(35936,'','कायनिर्माणम्','विशिष्ट्या पद्धत्या शरीरस्य पुष्टीकरणम्।; \"इदानीन्तनकाले तरुणाः कायनिर्माणाय व्यायामशालां गच्छन्ति।\"','noun'),(35937,'','व्यायामशाला','तद् स्थानं यत्र प्रशिक्षकः काय-निर्माणाय नूतनाः व्यायामप्रकाराः कार्यन्ते।; \"रमेशः प्रतिदिनं व्यायामशालां गच्छति।\"','noun'),(35939,'','आरोपणम्','ऊतिषु किमपि कृत्रिमम् अङ्गम् स्थायिरूपेण स्थापनस्य क्रिया।; \"अधुना नेत्रे तेजोजलस्य आरोपणं सरलं जातम्।\"','noun'),(35942,'','आहारविशेषज्ञः','सः विशेषज्ञः यः जनान् आहारविषयकम् उपदेशं करोति।; \"सः स्वस्य भारं न्यूनीकर्तुम् आहारविशेषज्ञेन कृतेन उपदेशानुसारेण आहारं करोति।\"','noun'),(35943,'','पुनर्वास-केन्द्रम्','तद् स्थानं यत्र व्यायामादिभिः व्याधेः शारीरिक्याः अक्षमतायाः वा चिकित्सा क्रियते।; \"रमेशः एकमासं यावत् पुनर्वास-केन्द्रे वासम् अकरोत्।\"','noun'),(35944,'','दृष्टिक्षतिः','दृष्टेः क्षतिः।; \"मधुमेहीषु दृष्टिक्षतेः अधिका शक्यता वर्तते।\"','noun'),(35945,'','पूर्वानुमतिः, पूर्वानुज्ञा','पूर्वा गृहीता अनुमतिः।; \"पूर्वानुमत्या एव अहम् इदं कार्यं करोमि।\"','noun'),(35946,'','परग्रहीय','अन्येन ग्रहेण सम्बद्धः।; \"एलियनसदृशं परग्रहीयाणां जीवानां विषये संशोधनं प्रचलति।\"','adjective'),(35986,'','परिभ्रमणम्','विज्ञानशास्त्रे कञ्चित् एकं वस्तु केन्द्रं मत्वा तस्य परितः भ्रमणस्य क्रिया।; \"पृथिवी सूर्यस्य तथा च चन्द्रमाः पृथिव्याः परिभ्रमणं करोति।\"','noun'),(35983,'','दृढ','अत्याधिकं निश्चयपूर्वकम्।; \"दृढैः निश्चयैः किमपि कर्तुं शक्यते।\"','adjective'),(35980,'','कूरगीभाषा, कोडगुभाषा, कूर्गीभाषा','द्राविडभाषापरिवारस्था एका भाषा।; \"कूरगीभाषा मुख्यत्वेन कोडगुमण्डले भाष्यते।\"','noun'),(35981,'','लोकलयः','लोकगीतानां लयः।; \"रायपूरनगरस्य नगरघटिका प्रतिघण्टं लोकप्रियः छत्तीसगढीयः लोकलयं श्रावयति।\"','noun'),(35982,'','सीमा','कस्यापि प्रदेशस्य स्थानस्य वा अन्तिमा रेखा।; \"सैनिकैः शत्रुसेना सीम्नः परे प्रेषिता।\"','noun'),(35979,'','अल्पमूल्य, न्यूनमूल्य, समर्घ','यद् अल्पेन मूल्येन भवति।; \"भारतस्य एतस्य अपेक्षया अल्पमूल्या यात्रा न भवति।\"','adjective'),(35976,'','भक्ष्यम्','मांसभक्षिभिः भक्ष्यमाणाः कीटादयः।; \"मुशलिका स्वस्य भक्ष्यं जिव्हया अवापतत्।\"','noun'),(35977,'','अवशेषः','व्ययनाशोपभोगविश्लेषणादिभ्यः अवशिष्टम्।; \"अस्मिन् सङ्ग्रहालये हडप्पानगरस्य अवशेषाः अपि सन्ति।\"','noun'),(35973,'','विकीर्णम्','सा ऊर्जा या किरणादीनां रूपेण प्रसार्यते।; \"विकीर्णस्य प्रयोगः चिकित्साक्षेत्रे अपि भवति।\"','noun'),(35974,'','विक्रेता','यः विक्रेतुं वस्तूनि क्रीणाति तानि रक्षयति च।; \"कारयानं क्रेतुं ते मारुतिनाम्नः कारयानस्य विक्रेतुः आपणम् अगच्छन्।\"','noun'),(35971,'','हरिद्राचूर्णम्','हरिद्रायाः पीतं चूर्णं यत् खादने पूजायां च उपयुज्यते।; \"माता आम्लसूपे हरिद्राचूर्णं मिश्रयितुं विस्मृता।\"','noun'),(35972,'','रक्तमरिचचूर्णम्','रक्तमरिचस्य चूर्णम्।; \"तेन आपणात् पञ्चकिलोग्रामपरिमाणं यावत् रक्तमरिचचूर्णम् आनीतम्।\"','noun'),(35970,'','भूमुद्गकणः, भूमुद्गकणीका, भूमुद्रकणिकः','भूमुद्गस्य अन्तस्थः भागः।; \"भूमुद्गकणेभ्यः तैलं निष्कास्यते।\"','noun'),(35965,'','नित्यकर्म','प्रतिदिनं क्रियमाणानि कार्याणि।; \"नित्यकर्माणि कृत्वा सः अध्ययनार्थं गच्छति।\"','noun'),(35912,'','सिकन्दरियानगरम्','इजिप्तदेशस्य द्वितीयतमं बृहद् नगरम्।; \"सिकन्दरियानगरस्य जनसङ्ख्या पञ्चत्रिंशत् लक्षम् इति अस्ति।\"','noun'),(35913,'','सिकन्दरिया','इजिप्तदेशस्य एकं बृहद् नौकास्थानम्।; \"समुद्रयानं सिकन्दरियां प्रति गच्छति।\"','noun'),(35915,'','उत्सुक','यस्य मनसि कञ्चित् कार्यं कर्तुं दृढा इच्छा वर्तते।; \"चित्रपटं द्रष्टुम् उत्सुकाः बालकाः शीघ्रम् एव सिद्धाः भवन्तु।\"','adjective'),(35917,'','आज्ञा, आदेशः, निर्देशः, निदेशः, शासनम्, शिष्टिः, अववादः','तथा करोतु तथा मा करोतु इति अधिकारपूर्वकं कथनम्।; \"आज्ञां प्राप्य सः कार्यम् अकरोत्।\"','noun'),(35909,'','जलपरिवहनम्','कस्यचन वस्तुनः जलमार्गेण एकस्मात् स्थानात् अन्यत्र नयनम्।; \"एषा उद्योगसंस्था जलपरिवहनस्य सेवां ददाति।\"','noun'),(35911,'','लटकिया-नौकास्थानम्','सीरियादेशस्य एकं नौकास्थानम्।; \"तद् समुद्रयानं लटकिया-नौकास्थानात् सिकन्दरिया-नौकास्थानं प्रति गच्छन् अस्ति।\"','noun'),(35904,'','प्रयासरत','किमपि कार्यं कर्तुं यः प्रयतते।; \"परीक्षायाः कृते प्रयासरताः सर्वे छात्राः उत्तीर्णाः जाताः।\"','adjective'),(35908,'','विमाननायकः','विमानस्य मुख्यः चालकः यस्य उत्तरदायित्वे तद् विमानं भवति।; \"विमाननायकः यात्रिभ्यः विमानस्य उड्डयनविषये असूचयत्।\"','noun'),(35873,'','धनुः','समुद्रस्य गभीरतायाः मापनस्य परिमाणम्।; \"एकः धनुः षट् पदं यावत् भवति।\"','noun'),(35874,'','द्वारम्, निर्गमनम्, कवाटः','उद्यानादिषु प्रवेशयितुं निर्मिता रचना।; \"अस्य परिसरस्य द्वारम् उद्घाटितं मा स्थापयतु।\"','noun'),(35875,'','मञ्जकः','रेलस्थानके वर्तमाना एका दीर्घा वेदिका यस्य पार्श्वे एव रेलयानं तिष्ठति।; \"मञ्जके बहवः जनाः सन्ति।\"','noun'),(35876,'','शुष्क','यस्मिन् जलस्य प्रमाणम् अल्पम् अस्ति।; \"माता शुष्कम् ओदनम् अपचत्।\"','adjective'),(35877,'','निःशेषीकरणम्','निःशेषस्य क्रिया।; \"तिब्बतदेशे उद्भूतस्य पक्षीज्वरः इति व्याधेः निःशेषीकरणं कृतम्।\"','noun'),(35878,'','प्राधान्यक्रमः','श्रेष्ठतायाः अनुसारेण व्यवस्थापनम्।; \"भारतीयान् नेतॄन् प्राधान्यक्रमे स्थापयतु।\"','noun'),(35879,'','प्रातःस्मरणम्','प्रातःकाले क्रियमाणं भगवतः नामस्मरणम्।; \"स्नानान्तरं सः प्रातःस्मरणं करोति।\"','noun'),(35880,'','प्राणाहुतिः','पञ्चप्राणेभ्यः पञ्चकवलरूपेण दीयमाना आहुतिः।; \"पितामहः प्राणाहुतिं दत्वा एव भोजनं करोति।\"','noun'),(35881,'','रुढ','समाजे व्यवहर्तुं यद् सर्वैः स्वीकृतम्।; \"सः इदानीं रुढायाः हिन्दीभाषायाः व्याकरणं लिखति।\"','adjective'),(35882,'','प्रक्षिप्त','ग्रन्थस्य सः भागः यः मूलग्रन्थे अनन्तरं समाविष्टः।; \"तुकारामस्य गाथायां काश्चन रचनाः प्रक्षिप्ताः सन्ति।\"','adjective'),(35883,'','अतिक्रुध्','अत्यधिकः क्रोधः।; \"भ्रष्टाचारविरुद्धं जनेषु अतिक्रुध् अस्ति।\"','noun'),(35884,'','प्राणिमात्रम्, प्राणिजातिः','सम्पूर्णा जीवसृष्टिः।; \"स्वतन्त्रता स्वाधीनता च प्राणीमात्रस्य जन्मजातः अधिकारः अस्ति।\"','noun'),(35885,'','अंशः','कस्यापि वस्त्वादीनां गुणधर्मस्य भागः।; \"मध्यप्रदेशस्य सागरक्रीडासङ्कुले रविवासरे विभिन्नानां प्रदेशानां लोककलानां अंशः दृष्टः।\"','noun'),(35886,'','प्रसाधन-गृहम्','तद् स्थानं यत्र मूत्रालयशौचालययोः व्यवस्था भवति।; \"विधायकेन स्वस्य निध्या प्रसाधनगृहाणां निर्माणं कृतम्।\"','noun'),(35889,'','वंशवादः','सः सिद्धान्तः यः एकः वंशः अन्यस्मात् वंशात् श्रेष्ठतरः निम्नतरः वा अस्ति इति मन्यते।; \"आस्ट्रेलियादेशे वंशवादस्य दीर्घा परम्परा अस्ति।\"','noun'),(35891,'','अभियाचना, अभ्यर्थना, याच्ञा','कस्यापि अधिकाररूपेण दृढतापूर्वेण विशिष्टायाः सेवायाः अपेक्षया कृता याचनस्य क्रिया।; \"श्रमिकाणां अभियाचना न पूरिता अतः ते कर्मन्यासं कुर्वन्ति।\"','noun'),(35893,'','गोपनम्, गुहनम्, निगुहनम्, छादनम्','किमपि वस्तु कः अपि विचारः वा अन्यैः न ज्ञायेत इति हेतुना आचरणम्।; \"स्वजनेभ्यः किमपि गोपनं योग्यं नास्ति।\"','noun'),(35894,'','परिदेवनकर्ता','यः परिदेवनं करोति।; \"असत्यात् परिदेवनात् परिदेवनकर्ता दण्डनीयः।\"','noun'),(35896,'','सूचित','यस्य सूचना पूर्वम् कृता।; \"यथा सूचितं तथा एव कार्यं करोतु।\"','adjective'),(35897,'','लोकपालः','जनसमूहस्य हितानां रक्षार्थे नियुक्तः पुरुषः समूहः संस्था वा।; \"यदि कस्यचित् नागरिकस्य कार्यं निर्धारिते समये न भवति तर्हि लोकपालेन सम्बन्धितः अधिकारी दण्ड्यते।\"','noun'),(35903,'','अशौचम्','गृहे कस्यापि मृत्योः कारणात् परिवारजनानां जायमाना अशुद्धिः।; \"अस्माकं गृहे अशौचं दशदिनात्मकं भवति।\"','noun'),(35898,'','सुरक्षाराशिः','जीवनरक्षायाः ग्राहकेण तस्यै संस्थायै दत्ता राशिः।; \"मम धनार्जनस्य अधिकः भागः सुरक्षाराशिः इति रूपेण गच्छति।\"','noun'),(35866,'','कृष्णनेत्रपटलम्, कृष्णपटलम्, कृष्णकाचः, कृष्णलिङ्गनाशः, कृष्णनिर्झरः','नेत्ररोगविशेषः- यस्मिन् नेत्रस्थे दीप्तोपले कृष्णपटलम् आगच्छति।; \"चिकित्सकानां मतेन भारते अन्धत्वस्य प्रमुखं कारणं कृष्णनेत्रपटलम् अस्ति।\"','noun'),(35867,'','फैसलाबादनगरम्','पाकिस्तानदेशस्य पञ्जाबराज्यस्य एकं नगरम्।; \"फैसलाबादनगरे एकस्मिन् कारयाने विस्फोटः जातः।\"','noun'),(35868,'','फैसलाबादमण्डलम्','पाकिस्तानदेशस्य पञ्जाबराज्यस्य एकं मण्डलम्।; \"रहीमः फैसलाबादमण्डलस्य कस्मिञ्चित् ग्रामे निवसति।\"','noun'),(35869,'','अक्कलकोटः','महाराष्ट्रराज्यस्य सोलापूरमण्डलस्थम् एकं स्थानम्।; \"अक्कलकोटः इति एकं प्रसिद्धं तीर्थस्थानम् अस्ति।\"','noun'),(35872,'','ऋणमुक्तिपत्रम्','ऋणमुक्तेः पत्रम्।; \"धनिकेन शम्भवे ऋणमुक्तिपत्रं दत्तम्।\"','noun'),(35870,'','क्षेपणीय','क्षेप्तुं योग्यः।; \"एषः वृतान्तः अवकरे क्षेपणीयः।\"','adjective'),(35871,'','फातिहाः, फात्याः','कुरान इति ग्रन्थस्य प्रथमः अध्यायः।; \"फातिहां मृतजनानां कृते पठ्यते।\"','noun'),(35861,'','ऊष्माङ्कः','उष्णतायाः परिमाणम्।; \"एकघण्टां यावत् व्यायामेन 200-300 ऊष्माङ्काः न्यूनीकर्तुं शक्यन्ते।\"','noun'),(35862,'','जीवाण्विक','जीवाणुसम्बन्धी।; \"रमेशः जीवाण्विकम् अध्ययनं करोति।\"','adjective'),(35863,'','जीवाण्विक','जीवाणुजनितः।; \"महेशः जीवाण्विकेन रोगेण पीडितः।\"','adjective'),(35859,'','स्वीकारोक्तिः','स्वीकारप्रदर्शनी उक्तिः।; \"अस्माकं कथने भवतः स्वीकारोक्तिं प्राप्य वयं प्रमुदिताः।\"','noun'),(35860,'','अधिकमूल्यम्','सा धनराशिः या अभिरक्षायै नियतम् अंशरूपेण ऋणच्छेदनार्थं दीयते।; \"भारतीय-जीवन-रक्षा-संस्थायाः अधिकमूल्यं दातव्यम् अस्ति।\"','noun'),(35865,'','प्राथमिक-चिकित्सा','आघातनेन अथवा कस्यचित् व्याधेः प्रकटनेन वैद्यस्य उपचारात् पूर्वं तस्मिन् एव क्षणे क्रियमाणा चिकित्सा।; \"रमेशः पीडितस्य पुरुषस्य प्राथमिक-चिकित्सायाः अनन्तरं तं गृहं प्रापयितवान्।\"','noun'),(35864,'','अस्थिक्षयरोगः','अस्थ्नः क्षयरोगः।; \"शीला अस्थिक्षयरोगेण पीडिता।\"','noun'),(35842,'','जेनेवानगरम्','स्विजरलैण्डदेशे वर्तमानम् एकं नगरम्।; \"अस्माकं पिता जेनेवानगरम् अगच्छत्।\"','noun'),(35843,'','जेनेवासरोवरः','नैऋत्य-स्विजरलैण्डदेशस्य तथा च फ्रान्सदेशस्य मध्यभागे स्थितः एकः सरोवरः।; \"जेनेवानगरं जेनेवासरोवरस्य मध्ये तटे स्थितः अस्ति।\"','noun'),(35845,'','असन्तुलित','यस्य प्रमाणं योग्यं नास्ति।; \"असन्तुलितः आहारः न कर्तव्यः।\"','adjective'),(35846,'','सन्तुलित','सन्तुलनयुक्तः।; \"भारतीयः क्रिकेटसङ्घः सन्तुलितः अस्ति।\"','adjective'),(35847,'','असन्तुलित','सन्तुलनरहितः।; \"इदानीं सर्वकारः असन्तुलितः अस्ति।\"','adjective'),(35848,'','स्टेट-बैङ्क-ऑफ-बीकानेर-ऐण्ड-जयपुर','एकः भारतीयः वित्तकोषः।; \"शीला स्टेट-बैङ्क-ऑफ-बीकानेर-ऐण्ड-जयपुर इति वित्तकोषे कार्यं करोति।\"','noun'),(35849,'','स्टेट-बैङ्क-ऑफ-हैदराबाद','एकः भारतीयः वित्तकोषः।; \"स्टेट-बैङ्क-ऑफ-हैदराबाद इति वित्तकोषस्य एका शाखा अस्माकं नगरे अपि अस्ति।\"','noun'),(35850,'','स्टेट-बैङ्क-ऑफ-इन्दौर','एकः भारतीयः वित्तकोषः।; \"रमेशः स्टेट-बैङ्क-ऑफ-इन्दौर इति वित्तकोषे कार्यरतः अस्ति।\"','noun'),(35851,'','स्टेट-बैंक-ऑफ-मैसूर','एकः भारतीयः वित्तकोषः।; \"रामस्य पिता स्टेट-बैंक-ऑफ-मैसूर इति वित्तकोषे शाखाप्रबन्धकः अस्ति।\"','noun'),(35858,'','बाह्यकम्','शरीरस्य अङ्गस्य उपरितना ऊतिः संरचना वा।; \"बाह्यकस्य क्षतिग्रस्तत्वं चिन्तापदं भवितुम् अर्हति।\"','noun'),(35856,'','सम्मूर्छा','अत्याधिकायाः मूर्च्छायाः अवस्था या दीर्घावधिका तथा च गभीरस्य व्याधेः कारणेन आघातेन वा भवति।; \"शयनस्य भेषजस्य अधिकमात्रायां ग्रहणेन अपि सम्मूर्च्छायाः शक्यता वर्तते।\"','noun'),(35852,'','स्टेट-बैङ्क-ऑफ-पटियाला','एकः भारतीयः वित्तकोषः।; \"मनोहरमहोदयः स्टेट-बैङ्क-ऑफ-पटियाला इति वित्तकोषे प्रबन्धकः अस्ति।\"','noun'),(35853,'','इच्छामृत्युः, दयामृत्युः','कस्यापि इच्छानुसारेण कष्टेन विना हननस्य क्रिया।(प्रायः असाध्यरोगेण पीडितं पुरुषम्)।; \"नैके जनाः इच्छामृत्योः याचनां कुर्वन्ति।\"','noun'),(35794,'','मार्फतम्, मारफतम्','उर्दुभाषीयायाः कवितायाः प्रकारः यस्मिन् लौकिकप्रेम्णः आधारेण ईश्वरं प्रति प्रेमभावः दर्श्यते।; \"मार्फतम् अन्योक्तिसदृशः प्रकारः अस्ति।\"','noun'),(35798,'','प्रियतम','यद् अधिकं प्रियम् अस्ति।; \"मम प्रियतमा क्रीडा फुटबाल इति अस्ति।\"','adjective'),(35800,'','पक्षकारः','कलहकारिषु पक्षेषु प्रत्येकः।; \"एषः अपि तस्मिन् प्रकरणे पक्षकारः आसीत्।\"','noun'),(35806,'','सङ्कलित','संगृहितं रक्षितं च।(धनम्); \"द्विवार्षिकः सङ्कलितः राशिः द्विसहस्रम् अस्ति।\"','adjective'),(35808,'','चलनिधिः','चलरूपेण वर्तमाना निधिः।; \"पर्याप्तस्य चलनिधेः निश्चितीकरणं केन्द्रियवित्तकोषस्य कार्यम् अस्ति।\"','noun'),(35809,'','अर्थदण्डः','कस्मिन्नपि अपराधे कृते अधिकारिणा धनरूपेण दीयमानः दण्डः।; \"पञ्चदशभ्यः दिनेभ्यः पूर्वं यदि ग्रन्थालये पुस्तकं न प्रत्यर्प्यते तर्हि प्रतिदिनम् एकस्य रूप्यकस्य अर्थदण्डः अस्ति।\"','noun'),(35810,'','दण्डः','कस्मिन्नपि अपराधे कृते धनरूपेण दीयमानं शासनम्।; \"सः दण्डं दातुं विमन्यते।\"','noun'),(35811,'','प्राथमिकता, वरीयता','महत्त्वानुसारेण क्रमेण स्थापनम्।; \"रिझर्व्ह बैंक इति वित्तकोशस्य प्राथमिकता वर्धितमूल्यस्य नियन्त्रणम् इति अस्ति।\"','noun'),(35841,'','अनिश्चितकालीन','यस्य समयः निश्चितः नास्ति।; \"वित्तकोषस्य कर्मकराः अनिश्चितकालीनं कर्मन्यासं कृतवन्तः।\"','adjective'),(35839,'','न्यू-बोङ्गाईगावमण्डलम्','असमराज्ये वर्तमानम् एकं मण्डलम्।; \"ममताबनर्जीमहोदया न्यू-बोङ्गाईगावमण्डले रेलकक्षानां यन्त्रशालाम् आरप्स्यते इति उद्घोषितवती।\"','noun'),(35838,'','नन्दीग्रामण्डलम्','पश्चिमबङ्गालराज्ये वर्तमानम् एकं मण्डलम्।; \"ममताबनर्जीमहोदया नन्दीग्रामण्डले रेलकक्षानां यन्त्रशालाम् आरप्स्यते इति उद्घोषितवती।\"','noun'),(35837,'','चेलिङ्घममण्डलम्','दक्षिणभारतराज्ये वर्तमानम् एकं मण्डलम्।; \"ममताबनर्जीमहोदया चेलिङ्घममण्डले रेलकक्षानां यन्त्रशालाम् आरप्स्यते इति उद्घोषितवती।\"','noun'),(35833,'','पुनर्विचारः','पुनः कृतः विचारः।; \"भवान् स्वनिर्णयविषये पुनर्विचारं करोतु।\"','noun'),(35834,'','प्रलोभक','यः जनान् मोहयति।; \"लोहमार्गस्य अनुमानपत्रं प्रलोभकम् अस्ति।\"','adjective'),(35828,'','हमबन्टोटामण्डलम्','श्रीलङ्कादेशस्य दक्षिणदिशि वर्तमानम् एकं क्षेत्रम्।; \"हमबन्टोटामण्डलस्य राजधानी हमबन्टोटानगरम् अस्ति।\"','noun'),(35826,'','हमबन्टोटानगरम्','श्रीलङ्कादेशे वर्तमानम् एकं नगरम्।; \"अद्यतनीया क्रिकेटक्रीडा हमबन्टोटानगरस्थे क्रीडाङ्गणे भविष्यति।\"','noun'),(35827,'','हमबन्टोटा-नौकास्थानम्, हमबन्टोटा','श्रीलङ्कादेशस्य एकं बृहद् नौकास्थानम्।; \"श्रीलङ्कादेशस्य यात्रासमये हमबन्टोटा-नौकास्थाने कार्यरतेन मम एकेन मित्रेण सह अहम् अमिलम्।\"','noun'),(35817,'','सरबियादेशीय','सरबियादेशस्य निवासी।; \"नैके सरबियादेशीयाः अस्माकं नगरे निवसन्ति।\"','noun'),(35822,'','साधनम्','यद् कार्यसिद्धये प्रकृष्टोपकारकं वर्तते।; \"वार्तां श्रोतुं इदानीं आकाशवाणी इति एकम् एव मम साधनम्।\"','noun'),(35786,'','भारतीयदण्डसंहिता','जम्मुम् एवं कश्मिरं त्यक्त्वा भारतदेशे केनापि भारतीयेन कृतस्य अपराधस्य परिभाषा तथा दण्डस्य विधानं क्रियमाणा संहिता या भारतीयसेनायां न प्रभवति।; \"आङ्ग्लकाले 1862तमे वर्षे भारतीयदण्डसंहिता आरब्धा।\"','noun'),(35814,'','विद्यावाचस्पतिः','एकः उपाधिः यः कस्यापि विशेषस्य संशोधनस्य अनन्तरं विश्वविद्यालयादिभ्यः प्राप्यते।; \"रमेशः मुंबई-विश्वविद्यालये विद्यावाचस्पतेः कृते पठति।\"','noun'),(35793,'','मार्फत, मारफतम्','इस्लामधर्मस्य सुफिसम्प्रदाये साधनायाः चतुर्षु स्थितिषु तृतीया स्थितिः यस्यां साधकः गुरोः उपदेशात् ज्ञानी भवति।; \"इस्लामधर्मे शरीअतम्, तरीकतम्, मार्फतम् तथा हकीकतम् एताः चतस्रः स्थितयः सन्ति।\"','noun'),(35792,'','गृहनिर्माणराज्यमन्त्री','गृहनिर्माणविभागस्य  राज्यमन्त्री।; \"गृहनिर्माणराज्यमन्त्री वृत्तान्तलेखकानां प्रश्नान् प्रत्युत्तरति।\"','noun'),(35790,'','जालम्','वस्तूनां जनानां वा संलग्ना प्रणाली।; \"सः आपणानां जालस्य स्वामी अस्ति।\"','noun'),(35788,'','नगर-विकास-विभागः','नगरस्य विकासार्थे कार्यरतः उत्तरदायी च विभागः।; \"नगर-विकास-विभागेन नगरस्य स्वच्छतायाः कृते निर्देशाः दत्ताः।\"','noun'),(35785,'','एपल-उद्योगसंस्था','सङ्गणाकानां निर्माणे कार्यरता एका उद्योगसंस्था।; \"एपल-उद्योगसंस्थया एकं नूतनम् उपकरणं निर्मितम्।\"','noun'),(35756,'','किरकुकनगरम्','इराकराज्यस्य उत्तरदिशि वर्तमानम् एकं नगरम्।; \"अमेरिकादेशीयैः सैनिकैः किरकुकनगरे विमानाक्रमणं कृतम्।\"','noun'),(35760,'','बलप्रयोगः','कमपि विरुध्य कृतः बलस्य सेनायाः वा प्रयोगः।; \"शासनेन प्रदर्शकेषु बलप्रयोगः कृतः।\"','noun'),(35762,'','लुबॉकनगरम्','अमेरिकादेशस्य टेक्सासराज्ये वर्तमानम् एकं नगरम्।; \"लुबॉकनगरात् अल्दावसारी बद्धः।\"','noun'),(35763,'','अङ्कशास्त्रम्','मानवस्य जीवने अङ्कानां प्रभावं सूचयन्तं शास्त्रम्।; \"सः अङ्कशास्त्रस्य आधारेण भविष्यं कथयति।\"','noun'),(35764,'','परमपदम्','अत्युच्चं पदम्।; \"उत्तमानां गुणानां कारणात् एव तेन परमपदं प्राप्तम्।\"','noun'),(35765,'','अग्रगण्य','गणनायाम् अग्रः श्रेष्ठः वा।; \"ज्ञानिषु अग्रगण्यं हनुमन्तं बुद्धेः बलस्य शौर्यस्य साहसस्य च देवतां मन्यते।\"','adjective'),(35766,'','सारथ्यम्','सारथेः कार्यम्।; \"महाभारतस्य युद्धे अर्जुनस्य सारथ्यं भगवान् श्रीकृष्णः चकार।\"','noun'),(35769,'','अम्बादेवी','महाराष्ट्रराज्यस्थस्य कोल्हापूरनगरस्य देवी।; \"अम्बादेवीं तया पुत्रस्य याचना कृता।\"','noun'),(35774,'',' ',' ; \"\"','noun'),(35775,'','स्वास्थ्यलाभः','कस्मादपि रोगात् शनैः शनैः मुक्तेः क्रिया।; \"स्वास्थ्यलाभाय मासस्य अवधिः आवश्यकम्।\"','noun'),(35776,'','रक्तशर्करा','रुधिरे वर्तमाना शर्करा।; \"मधुमेहिभिः रक्तशर्करा नियन्त्रितव्या।\"','noun'),(35780,'','चित्रणम्','सङ्गणकद्वारा निर्मितं चित्रम्।; \"निर्णायकाः कदाचित् निर्णेतुं चित्रणस्य उपयोगं कुर्वन्ति।\"','noun'),(35782,'','टप्पागानम्','गानप्रकारः यस्मिन् स्वराणां लघुः समूहः विशिष्टेन प्रकारेण गीयते।; \"टप्पागानस्य प्रचलनं लखनऊनगरस्य गुलामनबीशोरीमहोदयेन कृतम्।\"','noun'),(35783,'',' ',' ; \"\"','noun'),(35784,'','आईपैड','एकः लघुः सङ्गणकः।; \"आईपैड इत्यस्य भारः अतीव न्यूनः अस्ति।\"','noun'),(35754,'','कारागृहकर्मी','कारागृहस्य कर्मकरः।; \"एकः बन्दी कारागृहकर्मिणम् प्राहरत्।\"','noun'),(35755,'','मोसुलनगरम्, मोसूलनगरम्','इराकदेशे वर्तमानम् एकं नगरम्।; \"रमेशः मोसुलनगरे निवसति।\"','noun'),(35753,'','अनशनम्','अन्नादीन् अभुक्त्वा कृतः कर्मन्यासः।; \"एकः प्रमुखः नेता अनशनस्य प्रत्यादेशम् अददत्।\"','noun'),(35750,'','वाणिज्यदूतावासः','यत्र वाणिज्येन सम्बद्धानां कार्याणां कृते राजदूतः नियुक्तः भवति।; \"रमेशः कार्यार्थं वाणिज्यदूतावासं गतवान्।\"','noun'),(35751,'','वाणिज्यदूतावासः','वाणिज्यदूतः तथा तस्य सहकारिणः।; \"वाणिज्यदूतावासेन सूचना प्रकाशिता।\"','noun'),(35752,'','वाणिज्यदूतः','वाणिज्येन सम्बद्धः दूतः।; \"अफगणिस्तानदेशे वाणिज्यदूतस्य कारयाने आक्रमणं जातम्।\"','noun'),(35747,'','राज्यमन्त्री','सः मन्त्री यस्य कः अपि स्वतन्त्रः विभागः न भवति अपि तु यः कस्यचित् अन्यस्य मन्त्रिणः अधीनः भवति।; \"जेनामहोदयः रसायनम् एवं उर्वरक-मन्त्रालये राज्यमन्त्री अस्ति।\"','noun'),(35746,'','उद्योगमन्त्री','सः मन्त्री यस्यः अधिकारे उद्योगव्यवस्था वर्तते।; \"अद्य उद्योगमन्त्रिणा उद्योगपतीनां सभा सम्बोधिता।\"','noun'),(35745,'','गृहराज्यमन्त्री','सः मन्त्री यः गृहमन्त्रिणः अधिकारे वर्तते।; \"अद्य अस्माकं नगरे गृहराज्यमन्त्री आगच्छति।\"','noun'),(35693,'','कुटुम्बः, कुटुम्बम्','एकस्यैव पुरुषस्य वंशजाः।; \"तस्य परिवारे एकता अस्ति।\"','noun'),(35694,'','परिवारः','समानैः गुणसम्बन्दादिभिः युक्तः समूहः।; \"अस्माकं भाषा आर्यभाषाणां परिवारे अन्तर्भवति।\"','noun'),(35697,'','निरोधनम्, प्रतिबन्धनम्','प्रतिबन्धस्य कार्यम्।(विशिष्टेन लसेन); \"कानिचन निरोधनानि मुखेन स्वीक्रियन्ते।\"','noun'),(35698,'','तालिबानीय','तालिबानेन सम्बन्धितः।; \"युद्धे मृताः सर्वे तालिबानीयाः आतङ्किनः आसन्।\"','adjective'),(35704,'','विश्वस्तरीय','यद् विश्वस्य स्तरे भवति।; \"प्रधानमन्त्रिमहोदयः विश्वस्तरीये अधिवेशने भागं ग्रहितुं गच्छति।\"','adjective'),(35670,'','क्रान्तिः, क्रान्तिवलयः','सूर्यस्य भ्रमणमार्गः यः पृथिव्याः अपि भ्रमणमार्गः अस्ति।; \"अरस्तुना एव प्रथमं समशीतोष्णकटिबन्धस्य सीमा क्रान्तेः ध्रुवं यावत् निश्चिता।\"','noun'),(35671,'','नक्षत्रम्','विशिष्टया आकृत्या युक्तः तारकाणां समूहः।; \"अष्टाविंशतिः नक्षत्राणि सन्ति।\"','noun'),(35672,'','अभ्यासकः','यः अभ्यासं करोति।; \"भूगोलस्य अभ्यासकेभ्यः एतत् स्थानम् अतीव रोचते।\"','noun'),(35673,'','अपररात्रः, अमान्तः','रात्रेः अन्तिमः भागः।; \"अपररात्रे कस्मात् सहाय्यं प्राप्स्यति भवान्।\"','noun'),(35674,'','धूपनम्','धूपसन्धुक्षणेन पूजनम्।; \"अस्मिन् मन्दिरे प्रातःकाले महापूजायाः अनन्तरं धूपनम् क्रियते।\"','noun'),(35680,'','चान्दीपुरम्, चान्दीपुरतटम्','भारतदेशस्य समुद्रतीरे स्थितम् एकं पर्यटनस्थलम्।; \"चान्दीपुरं बङ्गालाखातस्य तटे स्थितः अस्ति।\"','noun'),(35681,'','व्हीलरद्वीपः','भारतदेशस्य उडीसाप्रान्तस्य सागरतटात् दूरे स्थितः एकः द्वीपः यः भुवनेश्वरनगरात् अनुमानतः पञ्चाशताधिकैकशतकिलोमीटरं यावत् दूरे स्थितः अस्ति।; \"भारतदेशः व्हीलरद्वीपे क्षेपणास्त्राणां परीक्षणं करोति।\"','noun'),(35743,'','प्रारम्भिक-सार्वजनिक-निर्गमम्','; \"','noun'),(35744,'','अनुवर्तिसार्वजनिकनिर्गमः','केनचित् निगमेन हट्टे स्वस्य भागः पूर्वं सन् अपि पुनः उपलभ्यन्ते वा जनैः क्रीयते तादृशी क्रिया।; \"अस्माकम् उद्योगसंस्थायाः अनुवर्तिसार्वजनिकनिर्गमः अद्यापि न प्राप्तः।\"','noun'),(35741,'','मलकानगिरीमण्डलम्','उडीसाराज्ये वर्तमानम् एकं मण्डलम्।; \"मलकानगिरीमण्डलस्य मण्डलाधिकारी माओवादिभिः बद्धः।\"','noun'),(35740,'','विकासात्मकम्','विकाससम्बन्धी।; \"सः विकासात्मके कार्ये मग्नः अस्ति।\"','adjective'),(35738,'','लुकासफिल्म-लिमिटेड-उद्योगसंस्था','एका प्रसिद्धा उद्योगसंस्था।; \"लुकासफिल्म-लिमिटेड-उद्योगसंस्था विश्वस्य सर्वासु सफलासु उद्योगसंस्थासु एका अस्ति।\"','noun'),(35737,'','सौरविद्युत्पेटिका','येन उपकरणेन सौरविद्युत् निर्मीयते।; \"शुद्धायाः ऊर्जायाः उत्पादने सौरविद्युत्पेटिकायाः तन्त्रम् अतीव उपयुक्तम्।\"','noun'),(35735,'','कोशपेटकः, कोशपेटकम्','मूल्यवन्ति वस्तूनि स्थापयितुम् उपयुज्यमानः पेटकः।; \"धनिकः स्वस्य धनं कोशपेटके स्थापयति।\"','noun'),(35729,'','रिक्तस्थानम्','यस्मिन् पदे कस्यापि नियुक्तिः न जाता।; \"अधोलिखितानां रिक्तस्थानानां कृते आवेदनं लिखतु।\"','noun'),(35726,'','हृदयाघातः, हृद्ग्रहः','हृदयस्य कार्ये अकस्मादेव जाता अनियमितता।; \"अस्मिन् एव वर्षे द्विवारं तस्य हृदयाघातः जातः।\"','noun'),(35721,'','बेनगाजीनगरम्','लीबियादेशस्य द्वितीयक्रमाङ्कस्य बृहत् नगरम्।; \"बेनगाजीनगरे विपक्षस्य सत्ता वर्तते।\"','noun'),(35722,'','सदृश','प्रायः समानम्।; \"सदृशानि मुखानि दृश्यन्ते एव।\"','adjective'),(35725,'','बीईदानगरम्','लीबियादेशस्य तृतीयक्रमाङ्कस्य बृहत् नगरम्।; \"बीईदानगरं यवनविद्रोहिणैः यवनराज्यं घोषितम्।\"','noun'),(35719,'','रणनैतिक','रणनीतिसम्बन्धि।; \"कस्यापि देशस्य रणनैतिकानां तथा च सामरिकानां हितानां सुरक्षाविषये अन्यैः देशैः न चिन्तनीयम्।\"','adjective'),(35718,'','प्रश्नात्मक, प्रश्नार्थक','तत् यस्मात् श्रोता उत्तरम् अपेक्षते।(वाक्यम्); \"शिक्षकः छात्रान् प्रश्नार्थकान् वाक्यान् कर्तुम् अकथयत्।\"','adjective'),(35716,'','तोबरूकनगरम्','ईजिप्तदेशस्य सीम्नि स्थितं लीबियादेशस्य एकं नगरम्।; \"तोबरूकनगरे गद्दाफ्यः एकं स्मारकम् अस्ति।\"','noun'),(35717,'','आत्मरक्षा, स्वरक्षा','स्वस्य रक्षा।; \"आत्मरक्षा प्रथमं कर्तव्या।\"','noun'),(35714,'','संस्करणम्','नूतनीकरणस्य सुशोभीकरणस्य च क्रिया।; \"अस्मिन् संस्करणस्य आवश्यकता अस्ति।\"','noun'),(35715,'','संस्करण','द्विजातीयानां कृते विहिता संस्कारस्य क्रिया।; \"पण्डितः अधुना अपि संस्करणं करोति।\"','noun'),(35707,'','त्रिभुजप्रदेशः','नदीमुखस्य सः त्रिभुजाकारः भूभागः यस्मात् नदी सागरे प्रवेशनात् पूर्वं नैकासु शाखासु विभज्यते।; \"नीलनामकः त्रिभुजप्रदेशः विश्वस्य बृहद् त्रिभुजप्रदेशः अस्ति।\"','noun'),(35708,'','डेल्टा','ग्रीकवर्णमालायाः चतुर्थः वर्णः।; \"डेल्टा इति वर्णः त्रिभुजाकृत्यां लिख्यते।\"','noun'),(35709,'','संयुक्त-उद्यमः','आपदः सहभागितायाः विशेषज्ञस्य आदानार्थं प्रदानार्थं वा उद्योगसंस्थायाः समूहेन संयुक्तरीत्या कृतः उपक्रमः।; \"संयुक्त-उद्यमस्य स्वामिनः द्वौ अधिकाः वा प्रतिभागिनः अस्ति।\"','noun'),(35706,'','नीलत्रिभुजप्रदेशः','जलेन परिवेष्टिता सा भूमिः यत्र नीलनदी शाखासु विभज्य भूमध्यसागरे प्रविशति।; \"नीलत्रिभुजप्रदेशः विश्वस्य बृहद् त्रिभुजप्रदेशः अस्ति।\"','noun'),(35691,'','अशोकस्तम्भः','मौर्यवंशीयेन चक्रवर्तिसम्राजाशोकेन ख्रिस्ताब्दपूर्वे तृतीये संवत्सरे स्थापितः स्तम्भः।; \"एकः अशोक-स्तम्भः दिल्लीनगरे महरौलीक्षेत्रे कुतुबमिनारस्य समीपे स्थितः अस्ति।\"','noun'),(35688,'','केन्द्रीयसाङ्ख्यिकीसङ्घटनम्','एकं सङ्घटनं यः भारते साङ्ख्यिकीयस्य क्रियारूपस्य समन्वयार्थं विकासार्थञ्च तथा साङ्ख्यिकीयं मानकं निर्धारयति।; \"केन्द्रीयसाङ्ख्यिकीसङ्घटनस्य कार्यालयः देहल्याम् अस्ति।\"','noun'),(35687,'','उपराज्यपालः','राज्यपालस्य सहायकः यः तस्य कार्ये सहाय्यं करोति तथा च तस्य अनुपस्थितौ तस्य कार्यस्य निरीक्षणं करोति।; \"भारतदेशस्य प्रत्येकस्मिन् राज्ये उपराज्यपालः अस्ति एव।\"','noun'),(35683,'','सुरक्षाविभागः','देशस्य सुरक्षया सम्बद्धः विभागः।; \"एतत् क्षेत्रं सुरक्षाविभागस्य कर्मकराणां कृते आरक्षितम्।\"','noun'),(35685,'','विधानभवनम्','तद् भवनं यत्र विधानसभायाः सभा भवति।; \"एकेन मनुष्येण विधानभवनस्य पुरतः आत्मघातस्य प्रयासः कृतः।\"','noun'),(35686,'','प्राबल्यम्','सा शक्तिः येन किमपि कारयितुं शक्यते।; \"तेषु अस्माकं प्राबल्यं नास्ति।\"','noun'),(35663,'','अपायः, बाधा, अपकारः, दोषः, हानिः, क्षतिः','अनिष्टपरिणामः।; \"श्वसनं यदि नासिकया अपेक्षया मुखेन क्रियते तर्हि  क्लोमनाम् अपायः भवितुम् अर्हति।\"','noun'),(35669,'','अनामकत्वम्','अनामकस्य अवस्था भावः वा।; \"तेन अनामकत्वस्य अन्धःकारे एव स्वजीवनं यापितम्।\"','noun'),(35654,'',' ',' ; \"\"','noun'),(35658,'','अधिकार्थ, अतिकृत, अतिकथ','कस्यापि वस्तुनः तस्य यथार्थस्य अपेक्षया अधिकं कृतं वर्णनम्।; \"भवतः अधिकार्थेषु वचनेषु कः विश्वसेत्।\"','adjective'),(35659,'','परिसमुत्सुक, पर्युत्सुक, समुत्तेजित','अतीव उत्साहयुक्तः।; \"मह्यं परिसमुत्सुकः पुरुषः न रोचते।\"','adjective'),(35660,'','अध्ययनशील','यः अध्ययने विशेषं प्रयत्नं करोति।; \"अध्ययनशीलः रमेशः कक्षायां सर्वदा अग्रस्थाने भवति।\"','adjective'),(35652,'','सर्वोच्च','उन्नततमः।; \"विश्वस्य सर्वोच्चं पर्वतशिखरं एवरेस्ट इति अस्ति।\"','adjective'),(35649,'','मिशिगनराज्यम्','अमेरिकादेशस्य उत्तरदिशः मध्यभागे वर्तमानम् एकं राज्यम्।; \"रमेशः मिशिगनराज्ये निवसति।\"','noun'),(35650,'','मिशिगनसरोवरः','अमेरिकादेशस्थः बृहत् सरोवरः।; \"मिशिगनसरोवरः विश्वस्य तृतीयक्रमाङ्कस्य बृहद् सरोवरः अस्ति।\"','noun'),(35647,'','वित्तराज्यमन्त्री','सः मन्त्री यः वित्तमन्त्रिणः अधिकारे वर्तते।; \"अद्य अस्माकं नगरे वित्तराज्यमन्त्री आगच्छति।\"','noun'),(35648,'','मिशिगनविश्वविद्यालयः','अमेरिकादेशस्य एकः प्रमुखः विश्वविद्यालयः।; \"महेशः मिशिगनविश्वविद्यालये पठति।\"','noun'),(35645,'','कान्धारनगरम्, कन्धारनगरम्','अफगाणिस्थानदेशस्य एकम् ऐतिहासिकं नगरम्।; \"कान्धारनगरम् अफगाणिस्थानदेशस्य एकं प्रमुखं वणिक् केन्दम् अस्ति।\"','noun'),(35646,'','कन्दहारप्रान्तः','अफगाणिस्थानदेशे वर्तमानः एकः प्रदेशः।; \"कन्दहारप्रान्तस्य राजधानी कान्धारनगरम् अस्ति।\"','noun'),(35633,'','तर्कशक्तिः','तर्कितुम् आवश्यकी शक्तिः।; \"अध्यापकाः छात्रेषु तर्कशक्तिं वर्धयितुं प्रयतन्ते।\"','noun'),(35634,'','प्रगतिपत्रम्','कस्यापि मूल्याङ्कनस्य परीक्षणपत्रम्।; \"तेन स्वपुत्रस्य विद्यालयात् प्राप्ते प्रगतिपत्रे स्वाक्षरी कृता।\"','noun'),(35638,'','सेवाकरः','वृत्त्यर्थं सेवार्थं वा सेवकेभ्यः कर्मकरेभ्यः वा शासनेन स्वीक्रियमाणः शुल्कः।; \"अहं महाराष्ट्रशासनाय सेवाकरं ददामि।\"','noun'),(35644,'','सैनडिएगोनगरम्','दक्षिणकैलिफोर्नियादेशे वर्तमानम् एकं रम्यं नगरम्।; \"सैनडिएगोनगरस्य प्राकृतिकी शोभा मनोहारिणी।\"','noun'),(35641,'','अल्पशो-मूल्यम्','वस्तुनः अल्पमात्रायां विक्रयणस्य मूल्यम्।; \"वस्तुनः क्रयणसमये तस्य अल्पशो-मूल्यात् अधिकं मूल्यं मा ददातु।\"','noun'),(35639,'','सीमाशुल्कम्','किमपि वस्तु सीम्नः पारं नेतुं दीयमानं शुल्कम्।; \"शासनेन सीमाशुल्कं वर्धितम्।\"','noun'),(35640,'','उत्पाद-शुल्कम्','कस्यापि वस्तुनः उत्पादने शासनेन आकारितं मूल्यम्।; \"शासनेन वज्रचूर्णे उत्पाद-शुल्कं वर्धितम्।\"','noun'),(35627,'','परिपालनम्','विनियोगस्य प्रचलनस्य वा क्रिया।; \"शासनः एतासां योजनानां परिपालनम् आवश्यकम् मन्यते।\"','noun'),(35630,'','गृहसचिवः','कस्यापि देशस्य राज्यस्य वा गृहमन्त्रालयस्य सचिवः।; \"गृहसचिवः न्यायालयस्य आदेशानां पालनम् अकरोत्।\"','noun'),(35632,'','पैत्तवः','एकः शारीरिकः द्रवः यः यकृते जायते।; \"पैत्तवस्य वर्धनं शरीरार्थे घातकः भवति।\"','noun'),(35621,'','उड्डयनमन्त्रालयः','एकः शासनविभागः यः कस्यापि मन्त्रिणः अधिकारे वर्तते।; \"पितृव्यः उड्डयनमन्त्रालये सचिवः अस्ति।\"','noun'),(35625,'','त्रिघातीय','यस्मिन् त्रयः घाताः सन्ति।; \"एते सर्वे त्रिघातीयाः अङ्काः सन्ति।\"','adjective'),(35618,'','लिबियादेशः','भूमध्यसागरस्य तटे आफ्रिकादेशस्य उत्तरदिशि वर्तमानः देशः।; \"लिबियादेशे सैन्यस्य शासनम् अस्ति।\"','noun'),(35617,'','मिसरातानगरम्','लिबियादेशस्य एकम् आधुनिकं नगरम्।; \"मिसरातानगरस्य अधिकाराः सर्वकारस्य विरोधिकैः गृहीताः।\"','noun'),(35606,'','मेक्सिको-अखातम्','मेक्सिकोदेशस्य पूर्वदिशि स्थितम् एकम् अखातम्।; \"मेक्सिको-अखातस्य गभीरस्य खननस्य प्रकल्पं पुनः आरब्धुम् अनुमतिः प्राप्ता।\"','noun'),(35614,'','क्षेत्रम्','समाजस्य अर्थव्यवस्थायाः वा सः भागः यस्मिन् जनाः कार्यं कुर्वन्ति।; \"ते सार्वजनिके क्षेत्रे कार्यं कुर्वन्ति।\"','noun'),(35602,'','अब्जाष्टम्','सूचनायाः परिमाणम्।; \"एकम् अब्जाष्टम् एकेन अर्बुदेन समानं भवति।\"','noun'),(35604,'','घनाकार','घनस्य आकारस्य।; \"इदं वस्तु घनाकारम् अस्ति।\"','adjective'),(35592,'','दुष्प्रभावः, कुप्रभावः','प्रतिकूलः प्रभावः।; \"भवतां एतेषां वचनानां बालकेषु दुष्प्रभावः भवेत्।\"','noun'),(35596,'','राजकोषः, राजकोशः','राज्ञः कोषः।; \"सर्वकारः राजकोषस्य अधिकं धनं मन्त्रिणां कृते एव उपयुनक्ति।\"','noun'),(35597,'','राजकोषीय, राजकोशीय','राजकोषसम्बन्धी।; \"शासनः राजकोषीयां हानिं न्यूनीकर्तुं प्रयतते।\"','adjective'),(35600,'','पृथुवाहिनी, पृथुवाहिका','एषा सञ्चारवाहिनीनां विधासु अन्यतमा अभीक्ष्णतानां विस्तृतराजिं बिभर्ति प्रायेण श्रव्यादारभ्य दृश्याभीक्ष्णतापर्यन्तम्।; \"नैकाभिः उद्योगसंस्थाभिः पृथुवाहिन्याः मूल्यं न्यूनीकृतम्।\"','adjective'),(35589,'','सुनियोजित','सम्यक्तया नियोजितम्।; \"राष्ट्रे प्रतिदिनं सुनियोजिताः वधाः भवन्ति।\"','adjective'),(35590,'','निःशस्त्रीकरणम्','शस्त्रहीनकरणस्य क्रिया।; \"सम्पूर्णायाः पृथिव्याः निःशस्त्रीकरणं सुलभं नास्ति।\"','noun'),(35577,'','विवाहित','यस्य विवाहः जातः।; \"सः स्वस्य विवाहितं पतिं त्यक्त्वा अन्येन सह निवसति।\"','adjective'),(35579,'','केन्द्रीयदूरसंचारमन्त्री','सः मन्त्री यस्य अधिकारे केन्द्रीयदूरसंचारमन्त्रालयः वर्तते।; \"सः केन्द्रीयदूरसंचारमन्त्रिणा त्यागपत्रं दत्तम्।\"','noun'),(35580,'','केन्द्रीयदूरसंचारमन्त्रालयः','सः मन्त्रालयः यः केन्द्रीयदूरसंचारमन्त्रिणः अधिकारे वर्तते।; \"सः केन्द्रीयदूरसंचारमन्त्रालये वृत्तिं प्राप्तवान्।\"','noun'),(35581,'','प्रचालकः','यः यन्त्रं परिचालयति।; \"सर्वे कर्मकराः प्रचालकस्य प्रतीक्षां कुर्वन्ति।\"','noun'),(35582,'','प्रचालकः, सञ्चालकः','यः कमपि उद्योगं प्रचालयति अथवा उद्योगसंस्थायाः स्वामी अस्ति।; \"वोडाफोन-उद्योगसंस्थायाः प्रचालकेन सह अहं सम्भाषणं कृतवती।\"','noun'),(35583,'','धूपेन्यम्','एकः वर्णहीनः तथा च अत्यधिकः ज्वलनशीलः यौगिकपदार्थः।; \"धूपेन्यं मधुरगन्धयुक्तः द्रवः अस्ति।\"','noun'),(35585,'','शवलेपनम्','शवस्य उपरि किञ्चित् लेपनस्य क्रिया।; \"शवस्य रक्षणार्थे शवलेपनं क्रियते।\"','noun'),(35586,'','हैमबर्गनगरम्, हमबर्गनगरम्','जर्मनीदेशस्य द्वितीयक्रमाङ्कस्य बृहद् नगरम्।; \"रमेशः हैमबर्गनगरे अटनार्थं गतः।\"','noun'),(35573,'','लॉसएन्जेलेसनगरम्','अमेरिकादेशस्य कैलिफोर्नियाराज्यस्य एकं नगरम्।; \"लॉसएन्जेलेसनगरम् अमेरिकादेशस्य द्वितीयक्रमाङ्कस्य अधिकजनसङ्ख्यायुक्तं नगरम् अस्ति।\"','noun'),(35574,'','इलिनोइसराज्यम्, इलिनायराज्यम्','अमेरिकादेशे वर्तमानम् एकं राज्यम्।; \"इलिनोइसराज्ये शिकागोनगरम् अस्ति।\"','noun'),(35575,'','पयस्य','दुग्धेन निर्मितम्।; \"क्षीरविकृतिदध्यादयः पयस्याः सन्ति।\"','adjective'),(35576,'','सरदारवल्लभभाईपटेलमहोदयः','भारतदेशस्य स्वातन्त्र्यसङ्ग्रामस्य सेनानीः यः स्वतन्त्रस्य भारतदेशस्य प्रथमः गृहमन्त्री तथा च उपप्रधानमन्त्री आसीत्।; \"सरदारवल्लभभाईपटेलमहोदयस्य जन्म गुजरातराज्यस्य नडियादनगरे अभवत्।\"','noun'),(35517,'','सुचारु','यः सम्यक् रीत्या भवति।; \"मोहनस्य मार्गदर्शनेन अस्याः संस्थायाः विकासः सुचारुः भवति।\"','adjective'),(35518,'','ध्वजारोपणम्','ध्वजप्रचालस्य क्रिया।; \"रक्तदुर्गे प्रधानमन्त्रिणा ध्वजारोपणं कृतम्।\"','noun'),(35519,'','प्रचालयनम्, विधूननम्','वायौ चलितुं प्रेरणस्य क्रिया।; \"तिरङ्गाध्वजस्य प्रचालयनस्य अनन्तरं प्रधानमन्त्रिणा देशः सम्बोधितः।\"','noun'),(35520,'','जनाक्रोशः','जनानाम् आक्रोशः।; \"जनाक्रोशं दृष्ट्वा नेतृमहोदयेन सभा स्थगिता।\"','noun'),(35522,'','भूसर्वेक्षणम्','भूमेः सर्वेक्षणम्।; \"अधिकारी अद्य अस्माकं ग्रामस्य भूसर्वेक्षणं करोति।\"','noun'),(35523,'','ह्वाइटहाउसम्','अमेरिकादेशस्य तत् शासकीयं भवनं यत्र तत्रत्यः राष्ट्रपत्युः कार्यालयः निवासश्च वर्तते।; \"भारतस्य प्रधानमन्त्री अद्य अमेरिकादेशस्य राष्ट्रपत्या सह ह्वाइटहाउस इत्यत्र मिलिष्यति।\"','noun'),(35524,'','ह्वाइटहाउसम्','अमेरिकादेशस्य मुख्यः कार्यकारी विभागः।; \"रमेशस्य एकं मित्रम् ह्वाइटहाउस इत्यत्र कार्यं करोति।\"','noun'),(35525,'','विदेशविभागः','सः विभागः यः विदेशसम्बन्धि कार्यं करोति।; \"अमेरीकादेशस्य विदेशविभागस्य प्रवक्ता आक्षेपाणां खण्डनं करोति।\"','noun'),(35526,'','म्यूनिखनगरम्','जर्मनीदेशे वर्तमानम् एकं बृहद् नगरम्।; \"म्यूनिखनगरं बवेरियाराज्यस्य राजधानी अपि अस्ति।\"','noun'),(35527,'','बवेरियाराज्यम्','जर्मनीदेशे वर्तमानम् एकं राज्यम्।; \"बवेरियाराज्यस्य राजधानी म्यूनिखनगरम् अस्ति।\"','noun'),(35528,'','प्रत्यर्पणम्','कस्मिन्नपि देशे स्थितः अन्यदेशस्य अपराधिनः गृहित्वा तस्मै एव देशाय पुनः अर्पणस्य क्रिया।; \"पाकिस्तानदेशः ब्रिटेनदेशात् मुशर्रफस्य प्रत्यर्पणम् इच्छति।\"','noun'),(35529,'','समतलभूमिः','पर्वतीयप्रदेशात् अन्यः भूभागः यः प्रायः समतलः भवति।; \"पर्वतानां मध्ये समतलभूमौ जनाः वसन्ति।\"','noun'),(35532,'','पाकिस्तानमुस्लिमलीगनवाजपक्षः','पाकिस्तानदेशस्य राजनैतिकः पक्षः।; \"पाकिस्तानमुस्लिमलीगनवाजपक्षः पाकिस्तानदेशस्य मुख्यः विपक्षः अस्ति।\"','noun'),(35534,'',' ',' ; \"\"','noun'),(35535,'','वाणी, वाक्, वाचा','भाषणस्य शक्तिः।; \"सप्तवर्षीयं मूकम् आरोडाविष्णुः गुरोः कृपया वाणीं प्राप्तवान्।\"','noun'),(35536,'','समाजवादी-पक्षः, एसपी','भारतस्य एकः राजनैतिकः पक्षः।; \"श्वः लखनौनगरे समाजवादीपक्षस्य विधायकानां सम्मेलनम् अस्ति।\"','noun'),(35537,'','बहुजन-समाजवादी-पक्षः','भारते वर्तमानः एकः राजनैतिकः दलः।; \"उत्तरप्रदेशराज्ये बहुजन-समाजवादी-पक्षस्य शासनम् अस्ति।\"','noun'),(35539,'','अस्तित्ववादम्','सः सिद्धान्तः यस्य अनुसारेण अस्तित्वम् एव मुख्यं तत्वं वर्तते।; \"अस्तित्ववादे मनुष्यः पर्यावरणं तत्वज्ञानस्य स्रोतरूपेण न वीक्षते।\"','noun'),(35540,'','अस्तित्ववादी','यः अस्तित्ववादम् आचरति।; \"अस्तित्ववादिनः सर्वदा अस्तित्वम् एव प्रमाणम् इति मन्यन्ते।\"','noun'),(35541,'','अस्तित्ववादिन्','अस्तित्ववादसम्बन्धी।; \"तस्य लेखने अस्तित्ववादिनः विचारस्य प्रभावः दृश्यते।\"','adjective'),(35550,'','अलिखित','यद् लिखितं नास्ति।; \"अस्य गणस्य केचन अलिखिताः नियमाः सन्ति।\"','adjective'),(35552,'','अर्ध-वर्तुलाकार, अर्ध-गोलाकार','अर्धवर्तुलस्य आकारस्य।; \"अर्ध-वर्तुलाकाराणि शौचालयानि निर्मितानि।\"','adjective'),(35554,'','अहिल्याबाई','अष्टादशमे संवत्सरे इन्दुरसंस्थानस्य कार्यसञ्चालिका स्त्री।; \"अहिल्याबाई अष्टादशवर्षाणि यावत् इन्दोरसंस्थानस्य धुरम् अवहत्।\"','noun'),(35556,'','जीवनरक्षा','सा रक्षा या रक्षितस्य मृत्योः पश्चात् तस्य उत्तराधिकारी प्राप्नोति।; \"अहं मम सप्तदशवर्षीयस्य पुत्रस्य कृते वैद्यकीया तथा च जीवनरक्षायाः नीतिं क्रेतुम् इच्छामि।\"','noun'),(35557,'','लैटिन-अमेरिकादेशः','दक्षिणदिग्वर्ती तथा च उत्तरदिग्वर्ती अमेरिकादेशः तथा च संयुक्त-राज्य-अमेरिकादेशस्य सः भागः यत्र लैटिनभाषा भाष्यते।; \"सः लैटिन-अमेरिकादेशात् आगतः।\"','noun'),(35558,'','मुदु, पेलव, पेशल, मुदु, मुदुल, मृदु, मराल, कोमल, ललित, मृदुल, कल, अपुष्ट, अरूक्ष, अरूक्षित, अरूक्ष्ण, अलूक्ष, आर्द्र, कौमार, क्लिन्न, धीर','यस्मिन् कठोरता नास्ति।; \"तस्य स्वभावः सरलः तथा च मृदुः अस्ति।\"','adjective'),(35559,'','मन्द','यस्मिन् अधिका उग्रता तीव्रता वा नास्ति।; \"इदानीमपि मन्दः ज्वरः अस्ति।\"','adjective'),(35560,'','मन्द, चिरकारिन्','यः शनैः शनैः स्वप्रभावं दर्शयति।; \"मादकानि भेषजानि मन्दस्य विषस्य कार्यं कुर्वन्ति।\"','adjective'),(35561,'','विधानपरिषद्','केषुचित् भारतीयेषु राज्येषु लोकतन्त्रस्य एका प्रतिनिधिसभा यस्याः सदस्याः अप्रत्यक्षनिर्वाचनद्वारा निर्वाचिताः भवन्ति तथा च केचन सदस्याः राज्यपालद्वारा नियुक्ताः भवन्ति।; \"विधानपरिषद् विधानमण्डलस्य एकम् अङ्गम् अस्ति यस्याः सदस्यानां कार्यकालः षण्णां वर्षाणां भवति।\"','noun'),(35572,'','शिकागोनगरम्','अमेरिकादेशस्य इलियानराज्यस्य बृहद् नगरं यस्य जनसङ्ख्या त्रीणिदशलक्षं यावत् अस्ति।; \"शिकागोनगरम् अमेरिकादेशस्य तृतीयक्रमाङ्कस्य अधिकजनसङ्ख्यायुक्तं नगरम् अस्ति।\"','noun'),(35571,'','यूरोपीयसङ्घः','युरोपखण्डस्य सप्तविंशतेः राष्ट्राणाम् एकः राजनैतिकः आर्थिकः सङ्घः यस्मिन् परस्परेषु प्रशासकीया संविभागिता वर्तते या सर्वान् प्रति समाना भवति।; \"यूरोपीयसङ्घस्य आरम्भः 1957 तमे वर्षे जातः।\"','noun'),(35570,'','विकेन्द्रीकरणम्','सा सामाजिकी प्रक्रिया यस्यां जनसमुदायः तथा च उद्योगाः नगरात् बहिः दूरे स्थानान्तरिताः भवति।; \"विकेन्द्रीकरणेन नगरस्य प्रदूषणं न्यूनीभवति।\"','noun'),(35562,'','सेवारत','यः सेवायां रतः अस्ति।; \"सेवारतेभ्यः अध्यापकेभ्यः वेतनं शीघ्रं दीयते।\"','adjective'),(35564,'','प्रभारः','कस्यचित् कार्यस्य निर्वहणस्य उत्तरदायित्वम्।; \"राष्ट्रपतिना नवनियुक्ताय उपराष्ट्रपतये प्रभारः दत्तः।\"','noun'),(35569,'','विकेन्द्रीकरणम्','सत्तायाः शक्तेः वा केन्द्रात् अन्यस्थाने गमनं विस्तारः वा।; \"लघूनां राज्यानां अवधारणया एव सत्तायाः विकेन्द्रीकरणं सम्बद्धम् अस्ति।\"','noun'),(35514,'','समावेशनम्','समावेशस्य क्रिया।; \"एकस्य नूतनस्य मण्डलस्य समावेशनं जातम्।\"','noun'),(35501,'','संसूचकः','उपकरणविशेषः येन कस्यापि वस्तुनः स्थितिः सूच्यते।; \"धातवः अन्वेषयितुं धातोः संसूचकम् उपयुज्यते।\"','noun'),(35502,'','आकलैण्डनगरम्, ऑकलैण्डनगरम्','न्यूजीलैण्डदेशे स्थितेषु नगरेषु बृहत् नगरम्।; \"पर्यटनार्थम् आकलैण्डनगरम् उत्तमम् अस्ति।\"','noun'),(35503,'','सिलिकॉनवैलीक्षेत्रम्','कैलिफोर्नियाराज्ये वर्तमानं क्षेत्रम्।; \"उच्च प्रौद्योगिकीनाम् उद्योगानां कृते सिलिकॉनवैलीक्षेत्रं ख्यातम् अस्ति।\"','noun'),(35506,'','मैरीलैण्डराज्यम्','मध्य-अटलाण्टिक-क्षेत्रे स्थितम् एकं अमेरिकादेशस्य राज्यम्।; \"मैरीलैण्डराज्यस्य उत्तरदिशि पेन्सिलवेनियाराज्यं वर्तते।\"','noun'),(35507,'','पेन्सिलवेनियाराज्यम्, पेनसिलवेनियाराज्यम्','अमेरिकादेशे वर्तमानम् एकं राज्यम्।; \"पेन्सिलवेनियाराज्यम् अमेरिकादेशस्य पूर्वदिशि स्थितम् अस्ति।\"','noun'),(35510,'','चितवनमण्डलम्','नेपालदेशस्य नारायणी इति क्षेत्रे वर्तमानम् एकं मण्डलम्।; \"चितवनमण्डले कृष्णिकायाः शस्यं सम्यक् भवति।\"','noun'),(35511,'','नारायणी, नारायणीनदी','एका नदी।; \"नारायणी नेपालदेशे भारतदेशे च स्रवति।\"','noun'),(35512,'','नारायणीक्षेत्रम्, नारायणी-अञ्चलक्षेत्रम्','नेपालदेशे वर्तमानम् एकं क्षेत्रम्।; \"नारायणीक्षेत्रे पञ्चमण्डलानि सन्ति।\"','noun'),(35513,'','मकवानपुरमण्डलम्','नेपालदेशे वर्तमानम् एकं मण्डलम्।; \"मम एकं मित्रं मकवानपुरमण्डले निवसति।\"','noun'),(35500,'','रक्षा-अनुसन्धानम्-तथा-विकास-सङ्घटनम्','रक्षासम्बद्धम् अनुसन्धानार्थं तथा विकासार्थं या संस्था कार्यं करोति।; \"मोहनः रक्षा-अनुसन्धानम्-तथा-विकास-सङ्घटने कार्यरतः अस्ति।\"','noun'),(35496,'','विनियोक्ता','सः पुरुषः संस्था वा यः अन्यान् जनान् स्वस्थाने कार्यार्थं नियोजयति।; \"विनियोक्त्रा कार्यालयेन अस्मिन् संवत्सरे कर्मकरान् अधिलाभांशः न दत्तः।\"','noun'),(35492,'','नियमः, सिद्धान्तः, ऋतम्, धर्म, नियमनम्','किमपि कार्यं कर्तुं निर्धारिताः निर्देशाः।; \"संविद् इत्यपि एकः नियमः एव।\"','noun'),(35494,'','विनियोक्तृ','यः नियुक्तिं करोति।; \"प्रधानमन्त्रिणः विनियोक्तारः द्वयोः सभयोः सदस्याः सन्ति।\"','adjective'),(35495,'','विनियोक्तृ','यः अन्यान् जनान् स्वस्थाने कार्यार्थं नियोजयति।; \"विनियोक्त्री उद्योगसंस्था अस्मिन् वर्षे कर्मकरेभ्यः अधिलाभांशं दातुं विमन्यते।\"','adjective'),(35491,'','संविद्','अयं वैधिकनियमानां सङ्ग्रहः यः जालकृतौ दत्तांशप्रसारणपद्धतिं निरूपयति।; \"संविदः नैके स्तराः भवन्ति।\"','noun'),(35490,'','अन्तर्जालसङ्केतः, अन्तर्जालनिकेतसङ्केतः, ऐपी-सङ्केतः','प्रत्येकानां सङगणकमुद्रणयन्त्रादीनाम् उपकरणादीनां विशिष्टा द्वात्रिंशत् अङ्कीया सङ्ख्या।; \"अन्तर्जालसङ्केतेन ज्ञातुं शक्यते यद् तद् उपकरणं कुत्र अस्ति।\"','noun'),(35464,'','महाकुम्भम्','शताधिकं चतुश्चत्वारिंशत्वर्षानन्तरं निर्वर्त्यमानं कुम्भपर्व।; \"द्वादशानां कुम्भानन्तरं महाकुम्भस्य आयोजनं भवति।\"','noun'),(35468,'','विस्तीर्ण, विस्तृत, महाकार, विशाल, पृथु, पर्याप्त, बहल','यद् लघु नास्ति।; \"महानगरेषु एतादृशी विस्तीर्णा समभूमिः न दृश्यते।\"','adjective'),(35470,'',' ',' ; \"\"','adjective'),(35471,'','स्रोतः','शरीरस्थमार्गविशेषः यस्य सङ्ख्या पुरुषेषु नव तथा च स्त्रीषु एकादश इति मन्यते।; \"शरीरे स्त्रोतसः प्राणान्नजलरसरक्तमांसमेदमलमूत्रशुक्रार्तवादीनां सञ्चारः भवति।\"','noun'),(35489,'','विसारः','कस्यापि पदार्थस्य अणूनाम् अधिकायाः सान्द्रतायाः न्यूनां सान्द्रताम् अभि गमनस्य क्रिया।; \"डायलिसिस इति क्रियायां विसारः महत्वपूर्णः अस्ति।\"','noun'),(35487,'','स्फटिकप्रभ, मणिमय','यस्य वर्णाकारादयः गुणाः स्फटिकम् इव भवन्ति।; \"स्फटिकप्रभाः पदार्थाः अधिकया शीघ्रतया प्रसारिताः भवन्ति।\"','adjective'),(35486,'','व्याश्लेषणम्','सा क्रिया यस्यां रुधिरात् अनावश्यकं जलं तथा च त्याज्यपदार्थाः अपाक्रियन्ते या च विशेषतः मानवानां वृक्कस्य कार्यं यदा अवरुद्धं वर्तते तदा क्रियते।; \"यदा वृक्कः सम्यक् कार्यं न करोति तदा व्याश्लेषणम् क्रियते।\"','noun'),(35484,'','उपमार्गः','यदा शरीरस्थाः धमन्यादयः भागाः अवरुद्धाः क्षतिग्रस्ताः वा भवन्ति तदा शल्यचिकित्सकेन निर्मितः वैकल्पिकः मार्गः।; \"शल्यचिकित्सकेन हृद्रोगिणः हृदये उपमार्गः निर्मितः।\"','noun'),(35479,'','वर्तिका','धूपेन ज्वलनशीलेन पदार्थेन वा वेष्टितः पदार्थः यः पूजनादिसमये प्रज्वाल्यते।; \"धूपवर्तिकादयः नित्यशः प्रयुज्यमानाः वर्तिकाः सन्ति।\"','noun'),(35476,'','स्थेयगणः','कञ्चित् विषयं चिन्तितुं कांश्चित् योजनां निर्मातुम् अथवा कस्याश्चित् प्रतियोगितायाः निर्णयं कर्तुम् एकत्रिताः जनाः।; \"वादविवादप्रतियोगितायाः स्थेयगणेन स्वनिर्णयः आयोजकाय प्रेषितः।\"','noun'),(35472,'','प्रतिबद्धता','प्रतिबद्धस्य अवस्था भावः वा।; \"वैवाहिकी प्रतिबद्धता पालनीया।\"','noun'),(35462,'','अनुभवसिद्ध','अनुभवेन यद् प्राप्यते।; \"अनुभवसिद्धेन ज्ञानेन अस्माभिः अस्य परीक्षणं कर्तव्यम्।\"','adjective'),(35460,'','महावस्त्रम्','सर्वेषां वस्त्राणाम् उपरि धार्यमाणः एकः वस्त्रविशेषः यः अन्येषां वस्त्राणाम् अपेक्षया अधिकः विस्तीर्णः भवति।; \"एतैः जनैः दत्तं महावस्त्रम् अद्य एव एतां देवीं परिधार्यते।\"','noun'),(35461,'','अनुत्पादक','यः उत्पादकः नास्ति।; \"अनुत्पादकं व्ययं न्यूनीकृत्य शासनेन राजकोषस्य स्थितेः सन्तुलनाय अवधानं दातव्यम्।\"','adjective'),(35458,'','सदनिका','बहुभिः अट्टैः निर्मितस्य भवनस्य कस्मिन्नपि अट्टे वर्तमानेषु नैकेषु गृहेषु एकः यस्मिन् अधिकाः प्रकोष्ठाः भवन्ति।; \"मम सदनिका द्वितीये अट्टे अस्ति।\"','noun'),(35448,'','मून्दडाः','वंशनाम्नः उपाधिः।; \"गुजरातराज्ये नैके मून्दडाः सन्ति।\"','noun'),(35449,'','मून्दडानगरम्','गुजरातराज्यस्य कच्छमण्डले वर्तमानं स्थानम्।; \"सः मून्दडानगरे निवसति।\"','noun'),(35450,'','समुद्रमार्गः','जलयानानां समुद्रे गमनागमनस्य मार्गः।; \"समुद्रमार्गेण गमनसमये जलदस्युभ्यः जागर्यात्।\"','noun'),(35446,'','पेन्सिलवेनियाविश्वविद्यालयः','पेन्सिलवेनियाराज्ये स्थितः एकः ख्यातः विश्वविद्यालयः।; \"शीला पेन्सिलवेनियाविश्वविद्यालये पठति।\"','noun'),(35457,'','आइफिल टॉवर, आयफिल टॉवर','फ्रान्सदेशस्य पेरिसनगरे स्थितं धातोः निर्मितं ३२४ मीटरं यावत् उन्नतं भवनम्।; \"आइफिल टॉवर इत्यस्य निर्माणं 1889तमे वर्षे अभवत्।\"','noun'),(35455,'','अधिक, अतिरिक्त','वर्तमानायाः मात्रायाः अधिकतरम्।; \"अहम् अधिकां रोटिकाम् इच्छामि।\"','adjective'),(35433,'','तैलमन्त्रालयः','सः मन्त्रालयः यः तैलसम्बन्धि कार्यं करोति।; \"तैलमन्त्रालयेण तैलस्य अयोग्यं विक्रयणम् अवरोद्धुं कठिनाः नियमाः कृताः।\"','noun'),(35439,'','रणजीचषकः','क्रिकेटक्रीडायां स्पर्धायाः विशिष्टा शृङ्खला।; \"सचिनः रणजीचषके अपि क्रीडति।\"','noun'),(35443,'','जलं तथा पर्यावरणमन्त्री','सः मन्त्री यः पर्यावरणसम्बन्धी कार्यं करोति।; \"जलं तथा पर्यावरणमन्त्री जलप्रदूषणात् रक्षणार्थे नूतनां योजनां उद्घोषयति।\"','noun'),(35445,'','कृष्णविवरः','अन्तरिक्षस्य सः भागः यस्य गुरुत्वाकर्षणक्षेत्रम् अतीव शक्तिशालि अस्ति।; \"कृष्णविवरे आगतं प्रकाशं सः पूर्णतः अवशोषयति।\"','noun'),(35429,'','महानिदेशालयः','महानिदेशकस्य कार्यालयः।; \"सः महानिदेशालयं गतवान्।\"','noun'),(35430,'','महानिदेशालय','महानिदेशकस्य कार्यालये कार्यरता कार्यकारिणी।; \"महानिदेशालयात् कर्मकराणां कृते सूचना प्रकाशिता।\"','noun'),(35424,'','दूरसञ्चार-विभागः','दूरसञ्चारस्य विभागः।; \"श्यामा दूरसञ्चार-विभागे कार्यरता अस्ति।\"','noun'),(35425,'','अर्बुदपतिः, अर्बुदस्वामी','यः अर्बुदस्य स्वामी अस्ति।; \"अर्बुदपतीनां सूच्यां नैके क्रीडकाः अपि सन्ति।\"','noun'),(35423,'','स्टेट-बैङ्क-ऑफ-इण्डिया','सर्वकारेण सञ्चालितः एकः भारतीयः वित्तकोषः।; \"तस्य लेखा स्टेट-बैङ्क-ऑफ-इण्डिया इति वित्तकोषे अपि अस्ति।\"','noun'),(35418,'','केन्द्रशासनम्','देशस्य मुख्यं शासनं यस्य मुख्यालयं राजधान्यां वर्तते।; \"केन्द्रशासनं कृषकाणां कृते नूतनाः योजनाः प्रचालयति।\"','noun'),(35417,'','स्वाधिकारपत्रम्','तद् अधिकारपत्रं यस्मिन् कस्यचित् वस्तुनः स्वाम्यम् अस्य मनुष्यस्य उद्योगसंस्थायाः वा अस्ति इति लिखितं भवति।; \"यावद् स्वाधिकारपत्रं न प्राप्यते तावत् किमपि वक्तुं न शक्यते।\"','noun'),(35412,'','शोधपत्रम्','तद् पत्रं यस्मिन् स्वेन कृतस्य शोधविषये लिखितं भवति।; \"रमेशः स्वस्य शोधपत्रम् अध्यापकाय दर्शयितुम् अगच्छत्।\"','noun'),(35413,'','युद्धग्रस्त','यः युद्धेन ग्रस्तः अस्ति।; \"युद्धग्रस्ते देशे नैकाः आपदः उद्भवन्ति।\"','adjective'),(35416,'','स्वाम्यम्','वस्तुनः निर्माणादिषु पूर्णस्य अधिकारस्य प्राप्तिः येन तस्य वस्तुनः आविष्कर्ता तानि वस्तूनि विक्रेतुं शक्नोति।; \"सः आयुर्वेदिकस्य औषधस्य स्वाम्यं प्राप्तुम् इच्छति।\"','noun'),(35409,'','तन्त्रिकाशास्त्रीय','तन्त्रिकाशास्त्रेण सम्बद्धः।; \"सः तन्त्रिकीयया व्याध्या पीडितः अस्ति।\"','adjective'),(35410,'','समादेशः','(सङ्गणकविज्ञानम्)आदेशपरकः शब्दः यः सङ्गणकविधिं विशिष्टं कार्यम् आदिशति।; \"इदानीम् अहं भवते एकस्य नूतनस्य समादेशस्य विषये कथयामि।\"','noun'),(35395,'','अधीक्षकः','आरक्षकाणाम् एकः उच्चाधिकारी।; \"अधीक्षकेण सह महानिरीक्षकः अपि घटनास्थले आसीत्।\"','noun'),(35396,'','उष्ण','यः शरीरे उष्णताम् उत्पादयति।; \"जातिफलमरिचिकालवङ्गतेजःपत्त्रादीनि उष्णानि व्यञ्जनानि सन्ति।\"','adjective'),(35405,'','क्षमादानम्','क्षमायाः दानम्।; \"राजा दुष्टाय मन्त्रिणे क्षमादानम् अकरोत्।\"','noun'),(35408,'','चहलुमः','यवनधर्मे मृत्योः पश्चात् चत्वारिंशत्तमे दिने क्रियमाणं कार्यम्।; \"सः रहीमस्य चहलुमे गतः।\"','noun'),(35394,'','महानिरीक्षकः','आरक्षकाणां सेनायाः वा उच्चपदस्थः अधिकारी।; \"महानिरीक्षकः शीघ्रमेव घटनास्थानं प्राप्तवान्।\"','noun'),(35392,'','जनजीवनम्','जनानां जीवनम्।; \"जलप्लावनेन जनजीवनं प्रभावितम्।\"','noun'),(35393,'','दक्षिण-आशियाई-क्षेत्रीय-सहयोग-सङ्घटनम्','आशियाखण्डस्य दक्षिणदिशि वर्तमानानां अष्टानां देशानाम् आर्थिकं तथा राजनैतिकं सङ्घटनं यस्य सदस्यानां देशानां जनसङ्ख्या प्रायः सार्ध अर्बुदं यावत् अस्ति।; \"दक्षिण-आशियाई-क्षेत्रीय-सहयोग-सङ्घटनम् अन्येषां सङ्घटनानाम् अपेक्षया अधिकं प्रभावशालि अस्ति।\"','noun'),(35391,'','जुबानगरम्','दक्षिणसुडानदेशस्य राजधानी।; \"जुबानगरं नीलनद्याः तटे स्थितम् अस्ति।\"','noun'),(35386,'','रूपम्','शरीरस्य आकृतिः।; \"रूपात् अधिकं गुणाः अपेक्ष्यन्ते।\"','noun'),(35387,'','वर्णनम्','कस्यापि मनुष्यस्य रूपवर्णादीनां विवरणं येन तं ज्ञातुं शक्यते।; \"सा आरक्षकं चोरस्य वर्णनं कथितवती।\"','noun'),(35388,'','दूरदर्शनम्','सा दूरसम्पर्कव्यवस्था या अन्यत्र स्थितानां वस्तूनाम् आलेखं सर्वत्र प्रसारयति।; \"दूरदर्शनस्य अनुसारेण इयं वार्ता असत्या।\"','noun'),(35389,'','उत्तर-अटलाण्टिक-सङ्घटनम्','1949 तमे संवत्सरस्य एप्रिलमासस्य चतुर्थे दिनाङ्के स्थापितं सङ्घटनं यद् सामूहिकां सुरक्षां प्रति बद्धम् अस्ति तथा येन सदस्याः राष्ट्राः अन्यैः कृतस्य आक्रमणस्य स्थितौ सहयोगार्थं बद्धाः भवन्ति।; \"उत्तर-अटलाण्टिक-सङ्घटनस्य मुख्यालयः बेल्जियमदेशस्य राजधान्यां ब्रुसेल्सनगरे अस्ति।\"','noun'),(35375,'','वाननिरीक्षणी, दूरदर्शनयन्त्रम्','यद् यन्त्रं दूरस्थानां वस्तूनाम् आलेखं बृहद् कृत्वा दर्शयति।; \"मुम्बईनगरस्य तारागृहे गगने स्थितान् ग्रहनक्षत्रान् द्रष्टुं वाननिरीक्षणी अस्ति।\"','noun'),(35368,'','मन्त्रालयः','मन्त्रिणः कार्यालयः।; \"नूतनेन मन्त्रिणा मन्त्रालयस्य कार्यं सम्यक् भवतु तदर्थं कर्मकराणां प्रार्थना कृता।\"','noun'),(35364,'','अट्टः, उदर्कः','उन्नता रचना यस्याः उपयोगः अवलोकनार्थं तथा च सङ्केतनार्थे क्रियते।; \"बर्लिननगरे वर्तमानः दूरदर्शनस्य अट्टः ख्यातः।\"','noun'),(35366,'','समयसारिणी','कार्यक्रमाणां तथा च तेषां निश्चितस्य समयस्य सूची।; \"समयसारिण्याः अनुसारेण अस्माकं परीक्षा द्विवादने आरप्स्यते।\"','noun'),(35370,'','क्रोशमापनपाषाणः','मार्गस्य पक्षे वर्तमानः पाषाणः यः विशिष्टात् स्थानात् तस्य स्थानस्य अन्तरं सूचयति।; \"क्रोशमापनपाषाणस्य अनुसारेण नगरम् इदानीं केवलं कोशद्वयं यावत् दूरे अस्ति।\"','noun'),(35353,'','निवेशसूचिः','मनुष्यस्य वित्तकोषस्य अन्यायाः संस्थायाः वा वित्तीयायाः सम्पत्तेः सूचिः।; \"सञ्चयस्य निवेशसूच्यां न्यूनेन लाभेन निराशः सः जातः।\"','noun'),(35354,'','प्रधानपुरुषः','महत्वपूर्णः प्रधानः वा पुरुषः।; \"विश्वसम्मेलने भागं ग्रहीतुं नैकेभ्यः स्थानेभ्यः ख्याताः प्रधानपुरुषाः आगच्छन्ति।\"','noun'),(35355,'','रासाय-चिकित्सा','एका उपचारपद्धतिः या अर्बुदरोगस्य कोशिकाः नाशयितुं क्रियते।; \"रासाय-चिकित्सा शस्त्रक्रियया सह अपि दीयते।\"','noun'),(35356,'','विकिरणचिकित्सा','विकिरणया ऊर्जया यथा क्ष-किरणसदृशैः किरणैः व्याधीनाम् उपचारः।; \"विकिरणचिकित्सया कर्करोगस्य उपचारः भवति।\"','noun'),(35357,'','शतकीय','शतकसम्बन्धी।; \"सहवागवीरेन्द्रस्य कोहलीविराटस्य शतकीयेन क्रीडनेन भारतः विजयं प्राप्तवान्।\"','adjective'),(35362,'','श्रव्यः','विद्युन्माध्यमैः अभिलिखितः तथा च प्रस्तुतः ध्वनिः।; \"अन्धानां कृते श्रव्यः साहाय्यकः भवति।\"','noun'),(35347,'','यकृतशोथः','यकृतस्य शोथः।; \"यकृतशोथस्य नैके प्रकाराः सन्ति।\"','noun'),(35349,'','सञ्चयः, सम्भारः, सामग्री','भविष्ये वस्तूनाम् उपयोगं कर्तुं तेषां कृतः सङ्ग्रहः।; \"उद्योगसंस्थानां समीपे पर्याप्तः सञ्चयः भवति।\"','noun'),(35345,'','आधारित','यद् कस्यचित् आधारेण वर्तते।; \"लोककथायाम् आधारितः चित्रपटः अयम्।\"','adjective'),(35344,'','चलाचल, स्थावरजङ्गम','गतिशीलः तथा स्थिरः।; \"अस्माकं देशस्य अधिकतरः नेतारः नैकेषां रूप्यकाणां चलाचलायाः सम्पत्तेः स्वामिनः सन्ति।\"','adjective'),(35332,'','सेवा','अन्येषां हिताय सुविधायै वा केनचित् मनुष्येण समूहेन वा कृतं कार्यम्।; \"भ्रमणध्वनेः उद्योगसंस्थया स्वग्राहकाणां कृते एका नूतना सेवा आरब्धा।\"','noun'),(35338,'','मन्दता','मन्दस्य अवस्था भावो वा।; \"मन्दतया सर्वे पीडिताः।\"','noun'),(35339,'','प्रतिसरणम्','अर्थशास्त्रानुसारेण हट्टस्य सा स्थितिः यस्यां जनानां क्रयशक्तेः न्यूनतायाः कारणात् वस्तूनां विक्रयणं मन्दायते।; \"प्रतिसरणेन ग्राहकाः विक्रेतारः च प्रभाविताः भवन्ति।\"','noun'),(35340,'',' ',' ; \"\"','noun'),(35341,'','भारतीय-वाणिज्य-तथा-उद्योग-महासङ्घः','भारतदेशेस्य वाणिज्यसङ्घानां संस्था।; \"भारतीय-वाणिज्य-तथा-उद्योग-महासङ्घस्य मुख्यालयः देहल्याम् अस्ति।\"','noun'),(35342,'','रिजर्व-बैङ्क-ऑफ-इण्डिया','भारतस्य केन्द्रीयवित्तकोषः यः रूप्यकाणि तथा च त्रिशत्-अर्बुदं यावत् डालर इति मुद्रायाः आरक्षितायाः निधेः वित्तीयां नीतिं नियन्त्रयति।; \"रिजर्व-बैङ्क-ऑफ-इण्डिया इति वित्तकोषस्य मुख्यालयः मुम्बईनगरे अस्ति।\"','noun'),(35330,'','असवाननगरम्','नाइलनद्याः तटे स्थितम् ईजिप्तदेशस्य एकं प्राचीनं नगरम्।; \"असवाननगरस्य सेतुः प्रसिद्धः अस्ति।\"','noun'),(35331,'','मूकदर्शक','यः प्रतिक्रियां न ददाति।; \"जनता मूकदर्शकानां सैनिकानां विरुद्धं निदर्शनं करोति।\"','adjective'),(35325,'','आयुक्तः','कस्यापि आयोगस्य प्रमुखः।; \"श्यामस्य पिता आरक्षकालये आयुक्तः अस्ति।\"','noun'),(35329,'','अलेक्जेन्ड्रियानगरम्','ईजिप्तदेशस्य द्वितीयक्रमाङ्कस्य बृहत् नगरं यद् देशस्य बृहत् नौकास्थानकम् अस्ति।; \"अलेक्जेन्ड्रियानगरस्य जनसङ्ख्या एकचत्वारिंशत् लक्षं यावत् अस्ति।\"','noun'),(35308,'','पाक्षिक, पाक्षिकपत्रिका','प्रत्येकेषु पञ्चदशेषु दिनेषु यस्याः पत्रिकायाः प्रकाशनं भवति।; \"वयं एकस्य पाक्षिकस्य प्रकाशनम् अपि कुर्मः।\"','noun'),(35310,'','प्रचारमाध्यमम्','वार्तापत्रस्य लेखकानां वृत्तान्तलेखकानां वा समूहः।; \"मन्त्रिमहोदयेन प्रचारमाध्यमे स्वस्य अपराधः स्वीकृतः।\"','noun'),(35311,'','निदेशालय','सः केन्द्रियः कार्यालयः यस्मात् अधीनस्थेभ्यः कार्यकर्तृभ्यः तेषां कार्यसम्बधिनः निदेशः प्रेष्यते।; \"निदेशालये अद्य सभा आसीत्।\"','noun'),(35312,'','सञ्चालक-मण्डलम्','कस्याः अपि संस्थायाः सञ्चलनार्थे निर्वाचितः समूहः।; \"सञ्चालक-मण्डलेन वृत्तिवर्धनस्य उपायाः सूचिताः।\"','noun'),(35313,'','एचडीएफसी-बैङ्क','एकः वित्तकोषः।; \"प्रियङ्का एचडीएफसी-बैङ्क इति वित्तकोषे लेखां प्रारब्धवती।\"','noun'),(35314,'','आईसीआईसीआई-बैङ्क','एकः वित्तकोषः।; \"आईसीआईसीआई-बैङ्क इति वित्तकोषेण ऋणं न दत्तम्।\"','noun'),(35315,'','पञ्जाब-नेशनल-बैङ्क','एकः वित्तकोषः।; \"सः पञ्जाब-नेशनल-बैङ्क इति वित्तकोषे धनं स्थापयितुं गतवान्।\"','noun'),(35316,'','समाजसेवकः, समाजसेवी','यः समाजस्य सेवां करोति।; \"अत्रत्येन समाजसेवकेन पञ्चाशतः युगलानां विवाहः कारितः।\"','noun'),(35317,'','प्रचाररोगः','अश्वानां अक्ष्णः रोगविशेषः यस्मिन् नेत्रस्य परितः मांसस्य वर्धनेन दृष्टिः बाध्यते।; \"प्रचाररोगेण पीडितस्य अश्वस्य शल्यचिकित्सा क्रियते।\"','noun'),(35319,'','दुबईः','संयुक्त-अरब-अमीरातस्य सप्तसु अमीरातेषु एकः यः फारसस्य आखाते दक्षिणभागे अरबप्रायद्वीपे वर्तते।; \"दुबईः संयुक्त-अरब-अमीरातस्य अधिकजनसङ्ख्यायुक्तः देशः।\"','noun'),(35320,'','जनयुद्ध, जनसङ्ग्राम','कस्यापि अनीप्सितस्य मनुष्यस्य स्थितेः कार्यस्य वा समाप्त्यर्थं जनैः मिलित्वा आरब्धम् एकम् अभियानम्।; \"जनयुद्धं पुरतः कस्यापि पक्षस्य सत्ता स्थातुं न शक्नोति।\"','noun'),(35323,'','केन्द्रीय-सतर्कता-आयोगः','भ्रष्टाचारस्य निरोधिकायाः संस्थायाः सूचनया भारतसर्वकारद्वारा स्थापिता संस्था या केन्द्रशासनस्य संस्थानां सतर्कताक्षेत्रे मार्गदर्शनं तथा उपदेशं करोति।; \"केन्द्रीय-सतर्कता-आयोगस्य स्थापना 1964 तमे वर्षे जाता।\"','noun'),(35324,'','केन्द्रीय-सतर्कता-आयुक्तः','केन्द्रीय-सतर्कता-आयोगस्य प्रमुखः।; \"केन्द्रीय-सतर्कता-आयुक्तस्य नियुक्तिः निश्चिता नास्ति।\"','noun'),(35303,'','आवर्तनम्, अभ्यावृत्तिः, आम्नायः, आवृत्तिः','मन्त्रादीनां पुनः पुनः पठनस्य क्रिया।; \"शिवपूजया सह रुद्रमन्त्राणाम् आवर्तनम् अनिवार्यम् अस्ति।\"','noun'),(35304,'','शीतकः','यस्मिन् अविलम्बता न विद्यते।; \"शीतकः सर्वत्र निन्द्यते।\"','noun'),(35305,'','नासिकागण्डः','नासिकायां जातः गण्डः।; \"पुष्पगन्धेन नासिकागण्डः उपशाम्यति।\"','noun'),(35268,'','आधिक्यम्, अधिकता, अतिशयः, अतिरेकः, अतीरेकः, आतिशय्यम्','आवश्यकायाः मात्रायाः अधिकम्।; \"धान्ये आधिक्ये जाते तस्य विदेशविक्रयणं कर्तव्यम्।\"','noun'),(35269,'','अद्यतनीकरणम्','कस्यापि वस्तुनः अद्यतनीयायां स्थितिं यावत् समीचिनीकरणम्।; \"लेखायाः अद्यतनीकरणाय सः वित्तकोषं गतवान्।\"','noun'),(35301,'','प्रशस्त','येन सम्मानः वर्धते।; \"सचिनस्य शतकस्य कारणात् सङ्घेन प्रशस्ताः अङ्काः प्राप्ताः।\"','adjective'),(35295,'','सहमतिपत्रम्','यस्मिन् पत्रे ऐकमत्यस्य विषये लिखितम् अस्ति तथा जनानां हस्ताक्षराणि भवन्ति।; \"सहमतिपत्रस्य प्रतिलिपीः प्रत्येकस्मै ददातु।\"','noun'),(35294,'','तारामण्डलम्, नक्षत्रमण्डलम्','तारकाणां समूहः।; \"अन्तरीक्षे नैकानि तारामण्डलानि सन्ति।\"','noun'),(35258,'','प्रजातीय','प्रजातिसम्बन्धी।; \"आर्थिकेन तथा च प्रजातीयेन संदर्भेण सूदानदेशे यवनानां तथा च ख्रिस्तानां प्रदीर्घः संघर्षः प्रचलति।\"','adjective'),(35291,'','व्याख्याता, प्राध्यापकः','महाविद्यालये पाठ्यमानानां शिक्षकाणाम् एकं विशिष्टं पदम्।; \"रामस्य पिता एकस्मिन् विश्वविद्यालये व्याखाता अस्ति।\"','noun'),(35290,'','मुख्यधारा','कस्यापि महत्वपूर्णः तथा च मुख्यः पक्षः यस्मिन् गतिमानता वर्तते।; \"अधुना बहवः जनाः समाजस्य मुख्यधारायाः दूरीभूताः।\"','noun'),(35284,'','नागासाकीनगरम्','जापानदेशे वर्तमानम् एकं नगरम् यस्य अर्थः दीर्घः द्वीपकल्पः इति अस्ति तथा च यत्र द्वितीये विश्वयुद्धस्य समये अमेरिकादेशेन परमाणु-प्रस्फोटः पातितः।; \"नागासाकीनगरे 1945तमे ख्रिस्ताब्दे अगस्तमासस्य नवमे दिनाङ्के परमाणु-प्रस्फोटः पातितः येन पञ्चाशत्सहस्त्रजनाः मृताः।\"','noun'),(35281,'','मध्यः, केन्द्रम्','कस्यापि वस्तुनः तत् स्थानं यस्मात् तस्य प्रान्तः समाने अन्तरे भवति।; \"प्रकोष्ठस्य मध्ये मन्दिरम् अस्ति।\"','noun'),(35283,'','हिरोशिमानगरम्','जापानदेशे वर्तमानम् एकं नगरं यत्र द्वितीये विश्वयुद्धे अमेरिकादेशेन परमाणु-प्रस्फोटः पातितः।; \"हिरोशिमानगरे परमाणु-प्रस्फोटेन अनुमानतः एकलक्षपञ्चशत्सहस्त्रजनाः मृताः।\"','noun'),(35276,'','वरानन','सुन्दरमुखयुक्तः।; \"वराननः राजा एव राजकन्यया वररूपेण वृतः।\"','adjective'),(35278,'','कुत्रचित्','अनिर्धारितं स्थानम्।; \"इदं पुस्तकं कुत्रचित् स्थापयतु।\"','noun'),(35275,'','वरानना, सुमुखी','सुन्दरमुखयुक्ता स्त्री।; \"राज्ञा स्वस्य वराननायाः पुत्र्याः स्वयंवरे नैके राजानः आमन्त्रिताः।\"','adjective'),(35274,'','वराननः, सुमुखः','सुन्दरं मुखम्।; \"राजा शान्तनुः सत्यवत्याः वरानने मोहितः जातः।\"','noun'),(35272,'','आयकरविभागः','आयकरस्य स्वीकृतिः यस्य विभागस्य कार्यम् अस्ति।; \"आयकरविभागेन अस्मिन् वर्षे गतवर्षस्य अपेक्षया द्विगुणितः करः स्वीकृतः।\"','noun'),(35271,'','नियन्त्रक-तथा-महालेखापरीक्षकः','सः शासकीयः अधिकारी यः संवैधानिक कार्याणि साधयति तथा सर्वकारस्य व्ययस्य निरीक्षणं करोति।; \"नियन्त्रक-तथा-महालेखापरीक्षकेण सर्वेषां राज्यानां आयव्ययस्य विवरणं याचितम्।\"','noun'),(35259,'','प्रसारमाध्यमम्','जनतायै वार्तां प्रेषयितुं प्रयुक्तं साधनम्।; \"दूरदर्शनम् आकाशवाणी इत्यादीनि प्रसारमाध्यमानि सन्ति।\"','noun'),(35262,'','उन्नततम','सर्वेषु उन्नतः।; \"हिमालयस्य उन्नततमं शिखरं नित्यं हिमाच्छादितम् अस्ति।\"','adjective'),(35264,'','व्यक्तिगतवृत्तम्','एकं वृत्तं यस्मिन् कस्यापि पुरुषस्य नाम, तस्य शिक्षणं कार्यञ्च तथा च तस्य अनुभवादीनां विस्तारपूर्वकं वर्णनं भवति।; \"व्यक्तिगतवृत्तं दृष्ट्वा विनियोक्ता पञ्चाशतम् जनान् साक्षात्कारार्थम् आहूतवान्।\"','noun'),(35251,'','दुर्दशाग्रस्तता','दुर्दशाग्रस्तस्य अवस्था।; \"दुर्दशाग्रस्ततायाः सम्पन्नतायां परिवर्तनम् अस्माकं कर्तव्यम्।\"','noun'),(35254,'','शङ्घाईनगरम्','चीनदेशस्य बृहद् नगरम्।; \"बालकाः ग्रीष्मकालस्य अवकाशे शङ्घाईनगरं गतवन्तः।\"','noun'),(35256,'','अन्तरराष्ट्रीयश्रमसङ्घटनम्','संयुक्तराष्ट्रस्य विशिष्टा संस्था या समाजस्य न्यायस्य तथा मानवस्य तथा श्रमस्य अधिकारान् प्रोत्साहयति।; \"अन्तरराष्ट्रीयश्रमसङ्घटनेन धनिकराष्ट्रेभ्यः आवहनं कृतं यद् ते वित्तीयानां संस्थानां रक्षणेन सह अनुद्योगिताम् अवरोद्धुं प्रयतताम् इति।\"','noun'),(35257,'','वस्त्रफलकम्, ललामम्, वैजयन्ती','एकं दीर्घं वस्त्रं कर्गजं वा यस्मिन् किमपि चिह्नम् अलङ्करणं सन्देशः वा लिखितः भवति।; \"वस्त्रफलकस्य निर्माणं प्राचीना कला वर्तते।\"','noun'),(35250,'','श्रेष्ठ','पदमर्यादादीनां दृष्ट्या यः आदितः अन्येषाम् अपेक्षया वा उत्तमायां स्थितौ अस्ति।; \"अत्र श्रेष्ठानां जातीनां प्राधान्याम् अस्ति।\"','adjective'),(35249,'','जनाधारः','जनानां समर्थनस्य आधारः।; \"उत्तरप्रदेशराज्ये काङ्ग्रेसपक्षस्य जनाधारः वर्धमानः अस्ति।\"','noun'),(35238,'','पुनर्स्थापित','पुनः स्थापितम्।; \"शासनः भूकम्पप्रभावितानि यन्त्राणि पुनर्स्थापितानि करिष्यति।\"','adjective'),(35246,'','भ्रान्तिनाशः','भ्रान्तेः मुक्तिः।; \"भ्रान्तिनाशस्य अनुभवः सुखदायकः अस्ति।\"','noun'),(35232,'','उच्चपदस्थ','उच्चपदे वर्तमानः।; \"रामस्य पिता सेनायाम् उच्चपदस्थः अधिकारी अस्ति।\"','adjective'),(35236,'','कुटीरवासी, कौटीर्या','यः कुट्यां निवसति।; \"किं कुटीरवासिभ्यः उत्तमानि गृहाणि दीयते।\"','noun'),(35237,'','राजकर्मकरः','शासकीयासु संस्थादिषु यः कार्यं करोति।; \"मम पिता राजकर्मकरः अस्ति।\"','noun'),(35231,'','क्वेटानगरम्','बलूचिस्तानदेशस्य राजधानी।; \"रहीमः क्वेटानगरे निवसति।\"','noun'),(35230,'','हृदयाघातः, हृद्ग्रहः','सा अवस्था यस्यां हृदयः स्वकार्यं स्थगयति।; \"मानसिकी आततिः हृदयाघातस्य कारणम् अस्ति।\"','noun'),(35228,'','शिष्टमण्डलः','केषाञ्चित् जनानाम् सः दलः यः विशेषकार्यार्थे अभ्यागमं करोति।; \"भारते आगते पाकिस्थानदेशस्य शिष्टमण्डले दशाधिकाः सदस्याः सन्ति।\"','noun'),(35212,'','आधारफलकम्, मुख्यफलकम्','सङ्गणकस्य एकः महत्वपूर्णः भागः।; \"अस्माकं सङ्गणकस्य आधारफलकम् अदुष्यत्।\"','noun'),(35218,'','कर्णभाषः','एकम् उपकरणं यद् विद्युत्सङ्केतान् ध्वनिषु परिवर्तयति तथा च यद् कर्णे स्थापयित्वा श्रूयते।; \"सः सङ्गणकस्य पुरतः उपविश्य कर्णभाषेण गीतं श्रुणोति।\"','noun'),(35220,'','वेतन-आयोगः','एकः शासकीयः आयोगः यः कर्मकराणां वेतनं निर्धारयति तथा तस्य निरीक्षणं करोति।; \"कदाचित् सर्वकारः वेतन-आयोगस्य सूचनाः शीघ्रमेव स्वीकरोति।\"','noun'),(35222,'','निवृत्तिः, सेवानिवृत्तिः','कस्याश्चित् क्रीडायाः अथवा कस्माच्चित् विशिष्टात् कार्यात् सर्वकालं यावत् अप्रवृत्तिः।; \"विश्वचषकप्रतियोगितायाः अनन्तरं प्रायः सचिनः क्रिकेट इति क्रीडायाः निवृत्तिं स्वीकरिष्यति।\"','noun'),(35225,'','ग्रैण्डस्लेम्','टेनिस इति क्रीडायाः एका प्रसिद्धा प्रतियोगिता।; \"ग्रैण्डस्लेम् इति प्रतियोगितायाः सेरेना नैकधा जेत्री अस्ति।\"','noun'),(35226,'','विरोधीस्वापकविभागः','यः विभागः मादकद्रव्याणां सेवने प्रतिबन्धं करोति।; \"मादकद्रव्यानां कृते विरोधीस्वापकविभागेन नैकेषु स्थानेषु आपातः कृतः।\"','noun'),(35209,'','केपटाउननगरम्','दक्षिण-आफ्रिकादेशस्य वैधानिका राजधानी।; \"जनसङ्ख्यायाः अनुसारेण केपटाउननगरं दक्षिण-आफ्रिकादेशस्य द्वितीयक्रमाङ्कस्य बृहद् नगरम्।\"','noun'),(35211,'','लासवेगसनगरम्','अमेरिकादेशे वर्तमानं नगरम्।; \"मनोजस्य अनुजः लासवेगसनगरे निवसति।\"','noun'),(35229,'','परिवेष्टः','वस्तु वस्तूनि वा यानि एकस्यां पेटिकायां कर्गजे वा संस्थाप्य पत्रमुद्रया कस्मैचित् प्रेष्यते।; \"पित्रा प्रेषितः परिवेष्टः अहम् अद्य प्राप्तवती।\"','noun'),(35227,'','यन्त्रशतघ्नी','एका स्वयंचालिता शतघ्नी।; \"सैनिकानां हस्ते यन्त्रशतघ्नी आसीत्।\"','noun'),(35206,'','उत्साहजनक, उत्साहवर्धक','यद् उत्साहम् उत्पादयति।; \"एतेषां प्रयोगाणाम् उत्साहजनकाः परिणामाः वयं प्राप्तवन्तः।\"','adjective'),(35207,'','योजना-आयोगः','यः आयोगः भविष्यत्काले क्रियमाणानां कार्याणां तथा विकासस्य योजनानां विषये कार्यं करोति।; \"योजना-आयोगस्य अध्यक्षेण सभायां योजनाः स्थापिताः।\"','noun'),(35193,'','कार्यक्रमः','विनोदनार्थं क्रियमाणं कार्यम्।; \"दूरदर्शने नैके कार्यक्रमाः प्रदर्श्यन्ते।\"','noun'),(35196,'','निश्चित','यस्य सत्यतायां सन्देहः नास्ति।; \"तेन निश्चिता वार्ता श्राविता।\"','adjective'),(35205,'','विषविधिः','यः विधिः कीटाणुः इव स्वस्य प्रतिकृतीः विधातुं शक्नोति तथा अन्यान् विधीन् प्रविश्य अपकरोति।; \"मानवस्य सहायतायाः अभावात् सङ्गणके विषविधिः प्रसारितुं न शक्नोति।\"','noun'),(35191,'','तन्त्रः, शैली','किञ्चित् विशिष्टं कार्यं कर्तुं उपयुज्यमाना प्रयोगात्मिका पद्धतिः।; \"रोगाणाम् उपचारार्थं प्रतिदिनं नूतनाः तन्त्राः उपयुज्यन्ते।\"','noun'),(35189,'','बहुजन-समाज-पक्षः','भारतदेशे वर्तमानः एकः राजनैतिकः दलः।; \"इदानीम् उत्तरप्रदेशराज्ये बहुजन-समाज-पक्षस्य शासनम् अस्ति।\"','noun'),(35187,'','कर्मण्यता','कर्मण्यस्य अवस्था गुणः भावः वा।; \"लक्ष्यं प्राप्तुं कर्मण्यता आवश्यकी।\"','noun'),(35184,'','आज्ञापालनम्, कर्तव्यपालनम्','आज्ञायां प्राप्तायां कठिनस्य अपि कार्यस्य योग्यरीत्या सम्पादनम्।; \"आज्ञापालनम् अस्माकं धर्मः अस्ति।\"','noun'),(35185,'','कर्मण्य','यद् धर्मानुसारी अस्ति।; \"कर्मण्यानां कर्मणाम् आचरणेन शुभफलं प्राप्यते।\"','adjective'),(35186,'','कर्मण्य','कर्मणा सम्बद्धः।; \"ते कर्मण्येषु विषयेषु वार्तालापं कुर्वन्ति।\"','adjective'),(35180,'','परदेशः','स्वस्य ग्रामप्रान्तनगरादीन् विहाय अन्यत् स्थानम्।; \"मम पिता परदेशं गतवान्।\"','noun'),(35181,'','नागपुरीय','नागपूरेण सम्बद्धः।; \"नागपूरीयाः पिच्छिलाः प्रसिद्धाः सन्ति।\"','adjective'),(35182,'','तन्त्रशुद्ध','यद् तन्त्रदृष्ट्या शुद्धं कृतम्।; \"ऊर्जानिर्माणाय तन्त्रशुद्धा पद्धतिः अवलम्बनीया।\"','adjective'),(35183,'','लोकायुक्तः','शासकीयः अधिकारी।; \"अत्रत्यस्य लोकायुक्तस्य स्थानान्तरणम् अभवत्।\"','noun'),(35173,'','अल्पपरिचयः','परस्पराभ्यां विशेषस्य परिचयस्य अभावः।; \"तेन सह मम अल्पपरिचयः अस्ति।\"','noun'),(35175,'','कोकणविभागः, कोङ्कणः','महाराष्ट्रराज्यस्य सह्याद्रिपर्वतस्य प्रतीच्यां दिशि वर्तमानः प्रदेशः।; \"कोकणविभागे विशेषतः नारिकेलः पूगफलम् आम्रफलञ्च उत्पद्यते।\"','noun'),(35168,'','प्रायोजित','(कार्यक्रमः परियोजना वा)केनचित् पुरुषेण समूहेन वा धनं दत्वा प्रवर्त्यते।; \"प्रायोजितानाम् प्रहर्तॄणां विरुद्धं गृहमन्त्रिणा झटिति कार्यवहनम् आरब्धम्।\"','adjective'),(35169,'','आत्मसम्मानः','आत्मनः सम्मानम्।; \"अस्माभिः आत्मसम्मानः रक्षणीयः।\"','noun'),(35171,'','पादुकाबन्धिनी','पादत्राणं पादे सम्यक्तया स्थातुं तेषां बन्धनार्थं उपयुक्ता बन्धिनी।; \"पादुकाबन्धिन्याः उद्घाटनेन पादुकाबन्धिनी पादे संश्लिष्यति।\"','noun'),(35172,'','सीसम्, सीसकम्, नागम्','अङ्कन्यां वर्तमानम् एकं वस्तु येन लिख्यते।; \"सीसं निर्मातुं मृत्तिकां कौकिलेयं च मिलित्वा चूर्णीकृत्य जले निमज्यते।\"','noun'),(35155,'','जालम्','तादृशी निर्मिता व्यवस्था परिस्थितिः वा यस्याम् अवरोधनात् अनन्तरं मुक्तिः न भवति।; \"आरक्षकाः घातकान् बद्धुं जालं योजयन्ति।\"','noun'),(35159,'','कपिला','एकेन एव वर्णेन युक्ता गौः।; \"तस्य समीपे कृष्णवर्णीया कपिला अस्ति।\"','noun'),(35164,'','केन्द्रम्, कण्टकम्','जन्मपत्रिकायां ग्रहाणां लग्नात् चतुर्थसप्तमदशमस्थानानि।; \"केन्द्रं शुभफलदायी अस्ति इति दैवज्ञः कथयति।\"','noun'),(35149,'','पाकिस्तानपीपल्सपक्षः','पाकिस्तानदेशस्य राजनैतिकः पक्षः।; \"पाकिस्तानपीपल्सपक्षेण अद्य लाहोरनगरे कर्मन्यासः क्रियते।\"','noun'),(35165,'','एकल','यः अन्यस्य साहाय्येन विना स्वयमेव कार्यं करोति।; \"सः एकः एकलस्य निगमस्य कर्मकरः अस्ति।\"','adjective'),(35153,'','दमः','महाभारतकालीनः एकः महर्षिः।; \"दमस्य उल्लेखः महाभारते प्राप्यते।\"','noun'),(35154,'','दमः','पुराणानुसारेण राजामरुतः पौत्रः यः वभ्रस्य कन्यायाः इन्द्रसेनायाः गर्भात् उत्पन्नः।; \"दमः वेदवेदाङ्गानाम् उत्तमः ज्ञाता तथा धनुर्विद्यायाम् अपि प्रवीणः आसीत्।\"','noun'),(35142,'','परीक्षकः','यः परीक्ष्यते।; \"परीक्षकः उत्तरपत्रिकां परीक्ष्यते।\"','noun'),(35144,'','पासाडेनिया','अमेरिकादेशे वर्तमानम् एकं नगरम्।; \"मम एकं मित्रं पासाडेनियानगरे निवसति।\"','noun'),(35146,'','टेक्सासराज्यम्','अमेरिकादेशस्य दक्षिणदिशि वर्तमानम् एकं राज्यम्।; \"रहीमः टेक्सासराज्ये निवसति।\"','noun'),(35140,'','लोकलेखासमितिः','लोकसभायाः स्थायिनी समितिः।; \"लोकसभायाः समितिषु लोकलेखासमितेः विशिष्टं स्थानम् अस्ति।\"','noun'),(35141,'','संयुक्तसंसदीयसमितिः','विशिष्टा महत्वपूर्णा वा समितिः।; \"संयुक्तसंसदीयसमितेः कार्यक्षेत्रं विस्तृतम् अस्ति।\"','noun'),(35136,'','नियन्त्रकः तथा महालेखा-परीक्षकः','अधिकारिविशेषः।; \"रमेशस्य पिता नियन्त्रकः तथा महालेखा-परीक्षकः अस्ति।\"','noun'),(35137,'','महालेखा-परीक्षकः','महालेखायाः परीक्षकः।; \"रजन्याः ज्येष्ठः भ्राता महालेखा-परीक्षकः अस्ति।\"','noun'),(35138,'','महाधिवेशनम्, महासम्मेलनम्','बृहत् अधिवेशनम्।; \"कांग्रेस इति पक्षस्य महाधिवेशने महान्तः नेतारः भागं ग्रहिष्यति।\"','noun'),(35132,'','गुर्जरजातीयः','गुर्जरजातेः सदस्यः।; \"गुर्जरजातीयाः वीराः सन्ति।\"','noun'),(35135,'','हवामहलम्','एकं दर्शनीयं भवनम्।; \"हवामहलं जयपूरनगरे अस्ति।\"','noun'),(35131,'','गुर्जरजातिः','एका जातिः।; \"गुर्जरजातिः अधिकतया भारतदेशे एवं पाकिस्थानदेशे अस्ति।\"','noun'),(35127,'','परिस्थितिजन्य','परिस्थित्या उत्पन्नः।; \"आदिमानवस्य विषये किञ्चित् परिस्थितिजन्यं प्रमाणं प्राप्तम्।\"','adjective'),(35056,'','श्रेष्ठत्वम्','क्रीडाप्रतिष्ठादिषु विशिष्टा उच्चस्थितिः।; \"प्रतियोगितायां क्रीडकानां श्रेष्ठत्वम् अपाक्रियते।\"','noun'),(35059,'','नीतिः','किमपि कार्यं कर्तुम् उपयोजिता विशिष्टा पद्धतिः।; \"स्वस्य योजनायाः सफलतायै सः नीतिं कल्पते।\"','noun'),(35060,'','संस्थितिः','किमपि कार्यं कर्तुं विशिष्टा अवस्था गतिः वा।; \"इदानीं क्रिकेटक्रीडायाः क्रीडाङ्गणे सचिनस्य संस्थितिः उत्तमा वर्तते।\"','noun'),(35061,'','यातायातावरोधः','कस्मिञ्चित् विशिष्टे समये विशिष्टे मार्गे जनानाम् अग्रे गमनस्य असाध्यत्वात् उत्पन्ना स्थितिः।; \"महानगरेषु यातायातावरोधः इदानीम् एका सामान्या समस्या वर्तते।\"','noun'),(35062,'','बलूचिस्तानप्रान्तः','क्षेत्रदृष्ट्या पाकिस्तानदेशस्य बृहत् प्रान्तः।; \"पाकिस्तानदेशस्य चतुश्चत्वारिंशत् प्रतिशतं भागः बलूचिस्तानप्रान्तस्य अस्ति।\"','noun'),(35069,'','सङ्घर्षपूर्ण','सङ्घर्षेण युक्तम्।; \"तेन सङ्घर्षपूर्णं जीवनं यापितम्।\"','adjective'),(35070,'','प्रबल, महत्','यः अन्यस्य अपेक्षया प्रबलः अस्ति।; \"विपक्षिणः प्रबलम् उत्तरं श्रुत्वा सः शान्तम् अभवत्।\"','adjective'),(35078,'','सर्वदलीय','सर्वेः दलैः सामूहिकरूपेण यद् क्रियते।; \"वित्तमन्त्रिणा सर्वदलीया सभा आयोजिता।\"','adjective'),(35079,'','सर्वदलीय','सर्वैः दलैः सम्बद्धः।; \"सर्वदलीयः निर्णयः स्वीकृतः भवेत्।\"','adjective'),(35081,'','सम्पर्कः','समूहे परस्परेषु समन्वयस्य माध्यमम्।; \"आरक्षकाः अपराधिनां सम्पर्कस्य अन्वेषणं करोति।\"','noun'),(35085,'','श्रमविभागः','श्रमेण सम्बद्धः शासकीयः विभागः।; \"श्रमविभागेन सर्वेषां कार्यप्रदानस्य घोषणा कृता।\"','noun'),(35088,'','प्रबलता, गाढता, भृशता','प्रसारितस्याः ऊर्जायाः मात्रा।; \"ह्यस्तनीयस्य भूकम्पस्य प्रबलता 5.9 इति आसीत्।\"','noun'),(35089,'','सामन्तरागः','सङ्गीते कर्नाटकपद्धत्या वर्तमानः एकः रागः।; \"गायकः सामन्तरागस्य वैशिष्ट्यानि कथयति।\"','noun'),(35093,'','स्फूर्जनम्, विदारणम्, विस्फोटः, स्फोटनम्','कस्माच्चित् वस्तुनः तस्य कः अपि भागः सशक्त्या पृथग्भवनम्।; \"एकस्य धूमकेतोः पृथिव्याः वायुमण्डले स्फूर्जनस्य आशङ्का अस्ति।\"','noun'),(35094,'','साधना, आराधना','परिश्रमपूर्वकं श्रद्धया च क्रियमाणा क्रिया उपासना वा यया किमपि विशिष्टं फलं प्राप्यते।; \"तान्त्रिकः द्वयोः वर्षयोः तन्त्रं प्राप्तुं साधनां कुर्वन् अस्ति।\"','noun'),(35096,'','सङ्गणकक्रीडा','सङ्गणके क्रीड्यमाना क्रीडा।; \"बालकाः सङ्गणकक्रीडां क्रीडन्ति।\"','noun'),(35101,'','क्रीडा','एकं सक्रीयं विनोदनं यस्य कृते शारीरिकस्य श्रमस्य प्रतिस्पर्धिनः च आवश्यकता भवति।; \"सः नैकासु क्रीडासु भागं गृह्णाति।\"','noun'),(35104,'','क्वींसलैण्डराज्यम्','आस्ट्रेलियादेशे वर्तमानम् एकं राज्यम्।; \"मनोहरः क्वींसलैण्डराज्ये निवसति।\"','noun'),(35105,'','आपातप्रबन्धनविभागः','सः विभागः यः आपत्काले परिस्थितेः नियन्त्रणं करोति।; \"महेशः आपातप्रबन्धनविभागे कार्यं करोति।\"','noun'),(35109,'','लेखापरीक्षा','लेखायाः परीक्षणम्।; \"सर्वकारेण काभ्यश्चित् उद्योगसंस्थाभ्यः लेखापरीक्षायाः याचनं कृतम्।\"','noun'),(35111,'','अशक्तता','गुणयोग्यतातीव्रतादिषु न्यूनस्य अवस्था।; \"युरोपीयेभ्यः आपणेभ्यः प्राप्तेभ्यः अशक्ततायाः वार्तया भारतीयम् आपणम् अपि मन्दायते।\"','noun'),(35122,'','आशियाचषकः','आशियाखण्डस्य स्तरे आयोजिता क्रिकेटक्रीडायाः प्रतियोगिता यस्याम् आशियाखण्डे वर्तमानाः केचन देशाः भागम् आवहन्ति।; \"अस्मिन् वर्षे आशियाचषकं भारतदेशः एव जेष्यति।\"','noun'),(35124,'','स्वास्थ्यम्','उत्तमा शारीरिकी अवस्था।; \"नैके भारतीयाः क्रीडकाः स्वास्थ्यस्य समस्यया ग्रस्ताः सन्ति।\"','noun'),(35052,'','सेनाध्यक्षः','सेनायाम् एकः अधिकारी।; \"रामस्य पिता सेनाध्यक्षः अस्ति।\"','noun'),(35053,'','सेनाधिकारी, सैन्याधिकारी','सेनायाम् उच्चपदे नियुक्तः अधिकारी।; \"प्रधानमन्त्री अद्य काश्मिरे कैश्चित् सैन्याधिकारीभिः अमिलत्।\"','noun'),(35050,'','हिंसाग्रस्त','यद् हिंसया प्रभावितम्।; \"मन्त्रिमहोदयः हिंसाग्रस्तं प्रदेशम् अभिगच्छति।\"','adjective'),(35051,'','नवनियुक्त','यः अधुना एव नियुक्तः।; \"नवनियुक्तानां कर्मकराणां प्रशिक्षणविषये अस्माकं संस्था चिन्तयति।\"','adjective'),(35048,'','वितरणकेन्द्रम्','यस्मात् केन्द्रात् स्थानात् वा किमपि वितीर्यते।; \"कृषकाणां कृते कृषिसम्बन्धिनां वस्तूनां वितरणकेन्द्रस्य आवश्यकता अस्ति।\"','noun'),(35043,'','क्रिकेटनियन्त्रकपरिषद्','क्रिकेटक्रीडासम्बद्धा परिषद्।; \"क्रिकेटक्रीडायां भागम् आवहन्तः प्रत्येकस्य देशस्य क्रिकेटनियन्त्रकपरिषद् अस्ति।\"','noun'),(35046,'','भारतीय-अन्तरिक्ष-अनुसन्धान-केन्द्रम्','भारतसर्वकारस्य संस्था या अन्तरिक्षेण सम्बद्धम् अनुसन्धानं करोति तथा तस्मिन् सहाय्यं करोति।; \"भारतीय-अन्तरिक्ष-अनुसन्धान-केन्द्रेण नैकेषाम् उपग्रहाणां निर्मितिः कृता।\"','noun'),(35006,'','पुण्यनगरीयः, पुण्यनगरीया','पुण्यपत्तनस्य मूलनिवासी।; \"पुण्यनगरीयाः चतुराः सन्ति।\"','noun'),(35008,'','पादत्राणम्, उपानह्','पादयोः सुरक्षार्थं पादयोः धार्यमाणः चर्मादीनां वस्तुविशेषः।; \"कृपया पादत्राणं बहिः स्थापयतु।\"','noun'),(35016,'','तरणकर्ता','तरणस्पर्धायां भागं ग्रहीतुं यः प्रशिक्षितः।; \"तरणकर्ता प्रतिदिनं घण्टाद्वयम् अभ्यासं करोति।\"','noun'),(35017,'','अधिकोषणम्, अधिकोष-व्यापारः, कुसीदवृत्तिः','वित्तकोषस्य कार्यम्।; \"नैके धनिकाः इदानीम् अधिकोषणं कुर्वन्ति।\"','adjective'),(35019,'','पक्षः','कस्यापि विषयस्य समर्थनस्य स्थितिः।; \"एतत् कार्यकरणस्य पक्षे अहं नास्मि।\"','noun'),(35020,'','विवरणपत्रिका','यस्मिन् पत्रे कस्यापि विषयस्य सम्पूर्णं विवरणं लिखितम् अस्ति।; \"भवान् पूर्वं वित्तकोषस्य विवरणपत्रिकां पठतु।\"','noun'),(35025,'','प्रबन्धनिदेशकः','कस्यापि संस्थायाः सः अधिकारी यः संस्थायाः कार्यादिषु निरीक्षणं करोति तेषां प्रति उत्तरदायी च अस्ति।; \"रामस्य पिता बृहत्याम् उद्योगसंस्थायां प्रबन्धनिदेशकः अस्ति।\"','noun'),(35040,'','निर्माणाधीन','यस्य निर्मितिः प्रचलति।; \"अस्मिन् शासकीयस्य निर्माणाधीनस्य भवने केचन जनाः स्वामित्वं कथयन्ति।\"','adjective'),(35037,'','आधुनिकीकरणम्','आधुनिकपद्धत्या आचरणम्।; \"विदेशिनाम् अनुकरणेन वयं नैकेषां वस्तूनां पद्धतीनां वा आधुनिकीकरणं कुर्मः।\"','noun'),(35035,'','संशोधित','यस्मिन् संशोधनं जातम्।; \"अस्मिन् पुस्तके अस्माकं संस्थया संशोधितानां नियमानाम् उल्लेखः अस्ति।\"','adjective'),(35032,'','टाटामोटर्स','टाटासमूहस्य एका बृहद् उद्योगसंस्था।; \"टाटामोटर्स इति उद्योगसंस्था वाहनान् निर्माति।\"','noun'),(35031,'','बान्धव्यम्, कौटुम्बम्','एकस्मिन् एव कुले उत्पन्नेन स्थापितः सम्बन्धः।; \"पितापुत्रयोः बान्धव्यं भवति।\"','noun'),(35027,'','नीतिः, नायः','केनचित् मनुष्येण कयाचित् संस्थया वा कस्यापि हिताय निर्मिता विशिष्टा योजना।; \"अस्माकम् उद्योगसंस्था नूतनाः नीतीः आरप्स्यते।\"','noun'),(35026,'','मुख्य-कार्यकारी-अधिकारी','कस्यापि संस्थायाः सर्वोच्चः अधिकारी यः संस्थायाः कार्याणां निरीक्षणं करोति तेषां प्रति उत्तरदायी च अस्ति।; \"मम मित्रं बृहत्याम् उद्योगसंस्थायां मुख्य-कार्यकारी-अधिकारी अस्ति।\"','noun'),(34967,'','घनः','तद् वस्तु यस्य दैर्घ्यं पृथुता उच्चता च समानं भवति।; \"घनस्य षट् भुजाः सन्ति।\"','noun'),(34968,'','घनः','सजातीयाङ्कत्रयस्य पूरणम्।; \"द्वयोः घनः अष्टौ अस्ति।\"','noun'),(34969,'','घनः','कस्या अपि सङ्ख्यायाः तृतीयः घातः।; \"पञ्च इति सङ्ख्यायाः घनात् द्वि इति सङ्ख्यायाः घनः न्यूनीक्रियताम्।\"','noun'),(34970,'','घनवाद्यम्','एकं तालवाद्यम्।; \"रतनः घनवाद्यं वादयति।\"','noun'),(34971,'','मेलबर्ननगरम्','आस्ट्रेलियादेशस्य विक्टोरिकाराज्यस्य राजधानीनगरं यत् आस्ट्रेलियादेशस्य द्वितीयक्रमाङ्कस्य बृहत् नगरम् अस्ति।; \"मुम्बईनगरम् इव मेलबर्ननगरम् अपि आस्ट्रेलियादेशस्य वित्तीयं व्यापारिकं च केन्द्रम् अस्ति।\"','noun'),(34976,'','गोवत्सः','गोः वत्सः।; \"गौः गोवत्सं लेढि।\"','noun'),(34977,'','कनिष्ठा, कनिष्ठ-गौरी','भाद्रपदशुक्लपक्षे ज्येष्ठनक्षत्रे पूज्यमाना देवी।; \"ज्येष्ठगौर्या सह कनिष्ठा अपि पूज्यते।\"','noun'),(34983,'','प्राणदण्डः','वधसदृशस्य गम्भीरस्य अपराधस्य कृते दीयमानः मृत्योः दण्डः।; \"उच्चन्यायालयेन अपराधिनां प्राणदण्डः अपरिवर्तितः।\"','noun'),(35002,'','पुरश्चरणम्','इष्टदेवतामन्त्रसिद्ध्यर्थं कृतं जपानुष्ठानम्।; \"समर्थरामदासेन द्वादशवर्षं गायत्रीमन्त्रस्य पुरश्चरणं कृतम्।\"','noun'),(35001,'','पूर्वभागः','कस्यापि धारावाहिकस्य सन्दर्भार्थं दर्शितः श्रावितः वा पूर्वः भागः।; \"धारावाहिकस्य प्रत्येकस्मिन् भागरम्भे पूर्वभागः प्रदर्श्यते।\"','noun'),(34995,'','उदरसर्वस्व','यः केवलम् उदरार्थे कार्यं करोति।; \"इदानीम् उदरसर्वस्वानां जनानां सङ्ख्या वर्धते।\"','adjective'),(34998,'','उदरवेदना, जठरव्यथा','उदरस्य वेदना।; \"सः उदरवेदनया त्रस्तः अस्ति।\"','noun'),(34999,'','पुरुषार्थः','भारतीयदर्शनशास्त्रानुसारेण पुरुषस्य प्रयोजनानि तेषु एकः।; \"धर्मार्थकाममोक्षाश्च पुरुषार्थाः सन्ति।\"','noun'),(34993,'','वीरगाथा','वीरतायाः प्रशंसागीतम्।; \"सः शिवाजीमहाराजस्य वीरगाथाम् अगायत्।\"','noun'),(34994,'','ग्रन्थकः','धार्मिकस्य विषयस्य लघ्वी पुस्तिका।; \"पितामहः प्रतिदिनं गुरुचरित्रस्य ग्रन्थकं पठति।\"','noun'),(34992,'','प्रजातन्त्रीय, लोकतन्त्रीय','जनैः निर्वाचितैः प्रतिनिधिभिः क्रियमाणस्य शासनपद्धतेः।; \"भारतदेशे प्रजातन्त्रीयः शासनकालः अस्ति।\"','adjective'),(34987,'','परिसीमा, पारावारः','आनन्दस्य दुःखस्य वा सीमा।; \"अस्याः वार्तायाः श्रवणेन तस्य आनन्दस्य परिसीमा एव नास्ति।\"','noun'),(34988,'','पश्यन्ती','मूलाधारोत्थिता हृदयगता नादस्य द्वितीया अवस्था।; \"पश्यन्ती गहना वाणी अस्ति।\"','noun'),(34990,'','ऊर्ध्वगामिन्','यद् ऊर्ध्वदिशं गच्छति।; \"अग्नेः ज्वालाः ऊर्ध्वगामिन्यः सन्ति।\"','adjective'),(34991,'','नामलेखनी','पात्रे नामनिर्देशनार्थे प्रयुक्तं सौल्विकस्य उपकरणम्।; \"सौल्विकः नामलेखन्या पात्रे मम नाम लिखति।\"','noun'),(34965,'','निश्चेतनम्','संवेदनायाः पूर्णा ईषद् वा नाशनस्य क्रिया।; \"निश्चेतनस्य क्रियायां विशिष्टम् औषधं जिघ्रापयित्वा अथवा सूच्यौषधं दत्वा शरीरं संवेदनाशून्यं क्रियते।\"','noun'),(34966,'','न्यू-साउथ-वेल्सराज्यम्','आस्ट्रेलियादेशस्य आग्नेये दिशि वर्तमानं राज्यम्।; \"मम एकं मित्रं न्यू-साउथ-वेल्सराज्ये निवसति।\"','noun'),(34963,'','रक्तबन्धिनी','शासनस्य कार्यालये वर्तमानानां पत्राणां रक्तवर्णीया बन्धिनी।; \"लिपिकः रक्तबन्धिन्यां बन्धितानि पत्राणि उद्घाटयति।\"','noun'),(34964,'','दीर्घसूत्रता','लाक्षणिकरूपेण तथा च व्यङ्ग्यात्मकरूपेण शासनकार्यस्य सम्पादने निर्णये वा जायमानः विलम्बः।; \"दीर्घसूत्रता देशस्य विकासे अवरोधिका भवति।\"','noun'),(34960,'','वायुप्रदूषणम्','वायौ जायमानं प्रदूषणम्।; \"अत्यधिकेन ध्वनिना अपि वायुप्रदूषणं भवति।\"','noun'),(34956,'','स्ववृत्तिः','स्वस्य वृत्तिः।; \"शासनेन कार्यहीनतां समापयितुं जनान् स्ववृत्तेः उपायः सूचितव्यः।\"','noun'),(34949,'','पावकवृत्तिः, दहनदुर्गम्','यन्त्रांशस्य तन्त्रांशस्य च एकं सुरक्षात्मकः भागः।; \"स्थानीयस्य क्षेत्रस्य जालेषु पावकवृत्तिः प्रयुज्यते।\"','noun'),(34946,'','आन्तर्जाल-सेवा-प्रदाता','यः आन्तर्जालस्य सेवां यच्छति।; \"मोहनः आन्तर्जाल-सेवा-प्रदातुः उद्योगे कार्यरतः अस्ति।\"','adjective'),(34945,'','आन्तर्जाल-सेवा-प्रदाता','सः पुरुषः संस्था वा यः आन्तर्जालस्य सेवां यच्छति।; \"अधुना हटे आन्तर्जाल-सेवा-प्रदातॄणां सङ्ख्या वर्धिता।\"','noun'),(34943,'','मुद्रकम्, मुद्रणयन्त्रम्','येन उपकरणेन सङ्गणकात् इष्टविषयं यथानुरूपं कर्गजे मुद्रयितुं शक्यते।; \"अनेन मुद्रकेण भवान् रञ्जितां प्रतिकृतिम् अपि स्वीकर्तुं शक्नोति।\"','noun'),(34934,'','आत्मतापत्रम्, परिचयपत्रम्','तद् पत्रं यस्मिन् कस्यापि आलेखेन सह तस्य परिचयः लिखितं भवति।; \"भवान् पूर्वम् आत्मतापत्रं सिद्धं करोतु।\"','noun'),(34932,'','होनोलूलूनगरम्','हवाईराज्यस्य राजधानी।; \"सः अटनार्थं होनोलूलूनगरम् अगच्छत्।\"','noun'),(34927,'','प्रमाणम्','कार्यविधेः निर्धारणार्थं मार्गदर्शिका योजना।; \"वित्तकोषस्य अधिकारिणा नूतनानि प्रमाणानि प्रेषितानि।\"','noun'),(34923,'','पृष्ठभूमिः','चित्रार्थे निर्मितं तलम्।; \"चित्रकारः नीलवर्णीयायां पृष्ठभूमौ चित्रम् आरेखति।\"','noun'),(34922,'','पृष्ठभूमिः','तत् तलं यस्मिन् मुद्रादयः मुद्रिताः।; \"पाटले पृष्ठभूमौ हरितः वर्णः शोभते।\"','noun'),(34919,'','उपत्यका, अधोभूमिः','अन्यस्मात् भूमेः अपेक्षया अधोदिशं स्थिता भूमिः।; \"अस्य ग्रामस्य केचन जनाः पर्वते निवसन्ति केचन उपत्यकायां निवसन्ति।\"','noun'),(34914,'','धूमपानम्','सुश्रुतानुसारेण विशिष्टानां भेषजानां धूमस्य नलिकया पीडितेन कृतं सेवनम्।; \"पीडितः धूमपानेन लाभम् अन्वभवत्।\"','noun'),(34912,'','धूमपानम्','मत्ततायै तमाखोः प्रज्वलनेन वारंवारं तस्य धूमस्य चोषणस्य निष्कासनस्य च क्रिया।; \"धूमपानम् आरोग्यार्थं हानिकारकम् अस्ति।\"','noun'),(34906,'','चित्रम्, आलेख्यम्','दूरदर्शनप्रसारणे यद् दृश्यते।; \"दूरदर्शनसञ्चात् केवलं ध्वनिः श्रूयते चित्रं न दृश्यते।\"','noun'),(34910,'','ध्वनिमुद्रणम्','ध्वनिचित्रादीनां मुद्रणस्य क्रिया।; \"गायकः ध्वनिमुद्रणं कर्तुं सिद्धः नास्ति।\"','noun'),(34903,'','योजनाबद्ध','यस्य योजना पूर्वमेव कृता।; \"श्रमेण अर्जितस्य धनस्य योजनाबद्धं रक्षणं कर्तव्यम्।\"','adjective'),(34902,'','योजनानुसारिन्','योजनाम् अनुसृत्य।; \"योजनानुसारी कार्यक्रमः सम्पन्नः।\"','adjective'),(34896,'','प्रापणम्','नष्टस्य धनस्य पुनर्प्राप्तेः क्रिया।; \"नष्टानां लक्षाधिकानां रूप्यकाणाम् अलङ्काराणां प्रापणस्य वार्ता आरक्षकेभ्यः प्राप्ता।\"','noun'),(34895,'','आततियुक्त','आतत्या युक्तः।; \"इदानींतने आततियुक्ते जीवने हसनम् आवश्यकम्।\"','adjective'),(34890,'','घटनाचक्रम्','क्रमेण जायमानानां घटनानां चक्रम्।; \"जनाः प्रकृतेः घटनाचक्रे परिवर्तनस्य प्रयासं कुर्वन्ति।\"','noun'),(34886,'','उपशमः','उत्तरदायित्वादीनां समापनेन अनुभूयमाना शान्तिः।; \"विवाहानन्तरं तेन उपशमः अनुभूतः।\"','noun'),(34882,'','भेण्टम्','चण्डिकादेव्याः स्तवनविशेषः।; \"भेण्टं पञ्जाबराज्ये गीयते।\"','noun'),(34885,'','समाजसेवा','समाजस्य सेवा।; \"समाजसेवां कुर्वतेषु जनेषु मम श्रद्धा वर्तते।\"','noun'),(34880,'','अर्जुनपुरस्कारः','राष्ट्रीय-क्रीडा-प्रतियोगितासु उत्तमयशः सम्पादकाय क्रीडकाय  भारतसर्वकारेण प्रदीयमानः पुरस्कारः यद् 1961 तमे वर्षात् आरब्धः।; \"अर्जुनपुरस्कारस्य जेत्रे पञ्चलक्षरूप्यकाणि कांस्यस्य लघुप्रतिमा तथा च प्रमाणपत्रं दीयते।\"','noun'),(34873,'','वित्तकोषकर्मकरः','वित्तकोषस्य कर्मकरः।; \"एकः वित्तकोषकर्मकरः अपप्रदानग्रहणसमये गृहीतः।\"','noun'),(34876,'','जनकल्याणविभागः','जनानां हितार्थे कार्यरता एका संस्था।; \"जनकल्याणविभागेन किन्नराणां स्थितिः अपि अवध्यातव्या।\"','noun'),(34872,'','बान्धवगढम्','भारतदेशस्य मध्यप्रदेशे वर्तमानं स्थानम्।; \"बान्धवगढे एकं प्रमुखम् उद्यानम् अस्ति।\"','noun'),(34871,'','वनविभागः','वनानां रक्षणार्थे कार्यरतः विभागः।; \"मोहनः वनविभागे कार्यं करोति।\"','noun'),(34795,'','भूगर्भीय','भूगर्भेण सम्बद्धः।; \"भूगर्भीयायाः क्रियायुक्ततायाः एव परिणामः भूकम्पः।\"','adjective'),(34796,'','निवासी, अधिवासी','कस्मिन्नपि स्थाने उष्यमाणः जीवः।; \"वनस्य नाशनेन तत्रस्थानां निवासिनां सङ्ख्या क्षीयते।\"','noun'),(34799,'','असुरक्षित','यत् न रक्षितम्।; \"असुरक्षिते वने अन्धःकारे न अटनीयम्।\"','adjective'),(34802,'','साङ्गणिकापराधः','सङ्गणकस्य तथा आन्तर्जालस्य च उपयोगेन कृतं चौर्यं तथा अनिष्टेन विधिना कस्यचित् कार्यम् इतस्ततः करणस्य अपराधः।; \"साङ्गणिकापराधेन लिप्तः मनुष्यः गृहीतः।\"','noun'),(34815,'','पुनःप्रदर्शनम्','पुनः कृतं प्रदर्शनम्।; \"निर्णायकः नैकवारं पुनःप्रदर्शनं दृष्ट्वा निर्णयति।\"','noun'),(34819,'','रक्षा','वनस्पत्यादीन् दग्ध्वा प्राप्तं भस्म।; \"कर्दलीपत्रस्य रक्षा मधुनि मिलित्वा अदनात् कासः उपशमति।\"','noun'),(34827,'','सर्बियागणराज्यम्','मध्यभागे तथा च आग्नेयदिक्वर्ती युरोपखण्डीयः देशः यः पूर्वं युगोस्लावियादेशे आसीत्।; \"2008तमे वर्षे सर्बियादेशः स्वतन्त्रः जातः।\"','noun'),(34828,'','अग्रयोधी','कस्मिन्नपि क्षेत्रे येन अनन्यसामान्यं प्रदर्शनं कृतम्।; \"क्रिकेटक्रीडायाः अग्रयोधिनं सचिनं सर्वे प्रशंसन्ति।\"','noun'),(34839,'','शुल्कम्','वस्तुनः आयातेन विदेशविक्रयणेन वा सर्वकारेण स्वीक्रियमाणं धनम्।; \"आयातस्य शुल्कं न्यूनकरणस्य विषये सर्वकारः चिन्तयति।\"','noun'),(34840,'','विदेशविक्रयणमूल्यम्','विदेशविक्रयणे दीयमानं मूल्यम्।; \"शासनः विदेशविक्रयणमूल्यस्य वर्धनविषये चिन्तयति।\"','noun'),(34842,'','चालकदलः','कस्यापि वाहनस्य चालकानां दलः।; \"विमानस्य चालकदलः आतङ्कवादिभिः स्वाधिकारे कृतः।\"','noun'),(34753,'','हाङ्गकाङ्गनगरम्','चीनदेशस्य ख्यातं नगरम्।; \"हाङ्गकाङ्गनगरं विश्वस्य प्रसिद्धं पण्यं केन्द्रम् अस्ति।\"','noun'),(34754,'','सूचकाङ्कः','कस्यापि कार्यादेः सूचकः अङ्कः।; \"वृतान्तानुसारेण वैश्विकसमृद्धेः सूचकाङ्के भारतः अष्टाशीतिः स्थाने गतः।\"','noun'),(34867,'','परमाण्विक','परमाणुसम्बन्धी।; \"परमाण्विकानां शस्त्राणां प्रयोगात् रक्षितव्यम्।\"','adjective'),(34870,'','अलास्काराज्यम्','क्षेत्रफलदृष्ट्या संयुक्त-राज्य-अमेरिकादेशस्य बृहत् नगरम्।; \"अलास्काराज्यं पूर्वं रशियादेशे आसीत्।\"','noun'),(34866,'','सिडनीनगरम्','आस्ट्रेलियादेशस्य बृहत् नगरम्।; \"प्रमुखेषु दर्शनीयेषु नगरेषु सिडनीनगरम् एकम्।\"','noun'),(34864,'','परीक्षणस्थलम्','तत् स्थानं यत्र कस्यापि वस्तुनः परीक्षणं क्रियते।; \"क्षेपणास्त्राणि परीक्षणस्थले नीयन्ते।\"','noun'),(34859,'','विहारसदस्यः','कस्यापि विहारस्य सदस्यः।; \"अद्य सायङ्काले विहारसदस्यानां सङ्गोष्ठिः अस्ति।\"','noun'),(34860,'','रावलपिण्डीनगरम्','पाकिस्तानदेशे वर्तमानं नगरम्।; \"रहीमः रावलपिण्डीनगरे निवसति।\"','noun'),(34858,'','आसनम्','विशिष्टस्य उपयोगस्य कृते निश्चितं स्थानम्।; \"अस्मिन् विश्वविद्यालये विद्यावाचस्पति इति पदवीप्रवेशाय न्यूनानि आसनानि सन्ति।\"','noun'),(34856,'','संलिप्तता','केषुचित् कार्यादिषु लिप्तस्य अवस्था भावः क्रिया वा।; \"हीने कर्मणि संलिप्तता अयोग्या।\"','noun'),(34855,'','पञ्जाब_तथा_सिन्धवित्तकोषः ','वित्तकोषविशेषः। ; \"तस्य लेखा पञ्जाब तथा सिन्धवित्तकोषे अस्ति।\"','noun'),(34852,'','दीर्घोत्पीठिका, लेखनपीठः ','एकः पीठविशेषः यस्य दीर्घता पृथुतायाः अपेक्षया अधिकं भवति। ; \"सः पुस्तकानि निष्कास्य दीर्घोत्पीठिकायां स्थापयति।\" SYNSET',''),(34851,'','दूरवेधिनीगृहम्','दूरवेधिनीनां समूहः।; \"दूरवेधिनीगृहस्य अभ्यासः क्रियते।\"','noun'),(34850,'','अग्न्यस्त्रागारम्','दूरवेधिन्यः स्थापनस्य स्थानम्।; \"केचन अधिकारिणः अग्न्यस्त्रागारे दूरवेधिन्यः निरीक्षणं कुर्वन्ति।\"','noun'),(34849,'','निगमीय','निगमसम्बन्धी।; \"निगमीयेन कुलेन तस्य सम्बन्धः वर्तते।\"','adjective'),(34848,'','डेलावेयरनदी','अमेरिकादेशे वहन्ती नदी।; \"डेलावेयरनदी पेन्सिलवेनियाराज्यात् स्रवति।\"','noun'),(34846,'','चित्रपटनिर्माता','यः चित्रपटं निर्माति।; \"मोहनः एकः कुशलः चित्रपटनिर्माता भवितुम् इच्छति।\"','noun'),(34847,'','फिलाडेल्फियानगरम्','अमेरिकादेशे वर्तमानं बृहत् नगरम्।; \"फिलाडेल्फियानगरं डेलावेयरनद्याः तटे स्थितम् अस्ति।\"','noun'),(34783,'','दीक्षान्त','दीक्षायाः अन्ते जायमानः।; \"विश्वविद्यालयस्य निदेशकस्य दीक्षान्तस्य भाषणस्य अनन्तरं छात्रेभ्यः उपाधिप्रमाणपत्रादयः दत्ताः।\"','adjective'),(34779,'','सङ्केतः','सा विद्युदुर्जा यस्याः बलाघातपरिवर्तनं यस्मात् परिवर्तते तस्य विषये अधिकं ज्ञानं यच्छति।; \"उपग्रहात् स्पष्टः सङ्केतः प्राप्तः।\"','noun'),(34773,'','वृत्तिः, भावः, संस्थितिः','कार्ये प्रवर्तयितुं कार्यात् दूरीकर्तुं वा मनसि वर्तमाना स्थितिः।; \"चीनदेशस्य वृत्तिम् अनुसृत्य एव भारतदेशेन आचरणं कृतम्।\"','noun'),(34772,'','विश्ववित्तकोषः','संयुक्तराष्ट्रसङ्घस्य सा विशिष्टा संस्था यस्याः मुख्यः उद्देशः सदस्यराष्ट्राणां पुनर्निर्माणे तथा विकासार्थं आर्थिसहायताप्रदानम् अस्ति।; \"विश्ववित्तकोषस्य मुख्यालयः वाशिङ्गटननगरे वर्तते।\"','noun'),(34770,'','भारतीय-रिजर्व-बैङ्कः','केन्द्रियः वित्तकोषः यः अन्यान् वित्तकोषान् सञ्चालयति देशस्य अर्थव्यवस्थां नियन्त्रयति च।; \"भारतीय-रिजर्व-बैङ्कस्य स्थापना एप्रिलमासस्य प्रथमे दिनाङ्के 1935तमे वर्षे जाता।\"','noun'),(34771,'','वित्तकोषः, धनागारः','या संस्था वृद्धौ आधारितस्य धनस्य आदानं प्रदानञ्च करोति।; \"अध्ययनार्थम् अपि वित्तकोषात् ऋणं प्राप्यते।\"','noun'),(34755,'','पुनर्मूल्याङ्कनम्','पुनः मुल्याङ्कनम्।; \"परीक्षार्थिनः उत्तरपत्रिकाणां पुनर्मूल्याकनम् इच्छन्ति।\"','noun'),(34756,'','शिखरसम्मेलनम्','तद् सम्मेलनं यस्मिन् नैकेषां देशानां प्रतिनिधयः भागं गृह्णन्ति।; \"जी-20 इति शिखरसम्मेलनं चीनदेशस्य राष्ट्रपतिः अपि गच्छति।\"','noun'),(34769,'','वित्तीयवर्षम्','कस्यापि देशस्य वित्तव्यवस्थायै निश्चितः द्वादशमासस्य समयः।; \"भारतीयानां वित्तीयवर्षम् एप्रिलमासस्य प्रथमदिनाङ्कात् आरभ्य मार्चमासस्य एकत्रिंशद्दिनाङ्कं यावत् भवति।\"','noun'),(34743,'','राज्यसभासदस्यः','राज्यसभायाः सदस्यः।; \"अमेरिकादेशीयः राज्यसभासदस्यः भारतदेशम् अभ्यागच्छति।\"','noun'),(34744,'','मध्यावधि','यः अवधेः प्राक् वर्तते।; \"अस्माकं प्रदेशे मध्यावधि निर्वाचनम् अस्ति।\"','adjective'),(34745,'','वर्जीनियाराज्यम्','संयुक्त-राज्य-अमेरिकादेशस्य एकं राज्यम्।; \"अस्माकं मित्रं वर्जीनियाराज्ये निवसति।\"','noun'),(34746,'','मध्यमवर्गः','उच्चनिम्नयोः मध्यस्तरीयः वर्गः।; \"वस्तूनां मूल्यवर्धनेन निम्नवर्गेण सह मध्यमवर्गः अपि त्रस्तः अस्ति।\"','noun'),(34740,'','निषेधोक्तिः, विरुद्धवचनम्, निदर्शनम्, विरोधः','असम्मतेः प्रदर्शनम्।; \"निषेधोक्तिं स्थगयित्वा किमपि भावात्मकं कार्यं करोतु।\"','noun'),(34741,'','उन्नततम','सर्वेषु उन्नतः।; \"पर्वतारोही उन्नततमं शिखरं गन्तुं प्रयतते।\"','adjective'),(34686,'','टाइटनः','शनिग्रहस्य बृहत् उपग्रहः।; \"टाइटनः बुधग्रहात् अपि बृहत् वर्तते।\"','noun'),(34689,'','ड्रेगनः','ट्यूनानी इति पौराणिकया कथानुसारेण जीवविशेषः यः श्वासोच्छ्वासद्वारा अग्निः क्षिपति तथा च तस्य शरीरं सर्पसदृशम् अस्ति।; \"केचन ड्रेगनाः पक्षवन्तः सन्ति।\"','noun'),(34690,'','विश्लेषक','यः विश्लेषणं करोति।; \"प्रत्येकस्य क्षेत्रस्य विश्लेषकाः भवन्ति।\"','noun'),(34691,'','वैश्लेषिक','यः विश्लेषणं करोति।; \"वैश्लेषिकस्य वैज्ञानिकस्य मतानुसारेण पृथिव्याः तापमानं वर्धेत एव।\"','adjective'),(34693,'','सम्बोधित','यस्य ध्यानम् आकृष्टम्।; \"सम्बोधिताः छात्राः आरेखं पश्यन्ति।\"','adjective'),(34694,'','सम्बोधित, आभाषित','यस्य बोधनं कृतम्।; \"सम्बोधितः विषयः कठिनः आसीत्।\"','adjective'),(34703,'','राजता, स्वाधिपत्यम्, स्वाराज्यम्, प्रभुत्वम्','राज्ञः इव अवस्था गुणः भावः वा।; \"कः अपि स्वस्य राजतां नाशयितुं न इच्छति।\"','noun'),(34713,'','सुखदायक, सुखभोगवत्','सुखदायी सर्वाभिः सुविधाभिः युक्तश्च।; \"तेन सुखदायकं कारयानं क्रीतम्।\"','adjective'),(34721,'','गगनयात्रिकः','यः अन्तरीक्षं गच्छति।; \"यूरीगागारिनमहोदयः प्रथमः गगनयात्रिकः आसीत्।\"','noun'),(34722,'','बैरलपरिमाणम्','द्रवपदार्थस्य मापनाय उपयुक्तं परिमाणम्।; \"169लीटरपरिमाणेन बैरलपरिमाणं भवति।\"','noun'),(34727,'','वजीरिस्तानराज्यम्','पाकिस्तानदेशे वर्तमानं राज्यम्।; \"अद्य वजीरिस्तानराज्ये विस्फोटाः जाताः।\"','noun'),(34728,'','स्वातमण्डलम्','पाकिस्तानदेशे वर्तमानं मण्डलम्।; \"स्वातमण्डले अद्य कतिचन आतङ्कवादिनः गृहीताः।\"','noun'),(34736,'','युद्धाभ्यासः','युद्धस्य अभ्यासः।; \"भारतीया सेना युद्धाभ्यासं करोति।\"','noun'),(34738,'','सदस्यीय','सदस्येन सम्बद्धः।; \"पञ्च सदस्यीयः विदेशिनां जनानां दलः अस्माकं ग्रामे अभ्यागच्छत्।\"','adjective'),(34682,'','संस्था','एकः उद्योगः यः अन्येषाम् उद्योगार्थं कार्यरतः अस्ति।; \"वार्तायाः संस्था दूरदर्शनस्य तथा च वार्तापत्राणां कृते वार्तां प्रेषयति।\"','noun'),(34683,'','विश्लेषणम्','कस्यापि विषयस्य तादृशं निरीक्षणं येन तस्य मूलरूपस्य ज्ञानं भवेत्।; \"वैज्ञानिकाः अन्तरिक्षयानात् प्राप्तस्य सामग्र्याः विश्लेषणं कुर्वन्ति।\"','noun'),(34678,'','ऑक्सफर्डविश्वविद्यालयः, ऑक्सफोर्ड विश्वविद्यालयः','इङ्ग्लण्डदेशस्य आक्सफर्डनगरे स्थितः एकः विश्वविद्यालयः।; \"अत्र्यत्याः केचन प्राध्यापकाः ऑक्सफर्डविश्वविद्यालये पठितवन्तः।\"','noun'),(34679,'','हारवर्डविश्वविद्यालयः, हॉरवर्डविश्वविद्यालयः','अमेरिकादेशस्य मैसचूसिटराज्ये वर्तमानः एकः विश्वविद्यालयः।; \"सः हारवर्डविश्वविद्यालयात् स्नातकः जातः।\"','noun'),(34681,'','वार्तासंस्था','सा संस्था या वार्तापत्राणां कृते वार्तानां सङ्कलनं करोति तथा ताः विद्युत्तन्त्रेण वितरति।; \"एषा वार्ता राष्ट्रियया वार्तासंस्थया प्राप्ता।\"','noun'),(34676,'','उत्पन्न','यत् पूर्वं नासीत् इदानीम् एव सञ्जातम्।; \"एषः अस्वच्छतया उत्पन्नः व्याधिः।\"','adjective'),(34677,'','ऑक्सफोर्डनगरम्, आक्स्फर्डनगरम्','इङ्ग्लण्डदेशस्य लन्दननगरस्य वायव्यां दिशि वर्तमानं नगरम्।; \"ऑक्सफोर्डनगरस्य विश्वविद्यालयः प्रसिद्धः अस्ति।\"','noun'),(34671,'','मुक्त, विमुक्त, निर्मुक्त','कस्मात् अपि बन्धनात् रहितः।; \"कारागृहात् मुक्तः बन्दिः कुटुम्बेन मिलित्वा अतीव आनन्दितः।\"','adjective'),(34672,'','जीवन्मुक्त','जीवन् एव मायाबन्धरहितः।; \"जीवन्मुक्तः पुरुषः कदापि न शोचति।\"','adjective'),(34673,'','मुक्त','यस्मात् रोगादयः दूरीकृताः।; \"पोलिओ इति व्याधेः मुक्तस्य जगतः महदाकाङ्क्षा अचिराद् एव सत्यं भविष्यति।\"','adjective'),(34675,'','रोधक्षमता','शरीरे वर्तमाना सा क्षमता यया कस्याः अपि व्याधेः शरीरस्य संरक्षणं भवति।; \"अधिकया रोधक्षमतया युक्ताः जनाः वारंवारं रोगेन पीडिताः न भवन्ति।\"','noun'),(34669,'','आपातः','अनपेक्षिततया कस्यापि घटनायाः क्षणादेव उपस्थापनम्।; \"आपातात् रक्षणस्य कः अपि उपायः नास्ति।\"','noun'),(34670,'','मर्यादारहित','यः मर्यादायाः पालनं करोति।; \"मर्यादारहिताय पुरुषाय लज्जा कुतः।\"','adjective'),(34651,'','देशव्यापिन्','सम्पूर्णं देशं यः व्याप्नोति।; \"भ्रष्टाचारः देशव्यापिनी समस्या अस्ति।\"','adjective'),(34652,'','माओवादः','माओजेदाङ्गद्वारा चीनदेशे विकसितः साम्यवादप्रकारः।; \"माओवादः 1950-60 मध्ये प्रवर्तितः।\"','noun'),(34653,'',' ',' ; \"\"','noun'),(34657,'','विभागः, भागः, शाखा','सुविधायै कार्यस्य कृतं विभाजनम्।; \"रमन्नामहोदयः गणितस्य विभागे कार्यरतः अस्ति।\"','noun'),(34658,'','गेन्दनम्','कन्दुकस्य क्षेपणस्य क्रिया।; \"तस्य गेन्दनं कः अपि प्रतिकर्तुं न शक्नोति।\"','noun'),(34659,'','प्रतिनिधिमण्डलम्','प्रतिनिधीनां मण्डलम्।; \"अमेरिकादेशात् आगतेन प्रतिनिधिमण्डलेन सह राष्ट्रपतिः श्वः मेलिष्यति।\"','noun'),(34668,'','अग्निशामकदलः','अग्निशामककर्मकराणां दलम्।; \"अग्निशामकदलः अन्ततः अग्निं शमयितुं सफलीभूतः।\"','noun'),(34650,'','उपप्रधानमन्त्री','कस्यापि देशस्य सः मन्त्री येन प्रधानमन्त्रिणः अनुपस्थितौ मन्त्रिमण्डलस्य सभायाः सभापतित्वम् ऊह्यते तथा प्रधानमन्त्रिणे रुग्णे सति अथवा तस्य मृत्यौ जाते तस्य धुरं वहति।; \"वर्तमाने शासने उपप्रधानमन्त्री नास्ति।\"','noun'),(34647,'','पोपगानम्','युवकेषु प्रियः नूतनः गानप्रकारः।; \"सकीरा पोपगानं गायति।\"','adjective'),(34648,'','पेन्टागानसंस्थानम्','अमेरिकादेशस्य सुरक्षाविभागस्य मुख्यालयः।; \"पेन्टागानसंस्थानस्य पञ्चकोणीयं भवनम् अस्ति।\"','noun'),(34649,'','पेन्टागानसंस्थानम्','अमेरिकादेशस्य सैन्यसंस्थानम्।; \"पेन्टागानसंस्थानस्य प्रवक्तुः इदं वक्तव्यम्।\"','noun'),(34644,'','कैलिफोर्नियाराज्यम्','प्रशान्तमहासागरस्य तटे स्थितम् अमेरिकादेशस्य राज्यम्।; \"कैलिफोर्नियाराज्यम् अमेरिकादेशस्य दर्शनीयं राज्यम् अस्ति।\"','noun'),(34645,'','पोपसङ्गीतम्','सः सङ्गीतप्रकारः यः प्रायः युवकानाम् आकर्षणम् अस्ति।; \"पोपसङ्गीतस्य लये सर्वे नृत्यन्ति।\"','noun'),(34646,'','पोपगायकः','यः पोपगानं गायति।; \"माइकलजैक्सनवर्यः महान् पोपगायकः आसीत्।\"','noun'),(34625,'','कोष्ठः','सुरक्षार्थं निर्मितम् अस्थायिस्थानं यत्र सैनिकादयः निवसन्ति।; \"आतङ्कवादीनां रणगोलप्रक्षेपेण कोष्ठः नष्टः।\"','noun'),(34631,'','स्विसवित्तकोषः','एकः आन्तरराष्ट्रियः वित्तकोषः।; \"स्विसवित्तकोषे नैकेषां भारतीयानां धनम् अस्ति।\"','noun'),(34632,'','विश्वचषकः','विश्वस्तरे जायमाना क्रीडास्पर्धा या विशिष्टेन समयेन भवति।; \"आगामी विश्वचषकं भारतदेशः एव जेष्यति।\"','noun'),(34636,'','चिरपरिचित','येन सह बहुभ्यः दिनेभ्यः परिचयः अस्ति।; \"मम गृहे अद्य एकः चिरपरिचितः अतिथिः आगमिष्यति।\"','adjective'),(34638,'','तन्त्री','विद्युच्छक्तेः प्रसारणं कुर्वाणः परिचालकः।; \"तन्त्री कार्यं न करोति।\"','noun'),(34639,'','शकलम्','सिलिकॉनधातोः लघुतमपत्रकस्य उपरि मुद्रितः अयं लघुतमः वैद्युतकपरिपथः विपुलपरिमाणेन निर्मितः भवति।; \"एकस्मिन् सङ्गणके नैकानि शकलानि भवन्ति।\"','noun'),(34641,'','वेणीरः','केशान् प्रक्षालयितुं प्रयुक्तं फेनकम्।; \"आपणे नैकप्रकारकाः वेणीराः उपलब्धाः।\"','noun'),(34643,'','हननम्','नाशनस्य क्रिया।; \"कस्यापि व्यक्तिस्वातन्त्रस्य हननं न करणीयम्।\"','noun'),(34585,'','अवारोपणम्, अवाहरणम्, अवचयनम्','अन्यस्मात् सङ्गणकात् दत्तांशम् आहत्य स्वसङ्गणके स्थापनम्।; \"इदानींतने काले दूरदर्शने अपि अवारोपणस्य सुविधा वर्तते।\"','noun'),(34586,'','गवेषकम्','पर्यङ्कभाषायाः लेखं द्रष्टुं निर्मितः विधिः।; \"जालगवेषकम् उत्तमं गवेषकम् अस्ति।\"','noun'),(34554,'','अस्थिरता','अस्थिरस्य भावः।; \"आतङ्कवादीनां कारणात् कश्मीरे अस्थिरता वर्तते।\"','noun'),(34555,'','कर्म, भूमिका','विशिष्टायां परिस्थितौ कस्यापि मनुष्यस्य कार्यम्।; \"कस्यापि विवाहे मातापित्रोः कर्म महत्वपूर्णं भवति।\"','noun'),(34557,'','लाभार्थी','यः लाभम् इच्छति।; \"क्रेता लाभार्थी भवति।\"','noun'),(34559,'','आनमित, आनामित','यद् अवनम्यते।; \"वृक्षस्य आनमितायां शाखायां बालकाः आन्दोलनं कुर्वन्ति।\"','adjective'),(34563,'','उद्वेलित','यत् पात्रस्य हिन्दोलनात् बहिः आगतः।; \"बालिकया उद्वेलितं दुग्धं माता प्रक्षालयति।\"','adjective'),(34564,'','उद्वेलित','यद् उद्गच्छति।; \"घटात् उद्वेलितेन जलेन सीमा आर्द्रा जाता।\"','adjective'),(34568,'','मुद्रित, कृतमुद्र, मुद्राङ्कित, मुद्राबद्ध','यद् वस्तु संवार्य तस्मिन् मुद्राङ्कनं कृतम्।; \"भवतः नाम्ना कार्यालयात् मुद्रितम् आवेष्टनं प्राप्तम्।\"','adjective'),(34571,'','विश्वासमतम्','कस्मिन्नपि विश्वासप्रदर्शनार्थं तस्य पक्षे विपक्षे वा दत्तं मतम्।; \"मन्त्री विश्वासमतं अजयत्।\"','noun'),(34579,'','गूगलम्','विश्वव्यापिजाले अधिकतया उपयुज्यमानम् अन्वेषणयन्त्रं यद् उपयोक्तुः कस्यचित् विषयस्य अन्वेषणे सहाय्यं करोति।; \"गूगलम् अस्माकं सहाय्यं करोति।\"','noun'),(34621,'','भाण्डारः','तत् स्थानं यत्र अधिकमात्रायां वर्तमानानि वस्तूनि स्थाप्यन्ते।; \"अस्माभिः खनिजानां भाण्डारः रक्षितव्यः।\"','noun'),(34618,'','नवोढा, नवविवाहिता, वधूः, नववरिका','इदानीमेव यस्याः विवाहः जातः।; \"नवोढायाः हत्यायाः कारणं कन्याधनम् इति कथ्यते।\"','noun'),(34616,'','उद्भूत, उदित, सञ्जात, निष्पन्न, जनित, जात, प्रवृत्त','यद् उत्पद्यते।; \"देशे उद्भूताम् आततिं न्यूनीकर्तुं सर्वैः प्रयतितव्यम्।\"','adjective'),(34615,'','घटनाक्रमः, घटनाचक्रम्','घटनानां क्रमः।; \"एकस्मिन् घटनाक्रमे चत्वारः अपराधिनः अन्वेषणीयाः।\"','noun'),(34614,'','बहुदलीय','बहुभिः दलैः सम्बद्धः।; \"अस्माकं प्रदेशे बहुदलीयं शासनम् अस्ति।\"','adjective'),(34612,'','मानवाधिकारः','विधितः सः अधिकारः यः सर्वेषां मानवानां कृते भवति यस्मिन् सर्वकारः अपि हस्तक्षेपं न करोति।; \"विचाराणां स्वातन्त्र्यम् अपि मानवाधिकारेषु एकः अस्ति।\"','noun'),(34610,'','नोबलशान्तिपुरस्कारः','सः नोबालपुरस्कारः यः शांततायै विशेषस्य योगदानस्य कृते दीयते।; \"अमेरिकादेशस्य राष्ट्रपतिः बराक-ओबामावर्यः नोबलशान्तिपुरस्कारं प्राप्तवान्।\"','noun'),(34609,'','भूखण्डः, भूसम्पत्तिः','गृहादीन् निर्मातुं भूमेः भागः।; \"पञ्जाबराज्ये तस्य भूखण्डः अस्ति।\"','noun'),(34608,'','विवेकाधीन','यद् नियमानुसारं नास्ति अपि तु कस्यचित् विशिष्टस्य आधिकारिकस्य विवेकानुसारम् अस्ति अस्ति।; \"कार्यालयात् ह्यः विवेकाधीनस्य अवकाशस्य सूचना प्राप्ता।\"','adjective'),(34598,'','वार्ताकारः','यः वृतान्तं वर्णयति।; \"श्याममोहनः वरिष्ठः वार्ताकारः अस्ति।\"','noun'),(34601,'','प्रत्यर्पणम्','कस्यचित् वस्तुनः स्वामिने एव दानम्।; \"पाकिस्तानदेशः कसाबस्य प्रत्यर्पणम् इच्छति।\"','noun'),(34594,'','निरोधक, निरोधिन् उपरोधक, उपरोधिन् प्रतिबन्धक','यः निरोधयति।; \"आतङ्कवादस्य निरोधकं दलं निर्मातुं सर्वकारः चिन्तयति।\"','adjective'),(34592,'','वर्गः','समानानां वस्तूनां समूहः यः कार्यादिषु उपयुक्तं भवति।; \"मया शब्दकोशस्य वर्गः क्रीतः।\"','noun'),(34591,'','दत्तांशसञ्चिका, सञ्चिका','लिखितस्य विषयस्य विद्युत्पत्रस्य वा एकत्रितः समूहः।; \"अनवधानेन सङ्गणकस्य दत्तांशसञ्चिका निष्कासिता।\"','noun'),(34589,'','पाठ्यसञ्चिका','सङ्गणकस्य सा सञ्चिका यस्यां मुद्रणयोग्यानि अक्षराणि सङ्ख्याः सङ्केताश्च अन्तर्भवन्ति।; \"सः पाठ्यसञ्चिकाम् अवारोपयति।\"','noun'),(34587,'','विश्वव्यापिजालम्','नैकेषां जालस्थलानां समूहेन निर्मितं सङ्गणकजालं यद् परिसंविदः माध्यमेन शब्दं चित्रमुद्रणञ्च तथा चित्रचालनं प्रस्तौति।; \"प्रत्येकक्षेत्रसम्बन्धि ज्ञानं विश्वव्यापिजाले सहजतया प्राप्यते।\"','noun'),(34580,'','अन्वेषणविधिः, अन्वेषणयन्त्रम्, गवेषकम्','सः विधिः येन मुख्यपदानाम् अन्वेषणद्वारा सूच्यांशं गवेषयितुं शक्यते।; \"अन्तर्जाले नैके अन्वेषणविधयः भवन्ति।\"','noun'),(34582,'','गवेषणम्','कमपि विशिष्टं विषयम् अनुद्दिश्य विश्वव्यापिजाले सूच्यांशस्य अन्वेषणम्।; \"अन्तर्जाले गवेषणेन ज्ञानं वर्धते।\"','noun'),(34545,'','दीपस्तम्भः','दीपयुक्तः स्तम्भः।; \"मार्गस्य एकस्मिन् भागे स्थितस्य द्वीपस्तम्भस्य अधः तौ वार्तालापं कुरुतः।\"','noun'),(34549,'','दृढ','स्वस्थानात् अन्यत्र कुत्रापि चलने असमर्थस्य अवस्था।; \"कीलकम् अत्यन्तं दृढं स्थितम् अस्ति।\"','adjective'),(34550,'','कठोर','दृढतया सतर्कतया च अवलोकितम्।; \"कठोरात् परीक्षणात् अनन्तरम् एव एषः परिणामः प्राप्तः।\"','adjective'),(34534,'','वास्तविकता, वास्तवम्, सत्यता','सत्यस्य अवस्था भावः वा।; \"वास्तविकता अस्ति यद् सः त्वां प्रीणाति।\"','noun'),(34539,'','पुनर्निरीक्षणम्','पुनः निरीक्षणम्।; \"मतदातॄणां सूचीनां पुनर्निरीक्षणस्य कार्यं प्रचलति।\"','noun'),(34540,'','आपत्तिः, आपद्, विप्लवः, विपत्तिः','अतीवहानियुक्ता दुर्घटना।; \"भोपालस्य वायोः आपत्तिः भारतदेशस्य औद्योगिकी आपत्तिः अस्ति।\"','noun'),(34551,'','हस्ताहस्तिका','तुल्यबलानां प्रतिस्पर्धिनां स्पर्धा।; \"अस्मिन् निर्वाचने भारतीयजनतापक्षः तथा कॉङ्ग्रेसपक्षयोः हस्ताहस्तिका अस्ति।\"','noun'),(34530,'','टेम्पोयानम्','यन्त्रेण चालितं वाहनम्।; \"श्यामः टेम्पोयानं चालयति।\"','noun'),(34531,'','शङ्खः, काहलः','वाहनादिषु अन्यान् सूचयितुं वर्तमानं वस्तु यस्य नोदनेन ध्वनिः श्रूयते।; \"भारवाहकस्य शङ्खस्य ध्वनिः दूरे अपि श्रूयते।\"','noun'),(34524,'','प्रशासकीय','प्रशासकेन सम्बद्धम्।; \"अस्माकं संस्थायाः एका प्रशासकीया सभा भविष्यति।\"','adjective'),(34528,'','बलम्, सुरक्षाबलम्','सुरक्षाकर्मिणां दलम्।; \"सः बले भागं ग्रहीतुम् इच्छति।\"','noun'),(34513,'','लश्कर-ए-तैबाः','यवनानाम् आतङ्कवादिसंस्था।; \"लश्कर-ए-तैबाः स्थापनं हाफिज़मुहम्मदसईदेन कृतम्।\"','noun'),(34520,'','लोकहितम्','जनानां हितम्।; \"तेन स्वजीवनं लोकहिताय समर्पितम्।\"','noun'),(34521,'','लोकहितम्','प्रजायाः हितस्य कार्यम्।; \"लोकहितम् एव तस्य जीवनस्य उद्देश्यम्।\"','noun'),(34522,'','न्यायमूर्तिः','न्यायाधीशस्य उपाधिः।; \"सत्यतापरीक्षणानन्तरम् एव न्यायमूर्तिना बेदीमहोदयेन निर्णयः दत्तः।\"','noun'),(34498,'','राष्ट्रीय-जनता-दलः','भारतदेशस्य राजनैतिकं दलम्।; \"बिहारराज्ये ह्यः राष्ट्रीय-जनता-दलस्य नेतृभिः स्थाने-स्थाने सभाः आयोजिताः।\"','noun'),(34499,'','लोक-जनशक्ति-पक्षः','भारतदेशस्य राजनैतिकः दलः।; \"लोक-जनशक्ति-पक्षस्य अध्यक्षः रामविलासपासवानमहोदयः अस्ति।\"','noun'),(34500,'','झारखण्डमुक्तिमोर्चाः','भारतदेशस्य क्षेत्रीयः राजनैतिकः दलः।; \"झारखण्डमुक्तिमोर्चाः प्रभावः प्रायः आदिवासिक्षेत्रेषु दृश्यते।\"','noun'),(34501,'','कम्यूनिस्ट-पार्टी-आफ-इण्डिया, भारतीयसाम्यवादिपक्षः','भारतीयः राजनैतिकः दलः।; \"कम्यूनिस्ट-पार्टी-आफ-इण्डियायाः स्थापनं 17 अक्टोबर 1920तमे दिनाङ्के अभवत्।\"','noun'),(34503,'','स्थानम्','प्रत्याशिनः राजकीयं निर्वाचनं क्षेत्रम्।; \"बिहारविधानसभायाः निर्वाचनस्य सर्वेषां स्थानानां निर्णयाः प्राप्ताः।\"','noun'),(34497,'','जनतादलयूनाइटेडपक्षः','भारतदेशस्य राजनैतिकं दलम्।; \"अस्मिन् निर्वाचने जनतादलयुनाइटेडपक्षः पराजितः।\"','noun'),(34485,'','सभाकारः, गृहकर्ता, गृहकारकः, गृहकारी, गृहसंवेशकः, निर्माता, मेता','यः भवनस्य गृहस्य वा निर्माणं करोति।; \"लोधामहोदयः प्रसिद्धः सभाकारः अस्ति।\"','noun'),(34487,'','अनुसूचित, अनुसूचीबद्ध','अनुसूच्यां बद्धः।; \"अनुसूचितानि पृष्ठानि सजगतया पठनीयानि।\"','adjective'),(34496,'','उपनिदेशकः, उपनिर्देशकः','निदेशकस्य कार्ये यः सहायतां करोति।; \"निदेशकस्य अनुपस्थितौ संस्थायाः कार्यम् उपनिदेशकेन सञ्चाल्यते।\"','noun'),(34510,'','समलैङ्गिक','समलिङ्गसम्बन्धी।; \"मेक्सिकोनगरस्य विधानसभया समलैङ्गिकानां विवाहानां कृते अनुमतिः दत्ता।\"','adjective'),(34508,'','भारवाहक','यः भारं वहति।; \"भारवाहके विमाने विस्फोटः जातः।\"','adjective'),(34509,'','निष्पक्षता, निष्पक्षत्वम्','पक्षपातरहितस्य अवस्था भावः वा।; \"प्रत्येकस्मिन् कार्ये निष्पक्षता रक्षितव्या।\"','noun'),(34505,'','उपमुख्यमन्त्री','मुख्यमन्त्रिणः अनुपस्थितौ यः तस्य कार्यं सञ्चालयति।; \"सुशिल-कुमार-मोदीमहोदयः बिहारराज्यस्य उपमुख्यमन्त्री भविष्यति।\"','noun'),(34504,'','मतगणनम्','मतानां गणनस्य कार्यम्।; \"मतगणनस्य आरम्भानन्तरं 2-3 घण्टानन्तरं परिणामाः आगताः।\"','noun'),(34482,'','अल्पाहारगृहम्','पाठशालामहाविद्यालयादिषु भोजनं तथा अन्यानि कानिचन वस्तूनि यत्र विक्रीयन्ते।; \"सायङ्काले अल्पाहारगृहं छात्रैः पूर्णं भवति।\"','noun'),(34484,'','मुष्टिः','सम्पिण्डिताङ्गुलिपाणियुक्तं परिमाणम्।; \"सः भिक्षुकं मुष्टिं यावत् धान्यम् अयच्छत्।\"','noun'),(34480,'','असोसीएशन-ऑफ-साउथईस्ट-एशियन-नेशन्ससङ्घः','आग्नेय-एशियामहाद्वीपस्य देशानां एकः सङ्घः राजनैतिकार्थिकसहाय्यार्थं समर्पितः अस्ति तथा यः विश्वव्यापिना आतङ्कवादेन योद्धुम् अमेरिकादेशस्य सहाय्यकः अस्ति।; \"असोसीएशन-ऑफ-साउथईस्ट-एशियन-नेशन्ससङ्घे आग्नेय-एशियामहाद्वीपस्य दश देशाः समाविष्टाः सन्ति।\"','noun'),(34479,'','वर्ष्म','भूमित्यानुसारेण सः बिन्दुः यत्र द्व्यधिकाः तिर्यक् रेखाः युज्यन्ते।; \"अस्य त्रिभुजस्य वर्ष्मणः कोणः 70अंशः अस्ति।\"','noun'),(34474,'',' ',' ; \"\"','noun'),(34476,'','गुपचुपम्','गुलाबजामुनम् इव मिष्टान्नविशेषः।; \"मम पुत्रेभ्यः गुपचुपं रोचते।\"','noun'),(34477,'','वार्त्ता, वृत्तम्','तादृशी घटना तादृशं कार्यं वा यस्य विषये जनाः अधिकं सम्भाषणं कुर्वन्ति।; \"वार्तां प्रसारयितुं न अधिकः समयः आवश्यकः।\"','noun'),(34478,'','वार्ता','विशिष्टं महत्त्वपूर्णं निश्चितं प्रामाणिकं वा कथनं सिद्धान्तः च।; \"एतां वार्तां यदि कोऽपि श्रुणोति तर्हि सर्वं विपरितं भवति।\"','noun'),(34473,'','अननुयोगाधीन, अपृच्छाधीन, अप्रश्नयोग्यः, पृच्छानर्ह, अननुयोज्य, अननुयोक्तव्य','उत्तरदायित्वं ज्ञात्वा यः तादृशम् न आचरति।; \"अननुयोगाधीनेषु पुरुषेषु कस्यापि कार्यस्य कृते न आश्रयणीयम्।\"','adjective'),(34472,'','मध्यस्थता, मध्यवर्तिता','मध्यस्थस्य अवस्था भावः वा।; \"मातापित्रोः मध्यस्थतया भ्रात्रोः मध्ये सन्धिः जातः।\"','noun'),(34469,'','रहस्योद्घाटक','यः अन्येषां रहस्यानि उद्घाटयति।; \"एषा रहस्योद्घाटिका वार्ता अद्य वार्तापत्रे आगच्छति।\"','adjective'),(34471,'','अलविदा','रमजानमासस्य अन्तिमः शुक्रवासरः।; \"अलविदे मस्जिदं पुरतः उत्सवः भविष्यति।\"','noun'),(34459,'','स्वविवेकः','स्वस्य विवेकः।; \"शासनाधिकारिणां स्वविवेकेन निर्णयस्य अधिकारः अस्ति।\"','noun'),(34460,'','दुर्भाग्यपूर्ण, दुर्भाग्ययुक्त','दुर्भाग्येन युक्तम्।; \"नीतेः अवमूल्यनात् अन्या दुर्भाग्यपूर्णा स्थितिः का भवेत्।\"','adjective'),(34457,'','आशीः, आशास्यम्, मङ्गलेच्छा, आशीरुक्तिः, आशीर्वचनम्, आशीर्वादः','अन्यस्य कस्यापि माङ्गल्यार्थं ईश्वरे कृता प्रार्थना।; \"कदाचित् औषधस्य अपेक्षया आशीः एव अधिका प्रभावशालिनी भवति।\"','noun'),(34453,'','साहाय्यम्','प्राकृतिकैः आपद्बिः प्रभावितानां दुर्घटनाग्रस्तानां वा जनानां साहाय्यार्थं कृतं कार्यम्।; \"शासनेन प्रजायै साहाय्यं दातुं योगदानस्य प्रार्थना कृता।\"','noun'),(34452,'','राष्ट्रीय-वैमानिकी-तथा-अन्तरिक्ष-प्रबन्धनम्','संयुक्त-राज्य-अमेरीकादेशस्य सङ्घीयस्य शासनस्य संस्था या अन्तरिक्षस्य कार्यक्रमाणाम् अनुयोगाधीनतां वहति।; \"राष्ट्रीय-वैमानिकी-तथा-अन्तरिक्ष-प्रबन्धनेन अन्तरिक्षे वाननिरीक्षणी प्रक्षेपिता या जगतः नैकान् रहस्यान् उद्घाटयन्ति।\"','noun'),(34451,'','अवरुद्ध, बाधित, प्रतिबद्ध','यस्य मार्गे बाधा उत्पन्ना।; \"शासनस्य व्यत्यासात् अवरुद्धं कार्यम् आरब्धम्।\"','adjective'),(34449,'','सनियम, नियन्त्रित, सावधारण','नियमैः युक्तः।; \"सनियमं लेखनं मनोरञ्जकं स्यात् एव इति नास्ति।\"','adjective'),(34450,'','प्रतिबद्ध, निबद्ध, न्यस्त','प्रतिज्ञादिभिः बद्धः।; \"स्ववचनैः प्रतिबद्धः भीष्मपितामहः पाण्डवानां पीडिताम् अवस्थां निष्क्रियः सन् ददर्श।\"','adjective'),(34448,'','स्थगित, निरुद्ध, अवरुद्ध, प्रतिरुद्ध','गमनसमये यः मध्ये एव गमनं स्थगयति।; \"स्थानके स्थगितात् यानात् जनाः अवतरन्ति।\"','adjective'),(34438,'','धनप्रेषः, धनादेशः','अन्यस्मिन् स्थाने निवासिने मनुष्याय पत्रालयात् प्रेष्यमाणस्य धनप्रत्यर्पणस्य लिखितः आदेशः।; \"प्रत्येकस्मिन् मासे रामः एकसहस्त्ररूप्यकस्य धनप्रेषं प्रेषयति।\"','noun'),(34439,'','धनादेशः','निर्दिष्टाय मनुष्याय धनं दातुं वित्तकोशे दत्तः लिखितः आदेशः।; \"अहं काले धनादेशं प्राप्तवान्।\"','noun'),(34440,'','धनादेश','धनदानस्य आदेशः।; \"सः पितु धनादेशः अन्यथाकर्तुं न शक्नोति।\"','noun'),(34446,'','स्थित, संस्थित','यः पादौ अवलम्ब्य तिष्ठति।; \"स्वामिना पुरतः स्थितः कर्मकरः आहूतः।\"','adjective'),(34431,'','सपदि, सद्यः, झटिति, अञ्जसा, क्षणात्, तत्क्षणे, तत्क्षणेन, अह्नाय, मङ्क्षु, स्राक्, अञ्जस्, अह्नाय, आपाततः, यथास्थानम्','विलम्बेन विना।; \"माता भवन्तं सपदि गृहं प्रति आहूतवती।\"','adverb'),(34432,'','दुष्प्रकृतिः','दुष्टा प्रकृतिः।; \"दुष्प्रकृतीः त्यक्तव्याः।\"','noun'),(34433,'','दुष्ट, अधम','दुष्क्रियया युक्तः।; \"दुष्टस्य पुरुषस्य संशोधनं सरलं नास्ति।\"','adjective'),(34434,'','अतिकृच्छः','षट्सु दिनेषु प्रचाल्यमानं कठिनं व्रतम्।; \"प्रायश्चितं कर्तुं अतिकृच्छः क्रियते।\"','noun'),(34437,'','मनोरोगतज्ञः','मनोरोगाणां चिकित्सायाः विशेषज्ञः।; \"अधिकाः जनाः मनोरोगतज्ञाय समस्यां कथयितुं बिभ्यन्ति।\"','noun'),(34430,'','आनयनम्','कस्यापि वस्तुनः मनुष्यादीनां वा स्थानान्तरनयनम्।; \"आपणात् दुग्धस्य आनयनाय विलम्बः जातः।\"','noun'),(34398,'','असंविधानीय','यद् संविधानस्य अनुसारेण नास्ति।; \"सर्वत्र प्रचाल्यमानानि असंविधानीयानि कार्याणि अवधारणीयानि।\"','adjective'),(34399,'','राज्यशासनम्','कस्यापि राज्यस्य प्रमुखं शासनं यस्य मुख्यं स्थानं राज्यस्य राजधानीनगरं वर्तते तस्मात् नगराद् एव राज्यस्य नियन्त्रणं करोति।; \"राज्यशासनस्य नीतिषु एव राज्यस्य प्रगतिः आधारिता अस्ति।\"','noun'),(34400,'','भूमिहीन','यस्य भूमिः नास्ति।; \"भूमिहीनेभ्यः जनेभ्यः सर्वकारः भूमिं ददाति।\"','adjective'),(34402,'','तालिबानसेना','रूढिवादिनां यावनानां नागरिकी सेना यया 1995तमे वर्षे अफगाणिस्थानदेशः स्वस्य अधिकारे कृतः।; \"जनेषु तालिबानसेनायाः विषये आतङ्कः अस्ति।\"','noun'),(34404,'','आख्यानम्','कल्पितम् असत्यं वा कथनम्।; \"पाठशालायाः आगन्तुं विलम्बे जाते बालकाः आख्यानं कथयन्ति।\"','noun'),(34406,'','अस्वीकारवादी','जनानां विचारान् अभिव्यञ्जयितुं समाजेन कृते निदर्शने यः भागम् आवहति।; \"अस्वीकारवादिनां मतं संस्थया सम्बद्धैः जनैः अङ्गीकृतम्।\"','noun'),(34408,'','दृषत्कणः','कस्यापि वस्तुनः लघुः खण्डः।; \"अद्य मम भोजने दृषत्कणाः आसन्।\"','noun'),(34413,'',' ',' ; \"\"','noun'),(34418,'','वसन्तोत्सवः, होलाका','तद् दिनं यदा रङ्गोत्सवं निर्वर्तयन्ति।; \"वसन्तोत्सवे भगवतः पूजनं कृत्वा जेष्ठेभ्यः आशीर्वचनं प्राप्तव्यम्।\"','noun'),(34419,'','प्राप्तिपत्रम्, आदानपत्रम्, प्राप्तिका','किमपि वस्तु प्राप्तम् इत्यस्य सूचकं पत्रम्।; \"मम पत्रस्य प्राप्तिपत्रम् इदानीमपि मया न प्राप्तम्।\"','noun'),(34422,'','अग्निशामकः','अव्यापकम् अग्निं शमयितुं प्रयुक्तं हस्तचालितम् उपकरणं येन विशिष्टाः रासायनिकाः पदार्थाः सिच्यते।; \"आधुनिकेषु भवनेषु अग्निशामकाः भवन्ति।\"','noun'),(34426,'','कम्पनम्','शैत्येन भयेन वा जायमानं रोमाञ्चयुक्तं परिप्लवनम्।; \"कम्पनात् रक्षितुं सः प्रकोष्ठम् अगच्छत्।\"','noun'),(34427,'','कीलकर्पासः','आसामदेशे उत्पन्नः कर्पासप्रकारः।; \"अस्मिन् संवत्सरे कीलकर्पासस्य उत्पादनं सम्यक् जातम्।\"','noun'),(34397,'','प्रत्यभियोजनम्','प्रतिरक्षकदलेन शत्रुदलविरुद्धं कृतम् आक्रमणम्।; \"सेना सर्वस्मात् स्थानात् प्रत्यभियोजनं करोति।\"','noun'),(34394,'','मुक्तिः, स्वातन्त्र्यम्, स्वतन्त्रता, मोचनम्, अवशता, मोक्षणम्','मुक्तस्य अवस्था भावः वा।; \"अमेरिकादेशे दासवर्गाणां मुक्तेः श्रेयः अब्राहमलिङ्कनमहोदयस्य अस्ति।\"','noun'),(34392,'','मुक्तिः','अनुयोगाधीनतादेः मुक्ततायाः अवस्था भावः वा।; \"ऋणात् मुक्तेः कृते गृहविक्रयणात् अन्यः न कश्चित् उपायः दृश्यते।\"','noun'),(34393,'','मुक्तिः, मोक्षः, कैवल्यम्, निर्वाणम्, श्रेयः, निःश्रेयसम्, अपवर्गः','मृत्योः कारणात् जायमाना नित्यसुखावाप्तिः।; \"जीर्णेन रोगेण पीडितः सः जीवनात् मुक्तिम् इच्छति।\"','noun'),(34390,'','नालः','जलवाहिन्याः सः प्रान्तः यस्मिन् वक्त्रं वर्तते तथा पिञ्जस्य नोदनेन जलं च स्रवति।; \"नालम् उद्घाट्य मा स्रावयतु।\"','noun'),(34387,'','गुरुपदम्','गुरोः पदम्।; \"गुरुपदस्य महत्वं विरलाः जनाः जानन्ति।\"','noun'),(34388,'','सुधाखण्डः, कक्खटी, कठिका, कठिनी, कठिनिका, खटी, खटिका, खटिनी, खडी, खडिका','सुधया निर्मिता एका यष्टिः यया फलकादिषु लिख्यते।; \"अध्यापकः कृष्णफलके सुधाखण्डेन लिखति।\"','noun'),(34386,'','आचार्यता','आचार्यस्य कार्यं धर्मः वा।; \"सः तस्य आचार्यतायाः कारणात् प्रसिद्धः अस्ति।\"','noun'),(34377,'','व्रणः','मानसिकेन आघातेन जाता मनसः दुःखदस्थितिः।; \"तस्याः घटनायाः स्मरणेन व्रणः पुनः जागृतः भवति।\"','noun'),(34378,'','उरणः, अजापुत्रः','अजायाः शावकः।; \"उरणस्य ध्वनिं श्रुत्वा अजा तत्र आगता।\"','noun'),(34352,'','कम्पिका','कस्मिन्नपि वाद्ये वर्तमानं काष्ठस्य धातोः वा सुपेशं पत्रं यद् वादनसमये वेगेन कम्पितं भूत्वा ध्वनिम् उत्पादयति।; \"अकार्डियनवाद्ये कम्पिकाः सन्ति।\"','noun'),(34353,'','कम्पित्रम्','यान्त्रिकम् उपकरणं यद् कम्प्यते कम्पनम् उत्पादयति च।; \"नैकेषु यन्त्रेषु कम्पित्रं वर्तते।\"','noun'),(34354,'','युग्ममुरली','वाद्यविशेषः यः काष्ठस्य दीर्घायाः नलिकायाः इव भवति।; \"युग्ममुरल्याः वादने सः निपुणः।\"','noun'),(34383,'','अग्निपर्वतः','ज्वालामुख्याः निर्गतैः पदार्थैः निर्मितः पर्वतः।; \"केचन सक्रियाः अग्निपर्वताः इदानीम् अपि प्रज्वलन्ति।\"','noun'),(34384,'','ज्वालामुखी','पृथिव्याः कस्यापि अन्यग्रहस्य वा पृष्ठभागे वर्तमानः सः छिद्रः यस्मात् लावारसः वाय्वादयः निर्गच्छन्ति।; \"ज्वालामुख्याः उद्रेकः प्रायः विस्फोटेन सह भवति।\"','noun'),(34381,'','अपुच्छ, वण्ट, विशिख','पुच्छरहितः।; \"बालकाः अपुच्छायाः मुशलिकायाः पृष्ठतः धावन्ति।\"','adjective'),(34379,'','प्रधानमन्त्री','मन्त्रिमण्डलस्य प्रधानपुरुषः यः संसदीयस्य प्रजातन्त्रस्य सदस्यः अपि अस्ति।; \"अस्माकं देशस्य प्रथमः प्रधानमन्त्री पण्डितजवाहरलालनेहरुमहोदयः आसीत्।\"','noun'),(34366,'','तालरसः','तालस्य फलेभ्यः निष्कासितः रसः यः मादकः भवति।; \"जनाः वृक्षस्य अधः उपविश्य तालरसं पिबन्ति।\"','noun'),(34368,'','पक्व, अग्निपक्व','अग्नौ निर्मितं भोजनम्।; \"पक्वं भोजनं सुपाच्यं भवति।\"','adjective'),(34369,'','दया, करुणा, अनुकम्पा, कृपा, कारुणिकता, कृपालुता, कारुण्यम्, अनुकम्पनम्, माया, विक्षेपः, अनुक्रोशः, अनुषङ्गः','स्वजनान् दुर्बलान् वा मनुष्यान् व्यथितं दृष्ट्वा तेषां दुःखादीनाम् दूरीकरणम्।; \"ईश्वरस्य दया अस्मासु भवेत्।\"','noun'),(34370,'','वीरगतिः','युद्धभूमौ वीरमरणेन प्राप्ता गतिः।; \"देहलीनगरे इण्डियागेट इति स्थानस्य भित्तौ वीरगतिं प्राप्तानां सैनिकानां नामानि लिखितानि सन्ति।\"','noun'),(34371,'','साक्षर','यः अक्षराणां पठनं लेखनञ्च जानाति।; \"अस्माकं देशे साक्षराणां जनानां सङ्ख्या प्रतिदिनं वर्धमाना अस्ति।\"','adjective'),(34373,'','अतिरिक्त','आवश्यकतायां यद् वर्धितम्।; \"आगामिमासात् आरभ्य विदेशात् आनीते मद्ये अतिरिक्तं शुल्कं भविष्यति।\"','adjective'),(34374,'','विना, ऋते, अन्तरेण, अन्तरा, परि, परिहाप्य, अप','एकं वर्जयित्वा।; \"भगवता विना अन्यः कः अपि शरण्यः नास्ति।\"','adverb'),(34372,'','अतिरिक्त','यः निर्धारिताद् अधिकः अस्ति।; \"अद्यतनीये परिणाहवति महार्हे जगति मासिकवेतनाद् अतिरिक्तेन वित्तस्य स्रोतसा विना कुटुम्बस्य सम्यक् परिपालनं सर्वथैव अशक्यम् अस्ति।\"','adjective'),(34363,'','कामसूत्रम्','महर्षिणा वात्स्यायनेन रचितः भारतस्य प्राचीनः कामशास्त्रस्य ग्रन्थः।; \"कामसूत्रस्य अनुवादः विश्वस्य सर्वासु भाषासु जातः।\"','noun'),(34364,'','कोकदेवः','कोकशास्त्रनाम्नः ग्रन्थस्य रचयिता।; \"कोकशास्त्रनामिकया रचनया एव कोकदेवः ख्यातः अस्ति।\"','noun'),(34365,'','वात्स्यायनः','प्रसिद्धः मुनिः यः कामसूत्रस्य रचयिता अस्ति।; \"वात्स्यायनस्य कामसूत्रस्य आङ्ग्लभाषायाम् अनुवादः प्रथमं रिचर्डएफबर्टनमहोदयेन कृतम्।\"','noun'),(34359,'','जातिवाचकसंज्ञा','व्याकरणशास्त्रे कस्यापि जातेः प्रत्येकस्य सदस्यस्य समानरूपेण सूचकः शब्दः।; \"गौश्वादयः जातिवाचकसंज्ञाः सन्ति।\"','noun'),(34360,'','अम्बुकण्टकः, अम्बुकिरातः, मकरः, कुम्भीरः, घण्टिकः, शिशुमारः','मकर्याः इव जलजन्तुविशेषः यस्य नासा मकर्याः अपेक्षया लघुः भवति।; \"अम्बुकण्टकः मकरश्च समानमेव इति जनाः चिन्तयन्ति।\"','noun'),(34361,'','कामशास्त्रम्','यस्मिन् शास्त्रे स्त्रीपुरुषयोः सम्भोगस्य प्रकाराणां रीतिनां तथा तयोः मध्ये वर्तमानस्य आकर्षणस्य च वर्णनं भवति।; \"कामशास्त्रं प्रौढैः एव पठनीयम्।\"','noun'),(34362,'','कोकशास्त्रम्','आचार्येण कोकदेवेन रचितः कामशास्त्रस्य ग्रन्थः।; \"कामसूत्रमिव कोकशास्त्रम् अपि ख्यातम् आसीत्।\"','noun'),(34357,'','चरितार्थ','यस्य प्रयोजनं सिद्धम्।; \"तस्य जीवनं चरितार्थम् आसीत्।\"','adjective'),(34355,'','अधिरथः','कर्णस्य पालकः पिता।; \"अधिरथस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(34356,'','राधा','अधिरथस्य पत्नी।; \"राधा अधिरथः च कर्णस्य पालनं चक्रतुः।\"','noun'),(34351,'','अकार्डियनवाद्यम्, अकर्डियनवाद्यम्','पेटिकासदृशः वाद्ययन्त्रविशेषः।; \"दीपकः अकार्डियनवाद्यस्य वादने कुशलः अस्ति।\"','noun'),(34347,'','विभूतिः','दिव्यास्त्रं यस्य वर्णनं रामायणे प्राप्यते।; \"विश्वामित्रः रामाय विभूतिं ददौ।\"','noun'),(34342,'','वातपेषणी, वायुचाल्यचक्रम्','वायोः गत्या एव भ्रमन् यन्त्रम्।; \"वातपेषण्याः उपरितने भागे वर्तमानं बृहत् चक्रं वायोः गत्या भ्रमति येन अधस्तनीये भागे वर्तमानं यन्त्रं कार्यं करोति।\"','noun'),(34343,'','जलस्तरः','जलस्य स्तरः।; \"नद्याः जलस्तरः निरन्तरं वर्धते एव।\"','noun'),(34344,'','चलचित्रकारः','यः चलच्चित्रं निर्माति।; \"कुशलः अभिनेता आमीरखानः चलचित्रकारः अपि अस्ति।\"','noun'),(34346,'','वित्तकोषविकर्षः, वार्धुषपत्रम्, अधिकोषविकर्षः','वित्तकोषेण निर्मितं लेख्यपत्रं यस्मिन् धनराशिः तथा तस्याः स्वामिनः वित्तकोषस्य च नाम लिखितं भवति।; \"आवेदनपत्रेण सह पञ्चाशद्रूप्यकाणां वित्तकोषविकर्षः अपि उद्योगसंस्थायाः नाम्ना भवता प्रेषणीयः।\"','noun'),(34350,'','प्रतीकविज्ञः','यः पुरुषः स्वविचारान् प्रतीकानां माध्यमेन प्रकटयति।; \"कुशलः प्रतीकविज्ञः स्पष्टरूपेण प्रतीकानां माध्यमेन विचारान् प्रकटयति।\"','noun'),(34348,'','प्रसाधकः, विभूषकः','यः भूषयति।; \"कुशलेन प्रसाधकेन तेन गृहं भूषयितम्।\"','noun'),(34341,'','वातपेषणी, वायुचाल्यचक्रम्','वायोः ऊर्जया विद्युदुर्जाम् उत्पादयन् यन्त्रविशेषः येन अन्यानि यन्त्राणि अपि प्रचाल्यन्ते।; \"प्रायः वातपेषण्यः समुद्रतटे दृश्यन्ते।\"','noun'),(34339,'','अनुशासनहीन','यः अनुशासनस्य पालनं न करोति।; \"शिक्षकः अनुशासनहीनान् छात्रान् कक्षायाः बहिः निरकासयत्।\"','adjective'),(34340,'','आण्विक','अणुना सम्बद्धम्।; \"प्रत्येकस्य तत्वस्य आण्विकी संरचना भिन्ना वर्तते।\"','adjective'),(34337,'','भारतोलनम्','व्यायामप्रकारविशेषः यस्मिन् कायनिर्माणाय भारः तुल्यते।; \"क्रीडकानां कृते भारतोलनम् अनिवार्यम् अस्ति।\"','noun'),(34338,'','अनावृत','आवरणरहितः।; \"महोदयायाः अनावृतं मुखं अल्पैः जनैः दृष्टम्।\"','adjective'),(34333,'','लोकप्रधान, जनप्रधान','यत्र जनानां प्राधान्यं भवति।; \"भारतदेशः लोकप्रधानः अस्ति।\"','adjective'),(34336,'','वैवाहिक','विवाहसम्बन्धी।; \"ते स्वस्य वैवाहिकेन जीवनेन आनन्दिताः सन्ति।\"','adjective'),(34282,'','अर्धभेदः','सः पक्षाघातः यस्मिन् शरीरस्य दक्षिणभागः वामभागः वा अक्रियः भवति।; \"अर्धभेदस्य रुग्णः वामहस्तेन भोजनं करोति।\"','noun'),(34283,'','आंशिकाङ्गघातः, आंशिकपक्षाघातः','अंशतः जातः पक्षाघातः।; \"पितामहः आंशिकाङ्गघातेन पीडितः।\"','noun'),(34286,'','स्थापित','यस्य स्थापनं जातम्।; \"ग्रामसभया क्रीडायै स्थापितायां समित्यां मम नाम अपि अस्ति।\"','adjective'),(34287,'','प्रागैतिहासिक','ज्ञातात् इतिहासात् पूर्वः कालः।; \"प्रागैतिहासिकस्य कालस्य विषये अधुनापि इतिहासज्ञेषु वैमत्यम् अस्ति।\"','adjective'),(34288,'','साम्प्रदायिकता','साम्प्रदायिकस्य अवस्था भावः वा।; \"समाजे साम्प्रदायिकतायाः प्रसरः न योग्यः।\"','noun'),(34289,'','युतकम्','शूर्पस्य उन्नतौ प्रान्तौ।; \"निष्पवनेन युतकात् शूर्पस्थानि वस्तूनि न पतन्ति।\"','noun'),(34291,'','प्रकम्पनः','राक्षसविशेषः।; \"प्रकम्पनस्य वर्णनं धर्मग्रन्थे प्राप्यते।\"','noun'),(34294,'','अर्धनग्न','अर्धं नग्नम्।; \"सः अभिनेत्रीणाम् अर्धनग्नानि चित्राणि अपश्यत्।\"','adjective'),(34301,'','अन्तरीक्षयानम्','अन्तरीक्षे प्रक्षेपितं यानम्।; \"इदम् अन्तरीक्षयानं मासं यावत् अन्तरीक्षे भविष्यति।\"','noun'),(34302,'','राष्ट्रगानम्, राष्ट्रगीतम्','राष्ट्रस्य प्रशंसागीतरूपेण सम्पूर्णेन राष्ट्रेण अङ्गीकृतं गीतम्।; \"राष्ट्रगानस्य रचयिता गुरुदेवरवीन्द्रनाथटैगोरमहोदयः अस्ति।\"','noun'),(34303,'','नवपरिणीत, नवविवाहित','ययोः विवाहः इदानीम् एव जातः।; \"नवपरिणीतौ दम्पती प्रसन्नौ दृश्येते।\"','adjective'),(34307,'','जिह्वालौल्यम्','अत्याहारिणः अवस्था।; \"जिह्वालौल्यस्य कारणात् मनोहरः दिने नैकवारं खादति।\"','noun'),(34310,'','पङ्गु','पादयोः कश्चित् दोषस्य विकारस्य वा कारणात् यः कष्टेन चलति।; \"पङ्गुः रुग्णः किञ्चित् दूरं चलित्वा उपाविशत्।\"','adjective'),(34313,'','उदारतावादिन्','यः उदारतावादस्य समर्थनं करोति।; \"सः उदारतावादी नेता अस्ति।\"','adjective'),(34314,'','असूर्यम्पश्या','सा स्त्री या सर्वदा आच्छादने एव भवति या सूर्येणापि न दृष्टा।; \"तस्याः असूर्यम्पश्यायाः विषये जनाः जल्पन्ति।\"','noun'),(34320,'','मौनी-अमावस्या','माघमासस्य अमावस्या।; \"मौनी-अमावस्यां सूर्योदयात् प्राक् पूर्वसङ्गमे स्नानं शुभं मन्यते।\"','noun'),(34321,'','ईवा','यहूदीधर्मानुसारेण तथा ख्रीष्ट्रीयधर्मानुसारेण आदमस्य पत्नी तथा मानवजातेः जननी प्रथमा स्त्री वा।; \"ईश्वरेण आदमस्य पर्शुकायाः ईवा उत्पादिता।\"','noun'),(34322,'','आदमः','यहुदी तथा ईसाईधर्मानुसारेण ईवायाः पतिः जगतः प्रथमः पुरुषश्च।; \"ईवायाः सूचनया एव आदमः निषिद्धं फलम् अखादत्।\"','noun'),(34331,'','हिममानवः','नेपालतिब्बतदेशादीनां हिमालयीने क्षेत्रे निवसन् मानवसदृशः प्राणिविशेषः।; \"हिममानवस्य वर्णनं पौराणिकासु कथासु प्राप्यते।\"','noun'),(34332,'','मोहरम्','नेपालदेशे सप्तदशशताब्देः मध्यात् आरभ्य द्वात्रिंशत्यधिकैकोनविंशतिं संवत्सरं यावत् प्रचलिता मुद्रा।; \"मोहरं सुवर्णस्य रजतस्य वा आसीत्।\"','noun'),(34126,'','योग्य, उपयुक्त','अत्यन्तम् उचितम्।; \"पञ्चविंशतिवर्षीयाः दीपिकायाः कृते योग्यस्य वरस्य आवश्यकता अस्ति।\"','adjective'),(34127,'','पश्चवर्तिजलम्','जलप्लावनेन अम्बुवर्धनेन अथवा जलबन्धेन अवसितम् जलम्।; \"केरलराज्ये पश्चवर्तिजले नौयात्रा प्रसिद्धा अस्ति।\"','noun'),(34128,'','विकेशः','पौराणिकः ऋषिः।; \"विकेशस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(34129,'','विक्रान्तः','धुन्धमारस्य पुत्रः।; \"विक्रान्तस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(34131,'','वैविध्यपूर्ण','विविधतया युक्तः।; \"भारतदेशः सांस्कृतिकपरम्परारूपेण न्यासेन वैविध्यपूर्णया ऐतिहासिक्या पृष्ठभूम्या च युक्तः देशः अस्ति।\"','adjective'),(34132,'','विषुवद्वृत्तम्, विषुवन्मण्डलम्','भूमध्यरेखया निर्मितं वृत्तम्।; \"विषुवद्वृत्तस्य व्यासार्धं ६,३७८:१३७ कि:मी इति अस्ति।\"','noun'),(34134,'','सङ्कुलम्','परस्परैः सम्बद्धा भवनादीनां संरचना।; \"सम्प्रति नगरेषु सङ्कुलानां सङ्ख्या वर्धमाना अस्ति।\"','noun'),(34135,'','जागरित','यः निद्रां समाप्य उत्थितः।; \"अपूर्णायाः निद्रायाः जागरितं बालकं माता शाययति।\"','adjective'),(34136,'','जालदेशः, जालस्थलम्','अन्तर्जाले वर्तमानानां जालपृष्ठानां समूहः।; \"इदानीन्तनकाले जालदेशात् सर्वविषयकं ज्ञानं लभ्यते।\"','noun'),(34137,'','पञ्चाशताधिकैकशत','शत इत्यस्याः सङ्ख्यायाः पञ्चाशत् इत्यस्याः सङ्ख्यायाः च योजनेन प्राप्ता सङ्ख्या।; \"सः पितामहस्य श्राद्धदिने पञ्चाशताधिकैकशतान् जनान् अभोजयत्।\"','adjective'),(34138,'','सौष्ठवता','सौष्ठवस्य अवस्था भावः वा।; \"इदानींतने काले शरीरस्य सौष्ठवता एकः आवश्यकः घटकः।\"','noun'),(34142,'','वास्तुवित्, वास्तुविद्, स्थपतिः','यः भवनस्य प्रारूपं निर्माति।; \"तेजोमहालयस्य वास्तुविदं सर्वे प्रशंसन्ति।\"','noun'),(34143,'','चतुःशत','त्रिशतम् अधिकम् एकशतम्।; \"मम भगिन्याः विवाहे चतुःशताः जनाः आसन्।\"','adjective'),(34144,'','द्विशत','एकशतम् अधिकम् एकशतम्।; \"गतवर्षे द्विशताः छात्राः विहारार्थं गताः।\"','adjective'),(34145,'','सप्ताधिकैकशत','एकशतम् अधिकं सप्त।; \"दुर्गम् इतः सप्ताधिकैकशतं सहस्रमानं दूरे अस्ति।\"','adjective'),(34147,'','सप्तशत','त्रिशतम् अधिकं चतुःशतम्।; \"सभायां सप्तशताः जनाः आसन्।\"','adjective'),(34041,'','क्वथनम्, उत्क्वथनम्, उत्पचनम्','द्रवे अत्युष्णतया बुद्बुदोद्गमनम्।; \"दुग्धस्य क्वथने आरम्भे सति ज्वालां न्यूनीकरोतु।\"','noun'),(34042,'','क्वथनम्, उत्क्वथनम्','द्रवपदार्थे अत्युष्णतया बुद्बुदोद्गमनं यावत् उष्णीकरणस्य क्रिया।; \"जलदुग्धयोः क्वथनम् भिन्ने तापमाने भवति।\"','noun'),(34048,'','उज्ज्वलय','मार्जनेन स्वच्छीकरणानुकूलः व्यापारः।; \"सेविका भाण्डानि उज्ज्वलयति।\"','verb'),(34050,'','विमलय','अलङ्कारादीनां वस्त्रादीनां वा मलापनयनप्रेरणानुकूलः व्यापारः।; \"पितामही स्वस्य पुरातनान् अलङ्कारान् सुवर्णकारेण विमलयति।\"','verb'),(34052,'','प्रकाशय, उज्ज्वलय','अन्धःकारापनयनानुकूलः व्यापारः।; \"सायङ्काले दीप्रज्वलनेन गृहं प्रकाश्यते।\"','verb'),(34055,'','पुनर्जात, प्रतिजात','येन पुनः जीवनं प्राप्तम्।; \"पुनर्जातं सत्यवन्तं दृष्ट्वा सावित्री आनन्दिता जाता।\"','adjective'),(34056,'','उज्वला, उज्ज्वला','वर्णवृत्तविशेषः।; \"उज्वलायां नगणः, नगणः, नगणः तथा रगणः भवन्ति।\"','noun'),(34070,'','संहार्य','उद्धार्य्य नेतुं योग्यः।; \"संहार्याणि वस्तूनि त्यक्त्वा अन्यानि वस्तूनि वाहकः आनेष्यति।\"','adjective'),(34074,'','वाह्य, सुवहनीय','यद् एकस्मात् स्थानात् अन्यं स्थानं प्रति सहजतया नेतुं शक्यते।; \"उत्सवे वाह्यानां शौचालयानां व्यवस्था आसीत्।\"','adjective'),(34094,'','उड्डीयमान','यः उड्डयते।; \"उड्डीयमानः पक्षी व्याधस्य तीरेण आहतः भूमौ अपतत्।\"','adjective'),(34096,'','आघातः','गमनसमये शरीरभागस्य केनचित् वस्तुना हननम्।; \"गमनसमये पाषाणेन आघातः जातः।\"','noun'),(34097,'','व्यवधानम्, अवरोधः','काष्ठपाषाणादीनां तानि वस्तूनि यैः आघातः भवति।; \"अस्मिन् मार्गे नैकानि व्यवधानानि सन्ति, सावधानतया गच्छतु।\"','noun'),(34098,'','पादप्रहारः','पादस्य अग्रभागेन मनुष्ये वस्तुनि वा कृतः प्रहारः।; \"यानचीटिकापरीक्षकः रेलयानस्य भूमौ निद्रितं पुरुषं पादप्रहारेण प्रत्यबोधयत्।\"','noun'),(34103,'','उतङ्कः','प्राचीनकालीनः ऋषिः।; \"धुन्धुराक्षसः उतङ्कस्य तपस्यायां बाधाम् उत्पादयति स्म।\"','noun'),(34115,'','कोविदारः, चमरिकः, कुद्दालः, युगपत्रकः, काञ्चनारः, कणकारकः, ताम्रपुष्पः, कुदारः, रक्तकाञ्चनः, विदलः','विभूषणार्थम् उपयुज्यमानानां विविधवर्णयुक्तानां पुष्पाणां वृक्षः।; \"वाटिकायां कोविदारस्य भिन्नप्रकारकाः वृक्षाः सन्ति।\"','noun'),(34277,'','अनुशासनहीनता','अनुशासनहीनस्य भावः।; \"इदानींतने काले अनुशासनहीनता अशासनञ्च वर्धितम्।\"','noun'),(34278,'','मतक्यम्','सर्वेषां सम्मतिः।; \"इदं कार्यं मतैक्येन कृतम्।\"','noun'),(34279,'','मध्यमवर्गीय','आर्थिकस्तरं सामाजिकस्तरं वा अनुसृत्य कृते विभागे उत्तमाधमयोः अन्तरा स्थितस्य वर्गस्य घटकः  तद्वर्गसम्बन्धी च।; \"न कदापि स्वीकुर्मः वयं मध्यमवर्गीयां  कन्यां विवाहार्थम्।\"','adjective'),(34280,'','महालक्ष्मी','नारायणस्य शक्तिः।; \"महालक्ष्म्या विना नारायणः अपूर्णः।\"','noun'),(34281,'','वर्णभेदः','मनुष्यस्य शरीरस्य कृष्णगौरादीन् वर्णान् अधिकृत्य आचरणे कृतः श्रेष्ठः कनिष्ठः इति भेदः।; \"इदानीम् अपि जनाः वर्णभेदं कुर्वन्ति।\"','noun'),(34265,'',' ',' ; \"\"','noun'),(34266,'','मोचनम्, प्रतिमोचनम्, विमोचनम्','बन्धनात् मुक्तेः क्रिया।; \"अहं तस्य अधमस्य मोचनम् एतावत् शीघ्रं न करिष्यामि।\"','noun'),(34267,'','मोचनम्, विमोचनम्','बन्धनात् मुक्तेः क्रिया।; \"मम समीपे स्वालङ्काराणां मोचनं कर्तुं पर्याप्तं धनं नास्ति।\"','noun'),(34275,'','राष्ट्रमण्डलम्','स्वतन्त्राणां 53 देशानां विश्वसमूहः यस्य मुख्यालयः लन्दननगरे अस्ति।; \"पौर्वस्य ब्रिटेनदेशस्य अधिनस्थाः सर्वे देशाः राष्ट्रमण्डलस्य सदस्याः सन्ति।\"','noun'),(34262,'','जगन्नाथः, जगदीशः, पुरुषोत्तमः','उत्कलदेशे पूर्व-पयोधेः उत्तरे तीरे महनद्यः च दक्षिणे स्थितस्य नीलाचलेन विभूषितस्य पुरुषोत्तमपुरी इति क्षेत्रस्य देवता।; \"जगन्नाथ विष्णुः एव।\"','noun'),(34263,'','दिक्सूचक','दिशः सूचकः।; \"नौकादिषु दिक्सूचकं यन्त्रं भवति।\"','adjective'),(34261,'','आक्रम्, अध्याक्रम्, प्रक्रम्, विक्रम्, व्यतिव्रज्','बलात् परराज्यस्य सीमानम् उल्लङ्घ्य तत्र प्रवेशनानुकूलः व्यापारः।; \"शत्रवः सोमनाथमन्दिरम् नैकवारम् आचक्रमुः।/परकीयैः भारतः नैकवारम् आक्रम्यत।\"','verb'),(34221,'','औरसः','सवर्णया भार्यया उत्पन्नः पुत्रः।; \"मङ्गलः तस्य औरसः नास्ति।\"','noun'),(34223,'','नूतन, नवीन, नव, अपूर्व, अभिनव, नवक, आर्द्र, प्रत्यग्र','यस्य विद्यमानता पूर्वं नासीत्।; \"किमपि नूतनं कार्यम् अस्माभिः कर्तव्यम्।\"','adjective'),(34228,'','आक्रामकता, आक्रामकत्वम्','आक्रामकस्य अवस्था भावः वा।; \"भारतदेशः आक्रामकतया स्पर्धाम् अजयत्।\"','noun'),(34239,'','संस्कारयुक्त','संस्कारस्य संस्कारेण वा सम्बद्धम्।; \"अत्र बालकेभ्यः संस्कारयुक्ता स्थितिः प्राप्यते।\"','adjective'),(34249,'','पातालीय','पातालसम्बन्धी।; \"पुराणेषु पातालीयानां नागानां कथाः सन्ति।\"','adjective'),(34250,'','आसञ्जनम्, संसञ्जनम्, समासञ्जनम्, आश्लेषणम्, संश्लेषणम्, अनुबन्धनम्','संसक्तीकरणस्य क्रिया।; \"सर्वेषां भित्तिपत्राणाम् आसञ्जनं होरायाम् एव भवितव्यम्।\"','noun'),(34252,'','अपराधित्वम्, अपराधिता','अपराधिनः अवस्था।; \"पत्युः अपराधित्वं प्रमाणीकृत्य एव पत्नी विवाहविच्छेदः कर्तुं शक्नोति।\"','noun'),(34253,'','क्रान्तिकारिन्','क्रान्त्या सम्बद्धः।; \"क्रान्तिकारीभिः नेतृभिः राष्ट्रस्य सिंहासनम् अर्जितम्।\"','adjective'),(34215,'','प्रत्यादा, ग्रह्, प्रत्यभिधा','अन्यस्मै दत्ते वस्तुनि पुनः स्वाधिकारस्थापनानुकूलः व्यापारः।; \"अग्रजा गतवर्षे दत्तां शाटिकां प्रत्याददाति।\"','verb'),(34216,'','सदोष, निषेधार्ह, वर्ज्य, परिहार्य, आशङ्कनीय','दोषयुक्तम्।; \"दूरदर्शने सदोषस्य दृश्यस्य दर्शनं निषिद्धम् अस्ति।\"','adjective'),(34218,'','नोआः','यहूदीधर्मस्य कुलपिता यः कुटुम्बेन पशुभिश्च सह चत्वारिंशत् दिनानि यावत् स्वनिर्मिते अर्णवपोते अवसत् तान् जलप्लावनात् अरक्षत् च।; \"नोआः उल्लेखः बायबलग्रन्थे प्राप्यते।\"','noun'),(34220,'','अवकीलकः, रोधः, अवष्टम्भः','वस्तुनः छिद्रं रन्ध्रं वा आच्छादयितुं तस्मिन् स्थाप्यमानं वस्तु।; \"अस्याः कूप्याः अवकीलकः शिथिलः अस्ति।\"','noun'),(34197,'','काचयुक्त','काचेन युक्तम्।; \"पटियालानगरस्य तक्षणकर्म्म तथा काचयुक्ता कला प्रसिद्धा अस्ति।\"','adjective'),(34198,'','अनु, अनुसृत्य','अनुसरणं कृत्वा।; \"सदाचरणस्य चर्चया सर्वे तृप्ताः परं तद् अनु कः आचरति।\"','adverb'),(34201,'','जनसेवकः','सः सामाजिकः कार्यकर्ता यः जनानां प्रजायाः वा सेवां करोति।; \"नेतारः आत्मानं जनसेवकः इति कथयन्ति।\"','noun'),(34206,'','आयत, वितत','यस्य दीर्घीकरणं कृतम्।; \"पितामहः आयतं रज्जुम् आसिनोति।\"','adjective'),(34207,'','विचाराधीन','चिन्तनार्थं प्रलम्बितानि कार्याणि।; \"विचाराधीनान् विषयान् शीघ्रमेव समापनस्य निर्णयः न्यायालयेन स्वीकृतः।\"','adjective'),(34208,'','उल्लम्बित, समुल्लम्बित','यद् लम्बते।; \"छदेः उल्लम्बितां रज्जुं दृष्ट्वा सर्पस्य भ्रमः जातः।\"','adjective'),(34209,'','कार्यकालः, अवधिः','कस्यचित् अधिकारिणः प्रतिनिधेः कृते वा तस्मिन् पदे कार्यं कर्तुं नियोजितः निश्चितः कालः।; \"मुख्यमन्त्रिणः कार्यकालः पञ्च वर्षाणि यावत् भवति।\"','noun'),(34213,'','समीकरणम्','समानायां स्थितौ स्थापनस्य क्रिया।; \"समीकरणेन विना असम्भवम् इदम्।\"','noun'),(34214,'','समीकरणम्','गणितशास्त्रानुसारेण यया क्रियया ज्ञातया राश्या अज्ञाता राशिः ज्ञातुं शक्यते।; \"अयं प्रश्नः समीकरणेन निराकरणीयः।\"','noun'),(34193,'','रायबहादुर','आङ्ग्लशासने श्रेष्ठेभ्यः भारतीयेभ्यः दत्ता उपाधिः।; \"रायबहादुरः मेहरारतनचन्दः ख्यातः आसीत्।\"','adjective'),(34192,'','पञ्चाशताधिकद्विशत','द्विशतम् अधिकं पञ्चाशत्।; \"एतद् युतकं मया पञ्चाशताधिकद्विशतैः रुप्यकैः क्रीतम्।\"','adjective'),(34190,'','स्कन्धपटः','पुरुषैः स्कन्धे धार्यमाणः वस्त्रविशेषः।; \"सम्प्रति स्कन्धपटस्य प्रचलनम् अस्ति।\"','noun'),(34186,'','फलपाकः','सम्पिष्टान् फलान् शर्करायां पक्त्वा निर्मितं मिष्टान्नम्।; \"बालकाः पुरोडाशेन सह फलपाकम् आनन्देन खादन्ति।\"','noun'),(34025,'','उच्छेदवादः','सः सिद्धान्तः यस्य अनुसारेण मृत्योः अनन्तरं सर्वं नश्यति आत्मनः सत्ता अपि न वर्तते।; \"सः उच्छेदवादस्य समर्थकः अस्ति।\"','noun'),(34027,'','उच्छेदवादी','यः उच्छेदवादम् अनुसरति।; \"उच्छेदवादी आत्मनः सत्तायां न विश्वसिति।\"','noun'),(34030,'','उच्छ्वसित','यद् उच्छ्वासेन बहिः आगतम्।; \"रुग्णस्य उच्छ्वसितात् वायोः दुर्गन्धः आयाति।\"','adjective'),(34036,'','धर्मचक्रः','धर्मस्य शिक्षार्थं भगवतः बुद्धस्य धर्मशिक्षारूपं चक्रम्।; \"भगवता बुद्धेन प्रथमं वाराणसीनगरे धर्मचक्रं चालितम्।\"','noun'),(34038,'','सान्द्रता, घनता','सान्द्रस्य अवस्था भावः वा।; \"जलमिश्रणेन दध्नः सान्द्रता न्यूनायते।\"','noun'),(34182,'','भाङ्गडानृत्यम्','पञ्जाबराज्यस्य लोकनृत्यम्।; \"भाङ्गडानृत्यं दृष्ट्वा प्रत्येकः नर्तितुम् इच्छति।\"','noun'),(34178,'','षष्ट्यधिकैकशत','एकशतम् अधिकं षष्टिः।; \"मम ग्रामः इतः षष्ट्यधिकैकशतं सहस्रमानं यावत् दूरे अस्ति।\"','adjective'),(34181,'','आतिथ्यपूर्ण','आतिथ्येन युक्तम्।; \"तस्य आतिथ्यपूर्णम् आचरणं मया विस्मर्तुं न शक्यम्।\"','adjective'),(34175,'','खात, निखात','यद् भूमौ स्थापितम् अस्ति।; \"कृषकेण भूमौ खातं धनं प्राप्तम्।\"','adjective'),(34174,'','समाहित, सङ्केन्द्रित','यद् एकत्रीभूतम्।; \"नदीतटे समाहितान् जनान् जलप्लावनात् स्वस्य रक्षणं करणीयं भवति।\"','adjective'),(34173,'','सङ्केन्द्रणम्','एकस्मिन् स्थाने एकस्मिन् एव समये नैकेषां वस्तूनां एकत्रीकरणस्य क्रिया।; \"वायुमण्डले कौकिलीयस्य वर्धमानं सङ्केन्द्रणं रोधनीयम्।\"','noun'),(34168,'','अभिव्यक्तशील','यः भावान् प्रकटयति।; \"अभिव्यक्तिशीलानां नेतॄणाम् अधिका प्रशंसा भवति।\"','adjective'),(34169,'','सम्भाषणशील','सम्भाषणं क्रियमाणः।; \"सः अतीव सम्भाषणशीलः मनुष्यः अस्ति।\"','adjective'),(34167,'','सम्भाषणशीलता, संवादशीलता','सम्भाषणशीलस्य अवस्था।; \"मातापितृभ्यां पुत्रैः सह सम्भाषणशीलता स्थापितव्या।\"','noun'),(34166,'','पाकशैली','पाकस्य पद्धतिः।; \"प्रत्येकस्य क्षेत्रस्य पाकशैली भिन्ना अस्ति।\"','noun'),(34162,'','प्रारूपयित','यस्य प्रारूपं कृतम्।; \"प्रारूपयितानां वस्तूनाम् आपणे कथं प्रदर्शनं करणीयम्।\"','adjective'),(34160,'','शिक्षकः','यः शिक्ष्यते।; \"मम पुत्रान् तरणं शिक्षयितुं उत्तमस्य शिक्षकस्य अन्वेषणं करोमि।\"','noun'),(34161,'','स्वास्थ्यकेन्द्रम्','शरीरस्य स्वास्थ्यरक्षणार्थम् आवश्यकैः उपकरणैः सुविधाभिश्च युक्तं स्थानम्।; \"इदानींतनीये व्यस्ते जीवने स्वास्थ्यकेन्द्राणाम् आवश्यकता वर्धते।\"','noun'),(34159,'','सप्ताहान्तः','सप्ताहस्य अन्ते।; \"अस्मिन् सप्ताहान्ते अहं बहिः भविष्यामि।\"','noun'),(34156,'','उच्चस्तरीय','उच्चस्तरस्य।; \"इमां समस्यां दूरीकर्तुं सर्वकारेण एका उच्चस्तरीया सभा आयोजिता।\"','adjective'),(34157,'','आह्वानपूर्ण, आह्वानयुक्त','आह्वानेन युक्तम्।; \"आह्वानपूर्णं कार्यम् इदम्।\"','adjective'),(34152,'','विमानसेवा','विमानयानेन गमनागमनस्य उपलब्धता।; \"भारतदेशस्य प्रत्येकस्मिन् नगरे विमानसेवा नास्ति।\"','noun'),(34151,'','शैलाटीय','शैलाटेन सम्बद्धः अथवा शैलाटस्य।; \"बस्तरमण्डलस्य शैलाटीयेषु क्षेत्रेषु आक्रमणं भवति।\"','adjective'),(34150,'','ऐलिफेन्टाद्वीपः','मुम्बईनगर्याः पूर्वस्यां दिशि दशकिलोमीटरं यावत् वर्तमानः द्वीपः।; \"ऐलिफेन्टाद्वीपस्य कन्दराः प्रसिद्धाः सन्ति।\"','noun'),(34149,'','वर्गीकृत','यस्य वर्गीकरणं कृतम्।; \"वर्गीकृतं पर्यायवाचकं समूहं पुनः पश्यतु।\"','adjective'),(34148,'','पञ्चशत','त्रिशतम् अधिकं द्विशतम्।; \"अत्र पञ्चशताः जनाः सुलभतया उपविशन्ति।\"','adjective'),(34123,'','तटीय','तटस्य तटेन सम्बद्धः वा।; \"भारतदेशस्य समुद्रेषु तटीया सुरक्षा वर्धनीया।\"','adjective'),(34125,'','तटरेखा','समुद्रनद्यादीनां जलस्य तथा च तत्रत्याः भूमेः मध्ये वर्तमाना  रेखा।; \"अयं मार्गः कतिचित् दूरं यावत् तटरेखायाः समम् अस्ति।\"','noun'),(34119,'','परासः','परिक्षिप्तेन वस्तुना प्राप्ता दूरता।; \"लोहसुषेः प्रक्षिप्तायाः गुलिकायाः परासः कियान्।\"','noun'),(34120,'','परासः','तद् क्षेत्रं यावत्पर्यन्तं कस्यापि क्रियायाः प्रभावः भवति।; \"ज्वालामुख्याः परासः अनेककिलोमीटरपरिमितः आसीत्।\"','noun'),(34121,'','परासः','विशिष्टेन वस्तुना अभिव्याप्तः स्थानस्य अवधिः।; \"लक्षद्वीपे प्रवालाणां विस्तृतं परासः अस्ति।\"','noun'),(34122,'','ललना','वर्णवृत्तविशेषः।; \"ललनायाः प्रत्येकस्मिन् चरणे भगणः, मगणः तथा द्वौ सगणौ च भवन्ति।\"','noun'),(34118,'','मणिकर्णः','हिमाचले पार्वतीनद्याः तटे स्थितं धार्मिकं स्थानम्।; \"शिवस्य रमणीया भूमिः मणिकर्णः।\"','noun'),(33875,'','भद्रमदा, इरावती','कश्यपऋषेः एका पत्नी।; \"भद्रमदा ऐरावतस्य माता आसीत्।\"','noun'),(34116,'','कोविदारपुष्पम्','विभूषणार्थम् उपयुज्यमानं पुष्पम्।; \"तेन मम कृते कोविदारपुष्पाणां गुच्छः आनीतः।\"','noun'),(34040,'','उत्क्वथनम्, उत्सेचनम्','द्रवपदार्थे अत्युष्णतया बुद्बुदोद्गमनं यावत् उष्णीकरणस्य क्रिया।; \"दुग्धस्य उत्क्वथनं विस्मृत्य शीला सम्भाषणे एव मग्ना जाता।\"','noun'),(34039,'','बुद्बुदाङ्कः','यस्मिन् तापमाने द्रवः क्वथति।; \"कस्मिन्नपि द्रवस्य प्रस्तारे यावत् न्यूनः भारः अस्ति तावत् एव न्यूनः तस्य बुद्बुदाङ्कः भवति।\"','noun'),(34021,'','पक्षः, गरुत्, छदः, पत्रम्, पतत्रम्, तनूरुहम्, शरपक्षः','पक्षिणाम् अवयवविशेषः येन ते डयन्ते।; \"रावणः जटायोः पक्षौ चिच्छेद।\"','noun'),(34014,'','दरीमुखः','रामस्य सेनायां वर्तमानः वानरः।; \"दरीमुखः बलशाली आसीत्।\"','noun'),(34017,'','उच्छादनम्','सुगन्धितेन द्रव्येण शरीरस्य निर्मलीकरणम्।; \"उच्छादनेन विना पिता गृहात् बहिः न गच्छति।\"','noun'),(34018,'','उच्छिष्ट, अवशिष्ट, उच्छेष, उत्त्यक्त, उत्सृष्ट','कस्यचित् वस्तुनः उपयोगं कृत्वा तस्माद् वस्तुनः अवशिष्टं त्यक्तं वस्तु।; \"कर्मकरः उच्छिष्टानां पदार्थानां ग्रहणं व्यमन्यत।\"','adjective'),(34020,'','उच्छिष्टभोजिन्, उच्छिष्टभोक्तृ','अन्येषाम् उच्छिष्टम् अन्नं यः खादति।; \"स्थानकेषु नैके उच्छिष्टभोजिनः भिक्षुकाः दृश्यन्ते।\"','adjective'),(34022,'','उच्छून, उत्पीन, उत्फुल्ल, उद्वृत्त, परिस्फीत, पीन, प्रशून, प्रवृद्ध, शून, स्फीत','यद् तस्य सामान्यात् आकारात् वर्धते।; \"सङ्गीता उच्छूनस्य मुखस्य चिकित्सायै वैद्यस्य समीपं गच्छति।\"','adjective'),(34009,'','उच्चयः','त्रिकोणस्य विरुद्धः भागः।; \"अस्य त्रिकोणस्य उच्चयः तस्य आधारस्य अपेक्षया दीर्घः अस्ति।\"','noun'),(34010,'','उच्चाटनम्','षट्कर्मान्तर्गताभिचारकर्मविशेषः।; \"तस्य तान्त्रिकस्य उच्चाटनं कदापि निष्फलं न भवति।\"','noun'),(34011,'','उच्चारणीय, उच्चार्माण','उच्चारणार्थं यद् योग्यम्।; \"अन्येषां सम्मुखम् उच्चारणीयः शब्दः नास्ति अयम्।\"','adjective'),(34012,'','उच्चार्यमाण','यस्य उच्चारणं क्रियते।; \"उच्चार्यमाणाः शब्दाः अवधातव्याः।\"','adjective'),(34013,'','तरङ्गित, तरङ्गिन्, विलोल, उल्लोल','ऊर्मीणाम् इव चञ्चलः।; \"आतपे तरङ्गितस्य जलस्य शोभा तु अवर्णनीया एव।\"','adjective'),(33998,'','नगरहारनगरम्','भारतदेशस्य वायव्यदिशि वर्तमानं प्राचीनं नगरं यस्य वर्णनं चीनदेशीयेन यात्रिकेण ह्वेनसाङ्गमहोदयेन कृतम्।; \"नगरहारनगरं राज्ञः कपिशस्य अधीने आसीत्।\"','noun'),(34001,'','विरञ्ज्','मनसः असङ्गानुकूलः व्यापारः।; \"प्रतिदिनं कलहेन गृहात् मम मनः विरज्यते।\"','verb'),(34002,'',' ',' ; \"\"','verb'),(34003,'','उच्चारणम्','आस्यप्रयत्नाभ्यां मुखात् व्यक्तैः ध्वनिभिः वाङ्निष्पत्तिः।; \"बालकस्य उच्चारणं शुद्धम् अस्ति।\"','noun'),(34007,'','सुप्तप्रलपितम्','सुप्तावस्थायां जल्पनस्य भाषणस्य क्रिया।; \"अग्रजायाः सुप्तप्रलपितं श्रुत्वा अहम् अबिभयम्।\"','noun'),(34008,'','श्रेष्ठ','यः आचारविचारादीनां दृष्ट्या महान् वर्तते।; \"अस्माभिः अस्माकं पूर्वजानां श्रेष्ठानाम् आदर्शानां पालनं कर्तव्यम्।\"','adjective'),(33985,'','प्रमोक्षणम्','ग्रहणस्य समाप्तिः।; \"प्रमोक्षणस्य अनन्तरमेव माता भोजनं करिष्यति।\"','noun'),(33990,'','विवस्त्रय','वस्त्रापनयनानुकूलः व्यापारः।; \"मत्ता स्त्री अकस्मात् विवस्त्रयति।\"','noun'),(33994,'','अवशेषः, अतिशेषः, परिशेषः, परिशेषम्, शिष्टम्','अवशिष्टं वस्तु।; \"मम अवशेषः नावश्यकः।\"','noun'),(33982,'','उग्रः','ज्योतिःशास्त्रानुसारं पूर्वफाल्गुनीपूर्वाषाढपूर्वभाद्रपदमघाभरण्यात्मकः नक्षत्रगणसमूहः।; \"उग्रस्य स्वभावः एव प्रबलः मन्यते।\"','noun'),(33983,'','उग्रः','दानवविशेषः।; \"उग्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33984,'','उग्रः','धृतराष्ट्रस्य शतपुत्रेषु एकः।; \"उग्रस्य उल्लेखः महाभारते प्राप्यते।\"','noun'),(33947,'','मुचुकुन्दः, छत्रवृक्षः, चित्रकः, प्रतिविष्णुकः, बहुपुत्रः, सुदलः, परिवल्लभः, सुपुष्पः, अर्घ्यार्हः, लक्षणकः, रक्तप्रसवः','वृक्षविशेषः।; \"मुचुकुन्दस्य वल्कलः पुष्पाणि च भेषजरूपेण उपयुज्यन्ते।\"','noun'),(33981,'','उग्रः','क्षत्रियपित्रा शूद्रमातरि उत्पन्नः सङ्करः जातिविशेषः।; \"उग्राणां स्वभावः उग्रः क्रूरश्च भवतीति मन्यते।\"','noun'),(33973,'','स्वधा','दक्षस्य कन्या।; \"स्वधा पितॄणां पत्नी अस्तीति मन्यते।\"','noun'),(33969,'','उच्छेत्ता, उन्मूलयिता','यः उन्मूलनस्य कार्यं करोति।; \"तब्बूनामकः उच्छेत्ता न जाने कुत्र गतः।\"','noun'),(33968,'','उपवत्स्यद्भक्तम्','उपवासस्य आरम्भात् पूर्वं कृतं भोजनम्।; \"यदा अहं जागरिता तदा माता उपवत्स्यद्भक्तम् अकरोत्।\"','noun'),(33955,'','उकलैदिसः','युनानीः गणितज्ञः।; \"रेखागणितस्य प्रवर्तकः उकलैदिसः।\"','noun'),(33965,'','इक्षुचूषणम्, इक्षुचोषणम्, इक्षुशोषणम्','इक्षुम् आकृष्य पानम्।; \"किं भवता क्षेत्रं गत्वा इक्षुचूषणस्य आनन्दः प्राप्तः।\"','noun'),(33948,'','मुचुकुन्दपुष्पम्','मुचुकुन्दस्य पुष्पम्।; \"मुचुकुन्दपुष्पस्य उपयोगः भेषजरूपेण भवति।\"','noun'),(33953,'','वमय, वामय, उद्वमय, उद्वामय, निर्वमय, निर्वामय, विनिर्वमय, विनिर्वामय, उद्गारय, उत्क्षेपय, उत्तारय, क्षेवय','वमनप्रेरणानुकूलः व्यापारः।; \"विषभुजं रुग्णं वैद्यः औषधं दत्त्वा वमयति।\"','verb'),(33873,'','इरावत्','पर्वतविशेषः।; \"सः इरावतम् आरोढुम् इच्छति।\"','noun'),(33874,'','ऐरावतः','नागविशेषः।; \"ऐरावतस्य वर्णनं पौराणिकासु कथासु प्राप्यते।\"','noun'),(33942,'','उच्चाटित','यस्य उच्चाटनं जातम्।; \"उच्चाटितस्य पुरुषस्य क्रियायां तान्त्रिकस्य अवधानं अस्ति।\"','adjective'),(33940,'','ईश्वरपरायण','ईश्वरनिष्ठः।; \"ईश्वरपरायणं मनुष्यम् ईश्वरः सर्वदा रक्षति।\"','adjective'),(33939,'','ईशानः','एकादशेषु रुद्रेषु एकः।; \"ईशानस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33936,'','ईर्ष्यकः','सः नपुंसकः यस्य कामवासना कस्यचित् सम्भोगं दृष्ट्वा एव उत्तेजिता भवति।; \"ईर्ष्यकः प्रतिदिनं कामोत्तेजकान् चित्रपटान् पश्यति।\"','noun'),(33935,'','ईर्ष्यणीय, स्पृहणीय','ईर्ष्यायै योग्यम्।; \"तस्याः ईर्ष्यणीयेन सौन्दर्येण सख्यः दुःखिताः जाताः।\"','adjective'),(33931,'','ईतिः','कृषिक्षेत्रस्य षट् उपद्रवाः।; \"अतिवृष्टिः अनावृष्टिः शलभाः मूषिकाः खगाः प्रत्यासन्नाः राजानश्च एताः ईतयः सन्ति।\"','noun'),(33928,'','ईक्षित, आलोकित, अवलोकित','यद् दृष्टम्।; \"ईक्षितानि पुस्तकानि शिक्षकेण प्रत्यर्पितानि।\"','adjective'),(33924,'','ईहामृगः','चतुरङ्कात्मकः दशरुपकेषु एकः भेदः यस्मिन् दिव्यः नायकः दिव्या नायिका च भवतः।; \"ईहामृगे मुख्यत्वेन नायिकायाः वीरतायाः प्रदर्शनं भवति।\"','noun'),(33927,'','हस्तरेखाविद्','हस्तरेखाणां ज्ञाता।; \"हस्तरेखाविदः अनुसारेण मम जीवनरेखा लघ्वी अस्ति।\"','noun'),(33922,'','अत्र, इह','अस्मिन् स्थाने।; \"गतावसरे वयम् अत्र एव अमिलाम।\"','adverb'),(33923,'','ओष्ठरागः','प्रसाधनसामग्रीविशेषः येन महिलाः ओष्ठौ रञ्जयन्ति।; \"इदानीन्तने काले आपणे प्रायः प्रत्येकस्य वर्णस्य ओष्ठरागाः लभ्यन्ते।\"','noun'),(33921,'','नौरज्जुः, नौगुणः','वातवसनोत्तलनस्य रज्जुः।; \"पोतवाहः नौरज्ज्वा नौकापटं बध्नाति।\"','noun'),(33918,'','इसमाईली','शीयासम्प्रदायस्य शाखाभेदः।; \"शीयासम्प्रदायस्य द्वितीया बृहत् शाखा इसमाईली अस्ति।\"','noun'),(33916,'','जलशोषणी','जलादयः द्रवाः शोषयितुं निर्मितः छिद्रयुक्तः वस्तुविशेषः।; \"आपणे नैकप्रकारकाः जलशोषण्यः प्राप्यन्ते।\"','noun'),(33914,'','इष्टता, इष्टत्वम्','इष्टस्य अवस्था भावः वा।; \"इष्टता अनिष्टता च मनुष्यस्य सुखदुःखयोः कारणं वर्तते।\"','noun'),(33911,'','विज्ञापित, प्रकाशित','विज्ञापनेन सूचितम्।; \"विज्ञापितानां भेषजानां सेवनं मा कुरु।\"','adjective'),(33905,'','इषीका, इशीका, इषिका, ईषिका','गजस्य अक्षिगोलः।; \"अस्य गजस्य इषीका रक्तवर्णीया अस्ति।\"','noun'),(33902,'','सङ्केतः','अन्येभ्यः गोपयित्वा परस्परयोः सूचनम्।; \"सः सैनिकः सहकारिणः सङ्केतस्य प्रतीक्षां करोति।\"','noun'),(33891,'','इलावृत्तम्','जम्बूद्वीपस्य नववर्षान्तर्गतवर्षेषु एकः अन्येषाम् अपेक्षया उन्नततमः अस्ति।; \"इलावृत्तस्य वर्णनं पुराणेषु अस्ति।\"','noun'),(33888,'','विश्वदेवः','देवताविशेषः।; \"नान्दीमुखश्राद्धे विश्वदेवः पूज्यते।\"','noun'),(33887,'','पुरुरवाः','देवताविशेषः।; \"पुरुरवाः पार्वणश्राद्धे पूज्यते।\"','noun'),(33886,'',' ','  ; \"\"','adjective'),(33884,'','इला','वैवस्वतमनुकन्या।; \"पुरूरवाः इलायाः पुत्रः आसीत्।\"','noun'),(33885,'','पुरूरवाः','प्राचीनः चन्द्रवंशीयः राजा।; \"राज्ञः पुरुरवसः इन्द्रस्य अप्सरसः ऊर्वश्याः च प्रेमकथा प्रसिद्धा अस्ति।\"','noun'),(33882,'','इलविला','पुलस्त्यपत्नी।; \"इलविलायाः वर्णनं पौराणिकेषु ग्रन्थेषु अस्ति।\"','noun'),(33881,'','इलविला','विश्वश्रवसः पत्नी।; \"इलविला कुबेरस्य माता आसीत्।\"','noun'),(33880,'','वाह्लीकः','गन्धर्वविशेषः।; \"वाह्लीकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33877,'','कर्दमः','प्रजापतेः अपत्यम्।; \"कर्दमः वाह्लीकदेशस्य राजा आसीत्।\"','noun'),(33876,'','इरावतीनदी','ब्रह्मदेशे वर्तमाना नदी।; \"ब्रह्मदेशस्य अन्यासु नदीषु इरावतीनदी दीर्घा वर्तते।\"','noun'),(33871,'','इरावत्','अर्जुनस्य पुत्रः।; \"नागकन्या उलूपी इरावतः माता आसीत्।\"','noun'),(33872,'','इरावत्','सर्पविशेषः।; \"इरावतः उल्लेखः पौराणिकासु कथासु प्राप्यते।\"','noun'),(33869,'','इरा','बृहस्पतेः माता।; \"इरायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33867,'','प्रेषणम्','एकस्मात् स्थानात् अन्यस्मिन् स्थाने किमपि वस्तु प्रेरणस्य क्रिया।; \"भवता पत्रस्य प्रेषणे किमर्थं विलम्बः जातः।\"','noun'),(33866,'','ईर्षित','यस्मै ईर्ष्यते।; \"सा ईर्षितायाः प्रतिवेशिन्याः मुखमपि द्रष्टुं न इच्छति।\"','adjective'),(33860,'','कुम्भः, गजकुम्भः','गजस्य मस्तकम्।; \"मन्दिरं पुरतः स्थितम् अलङ्कृतं कुम्भं बालकः स्पृशति।\"','noun'),(33864,'','निर्दिष्टसङ्ख्या','कस्यापि कार्यस्य सभायाः वा सञ्चालनार्थं सदस्यानाम् आवश्यकी न्यूनतमा सङ्ख्या।; \"निर्दिष्टसङ्ख्यायाः अभावात् नूतनः विधेयकः न स्वीकृतः।\"','noun'),(33859,'','इब्राहीमः','पैगम्बरविशेषः।; \"यहूदीयवनख्रीष्टीयाः इब्राहीमे स्वत्वं ज्ञापयन्ति।\"','noun'),(33828,'','इटालिकशैली','लेखनपद्धतिविशेषः।; \"इटालिकशैल्याम् अक्षराणि वक्राणि सन्ति।\"','noun'),(33832,'','इडा','वैवस्वतस्य मनोः द्वितीया पत्नी।; \"इडायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33833,'','इडा','दक्षस्य कन्या।; \"इडायाः विवाहः कश्यपऋषिणा सह अभवत्।\"','noun'),(33834,'','इडा','आकाशस्य अधिष्ठात्री देवी।; \"इडायाः उल्लेखः धर्मग्रन्थेषु प्राप्यते।\"','noun'),(33835,'','इडा','यज्ञकर्मणि दीयमानः आहुतिविशेषः।; \"प्रयाजानुयाजयोः मध्ये इडा अर्प्यते।\"','noun'),(33836,'','इडापात्रम्, इडापात्री','यज्ञपात्रविशेषः।; \"इडापात्रेण आहुतिम् अर्पयतु इति पण्डितेन यजमानाय कथितम्।\"','noun'),(33837,'','यज्ञपात्रम्','यज्ञकर्मणि उपयुज्यमानं पात्रम्।; \"अस्मिन् आपणे नैकानि यज्ञपात्राणि लभन्ते।\"','noun'),(33841,'',' ',' ; \"\"','noun'),(33843,'','इतस्ततः','नियोजितस्थाने अभावः अन्यत्र च विद्यमानत्वम्।; \"गृहे वस्तूनि इतस्ततः विकीर्णानि।\"','adverb'),(33844,'','गोकुलम्','गवां समूहः।; \"गोपः गोकुलम् अनुसरति।\"','noun'),(33848,'','आनुषङ्गिक, संयोगजन्य','यद् अनुषङ्गेन जायते।; \"तेन सह जातं मम आनुषङ्गिकं मेलनम् अहं विस्मर्तुं न शक्नोमि।\"','adjective'),(33849,'','सूचनापत्रम्','सूचनया युक्तं पत्रम्।; \"सूचनापत्रं पठित्वा आरक्षकाः सतर्काः जाताः।\"','noun'),(33850,'','इत्थम्','अनेन प्रकारेण।; \"इत्थं सः प्रतिदिनं कार्यरतः अस्ति।\"','adverb'),(33856,'','इल्वला','पञ्चभिः तारकाभिः युक्तः तारकासमूहः।; \"मृगनक्षत्रस्य उपरितने भागे इल्वला स्थिता अस्ति।\"','noun'),(33857,'','इब्रानी, यहूदी','पैगम्बरस्य इब्राहीमस्य वंशजाः।; \"अत्र केचन इब्रान्यः निवसन्ति।\"','noun'),(33768,'','इन्द्रसभा','स्वर्गस्थितः इन्द्रस्य कक्षः।; \"इन्द्रसभायाम् अप्सरसः नृत्यन्ति इति कथ्यते।\"','noun'),(33769,'','ताम्रजाक्षः','श्रीकृष्णस्य पुत्रः।; \"ताम्रजाक्षः सत्यभामायाः गर्भात् उत्पन्नः।\"','noun'),(33767,'','ताम्रध्वजः','राज्ञः मयूरध्वजस्य पुत्रः यः भगवतः भक्तः आसीत्।; \"ताम्रध्वजः धार्मिकः वीरश्च आसीत्।\"','noun'),(33821,'','इच्छाभोजनम्','रुचेः अनुसारं भोजनम्।; \"धनिकः पितुः श्राद्धे पण्डितानां कृते इच्छाभोजनस्य व्यवस्थाम् अकरोत्।\"','noun'),(33825,'','प्रचलनम्','कस्यापि वस्तुनः व्यवहारे उपयोगस्य क्रिया।; \"उद्योगसंस्थायाः नूतनानाम् उत्पादनानां प्रचलने किमर्थम् एतावान् विलम्बः।\"','noun'),(33819,'','इच्छापत्ररहित','येन इच्छापत्रं न लिख्यते।; \"इच्छापत्ररहितस्य पुरुषस्य पुत्रेषु धनार्थं परस्परेषु कलहः प्रारब्धः।\"','adjective'),(33817,'','उत्तरम्','वैदिककालीनः गीतविशेषः।; \"उत्तरस्य विषये गायकः अधिकं जानाति।\"','noun'),(33818,'','उत्तरः','काव्यालङ्कारविशेषः।; \"उत्तरे उत्तरं श्रुत्वा एव प्रश्नस्य अनुमानं कर्तुं शक्यते।\"','noun'),(33816,'','उत्तरः','राज्ञः विराटस्य पुत्रः।; \"उत्तरस्य भगिनी उत्तरा अभिमन्युना सह परिणिता।\"','noun'),(33814,'','इच्छाचारिन्','स्वेच्छया यः भ्रमति।; \"सः इच्छाचारी योगी कदापि कुत्रापि गच्छति।\"','adjective'),(33815,'','इच्छाफलम्','गणितशास्त्रे कस्यापि समस्यायाः समाधानम्।; \"शिक्षकः छात्रस्य इच्छाफलेन सन्तुष्टः आसीत्।\"','noun'),(33812,'','क्षीरकन्दः, क्षीरविदारी','कन्दविशेषः यस्मात् दुग्धं स्रवति।; \"वैद्यः क्षीरकन्दस्य दुग्धेन भेषजं निर्माति।\"','noun'),(33811,'','इक्षुरसः','इक्षोः रसः।; \"इक्षुरसः स्वादु पौष्टिकं च पेयम् अस्ति।\"','noun'),(33810,'','इक्षुमालिनी','पुराणेषु वर्णितः नदीविशेषः।; \"इक्षुमालिनी इन्द्रपर्वतात् प्रभवति।\"','noun'),(33809,'','प्राग्वंशः','यज्ञशालायां यजमानसदस्यादीनां निवासस्थानम्।; \"यजमानः प्राग्वंशं स्वच्छं करोति।\"','noun'),(33808,'','इक्षुमती','फर्रूखाबादनगरसमीपा नदी।; \"इक्षुमत्याः तटे आर्याणां निवासः आसीत्।\"','noun'),(33807,'','इक्षुज','इक्षोः इक्षुरसेन वा निर्मिताः पदार्थाः।; \"गुडशर्करादयः इक्षुजाः खाद्याः सन्ति।\"','adjective'),(33806,'','इक्षुकाण्डम्, इक्षुदण्डम्','इक्षोः दण्डः।; \"कृषकः शुष्कम् इक्षुकाण्डं ज्वालयति।\"','noun'),(33800,'','तार्प्यम्','तृपया निर्मितं वस्त्रम्।; \"तार्प्यं वैदिककाले उपयुज्यते स्म।\"','noun'),(33798,'',' ',' ; \"\"','adjective'),(33799,'','तृपा','लताप्रकारः।; \"वैदिककाले तृपायाः तन्तुभिः वस्त्राणि निर्मीयन्ते स्म।\"','noun'),(33794,'','तार्क्ष्यप्रसवः, अश्वकर्णवृक्षः','शङ्कुवृक्षस्य जातेः वृक्षविशेषः।; \"अस्मिन् स्थाने तार्क्ष्यप्रसवस्य आधिक्यम् अस्ति।\"','noun'),(33789,'','उपयाजः','कश्यपपुत्रः पुराणकालीनः ऋषिभेदश्च।; \"तारण्याः गर्भात् उपयाजस्य उत्पत्तिः जाता।\"','noun'),(33791,'','तारापीडः','पुराणकालीनः राजा यस्य अयोध्यायां राज्यम् आसीत्।; \"तारापीडस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(33788,'','याजः','कश्यपपुत्रः पुराणकालीनः ऋषिभेदश्च।; \"याजः उपयाजश्च सहोदरौ आस्ताम्।\"','noun'),(33787,'','तारणी','कश्यपऋषेः पत्नी।; \"तारण्याः गर्भात् याजोपयाजौ जातौ।\"','noun'),(33781,'','तारकमन्त्रः','ओम् रामाय नमः इति भगवतः रामस्य षडाक्षरी मन्त्रः।; \"गुरुः शिष्याय तारकमन्त्रं कथयति।\"','noun'),(33780,'','तारः, तारवृत्तः, तारकः','वर्णवृत्तविशेषः।; \"तारे अष्टादश वर्णाः सन्ति।\"','noun'),(33779,'','इन्धनगृहम्','तद् स्थानं यत्र इन्धनं स्थाप्यते।; \"वृष्टेः पूर्वं इन्धनगृहं इन्धनेन पूर्यते।\"','noun'),(33775,'','इन्द्रियार्थवादः, भोगवृत्तिः','इन्द्रियैः सुखोपभोगस्य वृत्तिः।; \"जीवेषु इन्द्रियार्थवादः प्राकृतिकः एव।\"','noun'),(33774,'','इन्द्रियार्थवादः','दार्शनिकः सिद्धान्तविशेषः यस्यानुसारेण सर्वं ज्ञानम् इन्द्रियैः एव प्राप्यते।; \"अधिकाः जनाः इन्द्रियार्थवादस्य समर्थकाः सन्ति।\"','noun'),(33771,'',' ',' ; \"\"','noun'),(33773,'','इन्द्रियज','इन्द्रियात् जातः।; \"मनुष्ये नैकाः इन्द्रियजाः कामनाः सन्ति।\"','adjective'),(33770,'','ताम्रपक्षा','श्रीकृष्णस्य पुत्री।; \"ताम्रपक्षायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33756,'',' ',' ; \"\"','noun'),(33757,'','तामरसः','वर्णवृत्तविशेषः।; \"तामरसस्य प्रत्येकस्मिन् चरणे एकः नगणः द्वौ जगणौ तथा एकः यगणः च भवति।\"','noun'),(33759,'','इन्द्रभाषः','इन्द्रतालस्य षट्सु भेदेषु एकः।; \"सङ्गीतज्ञः इन्द्रभाषस्य विषये कथयति।\"','noun'),(33760,'','इन्द्रवंशा','द्वादशवर्णयुक्तः वर्णवृत्तविशेषः।; \"इन्द्रवंशायाः प्रत्येकस्मिन् चरणे द्वौ तगणौ एकः जगणः तथा एकः रगणश्च भवति।\"','noun'),(33761,'','इन्द्रलुप्तः, इन्द्रलुप्तम्, केशघ्नम्, खालत्यम्','खल्वाटत्वस्य व्याधिः।; \"सः इन्द्रलुप्तेन पीडितः।\"','noun'),(33764,'','इन्द्रवस्तिः','ऊरोः अस्थि।; \"दुर्घटनायां मनोजस्य इन्द्रवस्तिः क्षतिग्रस्तः जातः।\"','noun'),(33765,'','इन्द्रवृद्धा','व्रणविशेषः।; \"पितामहः इन्द्रवृद्धां लिम्पति।\"','noun'),(33749,'','इन्द्रजालम्','अर्जुनस्य अस्त्रम्।; \"अर्जुनः शत्रौ इन्द्रजालं प्राहरत्।\"','noun'),(33751,'','इन्द्रधनुषीय','इन्द्रधनुषा सम्बद्धः।; \"लोकनर्तकैः मञ्चे इन्द्रधनुषीयाः वर्णाः प्रदर्शिताः।\"','adjective'),(33752,'','इन्द्रत्वम्','इन्द्रस्य प्रतिष्ठा शक्तिः च।; \"तपः कुर्वन्तं ऋषिं दृष्ट्वा इन्द्रत्वस्य नाशस्य विचारैः इन्द्रः भयग्रस्तः जातः।\"','noun'),(33753,'','इन्द्रध्वजः','इन्द्रस्य ध्वजः।; \"लोककलाकृतौ इन्द्रध्वजस्य विशेषं महत्वं वर्तते।\"','noun'),(33754,'','इन्द्रध्वजः','भारतस्य प्राचीनः उत्सवविशेषः।; \"इन्द्रध्वजे प्रायः नृत्यं गानं च भवति।\"','noun'),(33755,'','इन्द्रध्वजः','भाद्रपदशुक्लद्वादश्यां वर्षायाः तथा कृषेः वर्धनार्थं निर्वत्यमानः उत्सवः।; \"इन्द्रध्वजे इन्द्राय ध्वजम् अर्प्यते।\"','noun'),(33747,'','इन्द्रकीलः','हिमालयपर्वतस्य तद् शिखरं यत्र अर्जुनेन अस्त्रशस्त्राणां प्राप्त्यर्थं तपः आचरितम्।; \"मार्गदर्शकेन इन्द्रकीलः सूचितः।\"','noun'),(33742,'','इन्द्रः','द्वादशसु आदित्येषु एकः।; \"इन्द्रस्य वर्णनं पौराणिकासु कथासु प्राप्यते।\"','noun'),(33743,'','इन्द्रः','व्याकरणशास्त्रस्य प्राचीनः विद्वान्।; \"व्याकरणशास्त्रस्य प्रथमः आचार्यः इन्द्रः।\"','noun'),(33737,'','विमानशास्त्रम्, विमानविद्या','यस्मिन् शास्त्रे वायुयानस्य निर्माणस्य उड्डयनस्य च वैज्ञानिकम् अध्ययनं क्रियते।; \"दीपकः विमानशास्त्रस्य छात्रः अस्ति।\"','noun'),(33744,'','इन्द्रः','छन्दोविशेषः।; \"एतत् छन्दः इन्द्रस्य उदाहरणम्।\"','noun'),(33745,'','इन्द्रः','दक्षिणनेत्रस्य तारकम्।; \"मम इन्द्रे श्वेतं चिह्नम् अस्ति।\"','noun'),(33741,'','इन्दुवारः','ज्योतिषशास्त्रानुसारेण जन्मपत्रिकायां तृतीये षष्ठमे द्वादशे स्थाने ग्रहाणां सः संयोगः यः पीडादायकः मन्यते।; \"दैवज्ञः इन्दुवारस्य दुष्प्रभावनाशस्य उपायान् सूचयति।\"','noun'),(33740,'','चन्द्रमुखी','चन्द्रमसः इव मुखं यस्याः।; \"तां चन्द्रमुखीं युवतीम् एकवारं मेलितुम् इच्छामि।\"','adjective'),(33739,'','चन्द्रविजयः','एकः राजा।; \"पत्न्याः इन्दुमत्याः कारणात् चन्द्रविजयः मोक्षं प्राप्तवान्।\"','noun'),(33738,'','इन्दुमती','राज्ञः अजस्य पत्नी।; \"इन्दुमत्याः उल्लेखः पौराणिकासु कथासु प्राप्यते।\"','noun'),(33736,'','वैमानिकः','यः विमानयानेन यात्रां करोति विमानयानं चालयति वा।; \"शङ्कनीयः वैमानिकः विमानयानात् अवतारितः।\"','noun'),(33734,'','इन्दुमती','राज्ञः चन्द्रविजयस्य पत्नी।; \"इन्दुमती धार्मिकी स्त्री आसीत्।\"','noun'),(33735,'','वैमान','विमानस्य विमानेन वा सम्बद्धः।; \"वैमान्या आपत्त्या विमानस्य विलम्बः शक्यः।\"','adjective'),(33727,'','नदीकान्तः, हिज्जलवृक्षः, निचुलः, इज्जलः, पिचुलः, अम्बुजः, घनदः, कान्तः, जलजः, दीर्घपत्रकः, नदीलः, रक्तकः, कार्मुकः','सांवत्सरः वृक्षः यः नदीतटे समुद्रतटे वा प्राप्यते।; \"नियमकर्ता नदीकान्तस्य छेदनं कर्तुं सम्मतः नास्ति।\"','noun'),(33721,'','आहित, न्यस्त','यद् न्यासरूपेण स्थापितम्।; \"आहितान् अलङ्कारान् मोचयितुं कृषकः अगच्छत्।\"','adjective'),(33724,'','आह्निकम्','प्रत्येकस्मिन् दिने विशिष्टे समये क्रियमाणं धार्मिकं कार्यम्।; \"पितामहस्य आह्निके रामायणपठनस्य अपि समावेशः अस्ति।\"','noun'),(33706,'','आहार्य','हर्तुं योग्यम्।; \"यात्रासमये आहार्याणि वस्तूनि रक्षितव्यानि।\"','adjective'),(33707,'','हर्ता','यः हरति चोरयति वा।; \"हर्तॄणां गणः आरक्षकैः गृहितः।\"','adjective'),(33710,'','आहवनीयः','यज्ञादिकर्मणि उपयुज्यमानेषु अग्नेः त्रिषु प्रकारेषु एकः।; \"आहवनीयस्य आवाहनेन यज्ञस्य प्रारम्भः कृतः।\"','noun'),(33711,'','आहवनीय','यस्य आहुतिः दीयते।; \"पण्डितेन आहवनीयानां द्रव्याणाम् आहुतिः दत्ता।\"','adjective'),(33715,'','आहारशास्त्रम्','विज्ञानशास्त्रस्य सा शाखा यस्यां खाद्यानां गुणदोषाणां तेषु वर्तमानानां पोषकतत्त्वानां विवेचनं भवति।; \"मानसी आहारशास्त्रे विद्यावाचस्पति इति उपाधिः असम्पादयत्।\"','noun'),(33716,'','आहारशास्त्रज्ञः','यः आहारशास्त्रस्य ज्ञाता अस्ति।; \"आहारशास्त्रज्ञेन शरीरस्य कृते आवश्यकानां तत्त्वानां विषये सूचना कृता।\"','noun'),(33717,'','आहारिकः','जैनमतानुसारेण आत्मना सम्बन्धितेषु पञ्चशरीरेषु एकः।; \"आहारिकः आत्मनः भिन्नः अस्ति।\"','noun'),(33718,'',' ','  ; \"\"','noun'),(33719,'','आहार्यम्','वैद्यकशास्त्रानुसारेण सः व्याधिः यः शल्यक्रियया विना न उपशमति।; \"आहार्येण पीडितस्य रुग्णस्य समीपे शल्यक्रियार्थं धनं नास्ति।\"','noun'),(33720,'','आहार्य्यः','अभिनयस्य चतुर्षु प्रकारेषु भूषादिना रचितः एकः अभिनयप्रकारः।; \"आहार्य्ये सः निपुणः आसीत्।\"','noun'),(33699,'','गुणनीयम्','सः अङ्कः यस्य गुणनं क्रियते।; \"यदि गुणनीयं पञ्चाशत् तथा गुणनाङ्कम् पञ्च इति अस्ति तर्हि गुणनफलं कति भविष्यति।\"','noun'),(33700,'','आघातित','यस्मिन् आघातः जातः।; \"आघातितं काष्ठं भग्नं जातम्।\"','adjective'),(33697,'','आस्वादनीय','आस्वादनार्हः।; \"इदं खाद्यं दृष्ट्वा एव आस्वादनीयं न मन्यते।\"','adjective'),(33698,'','आस्वादित, स्वादित','यस्य रुचिः अनुभूता।; \"शबरी रामाय आस्वादितानि एव बदरीफलानि अददात्।\"','adjective'),(33696,'','आस्वादनम्','केषामपि विषयादीनाम् उपभोगस्य क्रिया।(लाक्षणिकः प्रयोगः); \"परनिन्दायाः आस्वादनं यः करोति स एव तस्य मधुरतां जानाति।\"','noun'),(33691,'','आस्रवः','पच्यमानस्य ओदनस्य उपरितनः फेनः।; \"आस्रवः पात्रात् बहिः उद्गच्छति।\"','noun'),(33692,'','आस्रवः','जैनमतानुसारेण आत्मनः शुभाशुभाः गतयः।; \"कर्मानुसारम् आस्रवः निर्धार्यते।\"','noun'),(33694,'','शब्दायमान','यद् शब्दं करोति।; \"शब्दायमानानां वाहनानां समीपतः गमनेन भासते यद् कर्णौ निष्क्रियौ भविष्यतः।\"','adjective'),(33695,'','आस्वादनम्','कमपि वस्तु मुखे स्थापयित्वा तस्य स्वादज्ञानस्य क्रिया।; \"पाकगृहात् ओदनविशेषस्य सुगन्धेन तस्य आस्वादनं कर्तुम् इच्छा जाता।\"','noun'),(33689,'','आस्फोटनम्','आस्फोटस्य क्रिया।; \"वीणायाः मधुरेषु तानेषु मध्ये पटहवादकेन वादितेन आस्फोटनेन श्रोतारः आकृष्टाः जाताः।\"','noun'),(33690,'','रक्तप','रक्तं पिबति इति।; \"मशकमत्कुणादयः रक्तपाः सन्ति।\"','adjective'),(33687,'','आस्फोटः','आघातेन उत्पन्नः शब्दः।; \"आस्फोटं श्रुत्वा माता अन्तः आगता।\"','noun'),(33688,'','आस्फोटनम्','सङ्गीतशास्त्रे पटहादिषु वाद्येषु आघातनेन जायमानः शब्दः।; \"सङ्गीतशास्त्रं पठितेन बालकेन आस्फोटनं ज्ञातम्।\"','noun'),(33685,'','आस्पदम्','जन्मपत्रिकायां दशमं स्थानम्।; \"पुत्र्याः आस्पदं प्रबलम् अस्ति।\"','noun'),(33681,'','आस्तरणम्, कुशासनम्','यज्ञवेदिकायाम् आस्तीर्यमाणं कुशस्य आसनम्।; \"पण्डितः आस्तरणे काष्ठं स्थापयति।\"','noun'),(33682,'','आस्तारपङ्क्तिः','चतुर्विंशतिवर्णयुक्तं वैदिकं छन्दः।; \"आस्तारपङ्क्तेः प्रथमे चतुर्थे च चरणे द्वादश तथा द्वितीये तृतीये च चरणे अष्ट वर्णाः भवन्ति।\"','noun'),(33663,'','आसारः','यद् आक्रमणं शत्रुं परिश्रित्वा क्रियते।; \"अभिमन्युः आसारे उपहतः।\"','noun'),(33664,'','आसारः, धारासम्पातः, वेगवृष्टिः','अतिवेगेन जायमाना वृष्टिः।; \"घण्टाद्वयात्मकेन आसारेण नगरे सर्वत्र जलप्लावनं जातम्।\"','noun'),(33650,'',' ','   ; \"\"','noun'),(33651,'','आसनम्','उपवेशनस्य विशिष्टा पद्धतिः।; \"भोजनसमये आसनं सम्यक् भवेत्।\"','noun'),(33652,'','आसनी','उपवेशनार्थं वस्त्रकुशचर्मादिभिः निर्मितम् एकं लघु आसनम्।; \"माता पूजायाः आसन्यां अन्यं कमपि उपवेष्टुं निषेधयति।\"','noun'),(33654,'','आश्रि, समाश्रि, संश्रि, अपाश्रि, अभिप्रपद्, अभिश्रि, आस्था, निगम्, भज्, निविश्, प्रविश्, प्रत्युत्सद्, प्रक्रम्','कस्यचन मनुष्यस्य वा कस्मिंश्चन स्थाने वा शरणस्वीकरणानुकूलः व्यापारः।; \"वर्षायाः त्रातुं सः समीपस्थं गृहम् आश्रयत्।\"','verb'),(33655,'','आसवः','फलान् निष्पीड्य निर्मितः एकः मद्यविशेषः।; \"आसवः तावत् मादकः न भवति।\"','noun'),(33658,'','आसवः','उत्तेजकः बलवर्धकः वा पदार्थः।; \"वैद्येन दत्तेन आसवेन तस्य दुर्बलता नष्टा जाता।\"','noun'),(33660,'','आसवनम्','कमपि द्रव्यम् उष्णीकृत्य तेन प्राप्तं बाष्पं शीतं कृत्वा तस्य बाष्पस्य पुनः द्रव्ये परिवर्तनस्य क्रिया।; \"रसायनशास्त्रे शुद्धिकरणस्य आसवनम् एकः मुख्यः उपायः।\"','noun'),(33662,'','चालनी','आसुतेः यन्त्रम्।; \"यन्त्रागारस्य चालन्यां दोषनिर्माणेन आसवः न भवति।\"','noun'),(33680,'','आस्तरणम्','वस्त्रादीन् विस्तीर्य तेषाम् आच्छादनस्य क्रिया।; \"माता आस्तरणे व्यस्ता अस्ति।\"','noun'),(33678,'','आसेधः, बन्धः, बन्धनम्','कस्यापि मनुष्यस्य रक्षणार्थं गोपनार्थं वा कृता व्यवस्था।; \"अस्य भागस्य दुर्वृत्तस्य आसेधः कृतः।\"','noun'),(33673,'','आसुतिः','आसवस्य कार्यम्।; \"लालाः इदानीम् आसुतिं त्यक्त्वा अन्यद् किञ्चिद् कार्यं करोति।\"','noun'),(33671,'','आसारितगीतम्','वैदिकगीतविशेषः।; \"महात्मा आसारितगीतस्य गायने मग्नः अस्ति।\"','noun'),(33665,'','मेघमाला','स्कन्दस्य अनुचरी मातृका।; \"मेघमालायाः वर्णनं स्कन्दपुराणे प्राप्यते।\"','noun'),(33635,'','आश्रयी','कस्यचित् आश्रयेण यः वर्धते।; \"श्वेतः कुष्ठरोगः रक्तमांसमेदानाम् आश्रयी अस्ति।\"','adjective'),(33636,'','आश्रयिन्','अन्यस्य आश्रये स्थित्वा कार्यादिकं क्रियमाणः।; \"सः राजसभायाः आश्रयी कविः आसीत्।\"','adjective'),(33637,'','आश्रित, उपजीविन्','स्वस्य भरणार्थं यः अन्यम् अपेक्ष्यते।; \"आश्रयदातुः मृत्योः वार्तां श्रुत्वा आश्रितः मनुष्यः दुःखितः जातः।\"','adjective'),(33639,'','अनुकम्पक','यः करुणया अनुकम्पनेन वा व्यवहरति।; \"एतेभ्यः अनाथेभ्यः बालकेभ्यः अनुकम्पकैः आश्रयः दत्तः।\"','adjective'),(33629,'','आश्रमवासिन्','यः आश्रमे निवसति।; \"आश्रमवासिनः साधकाः प्रातः चतुर्वादनतः रात्रौ नववादनपर्यन्तं यावत् साधनां कुर्वन्ति।\"','adjective'),(33630,'','आश्रमिक, आश्रमिन्','आश्रमेण सम्बद्धः।; \"आश्रमिकाणां नियमानां कठोरतया पालनं कर्तव्यम् एव।\"','adjective'),(33631,'','आश्रमिक, आश्रमिन्','हिन्दुधर्मानुसारेण चतुर्षु आश्रमेषु कमपि एकम् आश्रमम् यः निर्वहति।; \"भिन्नानाम् आश्रमिकाणां मनुष्याणां कार्याणि भिन्नानि भवन्ति।\"','adjective'),(33649,'','आसञ्जनम्','केनापि सह सम्यक्तया दृढीकरणस्य क्रिया।; \"तक्षकः आसञ्जनं करोति।\"','noun'),(33648,'','आषाढीय','आषाढानक्षत्रे जातम्।; \"ज्योतिषाचार्यः आषाढीयस्य बालकस्य ग्रहदशां पश्यति।\"','adjective'),(33647,'','आषाढी','आषाढमासस्य पूर्णिमा।; \"वेदव्यासस्य जन्मदिनरूपेण आषाढीं गुरूणां कृते निर्वर्तयन्ति।\"','noun'),(33646,'','अस्','अनुकरणानुकूलः व्यापारः।; \"मम पुत्री नाटके राज्ञी लक्ष्मी अस्ति।\"','verb'),(33645,'','आषाढा','पूर्वाषाढा तथा उत्तराषाढानक्षत्रम्।; \"राशिचक्रे विंशतितमस्य एकविंशतितमस्य च नक्षत्रस्य नाम आषाढा अस्ति।\"','noun'),(33641,'',' ',' ; \"\"','noun'),(33642,'','प्रतिज्ञात, आश्रुत','यस्मिन् विषये प्रतिज्ञा कृता।; \"प्रतिज्ञातां भूमिं दातुं सः निराकरोत्।\"','adjective'),(33644,'','आषाढीय','आषाढसम्बन्धि आषाढमासे जायमानः वा।; \"आकाशे आषाढीयाः मेघाः सन्ति।\"','adjective'),(33640,'',' ',' ; \"\"','adjective'),(33632,'',' ',' ; \"\"','noun'),(33634,'','आश्रयणीय, अवलम्बनीय','आश्रयितुं योग्यः।; \"आश्रयणीयः मार्गः एव अस्मान् लक्ष्यं प्रति प्रापयति।\"','adjective'),(33626,'','आश्रमवासः','आश्रमे निवासः।; \"आश्रमवासे नियमानां पालने अशक्तत्वात् सः गृहं प्रत्यागच्छत्।\"','noun'),(33628,'','आशुलिपिकः','अन्येन उक्तानि वाक्यानि यः तस्मिन्नेव समये शीघ्रगत्या लिखति।; \"अधिकारिणा उक्तानि वाक्यानि आशुलिपिकः अलिखत्।\"','noun'),(33584,'','आवेष्टनम्','तद् वस्तु येन किमपि आच्छाद्यते।; \"माता रामायणे आवेष्टनम् अस्थापयत्।\"','noun'),(33585,'','सर्पास्यः','राक्षसविशेषः यः खरस्य सेनापतिः आसीत्।; \"सर्पास्यस्य वर्णनं रामायणे अस्ति।\"','noun'),(33586,'','सर्पिः','वैदिकऋषिविशेषः।; \"सर्पेः वर्णनं वेदेषु प्राप्यते।\"','noun'),(33587,'','सर्पिः','राक्षसविशेषः।; \"सर्पेः वर्णनं विष्णुपुराणे प्राप्यते।\"','noun'),(33588,'','स्यन्दिकानदी','पौराणिकी नदी।; \"रामायणस्य अनुसारेण स्यन्दिकानदी कौशलराज्यस्य दक्षिणदिशि वहति स्म।\"','noun'),(33589,'','आशारागः','रागविशेषः।; \"गायिका आशारागं पाठयति।\"','noun'),(33595,'',' ',' ; \"\"','noun'),(33597,'','हेमाङ्गदः','यः सुवर्णस्य केयूरम् धारयति।; \"रात्रौ चौराः हेमाङ्गदात् तस्य केयूरम् अचोरयन्।\"','noun'),(33598,'','हेमाङ्गदः','वसुदेवस्य पुत्रः।; \"हेमाङ्गदस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33600,'','सर्वनाशिन्','यः सर्वनाशं करोति।; \"केचन जनाः सर्वनाशीनि कार्याणि एव कुर्वन्ति।\"','adjective'),(33603,'','पूर्वार्धः, प्रथमार्धम्, उपार्धम्, पूर्वार्धम्','कालस्य अथवा अन्येषां केषामपि वस्त्वादीनां द्वयोः अर्धभागयोः प्रथमः अर्धभागः।; \"अस्य मासस्य पूर्वार्धः मम कृते उत्तमः आसीत्।\"','noun'),(33604,'','हेम्नारागः','सङ्गीते एकः रागः।; \"सङ्गीतकारः हेम्नारागं गायति।\"','noun'),(33606,'','हैहयवंशः','क्षत्रियः वंशः यस्य जनकः राजा यदुः आसीत्।; \"सहस्त्रार्जुनः हैहयवंशे जातः।\"','noun'),(33607,'','अङ्गुष्ठचिह्नम्, अङ्गुष्ठस्थानम्','अङ्गुष्ठे मशीं लेपयित्वा कर्गजे अङ्गुष्ठस्य संघट्टनेन निर्मितं तद् चिह्नं यद् निरक्षराः जनाः हस्ताक्षरस्य स्थाने लिखन्ति।; \"लेखपालेन एकस्यां लेखापुस्तिकायां पुरुषस्य अङ्गुष्ठचिह्नं स्वीकृतम्।\"','noun'),(33609,'','आत्मनिर्भरता, स्वनिर्भरता','आत्मनिर्भरस्य अवस्था।; \"बालकेषु बाल्यावस्थायाः एव आत्मनिर्भरतायाः अभ्यासः भवेत्।\"','noun'),(33612,'','विलेखा','आघातेन उत्पन्नः व्रणः।; \"बालकेन नूतनायाम् उत्पीठिकायां विलेखा आरेखिता।\"','noun'),(33614,'','अप्रबल, अल्पशक्ति','गुणयोग्यताकौशलादिषु न्यूनता।; \"गणिते अप्रबलान् छात्रान् ते पाठयन्ति।\"','adjective'),(33615,'','तपोवनम्','तद् वनं यत्र तपस्विनः निवसन्ति तपः आचरन्ति च।; \"रामः वनवासकाले तपोवने नैकैः तपस्विनैः सह अमिलत्।\"','noun'),(33616,'','अन्तर्निहित','यद् पूर्णतया समाहितः।; \"अन्तर्निहिताय ईश्वराय किमर्थं बहिः पश्यसि।\"','adjective'),(33617,'','समर्पित','येन समर्पणं कृतम्।; \"श्रेष्ठस्य कार्यस्य कृते समर्पितान् जनान् प्रति मनसि श्रद्धा भवति।\"','adjective'),(33620,'','दार्शनिकता, दार्शनिकत्वम्','दार्शनिकस्य अवस्था।; \"कबीरस्य रचनासु तस्य दार्शनिकता ज्ञायते।\"','noun'),(33621,'','अग्निशामकयानम्','तद् यानं यस्मिन् अग्निशामकं यन्त्रं वर्तते।; \"अग्निशामकयानस्य ध्वनिः दूरपर्यन्तं श्रूयते।\"','noun'),(33571,'','सिंहिका','सा कन्या यस्याः जानुनी गमनसमये परस्पराभ्यां स्पृशतः यस्मात् सा विवाहयोग्या नास्ति इति मन्यते।; \"रमेशः सिंहिकया विवाहं कर्तुम् इच्छति किन्तु तस्य परिवारः अवमन्यते।\"','noun'),(33625,'','आश्चर्यम्','साहित्यशास्त्रे नवरसाणां नवसु स्थायीभावेषु एकः।; \"आश्चर्यम् अद्भुतरसस्य स्थायीभावः अस्ति।\"','noun'),(33623,'','आशा','दक्षप्रजापतेः कन्या।; \"आशायाः वर्णनं पुराणेषु अस्ति।\"','noun'),(33622,'','आशयः','शरीरे वर्तमानः अङ्गविशेषः यस्मिन् किमपि विशिष्टं तत्वं वर्तते।; \"अस्माकं शरीरे आमाशयगर्भाशयपित्ताशयमूत्राशयादयाः सप्त आशयाः सन्ति।\"','noun'),(33560,'','खासी','भारतीयः जनजातिप्रकारः।; \"खासी आधिक्येन मेघालये दृश्यते।\"','noun'),(33562,'','खासीभाषा','भारतदेशस्य मेघालयराज्ये या भाषा भाष्यते सा।; \"आसामराज्यस्य पर्वतीयेषु भागेषु अपि खासीभाषा भाष्यते।\"','noun'),(33563,'','वितरित, विभाजित','यस्य वितरणं कृतम्।; \"निर्धनेषु वितरितम् अन्नम् उत्तमं नास्ति।\"','adjective'),(33564,'','वचनबद्धता, वचनबद्धत्वम्','वचनबद्धस्य अवस्था भावः वा।; \"सम्प्रति अल्पीयाः जनाः वचनबद्धताम् आचरन्ति।\"','noun'),(33566,'','उपप्रवाहः','नद्यादीनां मुख्यप्रवाहात् प्रभूतः अन्यः प्रवाहः।; \"कृषिक्षेत्रे उपप्रवाहस्य जलम् अधिकं लाभदायकं भवति।\"','noun'),(33582,'','आवेदनीय, आवेद्य','आवेदनं कर्तुं योग्यम्।; \"कार्यालयस्य सर्वाणि आवेदनीयानि पत्राणि तैः दृष्टानि।\"','adjective'),(33583,'','आवेदित','यद् आवेदनरूपेण स्थापितम्।; \"इमम् उद्योगं कर्तुं आवेदितानां पत्राणां सङ्ख्या पञ्च सहस्त्रम् इति अस्ति।\"','adjective'),(33581,'','आविष्कृत, उपज्ञात, उत्पाद्य','यस्य आविष्कारः कृतः।; \"नूतनानि आविष्कृतानि यन्त्राणि अस्माकं जीवनम् अधिकं सुलभं कुर्वन्ति।\"','adjective'),(33580,'','आविद्धम्','खड्गस्य द्वाविंशतिषु प्रहारस्य प्रकारेषु एकः।; \"आविद्धे प्रविणात् योद्धुः शत्रुः बिभेति।\"','noun'),(33579,'','ऊर्णावस्त्रम्','ऊर्णया निर्मितं वस्त्रम्।; \"ऊर्णावस्त्रे उष्णता वर्तते।\"','noun'),(33576,'','आन्दमान','अन्दमानस्य अन्दमानेन सम्बद्धः वा।अन्दमानस्य अन्दमानेन सम्बद्धः वा।; \"आन्दमान्यां संस्कृतौ एकपत्नीत्वस्य नियमः अस्ति।\"','adjective'),(33556,'','आयरलैण्डद्वीपः','यस्मिन् द्वीपे आयरलैण्डदेशः स्थितः अस्ति।; \"आयरलैण्डद्वीपे अस्माकं यात्रा उत्तमा अभवत्।\"','noun'),(33557,'',' ','  ; \"\"','noun'),(33559,'','अंसफलकम्','स्कन्धस्य पाश्वे वर्तमानम् अस्थि यद् बृहद् समतलं तथा च त्रिकोणैः युक्तम् अस्ति।; \"द्विचक्रिकया पतित्वा तस्य अंसफलके भङ्गः उद्भूतः।\"','noun'),(33547,'','भवभूतिः, भूगर्भः, विश्रुतः','संस्कृतसाहित्यस्य महान् कविः नाटककर्ता च।; \"भवभूतिः महाराष्ट्रराज्यस्य ब्राह्मणकुटुम्बे जातः।\"','noun'),(33552,'','सिसलीद्वीपः, सिसिलीद्वीपः','भूमध्यसागरे वर्तमानः द्वीपः।; \"सिसलीद्वीपः भूमध्यसागरस्य महाद्वीपः वर्तते।\"','noun'),(33531,'','द्रविडी','रागिणीविशेषः।; \"गायकः द्रविडीं गायति।\"','noun'),(33532,'','क्षीरादः','सः शिशु यः मातुः दुग्धं पिबति।; \"शीलायाः क्षीरादः बालकः रोदिति।\"','noun'),(33543,'','निर्मोकः','सावर्णिमुनेः पुत्रः।; \"निर्मोकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33546,'','छायायुक्त','यत्र छाया अस्ति तद्।; \"आतपात् रक्षितुं वयं छायायुक्तं स्थानम् अगच्छाम।\"','adjective'),(33540,'','सौन्दर्यशास्त्रीय','सौन्दर्यशास्त्रेण सम्बद्धः।; \"सः केषाञ्चन सौन्दर्यशास्त्रीयाणां सिद्धान्तानां विवेचनं करोति।\"','adjective'),(33539,'','चन्दवंशः','एकः राजवंशः यस्य शासनं इदानीन्तनीये उत्तराखण्डे आसीत्।; \"चन्दवंशस्य राज्ञां शिल्पकलायां रुचिः आसीत्।\"','noun'),(33535,'','शेषाचलः','दक्षिणभारते वर्तमानः पर्वतविशेषः।; \"शेषाचलस्य धार्मिकी महत्ता अपि अस्ति।\"','noun'),(33534,'','शैक्षणिक','शिक्षणेन सम्बद्धः शिक्षणस्य वा।; \"सः शैक्षणिकस्य संस्थानस्य व्यवस्थापकः अस्ति।\"','adjective'),(33529,'','द्रविडः','द्रविडदेशस्य निवासी।; \"एषः द्रविडानां निवासः अस्ति।\"','noun'),(33530,'','द्रविडः','ब्राह्मणेषु एकः विभागः।; \"अस्माकं प्राध्यापकः ए.एम्.रावमहोदयः द्रविडः ब्राह्मणः अस्ति।\"','noun'),(33528,'','द्रविडः, द्रविडप्रान्तः','दक्षिणभारतस्य भागः यः उडिसाराज्यस्य सागरतटस्य आग्नेयदिशम् आरभ्य रामेश्वरपर्यन्तं व्याप्तः अस्ति।; \"मम प्रतिवेशी द्रविडस्य निवासी अस्ति।\"','noun'),(33522,'','शतायुध','शतेन आयुधेन युक्तः।; \"युद्धे शतायुधेन योद्ध्रा न कोऽपि जयति।\"','adjective'),(33524,'','शिथिलित','यः शिथिलः जातः।; \"शिथिलितेन शरीरेण सः मन्दः जातः।\"','adjective'),(33525,'','कोटारः','नीलगिरीपर्वते वसन् द्रविडजातेः सदस्यः।; \"अस्माकं कक्षायां कोटारः अस्ति।\"','noun'),(33521,'','शतावधानः','यः एकस्मिन्नेव समये शतानि कार्याणि कर्तुं शक्नोति।; \"इदानीन्तने काले शतावधानाः न दृश्यन्ते।\"','noun'),(33506,'','शोधनम्','द्रवस्थानां घनपदार्थानां वस्त्रेण शोधन्या वा विलगीकरणस्य क्रिया।; \"सीमा आमिक्षायाः शोधनं करोति।\"','noun'),(33507,'','मैरोनीनदी','दक्षिण-अमेरिकादेशस्य नदी।; \"मैरोनीनदी फ्रान्सीसीगुयाना इति उपनिवेशस्य सूरीनामदेशस्य मध्यभागात् वहति।\"','noun'),(33508,'','तारागृहम्, ताराङ्गणम्','यस्मिन् स्थाने जनान् अनुरञ्जयितुं शिक्षयितुं च ग्रहाणां गतिमानतां रात्रिकालीनम् आकाशं दर्शयितुं वर्तुलाकारः छदः भवति।; \"शिक्षिका छात्रान् तारागृहं नीतवती।\"','noun'),(33519,'','सिक्थवर्तिकास्थानम्','यस्मिन् पात्रे सिक्थवर्तिका प्रज्वाल्यते।; \"शीला सिक्थवर्तिकास्थानं प्रक्षालयति।\"','noun'),(33517,'','बदगाः','बदगाजातेः सदस्यः।; \"सः बदगाः इदानीम् अविवाहितः अस्ति।\"','noun'),(33518,'','शमीकः','पौराणिकः ऋषिविशेषः यः शृङ्गीऋषेः पिता आसीत्।; \"एकदा परीक्षितेन शमीकस्य कण्ठे मृतसर्पः स्थापितः।\"','noun'),(33512,'','आयानः, आयानघोषः','पुराणे वर्णितः गोपालकः।; \"राधिकायाः विवाहः आयानेन सह अभवत्।\"','noun'),(33516,'','बदगाजातिः','दक्षिणभारते वर्तमाना जनजातिः।; \"बदगाजातिः कृषिकार्यं करोति।\"','noun'),(33511,'','कुटिला','राधिकायाः ननान्दा आयानस्य भगिनी च।; \"कुटिलायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33509,'','विविध, भिन्न, पृथग्विध','अनेकप्रकारकः।; \"अस्माभिः विविधानि सांस्कृतिकाः कार्यक्रमाः अनुभूताः।\"','adjective'),(33510,'','प्लेटनदी','अमेरिकादेशे पश्चिमक्षेत्रे वर्तमाना नदी।; \"प्लेटनदी प्रायः पञ्चशत किलोमीटरपरिमाणं परितः गच्छति।\"','noun'),(33498,'','आवाहनम्','पूजनसमये मन्त्रेण देवतेभ्यः निमन्त्रणम्।; \"देवतानाम् आवाहनस्य अनन्तरं पूजनम् आरब्धम्।\"','noun'),(33501,'','आह्वाता, हावकः, नदिः','यः आह्वयति।; \"सः आह्वातारम् अन्वगच्छत्।\"','noun'),(33504,'','माहासागरीय, माहासामुद्रिक','महासागरेण सम्बद्धः।; \"केषुचित् माहासागरीयेषु भागेषु वायोः भारः न्यूनः अस्ति।\"','adjective'),(33493,'','प्रहसनम्, विदूषणम्','अप्रत्यक्षरूपेण अन्यान् श्रावयितुम् उच्चैः कृतम् अधिक्षेपयुक्तं वचनम्।; \"सः प्रहसनस्य प्रवृत्तिं न जहाति।\"','noun'),(33497,'','कुक्कुटध्वनिः','कुक्कुटस्य प्रातःकालीनः ध्वनिः।; \"ग्रामेषु इदानीम् अपि जनाः कुक्कुटध्वनिं श्रुत्वा जागरति।\"','noun'),(33464,'','ज्ञवर्णः','हिन्दीभाषायाः वर्णमालायां वर्तमानः संयुक्ताक्षरः यः इदानीं स्वतन्त्रवर्णरूपेण स्वीक्रियते।; \"जकारस्य ञकारस्य च संयोगेन ज्ञवर्णः प्राप्यते।\"','noun'),(33465,'','स्पर्शः','व्याकरणशास्त्रानुसारेण यस्य वर्णस्य उच्चारणसमये जिह्वायाः कश्चित् भागः मुखस्य कञ्चित् भागं स्पृशति श्वासः आंशिकं कालं अवरुध्यते च।; \"कादि मपर्यन्तवर्णाः स्पर्शाः इति कथ्यन्ते।\"','noun'),(33466,'','स्पर्शः','त्वचः सः गुणः येन त्वचा सह अन्यस्य वस्तुनः सम्पर्कस्य ज्ञानं भवति।; \"अङ्गस्य पक्षाघातेन तस्य अङ्गस्य स्पर्शस्य ज्ञानम् अपि नष्टं भवति।\"','noun'),(33467,'','स्पर्शः','सूर्यग्रहणस्य चन्द्रग्रहणस्य वा आरम्भः।; \"दूरदर्शनसञ्चे सूर्यग्रहणस्य स्पर्शात् आरभ्य मोक्षं यावत् दृष्यं दर्शितम्।\"','noun'),(33468,'','स्पर्शः','सम्भोगस्य प्रकारः।; \"रतबन्धस्य षोडशसु प्रकारेषु स्पर्शः एकः।\"','noun'),(33469,'','भूतकेतुः','दक्षसावर्णेः पुत्रः।; \"भूतकेतोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33470,'','आस्थापनम्, स्नेहवस्तिः','रुग्णस्य शरीरे अपाने नलिकया तैलस्थापनस्य क्रिया।; \"आस्थापनेन उदरशुद्धिः भवति।\"','noun'),(33471,'','मूर्द्धन्य','मूर्द्ध्ना सम्बद्धः।; \"टवर्गस्य सर्वे वर्णाः मूर्द्ध्ना उच्चार्यन्ते अतः ते मूर्द्धन्याः वर्णाः इति कथ्यन्ते।\"','adjective'),(33472,'','मूर्द्धन्य','यद् मूर्द्धनि स्थितम् अस्ति।; \"स्वामिनः मूर्धन्येन तिलकेन तस्य शैवत्वं ज्ञायते।\"','adjective'),(33473,'','मूर्धन्यवर्णः','यस्य वर्णस्य उच्चारणं मूर्ध्ना क्रियते।; \"टवर्गस्य सर्वे वर्णाः मूर्धन्यवर्णाः सन्ति।\"','noun'),(33474,'','दन्त्यवर्णः','यस्य वर्णस्य उच्चारणं दन्तैः भवति।; \"तवर्गस्य सर्वे वर्णाः दन्त्यवर्णाः सन्ति।\"','noun'),(33475,'','ओष्ठ्य','ओष्ठेन सम्बद्धः ओष्ठस्य वा।; \"सः ओष्ठ्येन रोगेण पीडितः अस्ति।\"','adjective'),(33476,'','ओष्ठ्यवर्णः','यस्य वर्णस्य उच्चारणम् ओष्ठाभ्यां भवति।; \"ओष्ठाभ्याम् उच्चारितत्वात् पवर्गस्य वर्णाः ओष्ठ्यवर्णाः सन्ति।\"','noun'),(33477,'','दन्त्योष्ठ','यद् दन्तैः ओष्ठाभ्यां च उच्चार्यते।; \"वकारः दन्त्योष्ठः वर्णः अस्ति।\"','adjective'),(33478,'','दन्त्योष्ठ्यवर्णः','यस्य वर्णस्य उच्चारणं दन्तैः ओष्ठाभ्यां च भवति।; \"हिन्दीवर्णमालायां वर्तमानः वर्णः वकारः दन्त्योष्ठ्यवर्णः अस्ति।\"','noun'),(33479,'','तरुमूलम्, अंह्रिः','वृक्षस्य मूलम्।; \"कर्मकराः भूमेः तरुमूलम् उन्मूलयन्ति।\"','noun'),(33482,'','शबरजातिः','दक्षिणभारते वर्तमाना जनजातिः।; \"शबरजातिः वनेषु पर्वतेषु च निवसति।\"','noun'),(33484,'','कपोतवृत्तिः','प्रतिदिनस्य अर्जनेन एव प्रतिदिनं खादनस्य क्रिया।; \"अधिकेषु कर्मकरेषु कपोतवृत्तिः भवति।\"','noun'),(33488,'','आवहः, आवहम्','पृथिव्याः द्वादशयोजनं ऊर्ध्वभागे प्रवहमाणः वायुः यत्र विद्युत् दीप्यते।; \"वायोः सप्तसु स्तरेषु प्रथमः स्तरः आवहः।\"','noun'),(33491,'','संसरणम्, गमनागमनम्','पुनः पुनः जन्ममृत्योः क्रिया।; \"संसारे जीवस्य संसरणस्य अन्तः मोक्षेण एव भवति।\"','noun'),(33462,'','क्षवर्णः, कूटः','हिन्दीभाषायाः वर्णमालायां वर्तमानः संयुक्ताक्षरः यः इदानीं स्वतन्त्रवर्णरूपेण स्वीक्रियते।; \"ककारस्य षकारस्य च संयोगेन क्षवर्णः प्राप्यते।\"','noun'),(33463,'','त्रवर्णः','हिन्दीभाषायाः वर्णमालायां वर्तमानः संयुक्ताक्षरः यः इदानीं स्वतन्त्रवर्णरूपेण स्वीक्रियते।; \"तकारस्य रेफस्य च संयोगेन त्रवर्णः प्राप्यते।\"','noun'),(33492,'','ध्वनिः','फकीरादिभिः उच्चैः कृतः शब्दः।; \"खाद्यविक्रेतुः ध्वनिं श्रुत्वा बालकाः लघुमार्गे अधावन्।\"','noun'),(33454,'','यकारः','वर्णमालायाः षड्विंशतितमः वर्णः यः स्पर्शोष्मयोः मध्यस्थत्वात् अन्तस्थः उच्यते।; \"यकारस्य उच्चारणस्थानं तालुः अस्ति।\"','noun'),(33455,'','रेफः','वर्णमालायाः सप्तविंशतितमः वर्णः यः स्पर्शोष्मयोः मध्यस्थत्वात् अन्तस्थः उच्यते।; \"रेफस्य उच्चारणस्थानं मूर्द्धा अस्ति।\"','noun'),(33456,'','लकारः','वर्णमालायाः अष्टविंशतितमः वर्णः यः अल्पप्राणः इत्यपि कथ्यते।; \"लकारस्य उच्चारणस्थानं दन्ताः सन्ति।\"','noun'),(33457,'','वकारः','वर्णामालायाः नवविंशतितमं व्यञ्जनं यद् उकारस्य विकारः इति मन्यते।; \"वकारस्य उच्चारणं दन्तानाम् ओष्ठयोः च सहाय्येन भवति।\"','noun'),(33458,'','शकारः','हिन्दीवर्णमालायाः त्रयोविंशतितमः महाप्राणः यस्य उच्चारणसमये उच्चारणेन्द्रियेषु ईषत् घर्षणं भवति यस्मात् सः ऊष्मा इति कथ्यते।; \"शकारस्य तालोः उच्चारणत्वात् सः तालव्यः शकारः इत्यपि उच्यते।\"','noun'),(33460,'','सकारः','वर्णमालायाः द्वात्रिंशत्तमः वर्णः।; \"दन्तानाम् उच्चारणस्थानभूतत्वात् सकारः दन्त्यः इति कथ्यते।\"','noun'),(33461,'','आवाहनम्, अभिहवः, अभिहूतिः, आकारणम्','आमन्त्रणस्य क्रिया।; \"मम आवाहनस्य अनन्तरं सः प्रकोष्ठात् बहिः आगतः।\"','noun'),(33459,'','षकारः','वर्णमालायाः एकत्रिंशत्तमः वर्णः यस्य मूर्द्धा इति उच्चारणस्थानभूतत्वात् मूर्धन्य इत्यपि कथ्यते।; \"षकारस्य उच्चारणं शकारस्य खकारस्य च उच्चारणमिव भवति।\"','noun'),(33453,'','मकारः, कालः','वर्णमालायाः पञ्चविंशतितमः वर्णः पवर्गस्य अन्तिमं व्यञ्जनञ्च।; \"मकारस्य उच्चारणम् ओष्ठाभ्यां नासिकया च भवति।\"','noun'),(33451,'','बकारः','वर्णमालायाः त्रयोविंशतितमः वर्णः पवर्गस्य तृतीयं व्यञ्जनञ्च।; \"बकारः ओष्ठ्यवर्णः अस्ति।\"','noun'),(33452,'','भकारः','हिन्दीवर्णमालायाः चतुर्विशंतितमः वर्णः पवर्गस्य चतुर्थं व्यञ्जनञ्च।; \"भकारः ओष्ठ्यवर्णः अस्ति।\"','noun'),(33450,'','फकारः','वर्णमालायाः द्वाविंशतितमः वर्णः पवर्गस्य द्वितीयं व्यञ्जनञ्च।; \"फकारस्य उच्चारणस्थाने औष्ठौ स्तः।\"','noun'),(33448,'','नकारः','वर्णमालायाः विंशतितमः वर्णः तवर्गस्य अन्तिमं व्यञ्जनञ्च।; \"नकारस्य उच्चारणं दन्तनासिकयोः भवति।\"','noun'),(33449,'','पकारः','वर्णमालायाः एकविंशतितमः वर्णः तथा स्पर्शेषु अन्तिमवर्गस्य प्रथमं व्यञ्जनम्।; \"पकारस्य उच्चारणम् ओष्ठाभ्यां भवति।\"','noun'),(33447,'','धकारः','वर्णमालायाः नवदशतमः वर्णः तवर्गस्य चतुर्थं व्यञ्जनञ्च।; \"सङ्गीतशास्त्रे धकारः धैवतस्य सूचकः संक्षिप्तरूपञ्च इति मन्यते।\"','noun'),(33445,'','थकारः','वर्णमालायाः सप्तदशतमः वर्णः तवर्गस्य द्वितीयं व्यञ्जनञ्च।; \"थकारस्य उच्चारणं दन्तजिह्वयोः संयोगेन भवति।\"','noun'),(33446,'','दकारः','वर्णमालायाः अष्टादशतमः वर्णः तवर्गस्य तृतीयं व्यञ्जनञ्च।; \"दकारस्य उच्चारणं दन्तस्य जिह्वाग्रस्य च संयोगेन भवति।\"','noun'),(33444,'','तकारः','वर्णमालायाः षोडशतमः वर्णः तवर्गस्य प्रथमं व्यञ्जनञ्च।; \"तकारस्य उच्चारणस्थानं दन्ताः सन्ति।\"','noun'),(33439,'','ढगणः','छन्दःशास्त्रानुसारेण पञ्चानां मात्राणां एकः गणः।; \"ढगणे तिस्रः मात्राः सन्ति।\"','noun'),(33440,'','ठगणः','छन्दःशास्त्रानुसारेण पञ्चानां मात्राणाम् एकः गणः।; \"ठगणे पञ्च मात्राः सन्ति।\"','noun'),(33441,'','डगणः','छन्दःशास्त्रानुसारेण पञ्चनां मात्राणाम् एकः गणः।; \"डगणे चतस्रः मात्राः सन्ति।\"','noun'),(33435,'','ढकारः','वर्णमालायाः चतुर्दशतमः वर्णः टवर्गस्य चतुर्थं व्यञ्जनञ्च।; \"ढकारस्य उच्चारणं मूर्द्ध्ना भवति।\"','noun'),(33436,'','णकारः','वर्णमालायाः पञ्चदशतमः वर्णः टवर्गस्य अन्तिमं व्यञ्जनञ्च।; \"णकारस्य उच्चारणस्थानं मूर्द्धा नासिका च स्तः।\"','noun'),(33437,'','णगणः','छन्दःशास्त्रानुसारेण पञ्चानां मात्राणाम् एकः गणः।; \"णगणे द्वे मात्रे स्तः।\"','noun'),(33433,'','ठकारः','वर्णमालायाः द्वादशतमः वर्णः टवर्गस्य द्वितीयं व्यञ्जनञ्च।; \"ठकारस्य उच्चारणं मूर्द्ध्ना भवति।\"','noun'),(33434,'','डकारः','वर्णामालायाः त्रयोदशतमः वर्णः टवर्गस्य तृतीयं व्यञ्जनञ्च।; \"डकारस्य उच्चारणं मूर्द्ध्ना भवति।\"','noun'),(33430,'','ञकारः','वर्णमालायाः दशमः तथा चवर्गस्य अन्तिमः वर्णः।; \"ञकारस्य उच्चारणस्थानं तालु नासिका च अस्ति।\"','noun'),(33431,'','टकारः','वर्णमालायाः एकादशतमः वर्णः टवर्गस्य प्रथमं व्यञ्जनम् च।; \"टकारस्य उच्चारणस्थानं मूर्द्धा अस्ति।\"','noun'),(33432,'','मूर्धा, मूर्द्धा','तालुगलशुण्डिकयोः मध्ये वर्तमानः भागः।; \"हिन्दीभाषायाः वर्णमालायाः टवर्गीयाणां वर्णानाम् उच्चारणं मूर्ध्ना भवति।\"','noun'),(33429,'','झकारः','वर्णमालायाः नवमं तथा चवर्गस्य चतुर्थं व्यञ्जनम्।; \"झकारस्य उच्चारणस्थानं तालुः अस्ति।\"','noun'),(33428,'','जकारः','वर्णमालायाः अष्टमः तथा चवर्गस्य तृतीयः वर्णः।; \"छन्दःशास्त्रे  जकारः जगणस्यसूचकः अस्ति।\"','noun'),(33426,'','चकारः','वर्णमालायाः षष्ठं चवर्गस्य च प्रथमं व्यञ्जनम्।; \"चकारस्य उच्चारणस्थानं तालुः अस्ति।\"','noun'),(33427,'','छकारः','वर्णमालायाः सप्तमं तथा चवर्गस्य द्वितीयं व्यञ्जनम्।; \"छकारः तालव्यं व्यञ्जनम् अस्ति।\"','noun'),(33401,'','जानुप्रहृतफलकम्','जानुनः वर्तुलाकारम् अस्थि।; \"तस्य वामपादस्य जानुप्रहृतफलके कापि समस्या अस्ति।\"','noun'),(33406,'','अन्वाहार्यम्','सा दक्षिणा तद् भोजनं वा यद् यज्ञादिषु पुरोहिताय दीयते।; \"अन्वाहार्यं प्राप्य पुरोहिताः सन्तुष्टाः जाताः।\"','noun'),(33407,'','अन्वाहार्यम्, मासिकश्राद्धम्','प्रत्येकस्मिन् मासे अमावस्यायां क्रियमाणं श्राद्धम्।; \"अन्वाहार्ये पण्डितेभ्यः दानं दीयते।\"','noun'),(33425,'','ङकारः','वर्णमालायाः कवर्गस्य अन्तिमः वर्णः।; \"ङकारस्य उच्चारणं कण्ठेन नासिकया च भवति।\"','noun'),(33424,'','घकारः','वर्णमालायाः स्पर्शेषु कवर्गस्य चतुर्थं व्यञ्जनं यद् घोषः तथा महाप्राणः अस्ति।; \"घकारस्य उच्चारणस्थानं कण्ठः अस्ति।\"','noun'),(33423,'','गकारः','वर्णमालायां स्पर्शेषु कवर्गस्य तृतीयं व्यञ्जनं यः अल्पप्राणः तथा घोषः अस्ति।; \"गकारस्य उच्चारणं कण्ठात् भवति।\"','noun'),(33422,'','खकारः','वर्णमालायां स्पर्शेषु कवर्गस्य द्वितीयं व्यञ्जनम्।; \"खकारस्य उच्चारणं कण्ठात् भवति।\"','noun'),(33421,'','ककारः','वर्णमालायां प्रथमं व्यञ्जनं यस्य उच्चारणस्थानं कण्ठः अस्ति।; \"ककारः स्पर्शः इत्यपि उच्यते।\"','noun'),(33418,'','ऐकारः','वर्णमालायां नवमः स्वरः।; \"कण्ठः तालुश्च ऐकारस्य उच्चारणस्थाने स्तः।\"','noun'),(33415,'','ऊकारः','वर्णमालायां षष्ठः स्वरः यस्य उच्चारणस्थाने औष्ठौ स्तः।; \"उकारस्य दीर्घरूपः ऊकारः यः कदाचित् अव्ययरूपेणापि प्रयुज्यते।\"','noun'),(33416,'','ऋकारः','वर्णमालायां सप्तमः स्वरः।; \"ऋकारस्य उच्चारणस्थानं मूर्द्धा अस्ति।\"','noun'),(33414,'','उकारः','वर्णमालायां पञ्चमः स्वरः यस्य उच्चारणस्थाने औष्ठौ स्तः।; \"त्रिषु प्रमुखेषु स्वरेषु एकः उकारः।\"','noun'),(33413,'','ईकारः','वर्णमालायां चतुर्थः स्वरः यः इकारस्य दीर्घरूपः।; \"प्रत्ययरूपेण ईकारं प्रयुज्य स्त्रीलिङ्गादीनां रूपाणि निर्मीयन्ते।\"','noun'),(33412,'','इकारः','वर्णामालायां तृतीयः स्वरः।; \"इकारस्य उच्चारणः तालुना भवति।\"','noun'),(33411,'','आकारः','वर्णमालायां द्वितीयः स्वरः यः अकारस्य दीर्घं रूपम्।; \"आकारस्य प्रयोगः उपसर्गरूपेण भवति।\"','noun'),(33408,'','आत्मदहनम्','आत्मदाहस्य कार्यम्।; \"ह्यः एकेन युवकेन आत्मदहनस्य प्रयत्नः कृतः।\"','noun'),(33410,'','अकारः','प्रथमः स्वरः येन विना व्यञ्जनानाम् उच्चारणम् अशक्यम्।; \"कण्ठात् उच्चार्यमाणत्वात् अकारः कण्ठ्यवर्णः।\"','noun'),(33397,'','गृहनिर्मित','यद् गृहे निर्मीयते।; \"गृहनिर्मितानि मिष्टान्नानि विशुद्धानि भवन्ति।\"','adjective'),(33398,'','आवसथ्यः','पञ्चाग्निषु एकः।; \"भोजनादीनां निर्माणे आवसथ्यम् उपयुज्यते।\"','noun'),(33399,'','पञ्चाग्नि','पञ्चानाम् अग्निनां समूहः।; \"अस्माकं जीवने पञ्चाग्निनां महत्वं वर्तते।\"','noun'),(33395,'','आवश्यक','येन विना कार्यसम्पादनं न शक्यम्।; \"पण्डितेन विवाहार्थम् आवश्यकानां वस्तूनां सङ्ग्रहः कृतः।\"','adjective'),(33396,'','आवसथिक, गार्ह, गार्ह्य, गेह्य, अवसथ्य','गृहस्य अथवा गृहेण सम्बद्धः।; \"आवसथिकेभ्यः कार्येभ्यः समयः एव न प्राप्यते येन अहं किमपि पठितुं न शक्नोमि।\"','adjective'),(33394,'','आकम्पित','यद् कम्प्यते।; \"झञ्झावातेन आकम्पितायाः शाखायाः फलानि पतन्ति।\"','adjective'),(33393,'','प्राणबाधः, असुभङ्गः, प्राणान्तिकम्, प्राणात्ययः','तद् व्यसनं यत् प्राणघातकम् अस्ति।; \"जिजीविषया सः प्राणबाधात् रक्षितः।\"','noun'),(33391,'','मणिस्कन्धः','नागविशेषः।; \"मणिस्कन्धस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33390,'','आनीत','यद् आनीयते।; \"विवाहार्थम् आनीतानि वस्तूनि प्रकोष्ठे स्थापयतु।\"','adjective'),(33387,'','मणिमेघः','एकः पौराणिकः पर्वतः।; \"पुराणानाम् अनुसारेण मणिमेघः दक्षिणभारते वर्तते।\"','noun'),(33383,'','कर्कोटकः','कद्रुपुत्रनागराजविशेषः।; \"कर्कोटकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33384,'','मणिमाला','वर्णवृत्तविशेषः।; \"मणिमालायाः प्रत्येकस्मिन् चरणे क्रमेण तयतयगणाः सन्ति।\"','noun'),(33385,'','आवर्तनम्','रुग्णस्य स्वास्थ्यलाभादनन्तरं तस्याः एव व्याधेः पुनः वृद्धिः।; \"पितृव्यः आवर्तनेन ग्रस्तः।\"','noun'),(33386,'','मणिमाला','कामक्रीडायां कपोले जातः वर्तुलाकारः दन्तक्षतः।; \"कान्ता कपोले स्थितां मणिमालां संछादययति।\"','noun'),(33389,'','आवर्तित, परिवृत्त','यद् परिवर्त्यते।; \"घटेः आवर्तितः सूचनादण्डः अयोग्यं समयं दर्शयति।\"','adjective'),(33388,'','आवर्तनीय','यस्य आवर्तनं भवितुम् अर्हति।; \"गीतायाः अनुसारेण कामनानाम् आवर्तनीयं स्वरूपं भवति।\"','adjective'),(33382,'','मणिभद्रकः','नागविशेषः।; \"नागपञ्चमी इति उत्सवसमये मणिभद्रक-सदृशाः नागाः प्राणिभ्यः अभयदानं यच्छन्ति।\"','noun'),(33381,'','आवर्तः','चतुर्षु मेघाधिपेषु एकः।; \"आवर्ताः अधिकं वर्षन्ति।\"','noun'),(33380,'','आवर्तः','यैः मेघैः अधिका वृष्टिः भवति।; \"अस्मिन् वर्षे आवर्तस्य अभावः अस्ति।\"','noun'),(33373,'','आवजवाद्यम्','तालवाद्यविशेषः।; \"अत्रत्ये सङ्गीतसङ्ग्रहालये आवजवाद्यम् अपि अस्ति।\"','noun'),(33374,'',' ',' ; \"\"','adjective'),(33376,'','आवनेय','अवन्याः उत्पन्नः।; \"आवनेयेषु खनिजेषु नैके धातवः सन्ति।\"','adjective'),(33379,'','आवरणशक्तिः','वेदान्तशास्त्रानुसारेण आत्मनः ज्ञानाच्छादनस्य शक्तिः।; \"आवरणशक्त्याः प्रभावः ज्ञानिषु अपि भवति।\"','noun'),(33370,'','निदोलः','गुरुत्वाकर्षणस्य प्रभावेण स्वतन्त्ररूपेण दोलायमानः उपकरणविशेषः।; \"केषुचित् घटीषु निदोलः वर्तते।\"','noun'),(33371,'','आन्दोलनम्, दोलनम्','कस्यापि आधारेण लम्बयित्वा पूर्वापरम् इतस्ततः वा गमनस्य क्रिया।; \"निदोलस्य अवस्थितम् आन्दोलनं ज्ञापयति यत् घटी कार्यविहीना जाता।\"','noun'),(33362,'','शोधप्रबन्धः','कस्मिन्नपि शोधकार्ये लिखितः ग्रन्थः।; \"शोधप्रबन्धम् उपस्थापयितुं मीना विश्वविद्यालयं गतवती।\"','noun'),(33363,'','मथित','यस्य मथनं जातम्।; \"मथिते दधिनि जलं मिश्रयित्वा तक्रं निर्मीयते।\"','adjective'),(33369,'','विलोडित','यद् विचाल्यते।; \"विलोडितस्य वृक्षस्य शाखा इदानीम् अपि आन्दोलयति।\"','adjective'),(33352,'','आवर्त्तनम्','दिनस्य सः कालः यदा सूर्यस्य पश्चिमदिगवस्थिता छाया पूर्वदिशं गच्छति।; \"किञ्चित् कालानन्तरम् आवर्त्तनम् अस्ति।\"','noun'),(33357,'','स्मारकम्','कञ्चित् कार्यं पदार्थं अथवा काचित् रचना या कस्यापि स्मृत्यर्थं रक्ष्यते।; \"पितामह्याः स्मारकं मात्रा सुरक्षिततया कपाटिकायां स्थापितम्।\"','noun'),(33358,'','स्मारणपत्रम्','कमपि विषयं स्मारयितुं लिखितं पत्रम्।; \"अस्य विषयस्य स्मारणपत्रं सर्वेभ्यः प्रेषितम्।\"','noun'),(33342,'','आलापक','यः आलापं करोति।; \"आलापकस्य गायकस्य ध्वनिः मधुरः अस्ति।\"','adjective'),(33344,'','आलपनीय','आलपितुं योग्यः।; \"आलपनीयः विषयः नास्ति अयम्।\"','adjective'),(33345,'','आलाप्य, आलापनीय','आलापस्य कृते योग्यम्।; \"अद्य मम स्वरः आलाप्यः नास्ति।\"','adjective'),(33346,'',' ',' ; \"\"','adjective'),(33347,'','गीत, आलापित','यद् गीयते।; \"गायिकया गीतं स्तोत्रं सर्वेभ्यः अरोचत।\"','adjective'),(33348,'','आलावर्तः','वस्त्रेण निर्मितं वीजनम्।; \"मातृष्वसा सुन्दरम् आलावर्तं निर्माति स्म।\"','noun'),(33350,'','लेख्य','लेखितुं योग्यः।; \"लेखकः लेख्यस्य विषयस्य अन्वेषणं करोति।\"','adjective'),(33351,'','लेख्य','यस्य लेखनं भविष्यति।; \"लेख्यः विषयः क्लिष्टः अस्ति।\"','adjective'),(33337,'','फरुण्डः, रसः, लतार्कः','पलाण्डोः हरितः भागः यस्य उपयोगः शाकादिषु क्रियते।; \"व्यञ्जनार्थम् आपणात् फरुण्डम् आनयतु।\"','noun'),(33339,'','कुलक्षणा','अशुभैः लक्षणैः युक्ता स्त्री।; \"कुलक्षणायाः गृहप्रवेशेन श्वशुरः अम्रियत।\"','noun'),(33331,'','अलङ्कारिक','अलङ्कारेण सम्बद्धम्।; \"कविना प्रयुक्तया अलङ्कारिकया भाषया काव्यस्य शोभां वर्धते।\"','adjective'),(33333,'','विजेता','यः प्रतियोगितायां प्रथमं स्थानं प्राप्नोति।; \"अस्मिन् राज्यस्तरीयायां क्रीडायाम् अस्माकं सङ्घः विजेता भविष्यति।\"','noun'),(33324,'','आर्यपुत्र','आर्याणां पुत्राः।; \"क्षतिमान् आर्यपुत्रः युद्धभूमेः सेनावासे नीतः।\"','noun'),(33325,'','आर्यागीतिः','आर्याछन्दसः भेदविशेषः यस्य समचरणेषु विंशतिः विषमचरणेषु द्वादश मात्राः सन्ति।; \"आर्यागीतेः इमाः पङ्क्तयः स्पष्टीकरोतु।\"','noun'),(33321,'','आर्द्राशनिः','अस्त्रविशेषः।; \"आर्द्राशन्याः उल्लेखः अधिकः न प्राप्यते।\"','noun'),(33322,'','आर्यः','आचार्यगुरुपत्यादीनाम् आदरणीयानां पुरुषाणां कृते उपयुक्तं सम्बोधनम्।; \"आर्य भवता सह मेलितुं केचन जनाः आगताः।\"','noun'),(33323,'','आर्यपुत्रः','पतिं सम्बोधयितुं पत्न्या उच्चारितम् आदरसूचकं सम्बोधनम्।; \"इदानीं पर्यन्तम् आर्यपुत्रः राजसभायाः न प्रत्यागच्छत्।\"','noun'),(33330,'','आर्षप्रयोगः','भाषायां कस्यापि शब्दस्य पदस्य वा सः प्रयोगः यः व्याकरणशास्त्रानुसारेण तु साधुः प्रयोगः नास्ति परं तस्य शब्दस्य प्राचीनैः ऋषिभिः प्रयोज्यत्वात् सः शब्दप्रयोगः लोके प्रचलितः अस्ति।; \"प्राचीने ग्रन्थे आर्षप्रयोगाः सन्ति।\"','noun'),(33326,'','आर्षकर्म','प्राचीनानां ऋषीणां परम्परा।; \"हिमालये इदानीम् अपि केचन ऋषयः आर्षकर्म आचरन्ति।\"','noun'),(33320,'','आर्द्रा','वर्णवृत्तविशेषः यस्य प्रथमे चतुर्थे च चरणे जगणः तगणः द्वौ गुरू च भवन्ति तथा द्वितीये तृतीये च चरणे द्वौ तगणौ जगणौ तथा द्वौ गुरू भवतः।; \"इमाः आर्द्रायाः पङ्क्तयः सन्ति।\"','noun'),(33316,'','आर्त्विज','ऋत्विजा सम्बद्धम्।; \"आर्त्विजेषु कर्मसु पवित्रता आवश्यकी।\"','adjective'),(33315,'','आर्तव','विशिष्टे ऋतौ यद् जायते।; \"आर्तवानां फलानां सेवनं स्वास्थ्यप्रदं भवति।\"','adjective'),(33297,'','आरोपणम्','स्थापनस्य क्रिया।; \"कृत्रिमाङ्गानाम् आरोपणेन विकलाङ्गानां कृते सहाय्यं लभते।\"','noun'),(33298,'','कीलालः','देवतानां पेयः यस्य वर्णनं पुराणेषु प्राप्यते।; \"कीलालः अमृतं च समानौ एव इति मन्यते।\"','noun'),(33314,'','आर्तगलः','वृक्षविशेषः।; \"आर्तगलस्य फलानि पेषयित्वा तस्य लेपनेन शोथः न्यूनायते।\"','noun'),(33308,'',' ',' ; \"\"','noun'),(33311,'','आर्घा','पीतवर्णीया मधुमक्षिका।; \"छदे आर्घायाः बृहत् मधुकोशः अस्ति।\"','noun'),(33307,'','आरोहित','यः आरोहति।; \"वृक्षे आरोहिता लता पुष्पैः शोभते।\"','adjective'),(33301,'','आरोहः','सङ्गीतशास्त्रे एकस्मात् स्वरात् अग्रीमं स्वरं यावत् आरोहणम्।; \"सा रे ग म प ध नि सा इत्यस्य क्रमशः उच्चारणम् आरोहः इत्युच्यते।\"','noun'),(33285,'','मलावरोधक','येन मलावरोधः भवति।; \"दध्योदनम्, दधि-कदलीफलस्य मिश्रणं मलावरोधकं मन्यते।\"','adjective'),(33295,'','आरोपित','यस्य आरोपणं कृतम्।; \"पुत्र्या आरोपितैः कथनैः दुःखितः सः आत्महननम् अकरोत्।\"','adjective'),(33296,'','आरोपणीय','आरोपणं कर्तुं योग्यम्।; \"मृतस्य आरोपणीयानाम् अङ्गानां कुटुम्बजनैः दानं कृतम्।\"','adjective'),(33268,'','क्षदनम्','अभिलेखनेन निर्मितं शिल्पम्।; \"मन्दिरस्य भित्तिकायां क्षदनं शोभते।\"','noun'),(33269,'','गरणम्, निगरणम्, गिलनम्','गरस्य क्रिया।; \"एकस्य मण्डूकस्य गरणस्य अनन्तरं सर्पः अन्यं मण्डूकं सङ्गृह्णाति।\"','noun'),(33273,'','आरोपणम्','एकस्मात् स्थानात् वृक्षम् उन्मूल्य अन्यत्र रोपणम्।; \"आरोपणस्य कृते उत्तमः कालः वर्षाकालः।\"','noun'),(33276,'','सुखेच्छा','सुखस्य इच्छा।; \"वयं सुखेच्छया एव कार्यं कुर्मः।\"','noun'),(33278,'','आरुकम्','हिमाचले वर्तमानः प्रसिद्धः औषधीविशेषः।; \"आरुकस्य उपयोगः मूत्रावरोधस्य निवारणे भवति।\"','noun'),(33281,'','तुष्टीकरणम्','सन्तोषप्रदानस्य क्रिया।; \"सर्वकारेण कस्यापि एकस्य समुदायस्य तुष्टीकरणं न कर्तव्यम्।\"','noun'),(33267,'','प्रत्यूषा','सूर्यदेवस्य पत्नी।; \"प्रत्यूषायाः वर्णनं केषुचित् धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(33266,'','निक्षुभा','सूर्यदेवस्य पत्नी।; \"पुराणेषु निक्षुभायाः पूजनं विधीयते।\"','noun'),(33248,'','कुमुदः','दिग्गजविशेषः।; \"कुमुदस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(33249,'','कुमुदः','रामसेनायाः वानरः।; \"कुमुदस्य वर्णनं रामायणे प्राप्यते।\"','noun'),(33252,'','आयसम्','लोहेन निर्मितं कवचम्।; \"राजप्रासादे आयसं धार्यमाणः सैनिकः अतिचरति।\"','noun'),(33257,'','आरम्भता','आरम्भस्य अवस्था भावः वा।; \"ग्रीष्मात् अनन्तरं वर्षाकालस्य आरम्भता मनः आल्हादयति।\"','noun'),(33259,'','आरम्','चक्रस्य परिधिं तस्य केन्द्रेण योक्तुं निर्मितः लोहस्य काष्ठस्य वा दण्डः।; \"तक्षकः आरं निर्माति।\"','noun'),(33244,'','आयः','जन्मपत्रिकायां एकादशस्थानम्।; \"आये स्थितेन ग्रहः राशी च मनुष्यस्य धनार्जनं निश्चिनुतः।\"','noun'),(33245,'','कुमारलसिता','अष्टवर्णैः युक्तः वर्णवृत्तविशेषः।; \"कुमारलसितायां जगणः सगणः तथा अन्ते लघुः गुरुश्च भवतः।\"','noun'),(33246,'','कुमुदः','भगवतः विष्णोः अनुचरः।; \"कुमुदस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33240,'','आमेरनगरम्','राजस्थानराज्यस्य जयपुरनगरस्य उपनगरं यद् पूर्वं जयपुरराज्यस्य राजधानी आसीत्।; \"आमेरनगरस्य स्थापना मीणा-राजा-आलन-सिंहेन कृता।\"','noun'),(33247,'','कुमुदः','नागविशेषः।; \"कुमुदस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33243,'','अमरकण्टकम्','मध्यप्रदेशराज्यस्थितायाः विन्ध्यपर्वतमालायाः पर्वतविशेषः।; \"अस्मिन् ग्रीष्मे ऋतौ वयम् अटनार्थम् अमरकण्टकम् अगच्छाम।\"','noun'),(33215,'','सेचनी','सेचनार्थं प्रयुक्तं पात्रम्।; \"सेचन्याः विविधाः प्रकाराः सन्ति।\"','noun'),(33223,'','अन्ध्रवंशः','मगधदेशस्य प्राचीनः राजवंशः।; \"अन्ध्रवंशस्य अनन्तरं मगधदेशस्य शासनम् अन्ध्रभृत्याः अलभन्।\"','noun'),(33224,'','अन्ध्रजातिः','जातिविशेषः यः मृगयां कृत्वा निर्वाहं करोति।; \"अन्ध्रजातेः उल्लेखः शास्त्रे अस्ति।\"','noun'),(33225,'','अन्ध्रभृत्यः','मगधदेशस्य अन्तिमस्य राज्ञः पुलोमस्य मृत्योः अनन्तरं यः राज्यस्य धुराम् अवहत्।; \"राज्ञः पुलोमस्य अनन्तरं मगधदेशस्य सञ्चालनं रामदेवप्रतापचन्द्रादिभिः सेनापतिभिः कृतम् अतः सेनापतीनां वंशः अन्ध्रभृत्यः इत्युच्यते।\"','noun'),(33228,'','आमिनाम्रम्','अवधदेशे प्राप्यमाणः लघुः मधुरश्च आम्रप्रकारः।; \"बालकाः प्राङ्गणे आमिनाम्राणि चूषन्ति।\"','noun'),(33233,'','गारुडिकः','विषवैद्यः।; \"अहं गारुडिकं न आश्रयामि।\"','noun'),(33236,'','गरुडास्त्रम्','प्राचीनः अस्त्रविशेषः।; \"रावणेन प्रहारितस्य नागास्त्रस्य परिणामं अवरोद्धुं श्रीरामेण गरुडास्त्रेण प्रहारः कृतः।\"','noun'),(33232,'','गारुडितालम्','सङ्गीतशास्त्रे अष्टप्रकारेषु तालेषु एकः तालविशेषः।; \"वादकः गारुडितालं वादयति।\"','noun'),(33231,'','गारुड','गरुडस्य गरुडेन सम्बद्धः वा।; \"गारुडेण मन्त्रेण सर्पस्य विषम् अपसार्यते।\"','adjective'),(33229,'','गारुडम्','सर्पविषं अपाकरणस्य मन्त्रम्।; \"गारुडस्य देवता गरुडः अस्ति।\"','noun'),(33230,'','गरुडम्','सेनायाः गरुडाकारः व्यूहभेदः।; \"प्राचीने काले युद्धे गरुडस्य प्रयोगः भवति स्म।\"','noun'),(33211,'','अन्धिका','स्त्रीवर्गविशेषः।; \"सा अन्धिकाम् अग्रे नयति।\"','noun'),(33214,'','अन्धः','परिव्राजकविशेषः।; \"अद्य अन्धानां समूहः इतः अगच्छत्।\"','noun'),(33210,'','अन्धिका','नेत्ररोगविशेषः।; \"माता अन्धिकया पीडिता अस्ति।\"','noun'),(33208,'','अन्धबिन्दुः','नेत्रपटलस्य तत् स्थानं यस्य प्रकाशग्रहणस्य असामर्थ्येन वस्तूनि न दृश्यन्ते।; \"बहुधा मधुमेहः अपि अन्धबिन्दोः कारणं भवति।\"','noun'),(33207,'','अधिनिर्णयः','न्यायाधीशादिभिः दत्तः निर्णयः।; \"निर्णायकैः ग्रामसभायाम् अधिनिर्णयः श्रावितः।\"','noun'),(33206,'','भ्रातृजाया','अनुजस्य पत्नी।; \"मम भ्रातृजाया सुशीला अस्ति।\"','noun'),(33202,'','दृग्विहीना, अन्धा, गलितनयना, गताक्षा, दृष्टिहीना','दर्शने असमर्था स्त्री।; \"दृग्विहीना स्वपौत्रस्य साहाय्येन गच्छति।\"','noun'),(33200,'','अन्धपूतनाग्रहः','बालकानां रोगविशेषः।; \"मयङ्कः अन्धपूतनग्रहेण पीडितः अस्ति।\"','noun'),(33199,'','अन्धपरम्परा','कस्यापि प्राचीनायाः प्रथायाः अविचारेण एव अनुकरणम्।; \"अस्माभिः अन्धपरम्परायाः रक्षितव्यम्।\"','noun'),(33197,'','अन्धतमसम्, अन्धतामसम्, महान्धकारम्, निबिडान्धकारम्','निबिडः अन्धकारः।; \"अन्धतमसे वने किमपि न दृश्यते।\"','noun'),(33198,'','अन्धतामिस्रम्','योगशास्त्रानुसारेण पञ्चप्रकारकाज्ञानान्तर्गताज्ञानविशेषः।; \"अन्धतामिस्रे मनुष्यः किमपि चिन्तयितुं न शक्नोति।\"','noun'),(33195,'','चाण्डालकर्म','चाण्डालस्य कार्यम्।; \"विपत्समये राज्ञा हरिश्चन्द्रेण अपि चाण्डालकर्म कृतम्।\"','noun'),(33196,'','वज्रदंष्ट्रः','वीरः मायावी च राक्षसः यः रावणस्य सेनायाम् आसीत्।; \"अङ्गदः वज्रदंष्ट्रं जघान।\"','noun'),(33192,'','वज्रकेतुः','राक्षसविशेषः।; \"वज्रकेतोः नरके अधिकारः आसीत्।\"','noun'),(33191,'','वज्रः','विश्वामित्रस्य पुत्रः।; \"वज्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33189,'','वज्रोदरी','राक्षसीविशेषः।; \"वज्रोदर्याः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33185,'','वातमृगः, वातप्रमीः','यः मृगः वायोः दिशम् अभिमुख्य धावति।; \"आखेटकस्य अमोघात् लक्ष्यात् वातमृगः न परित्रातः।\"','noun'),(33187,'','अन्धकूपः','अन्धकारमयः कूपः।; \"सः पत्नीम् अन्धकूपे प्रालुठत्।\"','noun'),(33188,'','अन्धकूपः','नरकप्रकारः।; \"यः अन्यान् पीडयति सः अन्धकूपं गच्छति यत्र सर्पादयः विषदाः जीवाः तस्य रक्तं पिबन्ति।\"','noun'),(33180,'','उत्कूलनिकूलम्','उपरितः अधः अधस्तः उपरि गमनस्य अवस्था भावो वा।; \"तरङ्गाणाम् उत्कूलनिकूलं मोहयति।\"','noun'),(33184,'','अन्धःकारय','प्रकाशापनयनानुकूलः व्यापारः।; \"सः शयनात् पूर्वं प्रकोष्ठम् आन्धःकारयत्।\"','verb'),(33174,'','अन्त्रवृद्धिः','अन्त्रसम्बन्धी रोगविशेषः।; \"अन्त्रवृद्धेः कारणात् सः चलनसमये पीडाम् अनुभवति।\"','noun'),(33178,'','अन्दोलनम्, आन्दोलनम्, आलोलः','ऊर्मीणां समुद्वहनम्।; \"समुद्रतटे उपविश्य अन्दोलनस्य दर्शनं सुखदायकं भवति।\"','noun'),(33170,'','अन्त्यानुप्रासः','अनुप्रासालङ्कारस्य पञ्चसु प्रकारेषु एकः यस्मिन् कस्यापि पद्यस्य अन्तिमेषु अक्षरेषु साम्यं भवति।; \"शिक्षकः छात्राय अन्त्यानुप्रासस्य उदाहरणम् अपृच्छत्।\"','noun'),(33171,'','अन्त्रकूजनम्, अन्त्रविकूजनम्','अन्त्राणां ध्वनिः।; \"केवलं जलपानेन अपि कदाचित् अन्त्रकूजनस्य आभासः भवति।\"','noun'),(33166,'','चाण्डालिनी','देवताविशेषः।; \"ग्रामस्थाः जनाः चाण्डालिनीं पूजयन्ति।\"','noun'),(33167,'','चाण्डाली, दुष्टा','अधमा स्त्री।; \"चाण्डाल्याः सर्वे दूरे तिष्ठति।\"','noun'),(33169,'','अन्त्याक्षरी','पूर्वम् उक्तस्य छन्दसः पद्यस्य वा अन्तिमेन अक्षरेण आरभ्यमाणम् अन्यत् छन्दः पद्यम् वा।; \"साहित्यस्य ज्ञानवर्धकं धनम् अन्त्याक्षरी अस्ति।\"','noun'),(33159,'','अन्तःसारः','अन्तःस्थं तत्त्वम्।; \"अर्कः अन्तःसारः एव अस्ति।\"','noun'),(33161,'','हकारः','वर्णमालायाः अन्तिमं व्यञ्जनम्।; \"हकारेण आरभ्यमाणानि कतिचन पदानि वदतु।\"','noun'),(33162,'','अन्त्याक्षरम्, वागुत्तरम्','अन्तिमम् अक्षरम्।; \"अस्याः कवितायाः सर्वाणि अन्त्याक्षराणि समानानि एव।\"','noun'),(33163,'','अन्त्यविपुला','आर्याछन्दसः प्रकारः।; \"अन्त्यविपुलायाः द्वितीयस्य दलस्य तृतीयं गणं यावत् चरणः अपूर्णः एव भवति तथा द्वयोः दलयोः द्वितीयः तथा चतुर्थः गणः भवति।\"','noun'),(33158,'','अन्तःसार','अन्तःस्थेन तत्त्वेन युक्तम्।; \"महात्मनः अन्तःसारेण कथनेन सर्वे प्रभाविताः।\"','adjective'),(33146,'','अन्तःपटः','विवाहसमये वधुवरयोः मध्ये स्थाप्यमानः पटः।; \"अन्तःपटस्य एकस्मिन भागे वरमालां गृहीत्वा कन्या तिष्ठति।\"','noun'),(33153,'','अन्तःशुद्धिः','अन्तःकरणस्य पवित्रता निर्मलता वा।; \"अन्तःशुद्ध्या विना पूजनं व्यर्थमेव।\"','noun'),(33151,'','अन्तःपुरप्रचारः','स्त्रीणां संलापः।; \"तस्यै अन्तःपुरप्रचारः न रोचते।\"','noun'),(33143,'','अन्तःक्रिया','अन्तः जायमाना क्रिया।; \"अस्याम् उद्योगसंस्थायां नैकाः अनीप्सिताः अन्तःक्रियाः भवन्ति।\"','noun'),(33144,'','अन्तःकोपः','मनसि वर्तमानः क्रोधः।; \"सा अन्तःकोपं न प्रकटयति।\"','noun'),(33145,'','अन्तःकोशम्','अभ्यन्तरः कोष्ठः।; \"अन्तःकोशात् घृतस्य करण्डम् आनयतु।\"','noun'),(33140,'','अन्तेवासी','विद्याम् अध्येतुं गुरुसमीपे यः वसति।; \"प्राचीने काले अन्तेवासिनेभ्यः शिक्षणं दीयते स्म।\"','noun'),(33135,'','आसन्ननिवासिन्','समीपे वसति इति।; \"अद्य अस्माकम् आसन्ननिवासिनः वणिजः आपणं निरुद्धम् अस्ति।\"','adjective'),(33123,'','अन्तःपुरिकः, अन्तःपुरवर्ती, अन्तर्वंशिकः, अन्तर्वेश्मिकः','अन्तःपुररक्षकः।; \"अन्तःपुरिकः आगन्तुकम् अन्ते प्रवेशयितुम् अवारुणत्।\"','noun'),(33129,'','प्रियमेधः','राज्ञः अजमीढस्य पुत्रः।; \"प्रियमेधस्य वर्णनं पुराणेषु अस्ति।\"','noun'),(33130,'','अन्तःस्थवर्णः, अर्धस्वरः','य र ल व इत्यादयः चत्वारः वर्णाः।; \"स्पर्शाणाम् उष्मणां च मध्ये वर्तमानत्वात् एते अन्तःस्थवर्णाः इति कथ्यन्ते।\"','noun'),(33132,'','अन्तःसलिल','यस्य जलस्य प्रवाहः अन्तः भवति।; \"भारतदेशे अन्तःसलिलाः नद्यः सन्ति।\"','adjective'),(33134,'','अन्तेवसायिन्','समाजविशेषः यः ग्रामप्रान्ते निवसति।; \"अन्तेवासिनः कदाचित् ग्रामम् आगच्छन्ति।\"','noun'),(33109,'','लापिका','प्रहेलिकायाः भेदः।; \"अन्तर्लापिका बहिर्लापिका च लापिकायाः द्वौ भेदौ।\"','noun'),(33111,'','अन्तर्वाणिज्यम्','देशस्य आन्तरिकेषु भागेषु क्रियमाणं वाणिज्यम्।; \"सर्वकारः अन्तर्वाणिज्यं प्रोत्साहयति।\"','noun'),(33112,'','अन्तर्बाष्पः','अश्रुरहितम् आन्तरिकं दुःखम्।; \"पुत्रस्य मृत्योः अन्तर्बाष्पेण सः मौनी जातः।\"','noun'),(32963,'','आनर्तः','सौराष्ट्रस्य निवासी।; \"मम प्रतिवेशी आनर्तः अस्ति।\"','noun'),(33139,'','चन्द्रशाला, चन्द्रशालिका','चन्द्रिकायाः आनन्दम् अनुभवितुम् उन्नते अट्टालके निर्मितः प्रकोष्ठः।; \"अस्मिन् प्रासादे चन्द्रशाला अपि अस्ति।\"','noun'),(33136,'','अन्तिक','अन्तपर्यन्तं यद् गच्छति।; \"ग्रामस्य अन्तिकः मार्गः अयम्।\"','adjective'),(33114,'','शाम्भवी','नीलवर्णीया दुर्वा।; \"भूमौ पल्लवितां शाम्भवीं सः उन्मूलयति।\"','noun'),(33116,'','कुब्जिका','अष्टवर्षीया कन्या या देव्याः उत्सवकाले देवीरूपेण पूज्यन्ते।; \"केचन जनाः नवरात्रोत्सवकाले कुब्जिकाः पूजयन्ति।\"','noun'),(33118,'','दीप्तकेतुः','पौराणिकः राजा।; \"दीप्तकेतोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33121,'','अन्तर्वेगः','ज्वरविशेषः यस्मिन् अधिका पिपासा भवति तथा दाहः, भ्रामरं, शिरोवेदना, उदरवेदना च भवति।; \"रुग्णः अन्तर्वेगेण पीडितः अस्ति।\"','noun'),(33100,'','मलम्','शरीरे वर्तमानाः अनीप्सिताः पदार्थाः।; \"मलस्य अवरोधेन नैके व्याधयः उत्पद्यन्ते।\"','noun'),(33101,'','अन्तर्मुख','यस्य मुखम् अन्तःस्थितं भवति।; \"अन्तर्मुखः कूर्मः इव यः इन्द्रियान् सङ्कोचयितुं शक्नोति तस्मै एव साक्षात्कारः भवति।\"','adjective'),(33102,'','अन्तर्मुखम्','कर्तरीप्रकारः यस्य अग्रः अन्तःस्थितः भवति।; \"अन्तर्मुखस्य उपयोगः शस्त्रक्रियायां भवति।\"','noun'),(33104,'','मोहेनजोदडोनगरम्','2600वर्षपूर्वं सिन्धुतटस्थं बृहत् नगरं यद् इदानीं पाकिस्तानदेशस्य सिन्धप्रदेशे अस्ति।; \"प्राचीनेषु नगरेषु मोहेनजोदडोनगरम् एकम्।\"','noun'),(33105,'','अन्तर्योगः','मनसा क्रियमाणः योगः।; \"अन्तर्योगेन विना साधना न शक्यते।\"','noun'),(33106,'','अन्तर्लम्बः','त्रिकोणे वर्तमानः लम्बः।; \"अस्य अन्तर्लम्बस्य दैर्घ्यम् मिमीताम्।\"','noun'),(33108,'','बहिर्लापिका','प्रहेलिकाभेदः यस्य उत्तरं पदयोजनायाः बहिः भवति।; \"एक गुनी ने यह गुन कीनी, हरियल पिंजरे में दे दीनी। देखा जादूगर का हाल, डाले हरा निकाले लाल।।इदं बहिर्लापिकायाः उदाहरणम् अस्ति।\"','noun'),(33096,'','अन्तर्भावः','जैनदर्शने अष्टानां कर्मणां क्षयः येन मोक्षप्राप्तिः भवति।; \"सः जैनमुनिः अन्तर्भावात् अनन्तरं मोक्षं प्राप्तवान्।\"','noun'),(33098,'','अन्तर्भौम','पृथिव्याः अन्तस्थः भागः।; \"नैकानि अन्तर्भौमानि वस्तूनि अस्माकं कृते लाभदायकानि सन्ति।\"','adjective'),(33099,'','अन्तर्गतमनस्','स्वविचारान् एव यः चिन्तयति।; \"अन्तर्गतमनसः पुरुषस्य विषये अवबोधनं कठिनं भवति।\"','adjective'),(33094,'','विलयनम्, संलयनम्','कस्यापि घनपदार्थस्य द्रवपदार्थेन एकीभवनस्य क्रिया।; \"शीतलस्य जलस्य अपेक्षया उष्णे जले शर्करायाः विलयनं शीघ्रं भवति।\"','noun'),(33093,'','मतिभ्रमः, मतिभ्रान्तिः, मतिविभ्रमः','मानसिक्याः अस्थिरतायाः कारणात् उत्पन्ना अवस्था यस्यां कश्चन तद् श्रुणोति पश्यति वा यद् वास्तवे तु न विद्यते एव।; \"वृद्धावस्थायाः कारणात् पितामहः मतिभ्रमेण पीडितः भवति।\"','noun'),(33090,'','अन्तर्गान्धारः','सङ्गीतशास्त्रे तृतीयस्य स्वरस्य भेदविशेषः।; \"सङ्गीतज्ज्ञः अन्तर्गान्धारं ज्ञापयति।\"','noun'),(33088,'','अन्तरिक्षः','ऋषिविशेषः।; \"अन्तरिक्षस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33080,'','नृपसभम्','राजगृहे राज्ञः उपवेशनस्य स्थानम्।; \"नृपसभे राजा चिन्तयन् आसीत्।\"','noun'),(33081,'','आदिग्रन्थः','कबीरविरचितग्रन्थविशेषः।; \"आदिग्रन्थे 243 सूक्तयः सन्ति।\"','noun'),(33079,'','आभ्युदयिक','अभ्युदयेन सम्बद्धम्।; \"प्रत्येकस्मिन् शुभकार्ये आभ्युदयिकं श्राद्धं क्रियते।\"','adjective'),(33076,'','आभोगः','कविनामयुक्तं काव्यम्।; \"पूर्वतनीयानां कवीनां रचनासु आभोगस्य विद्यमानता सामान्या आसीत्।\"','noun'),(33077,'','आभ्युदयिकम्','श्राद्धविशेषः यः कर्तुः अभ्युदयस्य प्रयोजनम् अस्तीति मन्यते।; \"अस्माकं प्रतिवेशी अद्य आभ्युदयिकं करोति।\"','noun'),(33070,'','मनुस्मृतिः','एका प्रमाणिता स्मृतिः यस्याः रचयिता स्वायम्भुवः मनुः अस्ति।; \"तस्मै मनुस्मृतेः पाठनं रोचते।\"','noun'),(33069,'','स्मार्तः','स्मृत्यनुसारं यः आचरति।; \"आधुनिके काले स्मार्तानाम् उपलब्धता कठिना एव।\"','noun'),(33061,'','ब्रह्मग्रन्थिः','यज्ञोपवीतस्य मुख्या ग्रन्थिः।; \"ब्रह्मग्रन्थ्याः अपरा अन्या ग्रन्थिः न भवति।\"','noun'),(33062,'','ब्रह्मयोगः','अष्टादशानां मात्राणां तालविशेषः।; \"ब्रह्मयोगे द्वादश आघाताः सन्ति।\"','noun'),(33064,'','पञ्चदेवता','दुर्गाशिवविष्णुगणेशसूर्यदेवाः एते पञ्चदेवाः येषां विशिष्टानुष्ठानेन पूजनं क्रियते।; \"स्मार्ताः जनाः पञ्चदेवतायाः आराधनां कुर्वन्ति।\"','noun'),(33029,'','स्रावित','स्रावरूपेण यद् स्रवति।; \"शरीरस्य केभ्यश्चित् अङ्गेभ्यः निश्चितायां मात्रायां स्रावितः स्रावः आवश्यकं भवति।\"','adjective'),(33055,'','वेणः','वर्णसङ्करजातिविशेषः।; \"वेणस्य मुख्यः व्यवसायः सङ्गीतसम्बद्धः आसीत्।\"','noun'),(33054,'','चारुः','कृष्णपुत्रः।; \"रुक्मिण्याः गर्भात् चारुः उत्पन्नः।\"','noun'),(33052,'','पलवलमण्डलम्','हरियाणाराज्ये वर्तमानं मण्डलम्।; \"भारतीयस्वतन्त्रतासङ्ग्रामे पलवलमण्डलस्य विशेषं योगदानम् आसीत्।\"','noun'),(33049,'','दृढायुः','ऐलपुत्रः।; \"दृढायुः उर्वश्याः गर्भात् जातः।\"','noun'),(33050,'','ऐलः','पौराणिकः राजाविशेषः।; \"उर्वश्या उत्पन्नः दृढायुनामकः ऐलस्य पुत्रः आसीत्।\"','noun'),(33047,'','दुर्मुखः','यक्षविशेषः।; \"दुर्मुखस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33048,'','दृढपदम्','त्रयोविंशतीनां मात्राणां छन्दोविशेषः।; \"दृढपदस्य अन्ते द्वौ गुरू भवतः।\"','noun'),(33046,'','दुर्मुखः','नागविशेषः।; \"दुर्मुखस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33045,'','दुर्मुखी','राक्षसीविशेषः।; \"दुर्मुख्याः वर्णनं रामायणे प्राप्यते।\"','noun'),(33038,'','कषायपात्रम्, चायपात्रम्','कषायं निर्मातुम् उपयुज्यमानं पात्रम्।; \"कषायं निर्मातुं माता कषायपात्रे जलम् उष्णीकरोति।\"','noun'),(33035,'','नलिनी, मनहरणम्','वर्णवृत्तविशेषः।; \"नलिन्याः प्रत्येकस्मिन् चरणे पञ्च सगणाः भवन्ति।\"','noun'),(33036,'','नलिनी','नारिकेलनिर्मिता सुरा।; \"कुल्यायाः तटे उपविश्य द्वौ कर्मकरौ नलिनीं पिबतः।\"','noun'),(33034,'','नलिका','अस्त्रविशेषः यः इदानींतनीयायाः लोहसुष्यायाः इव आसीत् इति कथ्यते।; \"नलिकायाः गुलिकाः शराः वा उत्सृज्यन्ते स्म।\"','noun'),(33025,'','राजप्रिया, राजपुष्पी','करुणीवृक्षस्य पुष्पाणि यानि कोकणप्रान्ते प्राप्यन्ते।; \"शीला राजप्रियायाः मालां निर्माति।\"','noun'),(33019,'','भोजः','वसुदेवस्य पुत्रः।; \"भोजस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33020,'','भोजः','कृष्णस्य सखा।; \"भोजस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33023,'','राजाद्रिः','आर्द्रकविशेषः।; \"राजाद्रेः उपयोगः औषधरूपेण क्रियते।\"','noun'),(33024,'','करुणी, ग्रीष्मपुष्पी, राजपुष्पी, रक्तपुष्पी, चारिणी, राजप्रिया, सूक्ष्मा, ब्रह्मचारिणी','पुष्पवृक्षविशेषः यः विशेषतः कोकणप्रदेशे भवति।; \"कृषकः करुणीम् उन्मूलयति।\"','noun'),(33017,'','भद्रः, तुषितः','स्वायम्भुवमन्वन्तरे विष्णोः जातः देवगणभेदः।; \"भद्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33016,'','भद्रः','बलदेवस्य सहोदरः।; \"भद्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33014,'','भद्रः','दिग्गजविशेषः।; \"उत्तरदिशः दिग्गजः भद्रः अस्ति।\"','noun'),(33015,'','भद्रः','विष्णोः द्वारपालः।; \"भद्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(33012,'','पेषणम्, संचूर्णनम्','पेषस्य क्रिया।; \"गोधूमानां पेषणम् अभवत्।\"','noun'),(33013,'','पिष्टपेषणम्','एकवारं सम्यक् कृतं कार्यं पुनः तथैव कृत्वा वृथा परिश्रमः।; \"बहुधा वृत्तान्तलेखकाः कस्याश्चित् वार्तायाः पिष्टपेषणं कुर्वन्ति।\"','noun'),(33010,'','आभीरपल्ली','प्राचीनं स्थानं यत्र गोपाः निवसन्ति स्म।; \"आभीरपल्ल्यां निवसन्तः जनाः सुखिनः आसन्।\"','noun'),(33011,'','पिष्टपेषणम्','पिष्टस्य वस्तुनः पुनः पेषणस्य क्रिया।; \"शीला व्यञ्जनानां पिष्टपेषणं करोति।\"','noun'),(33009,'','आभीरः','छन्दोविशेषः यस्य प्रत्येकस्मिन् चरणे एकादश मात्रा अन्ते जगणः च भवति।; \"इदम् आभीरस्य उदाहरणम् अस्ति।\"','noun'),(33003,'','आध्यात्मिकता, अध्यात्मिकता','आध्यात्मिकस्य अवस्था भावः वा।; \"प्रेम, दया तथा अहिंसा आध्यात्मिकतां वर्धयन्ति।\"','noun'),(33008,'','आभारः','चतुर्भिः चरणैः युक्तः वर्णवृत्तविशेषः।; \"आभारस्य प्रत्येकस्मिन् चरणे अष्ट तगणाः भवन्ति।\"','noun'),(33001,'','जलीय, अम्बुमत्','जलस्य अथवा जलेन सम्बद्धः।; \"पृथिव्याः प्रायः प्रतिशतं पञ्चसप्ततिः भागः जलीयं क्षेत्रम् अस्ति।\"','adjective'),(32988,'','आप्लावनम्','जले अवगाहनम्।; \"एतावता वर्षया ग्रामस्य आप्लावनं भविष्यति।\"','noun'),(32998,'','हडप्पाः','सिन्धुप्रदेशस्य क्षेत्रविशेषः यत्र पुरातनीयायाः संस्कृतेः भग्नावशेषाः प्राप्ताः।; \"हडप्पाः संस्कृतिं ज्ञातुं सः उत्सुकः अस्ति।\"','noun'),(32987,'','आपानम्','नैकैः जनैः सह मद्यपानम्।; \"मदिरालये आपानं सर्वदा दृश्यते एव।\"','noun'),(32976,'','आपत्कालिक','यद् आपत्काले भवति।; \"जलप्लावनसदृशाः आपात्कालिकायाः स्थितेः रक्षितुं व्यवस्था कृता वर्तते।\"','adjective'),(32980,'','मोक्षदायिन्','मोक्षं ददाति इति।; \"ईश्वरभक्तिः मोक्षदायिनी अस्ति।\"','adjective'),(32983,'','आपातः','अतर्कितोपपन्ना घटना।; \"अस्माकं देशे प्रतिवर्षं जलप्लावनभूकम्पसदृशेषु आपाते नैके जनाः म्रियन्ते।\"','noun'),(32975,'','आपणिकः','आपणात् स्वीक्रियमाणः करः।; \"आरक्षकः आपणिकं सङ्गृह्णाति।\"','noun'),(32974,'','आनुमानिक','अनुमानेन सम्बद्धम्।; \"अस्मिन् वर्षे धान्यस्य आनुमानिकम् उत्पादनं शतं लक्षधान्यं यावत् भविष्यति इति मन्यते।\"','adjective'),(32973,'','कुलेखिन्','यः सुन्दरं स्पष्टं च न लिखति।; \"एतत् पत्रं केनचित् कुलेखिना मनुष्येण लिखितम् अस्ति।\"','adjective'),(32965,'','सौराष्ट्रीभाषा','सौराष्ट्रस्य भाषा।; \"इदं पुस्तकं सौराष्ट्रीभाषायां लिखितम् अस्ति।\"','noun'),(32944,'','व्याघ्राक्षः','कार्तिकेयस्य अनुचरः।; \"व्याघ्राक्षस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32945,'','व्याघ्रपुष्पिः','ऋषिविशेषः।; \"व्याघ्रपुष्पेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32950,'','आधिभौतिक','भौतिकानां पदार्थानां कारणात् जायमानं दुःखम्।; \"सर्वेषां व्याधीनां समावेशः आधिभौतिके दुःखे भवति।\"','adjective'),(32951,'','आधिवेदनिकम्','द्वितीयस्मात् विवाहात् पूर्वं प्रथमायै पत्न्यै दत्तं धनम्।; \"मङ्गला आधिवेदनिकेन सन्तुष्टा नास्ति।\"','noun'),(32953,'','आनन्दभैरवः','वैद्यकशास्त्रे रसविशेषः।; \"आनन्दभैरवस्य कृशतां दूरीकर्तुम् उपयोगः क्रियते।\"','noun'),(32955,'','आनकः','शब्दं कुर्वाणः मेघः।; \"आनकस्य स्तनितेन अहं जागरिता।\"','noun'),(32956,'','आनतः','जैनधर्मीयाणां देवता।; \"आनतस्य उल्लेखः जैनानां धर्मग्रन्थेषु प्राप्यते।\"','noun'),(32959,'','शुष्कचर्चनम्, विकथा, वृथाकथा, हतजल्पितम्','सारहीनं कथनम्।; \"भवतः शुष्कचर्चनं श्रोतुं मम समीपे समयः नास्ति।\"','noun'),(32960,'','निकरः','केनचित् कार्ये कृते सादरं दीयमानं धनम्।; \"परीक्षकेभ्यः पञ्चशतं रूप्यकं निकरं दत्तम्।\"','noun'),(32961,'','आनद्ध','चर्मणा आच्छादितं वाद्यम्।; \"पटहः आनद्धं वाद्यम् अस्ति।\"','adjective'),(32962,'','नृत्यशाला, नर्तनशाला, आनर्तः','यत्र नृत्यं क्रियते।; \"नृत्यशालायां नर्तक्याः नुपूराणां ध्वनिः अनुनदति।\"','noun'),(32943,'','व्रजभाषा','व्रजक्षेत्रीया भाषा।; \"सूरदासस्य काव्यं व्रजभाषायाम् अस्ति।\"','noun'),(32935,'','मूसीनदी','भारतीया नदी।; \"मूसीनदी कृष्णानद्याः सहायिका नदी अस्ति।\"','noun'),(32938,'','आधर्षित','न्यायालये यस्य अपराधः सिद्धः जातः।; \"आधर्षितः मनुष्यः इदानीम् अपि आत्मानं निरपराधं कथयति।\"','adjective'),(32934,'','मूलानदी','भारतीया नदी।; \"मूलानदी महाराष्ट्रराज्यात् वहति।\"','noun'),(32933,'','मूठानदी','भारतीया नदी।; \"मूठानदी अतीव प्रदूषिता अस्ति।\"','noun'),(32914,'','पुनपुननदी','भारतीया नदी।; \"पुनपुननदी बिहारराज्यात् वहति।\"','noun'),(32915,'','पेन्नारनदी','भारतीया नदी या कर्नाटकराज्यात् बङ्गालराज्यस्य अखातपर्यन्तं वहति।; \"पेन्नारनद्याः जलस्य उपयोगः सेचनादिषु कार्येषु क्रियते।\"','noun'),(32931,'','बैगईनदी','भारतीया नदी।; \"दक्षिणभारतदेशात् बैगईनदी वहति।\"','noun'),(32932,'','महानन्दानदी','भारतीया नदी।; \"महानन्दानदी बङ्गालराज्यात् वहति।\"','noun'),(32930,'','आद्याक्षरम्','नैकपदयुक्तनाम्नः प्रत्येकस्य पदस्य आद्यः अक्षरः यस्य उपयोगः हस्ताक्षरं कर्तुं क्रियते।; \"हजारीप्रसादद्विवेदीमहोदयस्य आद्याक्षराणि ह प्र द्वि सन्ति।\"','noun'),(32929,'',' ',' ; \"\"','adjective'),(32903,'','शान्तिदेवा','उग्रसेनस्य अनुजः देवकनाम्नः यदुवंशीयस्य पुत्री।; \"शान्तिदेवा देवक्याः भगिनी आसीत्।\"','noun'),(32904,'','उपदेवा','उग्रसेनस्य अनुजस्य देवकस्य पुत्री।; \"उपदेवा देवक्याः भगिनी आसीत्।\"','noun'),(32905,'','सहदेवा','उग्रसेनस्य अनुजस्य देवकस्य पुत्री।; \"सहदेवा देवक्याः सहोदरी आसीत्।\"','noun'),(32906,'','धृतराष्ट्री','कश्यपऋषेः पत्नी।; \"धृतराष्ट्र्याः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32907,'','धार्तराष्ट्र','धृतराष्ट्रस्य धृतराष्ट्रेण वा सम्बद्धः।; \"इदानीन्तनीयाः केचन नेतारः पुत्रमोहस्य धार्तराष्ट्रां परम्परां पालयन्ति।\"','adjective'),(32908,'','धृतिः','दक्षप्रजापतेः पुत्री।; \"धृतेः वर्णनं पुराणेषु अस्ति।\"','noun'),(32909,'','धृतिः','जयद्रथस्य पुत्रः।; \"धृतेः वर्णनं पुराणेषु अस्ति।\"','noun'),(32910,'','गोमतीनदी, वाशिष्ठी','भारतीया नदी या उत्तरप्रदेशराज्ये वहति तथा गङ्गानद्याः सहायिका अस्ति।; \"गोमतीनद्याः वर्णनं पुराणेषु अपि अस्ति।\"','noun'),(32911,'','इन्द्रावतीनदी','भारतीया नदी या उत्कलप्रान्तात् प्रभूय छत्तीसगडराज्ये वहति।; \"इन्द्रावतीनद्याः दैर्घ्यम् अनुमानतः 240 क्रोशकम् इति अस्ति।\"','noun'),(32912,'','टोन्सनदी','यमुनानद्याः सहायिका नदी।; \"टोन्सनदी देहरादूननगरात् अनुमानतः 50-60 किलोमीटरं दूरे यमुनानदीं मिलति।\"','noun'),(32928,'','आदेशः','व्याकरणशास्त्रे एकस्य वर्णस्य स्थाने अन्यस्य वर्णस्य उपस्थितिः।; \"सच्चरितम् इत्यत्र त् इत्यस्य स्थाने च् इति आदेशः भवति।\"','noun'),(32927,'','आदेशः','ज्योतिःशास्त्रानुसारेण ग्रहाणां फलम्।; \"भवतः जन्मपत्रिकानुसारेण अस्मिन् समये भवतः आदेशः प्रतिकूलः अस्ति।\"','noun'),(32926,'','आदेयकर्म','जैनमतानुसारेण जीवानुगामि कर्म।; \"आदेयकर्म नित्यं सुखदायकं नास्ति।\"','noun'),(32925,'','उद्दीप्त','यस्य उद्दीपनं जातम्।; \"उद्दीप्तानाम् कामनानाम् अप्राप्तिः एव क्रोधस्य कारणम्।\"','adjective'),(32924,'','उद्दीपक','जठराग्निम् उद्दीपयति असौ।; \"आमलकम् उद्दीपकं खाद्यम् अस्ति।\"','adjective'),(32922,'','आदिष्ट','यस्मिन् सन्दर्भे आदेशः प्राप्तः।; \"आदिष्टं कार्यं कदा पूर्णं भविष्यति।\"','adjective'),(32917,'','चित्रावतीनदी','भारतीया नदी।; \"चित्रावतीनदी पेन्नारनद्याः सहायिका नदी अस्ति।\"','noun'),(32916,'','पापाधननदी','भारतीया नदी।; \"पापाधननदी पेन्नारनद्याः सहायिका अस्ति।\"','noun'),(32913,'','तवानदी','भारतीया नदी।; \"मध्यप्रदेशराज्यस्य होशङ्गाबदमण्डले तवानद्याः तथा नर्मदानद्याः संयोगः भवति।\"','noun'),(32884,'','आत्रेयीनदी','प्राचीना नदी या अधुना दीनाजपूरमण्डले अस्ति।; \"आत्रेयीनद्यां निर्मितस्य सेतोः नाम सरोजः अस्ति।\"','noun'),(32885,'','आत्रेयी','अत्रिवंशोत्पन्ना स्त्री या वेदान्तशास्त्रस्य ज्ञात्री आसीत्।; \"आत्रेयी स्वस्य विद्वत्तायाः कृते ख्याता आसीत्।\"','noun'),(32886,'','आत्रेयी','अत्रिगोत्रोत्पन्ना स्त्री।; \"अपाला एका आत्रेयी आसीत्।\"','noun'),(32888,'','आथर्वणः','अथर्ववेदस्य ज्ञाता ब्राह्मणः वा।; \"आथर्वणः सर्वत्र ख्यातः अस्ति।\"','noun'),(32890,'','आथर्वणः','अथर्वणः ऋषेः वंशजः।; \"पण्डितः उमाशङ्करः आथर्वणः अस्ति।\"','noun'),(32892,'','आथर्वणः','अथर्वणः पुत्रः।; \"आथर्वणः ब्रह्मणः पौत्रः आसीत्।\"','noun'),(32896,'','लतिका','लघ्वी लता।; \"वृक्षेषु लतिका लम्बते।\"','noun'),(32898,'','आदित्यः','अदितेः अपत्यम्।; \"आदित्यानां सङ्ख्या विविधेषु पुस्तकेषु भिन्ना एव लिखिता अस्ति।\"','noun'),(32899,'','आदित्यः','द्वादशमात्राणां छन्दोविशेषः।; \"इदं पद्यम् आदित्यस्य उत्तमम् उदाहरणम् अस्ति।\"','noun'),(32900,'','आदित्यकेतुः, उदयभातः','देहलीनगरस्य राजा यस्य पूर्वजानां 375वर्षं यावत् देहलीनगरे राज्यम् आसीत्।; \"आदित्यकेतुः जाटजातीयः राजा आसीत्।\"','noun'),(32901,'','देवकः','युधिष्ठिरस्य पुत्रः।; \"देवकस्य वर्णनं पुराणे अस्ति।\"','noun'),(32902,'','धृतदेवा','यदुवंशीयस्य देवकस्य पुत्री।; \"धृतदेवा देवक्याः भगिनी तथा कृष्णस्य मातृष्वसा आसीत्।\"','noun'),(32870,'','मेघनादरसः','आयुर्वेदे वर्तमानः रसौषधः।; \"मेघनादरसः ज्वरनाशकः अस्ति।\"','noun'),(32880,'','आत्रेयः','अत्रिमुनेः वंशजः।; \"ते आत्मानम् आत्रेयं कथयन्ति।\"','noun'),(32881,'','आत्रेयः','अत्रिमुनेः पुत्रः।; \"दुर्वासाचन्द्रमादयः आत्रेयाः सन्ति।\"','noun'),(32882,'','आत्रेयः','आत्रेयीनद्याः समीपस्थः देशः।; \"आत्रेयः इदानीं दीनाजपुरम् इति नाम्ना प्रसिद्धः अस्ति।\"','noun'),(32855,'','यादवः','यदुसम्बन्धी।; \"श्रीकृष्णस्य जन्म यादवे कुले जातः।\"','adjective'),(32857,'','आत्मकृत, स्वकृत','यद् आत्मना क्रियते।; \"आत्मकृतानां कर्मणां फलं तु भोक्तव्यम् एव।\"','adjective'),(32858,'','स्वरक्षित','स्वशक्त्या रक्षितम्।; \"राज्ञः स्वरक्षिता सेना कदापि न पराजिता।\"','adjective'),(32860,'','आत्मतत्त्वम्','आत्मनः यथार्थं स्वरूपम्।; \"श्रीमद्भगवद्गीता आत्मतत्त्वं प्रतिपादयति।\"','noun'),(32863,'','डिङ्गलभाषा','राजस्थानराज्यस्य मध्ययुगीना भाषा।; \"डिङ्गलभाषायां चारणकाव्यं लिखितम् अस्ति।\"','noun'),(32865,'','आत्मद्रोहिन्','आत्मानम् एव क्लिश्नाति इति।; \"आत्मद्रोहिणः प्रतिहताः भवन्ति।\"','adjective'),(32867,'','परस्मैपदम्','संस्कृतभाषायाः व्याकरणशास्त्रानुसारेण धातोः द्वयोः प्रत्ययसमूहयोः एकः यः कर्तारम् अभिधत्ते।; \"नम् धातोः ति प्रत्यतेन नमति इति परस्मैपदं रूपं प्राप्यते।\"','noun'),(32868,'','आत्मनेपदम्','संस्कृतभाषायाः व्याकरणशास्त्रानुसारेण धातोः द्वयोः प्रत्ययसमूहयोः एकः येन युक्तं क्रियापदं क्रियाफलं कर्तारम् अभिप्रैति इति सूचयति।; \"राज् धातोः त प्रत्यये राजते इति आत्मनेपदं रूपं भवति।\"','noun'),(32869,'','उदरम्भरिः, आत्मम्भरिः, कुक्षिम्भरिः','यः स्वोदरमात्रं पूरयति।; \"उदरम्भरेः कुटुम्बिनः बुभुक्षिताः एव स्वपन्ति।\"','noun'),(32853,'','युक्तिः','अर्थालङ्कारविशेषः।; \"रहस्यस्य क्रियायाः वा अन्येभ्यः कुशलतापूर्वकं गोपनं वर्ण्यते युक्तौ।\"','noun'),(32854,'','यादवः','यदोः कुलजाः।; \"परस्परयोः जातस्य युद्धस्य कारणात् एव यादवानां विनाशः जातः।\"','noun'),(32849,'','पातालनिवासी','पातालस्य निवासी।; \"विष्णुपुराणानुसारेण केचन दानवाः नागगणाः च पातालनिवासिनः सन्ति।\"','noun'),(32846,'','अग्निपूजकः','सः मनुष्यः यः अग्निं पूजयति।; \"प्राचीनाः आर्याः अग्निपूजकाः आसन्।\"','noun'),(32851,'','सूक्ष्मशरीरम्','ज्ञानेन्द्रियपञ्चकं कर्मेन्द्रियपञ्चकं वायुपञ्चकं बुद्धिमनसी चेति सप्तदश अवयवाः।; \"आत्मनः मोक्षप्राप्तिपर्यन्तं सूक्ष्मशरीरं वर्तते।\"','noun'),(32835,'','आडिः','मत्स्यविशेषः।; \"अस्मिन् तडागे नैकाः आडयः सन्ति।\"','noun'),(32839,'','आतङ्कः','वाद्यस्य ध्वनिविशेषः।; \"आतङ्कस्य ध्वनिना वादकः प्राकम्पत।\"','noun'),(32840,'','आतपशुष्क','यद् आतपे शुष्कम्।; \"अत्र आतपशुष्काः मीनाः आतपशुष्काणि शाकानि च प्राप्यन्ते।\"','adjective'),(32842,'','आतर्पणम्, प्रीणनम्','माङ्गलिकं लेपनम्।; \"विवाहात् पूर्वं हरिद्राचन्दनादिभिः कन्यायाः आतर्पणं क्रियते।\"','noun'),(32818,'','आटोपः','उदरे वायुजन्यध्वनिविशेषः।; \"उदरस्थस्य वायोः कारणात् एव आटोपः भवति।\"','noun'),(32824,'','आडम्बरः','बृहत् पटहविशेषः।; \"युद्धकाले आडम्बरं वादयते स्म।\"','noun'),(32825,'','पञ्चनदः','पञ्चनदिभिः युक्तः देशः।; \"अहं पञ्चनदे निवसामि।\"','noun'),(32834,'','प्रकम्पनम्','प्रकम्पस्य क्रिया अवस्था भावः वा।; \"अर्णवपोतस्य प्रकम्पनेन भीतानां यात्रिकाणां क्षेपणिकः समाश्वासनं कुर्वन् आसीत्।\"','noun'),(32815,'','आज्यभागः','उत्तरभागे दक्षिणभागे च दीयमाना घृताहूतिः।; \"अग्निदेवतायै सौमदेवतायै च आज्यभागः प्रदीयते।\"','noun'),(32816,'','आज्यपात्रम्, आज्यस्थाली','यज्ञकर्मणि घृतं स्थापयितुम् उपयुक्तः पात्रविशेषः।; \"अन्तिमायाम् आहुत्याम् आज्यापात्रे वर्तमानं घृतम् अग्नौ अर्पितम्।\"','noun'),(32799,'','आच्छादः, आच्छादनम्','आच्छादयितुम् उपयुज्यमानः वस्त्रविशेषः।; \"भवत्याः पूजायाः स्थाल्याः आच्छादः सुन्दरः अस्ति।\"','noun'),(32802,'','आजमीढ','आजमीढस्य कुलजाः।; \"दृढनेमिः आजमीढः राजा आसीत्।\"','adjective'),(32804,'','दृढनेमिः','आजमीढवंशीयः राजा।; \"दृढनेमिः कुशलः राजा आसीत्।\"','noun'),(32808,'','आजानेयः','श्रेष्ठजातीयः अश्वः।; \"आजानेये आरुढः योद्धा वीरतापूर्णं कार्यम् अकरोत्।\"','noun'),(32809,'','आज्ञाचक्रम्','तन्त्रानुसारेण षट्चक्रान्तर्गतं षष्ठचक्रम्।; \"द्विदलयुक्तं कमलाकारम् आज्ञाचक्रम् अस्तीति मन्यते यस्मिन्नेव ध्यानावस्थायाम् ऐकाग्र्यं क्रियते।\"','noun'),(32811,'','आज्ञापालनम्','आज्ञया अनुसारेण कार्यसम्पादनस्य क्रिया।; \"गुरोः आज्ञापालनेन ज्ञानप्राप्तौ साहाय्यं लभते।\"','noun'),(32812,'','आज्ञाभङ्गः, आज्ञाप्रतिघातः','आज्ञायाः उल्लङ्घनस्य क्रिया।; \"आज्ञाभङ्गस्य कारणात् कर्मकरः कार्यालयात् निष्कासितः।\"','noun'),(32813,'','आज्यादोहः','सामवेदस्य सूक्तम्।; \"आज्यादोहे तिस्रः ऋचः सन्ति।\"','noun'),(32793,'','आचार्यता, आचार्यत्वम्','आचार्यस्य कार्यं पदं भावः वा।; \"तस्य आचार्यतां सर्वे इच्छन्ति।\"','noun'),(32798,'','आच्छकः, रञ्जनद्रुः, पक्षीकः, पक्षिकः, आक्षिकः','वृक्षविशेषः।; \"आच्छकेन रक्तवर्णः निर्मीयते।\"','noun'),(32791,'','भाष्यकारः','यः सूत्राणि स्पष्टीकरोति।; \"ब्रह्मसूत्रस्य प्रमुखः भाष्यकारः शङ्कराचार्यः अस्ति।\"','noun'),(32781,'','प्रलोठनम्, प्रकर्षणम् घट्टनम्, प्रोहणम्','प्रलुठ्यते इति।; \"तस्य प्रलोठनेन अहम् अपतम्।\"','noun'),(32787,'','आचार्यः','उपनयनसंस्कारस्य समये यः बटवे गायत्रीमन्त्रम् उपदिशति।; \"बालकस्य कर्णे गायत्रीमन्त्रम् उक्त्वा आचार्येण स्वस्थानं गृहीतम्।\"','noun'),(32779,'','आचरित, व्यवहृत','यस्य आचरणं कृतम्।; \"महापुरुषैः आचरितं कार्यम् अस्माभिः अनुसर्तव्यम्।\"','adjective'),(32778,'','आचरणीय','व्यवहर्तुम् आचरितुं वा योग्यः।; \"आचरणीयानां नियमानाम् अस्माभिः पालनं कर्तव्यम्।\"','adjective'),(32772,'','घोणसः','सरिसृपविशेषः।; \"घोणसः विषयुक्तः भवति।\"','noun'),(32771,'','आघ्रातम्','ग्रहणस्य दशसु भेदेषु एकः।; \"आघ्राते चन्द्रमण्डलस्य सूर्यमण्डलस्य वा कश्चित् भागः मन्दप्रभः दृश्यते।\"','noun'),(32763,'','आघ्राणम्, अवघ्राणम्','घ्राणस्य क्रिया।; \"कर्पूरस्य आघ्राणं सुखदायकं भवति।\"','noun'),(32769,'','आघ्रात, घ्रात, शिङ्घित','यस्य आघ्राणं क्रियते।; \"केचन जनाः आघ्रातानि पुष्पाणि भगवते न अर्पयन्ति।\"','adjective'),(32762,'','आघूर्णित, परिभ्रमित','यः भ्रमति।; \"सूर्यं परितः आघूर्णितानां ग्रहाणां गतिः भिन्ना वर्तते।\"','adjective'),(32758,'','घर्षित','यस्य घर्षणं कृतम्।; \"घर्षितं शरीरं शोभते।\"','adjective'),(32759,'','मार्जित, घर्षित','यद् बलेन स्वच्छीकृतम्।; \"मार्जितानि पात्राणि शोभन्ते।\"','adjective'),(32760,'','आघारः','यज्ञादिषु घृतधारादानम्।; \"यज्ञस्य अग्निः आघारेण अधिका एव प्रज्वलितः।\"','noun'),(32749,'','आग्नेय','यस्य देवता अग्निः अस्ति।; \"आग्नेये यज्ञे दत्ता आहुतिः अग्निदेवतायै प्राप्यते।\"','adjective'),(32757,'','आग्नेयभाषासमूहः','भाषाविज्ञानानुसारेण भारतस्य आग्नेयदिशि भाष्यमाणानां भाषाणां वर्गः।; \"आग्नेयभाषासमूहे इण्डोनेशिया इत्यत्र तथा तत्समीपस्थेषु द्वीपेषु भाष्यामाणाः भाषाः सन्ति।\"','noun'),(32748,'','आग्नेय','अग्निम् उद्दीपयितुं यः समर्थः।; \"अग्नितैलादयः आग्नेयाः पदार्थाः सन्ति।\"','adjective'),(32747,'','आग्नीध्रः','स्वायम्भुवमनोः पुत्रस्य प्रियव्रतस्य दशसु पुत्रेषु एकः।; \"भागवतपुराणानुसारम् आग्नीध्रः जम्बूद्वीपस्य राजा आसीत्।\"','noun'),(32746,'','आग्नीध्रम्','यज्ञीयस्य अग्नेः प्रज्वलनस्य क्रिया।; \"आग्नीध्रस्य कृते मन्त्रोच्चारणं भवति।\"','noun'),(32745,'','आग्नीध्रः','मनोः द्वादशसु पुत्रेषु एकः।; \"विष्णुपुराणे आग्नीध्रस्य निर्देशः वर्तते।\"','noun'),(32740,'','कर्णछेदः','अलङ्कारधारणाय कर्णे कृतः छेदः।; \"बृहद्भ्यां कर्णाभूषणाभ्यां मातामह्याः कर्णछेदः वर्धितः।\"','noun'),(32743,'','आगिवर्तः','मेघविशेषः।; \"आगिवर्तस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32744,'','आग्नीध्रः','यज्ञे अग्नेः प्रज्वालकः ऋत्विक्।; \"आग्नीध्रः मन्त्रम् उच्चारयन् यज्ञकुण्डे अग्निं प्रज्वालयति।\"','noun'),(32739,'','पुनर्निर्वाचनम्','पुनः निर्वाचनम्।; \"निर्वाचनप्रक्रियायां केषुचन निर्वाचनकेन्द्रेषु विप्लवेन पुनर्निर्वाचनम् आदिष्टम्।\"','noun'),(32734,'','वेदविद्या, आगमविद्या','वेदानां विद्या।; \"विषयस्य गूढत्वात् अधुनापि वेदविद्या गुरुमुखात् एव प्राप्स्यते।\"','noun'),(32725,'','भीमरथः','काशीराज्यस्य शासकः एकः चन्द्रवंशी राजा।; \"दिवोदासः भीमरथस्य पुत्रः आसीत्।\"','noun'),(32726,'','दिवोदासः','पुराणे वर्णितः एकः पुरुषः यः अप्सरसः मेनकायाः गर्भात् जातः।; \"दिवोदासः अहल्यायाः पुत्रः आसीत्।\"','noun'),(32707,'','आख्यानकी','दण्डकवृत्तभेदः यस्य विषमेषु चरणेषु तगणः तगणः जगणः तथा द्वौ गुरू भवतः समचरणेषु च जगणः तगणः जगणः तथा द्वौ गुरू भवतः।; \"आख्यानकी इन्द्रवज्रायाः उपेन्द्रवज्रायाः योगेन भवति।\"','noun'),(32731,'','आगमः','व्याकरणे प्रत्ययस्य अवयवरूपेण विहितः वर्णः वर्णसमुदायो वा यः अर्थवान् नास्ति।; \"भूयात् इत्यत्र या इति तिपः आगमः अस्ति।\"','noun'),(32730,'','शब्दप्रमाणम्, शब्दः, मौखिकप्रमाणम्, आप्तप्रमाणम्','यस्य प्रमाणं शब्दाः।; \"अधिवक्ता शब्दप्रमाणेन अपराधं प्रतिपद्यते।\"','noun'),(32727,'','मित्रावसुः','एकः गंधर्वः।; \"मित्रावसुः विश्वावसोः पुत्रः आसीत्।\"','noun'),(32728,'','मित्रेयुः','राज्ञः दिवोदासस्य एकः पुत्रः।; \"मित्रेयोः वर्णनं पुराणेषु वर्तते।\"','noun'),(32723,'','दिवोदासः','एकः चन्द्रवंशी राजा यः भीमरथस्य पुत्रः तथा च काशीराज्यं शशास।; \"दिवोदासः धन्वन्तरेः अवतारः आसीत् इति जनाः मन्यन्ते।\"','noun'),(32724,'','गाणितीय','गणितसम्बन्धी।; \"तस्य गणितीयं ज्ञानम् अल्पम् अस्ति।\"','adjective'),(32722,'','मित्रा','मैत्रेयर्षेः माता।; \"मित्रायाः वर्णनं पुराणेषु वर्तते।\"','noun'),(32721,'','मित्रा','एका अप्सराः।; \"मित्रायाः वर्णनं पुराणेषु वर्तते।\"','noun'),(32720,'','मित्रविन्दः','द्वादशस्य मनोः एकः पुत्रः।; \"मित्रविन्दस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32719,'','मित्रविन्दः','कृष्णस्य पुत्रः।; \"मित्रविन्दः मित्रविन्दायाः गर्भात् जातः।\"','noun'),(32718,'','आप्तकाम','यस्य सर्वाः इच्छाः सिद्धाः जाताः।; \"आप्तकामः मनुष्यः सर्वदा प्रसन्नः भवति।\"','adjective'),(32717,'','मित्रवाहः','द्वादशस्य मनोः एकः पुत्रः।; \"मित्रवाहस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32716,'','मित्रा','मित्रनाम्नः आदित्यस्य पत्नी।; \"मित्रायाः वर्णनं पुराणेषु वर्तते।\"','noun'),(32715,'','आगतपतिका','सा नायिका यस्याः पतिः प्रत्यागतः।; \"आगतपतिका अतीव मुदिता।\"','noun'),(32711,'','आगन्तुकम्, आगन्तुः','रोगविशेषः- बहिः कारणाद् जायमानः रोगः।; \"बालकः आगन्तुकेन पीडितः।\"','noun'),(32712,'','आगन्तुक','अज्ञातकुतशीलादिः नवागतः।; \"आश्रमे आगन्तुकाः जीवाः सम्यक् सेव्यन्ते।\"','adjective'),(32714,'','शीर्षकम्','पत्रलेखनसमये आरम्भे सम्बोधनार्थं लिख्यमानं पदम्।; \"शीर्षकेण ज्ञायते यद् पत्रं कम् उद्दिश्य लिखितम् अस्ति इति।\"','noun'),(32708,'','उपेन्द्रवज्रा','एकादशानां वर्णानां वर्णवृत्तविशेषः।; \"उपेन्द्रवज्रायां जगणः तगणः जगणः तथा द्वौ गुरू भवतः।\"','noun'),(32701,'','लेखापुस्तकम्','यस्मिन् पुस्तके धनराशेः विवरणं लिखितं भवति।; \"धनिकः लेखापुस्तके किमपि लिखति।\"','noun'),(32705,'','व्याख्याता','यः विवरणं करोति।; \"गोष्ठ्यां व्याख्याता विलम्बेन आगच्छत्।\"','noun'),(32706,'','वक्ता, आख्याता','यः वक्ति।; \"जनाः वक्तुः आख्यानेन मुग्धाः जाताः।\"','noun'),(32679,'','कुण्ठता, कौण्ठ्यम्, उपलेपः','कुण्ठीभवनम्।; \"प्रायः तिग्मेषु वस्तुषु कुण्ठता किट्टकात् एव भवति।\"','noun'),(32680,'','महाविक्रमः','एकः नागः।; \"महाविक्रमस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32496,'','अहिः','एकविंशतिभिः वर्णैः युक्तः छन्दोविशेषः।; \"अहौ आदौ षट् भगणाः भवन्ति तथा अन्ते मगणः भवति।\"','noun'),(32497,'','अहिकः','सर्पविशेषः यः अन्धः अस्ति इति मन्यन्ते।; \"अहिकः विषयुक्तः नास्ति।\"','noun'),(32498,'','अहिक्षेत्रम्','कम्पिलनदी तथा च चम्बलनदी इत्यनयोः नद्योः अन्तरे वर्तमानः पाञ्चालदेशः।; \"द्रौपद्याः स्वयंवरम् अहिक्षेत्रे अभवत्।\"','noun'),(32695,'','आक्षेपकः','वातरोगविशेषः।; \"आक्षेपके शरीरं कम्पते।\"','noun'),(32700,'','बन्धुः','वर्णवृत्तविशेषः।; \"बन्धोः प्रत्येकस्मिन् चरणे त्रयः भगणाः तथा द्वौ गुरू भवतः।\"','noun'),(32693,'','आक्षिक','द्यूतक्रीडासम्बद्धम्।; \"आक्षिकाणां क्रीडानाम् आसक्त्या तस्य जीवनं नष्टम्।\"','adjective'),(32694,'','आक्षिप्त, आयस्त','यः क्षिप्तः।; \"आक्षिप्तेन अस्त्रेण लक्ष्यं वेधितम्।\"','adjective'),(32690,'','आक्रमणीय','आक्रमितुम् अर्हः।; \"राष्ट्रस्य आक्रमणीया स्थितिः आन्तरिकया अस्थिरतया उद्भवति।\"','adjective'),(32688,'','आक्रमणम्, आघातः, अभ्याघातः, उपघातः','केनापि अस्त्रेण शस्त्रेण वा कृतः प्रहारः।; \"ग्रामीणाः आततायिनाम् आक्रमणं कियत्कालपर्यन्तं सहेरन्।\"','noun'),(32687,'','आक्रमणम्, अभ्याघातः, आघातः, उपघातः','प्रहर्तुं निपतनस्य क्रिया।; \"सिंहस्य आक्रमणेन आहतः पुरुषः रुग्णालयम् आनीयत।\"','noun'),(32686,'','महापद्मः','एकः किन्नरः।; \"महापद्मः कुबेरस्य सेवकः आसीत्।\"','noun'),(32681,'','आकूतिः','स्वायम्भुवमनोः तिसृषु पुत्रीषु एका पुत्री।; \"आकूत्याः पाणिग्रहणं रुचिनाम्ना ऋषिणा कृतम्।\"','noun'),(32682,'','रुचिः','एकः प्रजापतिः।; \"रुचिः रौच्यस्य मनोः पिता आसीत्।\"','noun'),(32683,'','आकृतिः','वर्णवृत्तविशेषः।; \"आकृतौ पञ्चतः द्वाविंशतिपर्यन्तं वर्णाः भवितुम् अर्हन्ति।\"','noun'),(32685,'','आक्रन्दः','भारतीयनीतिशास्त्रानुसारं तत् राज्यं यत् शत्रुराज्यस्य मित्रं तथा च तस्मिन् आक्रामति शत्रुराज्यस्य सहाय्यतां करोति।; \"राज्ञा आक्रन्दस्य चेष्टाः ज्ञातुं चाराः प्रेषिताः।\"','noun'),(32675,'','महावटः','पुराणेषु वर्णितः एकः वटवृक्षः।; \"प्रलयकाले मनुना स्वस्य नौका महावटे बद्धा।\"','noun'),(32678,'','आकुञ्चनीय','आकुञ्चने योग्यः।; \"जलौकायाः शरीरम् आकुञ्चनीयं भवति।\"','adjective'),(32665,'','खपुष्पम्','आकाशे जातं पुष्पम्।; \"खपुष्पं केन वा दृष्टम्।\"','noun'),(32666,'','खपुष्पम्','असम्भवं वस्तु।; \"भवतः योजना अद्य खपुष्पम् एव प्रतिभाति।\"','noun'),(32667,'','आकाशशयनम्','अनाच्छादितायां भूमौ शयनस्य क्रिया।; \"ग्रीष्मे ऋतौ आकाशशयनं सुखदायकं भवति।\"','noun'),(32668,'','आकाशभाषितम्','; \"','noun'),(32671,'','महावृक्षः','एकः वन्यः वृक्षः।; \"महावृक्षः अतीव शोभनीयः अस्ति।\"','noun'),(32674,'','महार्द्रकम्, वनजः, ऐन्द्रम्','वन्यम् अर्द्रकम्।; \"सः महार्द्रकं अर्द्रकरूपेण वेत्ति।\"','noun'),(32658,'','माणवः, माणवकः','षोडशानां मौक्तिकानां माला।; \"मीरा माणवं धारयति।\"','noun'),(32660,'','माणवक्रीडा','वर्णवृत्तविशेषः।; \"माणवक्रीडायाः प्रत्येकस्मिन् चरणे भगणः तगणः तथा द्वौ लघू भवतः।\"','noun'),(32661,'','मातङ्गः','एकः नागः।; \"मातङ्गस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32662,'','मातङ्गी','कश्यपर्षेः सुता।; \"मातङ्ग्याः वर्णनं पुराणेषु वर्तते।\"','noun'),(32654,'','मायिनी, मायाकारिणी, माया, अभिचारिणी','स्त्री अभिचारी।; \"मायिनी मायां दर्शयति।\"','noun'),(32655,'','मसीशोषफलम्, मसीचुषः, चूषपत्रम्','मसीशोषकं तृष्टपत्रम्।; \"मसीशोषफलेन पत्रस्था सर्वा मसी शोषिता।\"','noun'),(32657,'','माघः','एकः प्राचीनः कविः यस्य संस्कृतकाव्यं प्रसिद्धं वर्तते।; \"माघेन शिशुपालवधम् इति काव्यं रचितम्।\"','noun'),(32651,'','आरोग्यशास्त्रम्, आरोग्यविद्या, आरोग्यविज्ञानम्','तद् शास्त्रम् यस्मिन् रुग्विनिश्चयसम्बन्धि तथा च  अनामयजीवनसम्बन्धि विवेचनं क्रियते।; \"मिताली आरोग्यशास्त्रम् अध्यापयति।\"','noun'),(32652,'','नागरिकशास्त्रम्, पौरनीतिः','तत् सामाजिकशास्त्रं यस्मिन् प्रजायाः हितसम्बन्धविषयस्य विवेचनम् अस्ति।; \"सः नागरिकशास्त्रस्य विद्यार्थी अस्ति।\"','noun'),(32653,'','पाठ्यपुस्तकम्','विद्यालयेषु पठनार्थं विनिर्मितं पुस्तकं।; \"अस्मिन् संवत्सरे पाठ्यपुस्तकेषु परिवर्तनं कृतम्।\"','noun'),(32649,'','ग्रन्थबन्धकः','यः ग्रन्थादीन् बध्नाति।; \"मोहनः ग्रन्थबन्धकात् ग्रन्थम् आनेतुं गतः।\"','noun'),(32650,'','भाण्डवाहः, वैवधिकः','यः गृहे गृहे गत्वा वस्तूनि विक्रीणाति।; \"भाण्डवाहस्य ध्वनिं श्रुत्वा बालकाः गृहात् बहिः आगच्छन्ति। \"','noun'),(32648,'','भैषजिकः','यः भेषजानि विक्रीणाति।; \"भैषजिकस्य पार्श्वे एतद् औषधं नास्ति।\"','noun'),(32647,'','हृद्रोगः, हृदयव्याधि','हृदयसम्बन्धिनी व्याधिः।; \"रक्तचापः एकः हृद्रोगः अस्ति।\"','noun'),(32646,'','आन्त्रवृद्धिः','रोगविशेषः आन्त्रस्य रोगः।; \"सः आन्त्रवृद्ध्या पीडितः।\"','noun'),(32644,'','वायुसेनाध्यक्षः','वायुसेनायाः प्रधानः अधिकारी।; \"ए वाय टीपणीस महोदयः भूतपूर्वः वायुसेनाध्यक्षः आसीत्।\"','noun'),(32645,'','अण्डवृद्धिः','रोगविशेषः- सः रोगः यः पुरुषस्य अण्डकोशे उद्भवति।; \"अण्डवृद्ध्याम् अण्डकोशे द्रवस्य सञ्चयनं भवति।\"','noun'),(32640,'','पारम्','एकदेशात् अन्यदेशे।; \"एषः वित्तकोषः अस्य मार्गस्य पारम् अस्ति।\"','adverb'),(32641,'','यवक्षारः, स्वर्जिः, सर्जिः, सर्जिका, सर्जिकाक्षारः, सर्जिक्षारः, सर्जी','मृदः निर्यासमानः क्षारः।; \"अङ्गार-गन्धकादिभिः सह यवक्षारस्य मिश्रणं शीघ्रविदारकं भवति।\"','noun'),(32642,'','शीतज्वरः, ज्वरः, शीतगात्रः, शीतरूरः, शीताङ्गः','शैत्यस्य ज्वरस्य च पर्यायवृत्तिः।; \"शीतज्वरः विषाणुजः रोगः अस्ति।\"','noun'),(32643,'','संयोगभूमिः','सः लघुः स्थलभागः द्वौ बृहत्खण्डौ युङ्क्ते तथा च  यस्य अभितः जलम् अस्ति।; \"पनामा इति संयोगभूमिः उत्तरं तथा च दक्षिणम् अमेरीकादेशम् अनुबध्नाति।\"','noun'),(32638,'','तत्समयम् एव, तदा एव, तदा, तत्समये, तत्र एव, तत्रैव','तस्मिन् समये एव।; \"भवद्भ्यः तत्समयम् एव अत्र संशुद्धिः अपेक्षिता आसीत्।\"','adverb'),(32639,'','अतः, अतः एव, अनेन कारणेन, अस्मात् कारणात्','अस्मात् कारणात्।; \"सः भवत्या सह किम् अपि न अभाषत अतः एव भवती दुःखी अस्ति वा।\"','adverb'),(32636,'','श्वस्, प्र+अन्','श्वसनानुकूलव्यापारः।; \"सजीवाः श्वसन्ति।\"','verb'),(32637,'','यथा, यत्प्रकारेण, येन प्रकारेण','येन प्रकारेण।; \"भवान् यथा वक्ति तद् न सम्यक् अस्ति। \"','adverb'),(32635,'','स्मृ','कथनस्य पूर्वानुभूतस्य वा स्मरणानुकूलव्यापारः।; \"न स्मरामि अहं कुत्र दृष्टः भवान् पूर्वम्।\"','verb'),(32633,'','प्रयत्','कार्यसिद्ध्यनुकूलव्यापारः।; \"यशप्राप्त्यर्थं सः प्रायतत।\"','verb'),(32634,'','संवृ, पिध्','गमनागमनस्य अवरोधनानुकूलव्यापारः।; \"छात्रावासस्य प्रवेशद्वारम् अष्टवादने संवार्यते।\"','verb'),(32630,'','दण्ड्','अपराधिनं अपराधार्थे शारीरम् अथवा आर्थिकं दण्डं प्रदानानुकूलव्यापारः।; \"वधस्य अपराधात् न्यायाधीशः श्यामम् आजीवनं कारावासं भवतु इति अदण्डयत्।\"','verb'),(32631,'','द्विष्','कमपि दुर्जनं मत्वा तस्य अपवारणानुकूलव्यापारः।; \"न द्विष्यात् कमपि।\"','verb'),(32632,'','परीक्ष्','ज्ञानपरीक्षणार्थं पृच्छनानुकूलव्यापारः।; \"अध्यापकः छात्राणां गणितज्ञानं परीक्षते।\"','verb'),(32621,'','राजमाषः','क्षुपविशेषः- यस्य बीजगुप्तेः बीजानि धान्यरुपेण उपयुज्यन्ते।; \"कृषीवलः कृषीक्षेत्रे राजमाषान् रोपयति।\"','noun'),(32622,'','संतपनम्, सांतपनम्, प्रतापनम्, प्रतपनम्, तपनम्','तापनक्रिया यस्यां वेदनाशमनार्थे शरीरस्य कम् अपि भागम् ऊष्णजलादिना तपति।; \"संतपनेन खल्लिं शाम्यति।\"','noun'),(32628,'','गुण्, संगुणय','सङ्ख्यायाः सङ्ख्यया गुणनाकूलव्यापारः।; \"द्वे द्वाभ्यां गुणयतु।\"','verb'),(32627,'','आहृ, ऋणं कृ','ससमयं धनस्य अथवा कस्यापि वस्तुनः पुनर्देयत्वेन स्वीकृत्य ग्रहणात्मकः व्यापारः।; \"मया एकसप्ताहं तस्य पुस्तकम् आहृतम्।\"','verb'),(32625,'','आज्ञां पाल्','आज्ञायाः पालनानुकूलव्यापारः।; \"पित्रोः आज्ञां पालयतु।\"','verb'),(32624,'','अनुवाद कृ','एकभाषातः अन्यभाषायां छायानुकूलव्यापारः।; \"रामायणस्य नैकासु भाषासु अनुवादः क्रियते।\"','verb'),(32623,'','भर्जनम्','अग्निसंयोगेन पचनम्।; \"रोटिकायाः भर्जनं सम्यक् नास्ति।\"','noun'),(32620,'','कल्याणवीजः, कृष्णमसूरः, मसूरिका, मसरा, मसुरः','क्षुपविशेषः- यस्य बीजं द्विदलयुक्तं अस्ति तथा च यस्य आढकीं शाकरूपेण अत्ति।; \"कृषकः कल्याणबीजं अवलूनाति।\"','noun'),(32619,'','आकाङ्क्षा','न्यायशास्त्रानुसारेण वाक्यार्थज्ञानस्य हेतुषु एकः हेतुः।; \"आकाङ्क्षा योग्यता संनिद्धिः तथा च तात्पर्यम् इति वाक्यार्थस्य चत्वारि  हेतवः सन्ति।\"','noun'),(32615,'','परिवृत्तिः','अर्थालङ्कारभेदः।; \"परिवृत्तौ परिवर्तनस्य कथनं भवति।\"','noun'),(32611,'','अनुगणित','येषां गणना जाता।; \"अनुगणितानि वस्तूनि अन्यत्र स्थापय।\"','adjective'),(32612,'','पूरुः','एकः राक्षसः।; \"पूरोः वर्णनं पुराणेषु वर्तते।\"','noun'),(32613,'','कृष्णला, गुञ्जा, कृष्णलकः, गुञ्जिका','परिमाणविशेषः- त्रियवपरिमाणम्।; \"पुरा जनाः सुवर्णभारार्थे कृष्णला इति मानम् औपयुज्यन्त।\"','noun'),(32614,'','अन्वेषणीय','यस्य विषये अधिकं ज्ञातुं शक्यते।; \"एतादृशानां महत्वपूर्णानाम् अन्वेषणीयानां च प्रकरणानां विषये आरक्षकाः कथम् अज्ञाः भवितुम् अर्हन्ति।\"','adjective'),(32608,'','आकर्षणी','प्राचीनकालीना धातुमुद्रा।; \"सङ्ग्रहालयेषु अपि आकर्षणी दुर्लभा।\"','noun'),(32607,'','आकर्षणम्','तन्त्रशास्त्रीयः एकः प्रयोगः।; \"आकर्षणस्य प्रयोगेण दूरस्थः पुरुषः पदार्थः वा उपागच्छति।\"','noun'),(32606,'','आकर्षः','धनुरभ्यासवस्तु।; \"एकलव्यः आकर्षेण शब्दभेदी अभवत्।\"','noun'),(32586,'','पितृकुल्या','महाभारते वर्णिता नदी या मलयपर्वतात् प्रभवति।; \"पितृकुल्यायाः विशेषं महत्त्वं वर्तते।\"','noun'),(32587,'','पितृरिष्टम्','फलितज्योतिषानुसारेण यः योगः यस्मिन् अपत्यजन्मानन्तरं पिता म्रियते।; \"सोहनः पितृरिष्टे जातः।\"','noun'),(32592,'','कण्ठाभरणम्, कण्ठभूषणम्, गलमेखला, ग्रैवम्, ग्रैवेयम्, ग्रैवेयकम्, माला, मालिका, हारः, कण्ठसूत्रम्','कनकस्य वा रजतस्य कण्ठे धार्यमाणम् आभरणम्।; \"सा हीरकस्य कण्ठाभरणं धारयति।\"','noun'),(32600,'','आकम्पनम्','ईषत्कम्पनम्।; \"तस्य हृदयस्य आकम्पनम् अहं स्पष्टं श्रोतुं शक्नोमि।\"','noun'),(32603,'','आकरः','खड्गस्य द्वात्रिंशत्-प्रकारेषु एकः प्रकारः।; \"वीरगत्यां प्राप्तः सैनिकः आकरे पारंगतः आसीत्।\"','noun'),(32605,'','मूलभाषा','सा भाषा या अन्यासां भाषाणां जननी इति कथ्यते तथा च ताः भाषाः अस्याः जननीभाषायाः शब्दान् स्वीकृत्य स्वस्य शब्दसम्पद् संवर्धयन्ति।; \"हिन्दीबङ्गालीगुजरातीभाषाणां मूलभाषा संस्कृतभाषा अस्ति तथा उर्दूभाषायाः मूलभाषा अरबीभाषा फारसीभाषा च स्तः।\"','noun'),(32574,'','चर्मपट्टिका','सः पटः यत्र अक्षाः स्थाप्यन्ते।; \"द्यूतक्रीडायै तेन चर्मपट्टिका आस्तीर्यते।\"','noun'),(32575,'','पज्झटिका','षोडशमात्राणां छन्दोविशेषः।; \"पज्झटिकायां षष्ठी मात्रा तथा अष्टमी मात्रा गुर्वी भवति तस्मिन् जगणः निषिद्धः च भवति।\"','noun'),(32579,'','पिठरः','एकः दानवः।; \"पिठरस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32580,'','पिठरकः','एकः नागः।; \"पिठरकस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32581,'','पिठीनाः','एकः ऋषिः।; \"पिठीनसः वर्णनं पुराणेषु वर्तते।\"','noun'),(32583,'','पितरिशूरः','यः केवलं पितुरग्रे वीरवत् आचरति।; \"पितरिशूरः परजनानाम् अग्रे भीरुवत् आचरति।\"','noun'),(32584,'','पितामहः','एकः पौराणिकः ऋषिः।; \"पितामहेन केचन ग्रन्थाः लिखिताः।\"','noun'),(32585,'','शास्त्रकारः','यः शास्त्रं विशेषत्वेन धर्मशास्त्रं रचयति।; \"शास्त्रकाराणां सूच्यां ऋषयः मुनयः अपि सन्ति।\"','noun'),(32558,'','धाकजातिः','भीलजातिः इव वन्यः जातिविशेषः।; \"अस्मिन् वन्ये क्षेत्रे धाकजातिः दृश्यते।\"','noun'),(32560,'','द्यु-मणिः','वैद्यकपद्धत्या शोधितं ताम्रम्।; \"द्युमणिः नैकाणां रोगाणां उपचारेषु उपयुज्यन्ते।\"','noun'),(32567,'','प्रक्षालनमूल्यम्','प्रक्षालनस्य मूल्यम्।; \"अहं महेशाय शतरूप्यकाणि प्रक्षालनमूल्यं दत्तवती।\"','noun'),(32569,'','लेखनमूल्यम्','लेखनस्य मूल्यम्।; \"सः पत्रस्य लेखनमूल्यम् इच्छति।\"','noun'),(32541,'','तोडीतालः','तालविशेषः।; \"तोडीताले चतस्रः मात्राः सन्ति।\"','noun'),(32545,'','रतिसुन्दरः','रतिबन्धविशेषः।; \"रतिसुन्दरस्य वर्णनं कामशास्त्रे प्राप्यते।\"','noun'),(32550,'','मणिः','अश्मजातीयरत्नविशेषः यस्मिन् छेदं कर्तुं शक्यते।; \"सीमा मणीनां मालां धारयति।\"','noun'),(32553,'','नटनारायणः','एकः रागः यः वर्षर्तौ गीयते।; \"नटनारायणः दिनस्य तृतीये प्रहरे गीयते।\"','noun'),(32554,'','नटमल्हारः','एकः सङ्करः रागः यः नटस्य मल्हारस्य च मिश्रणेन जायते।; \"नटमल्हारे शुद्धस्वराः प्रयोक्तव्याः।\"','noun'),(32555,'','नटमलः','एकः रागः।; \"गायकः नटमलं गायति।\"','noun'),(32556,'','नटमल्हारी','रागिणीविशेषः।; \"सङ्गीतज्ञः नटमल्हारीं ज्ञापयति।\"','noun'),(32552,'','रथगुप्तिः, वरूथः, रथगोपनम्','काष्ठस्य वा अयसादीनाम् आवरणं यत् रथस्य शस्त्रादिभ्यः रक्षार्थं तत्परितः वर्तते।; \"रथगुप्तिः रथस्य सुरक्षार्थं वर्तते।\"','noun'),(32525,'','मोदकः','वर्णवृत्तविशेषः।; \"मोदकस्य प्रत्येकस्मिन् चरणे चत्वारः भगणाः भवन्ति।\"','noun'),(32529,'','चौबंसा','वर्णवृत्तविशेषः।; \"चौबंसायाः प्रत्येकस्मिन् चरणे नगणः यगणश्च भवतः।\"','noun'),(32523,'','मोनसः','एकः गोत्रप्रवर्तकः ऋषिः।; \"मोनसस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(32524,'','मोहठा','वर्णवृत्तविशेषः।; \"मोहठायाः प्रत्येकस्मिन् चरणे त्रयः रगणाः एकः गुरुश्च भवति।\"','noun'),(32519,'','प्रत्युत्तरम्','प्राप्तस्य उत्तरस्य टीकायाः वा प्रतिक्रियारूपेण दीयमानम् उत्तरम्।; \"मया सर्वासां टीप्पणीनां प्रत्युत्तरं लिखितम्।\"','noun'),(32521,'','कटुकीटः, दंशः, पुत्तिका, भम्भरालिका, मशः, मशकः, मलिम्लुचः, रणरणः, सूचीतुण्डः, सूचीमुखः, सूच्यास्यः, वज्रतुण्डः, सूक्ष्ममक्षिका, क्षुद्रः','झिरीविशेषः।; \"बालाः कटुकीटं ग्रहितुम् अयतन्त।\"','noun'),(32522,'','मोतियदामः','वर्णवृत्तविशेषः।; \"मोतियदामस्य प्रत्येकस्मिन् चरणे चत्वारः जगणाः भवन्ति।\"','noun'),(32491,'','अहल्या','क्रष्टुं; \"','noun'),(32493,'','हंसी','वर्णवृत्तविशेषः।; \"हंस्याः प्रत्येकस्मिन् चरणे द्वौ मगणौ एकः तगणः एकः सगणः तथा एकः गुरुश्च भवति।\"','noun'),(32494,'','अमेध्य','होतुम् अनर्हम्।; \"अमेध्यं द्रव्यं न जुहुयात्।\"','adjective'),(32482,'','अनपहार्य, अनपहरणीय, अहार्य','यत् अपहर्तुं न अर्हति।; \"ज्ञानम् अनपहार्यं वस्तु।\"','adjective'),(32486,'','प्रपा','पशूनां कृते जलपानार्थं निर्मितम् उदधानम्।; \"गोपालकः प्रपां परितः पशून् आनयत्।\"','noun'),(32487,'','अहर्गणः, द्युवृन्दम्, दिनौघः, द्युगणः, दिनपिण्डः','ग्रहाणां मध्यादिज्ञानार्थं श्वेतवाराहकल्पावधिसृष्ट्यवधिब्रह्मसिद्धान्तोक्तकल्पावधिकल्याब्धावधि वा इष्टकालपर्यन्तं परिगणितदिनसमूहः।; \"ज्योतिषाचार्यः अहर्गणस्य गणनां करोति।\"','noun'),(32514,'','सार्धत्रयः','त्र्यधिकम् अर्धः।; \"एतावताम् आम्राणां भारः सार्धत्रयः प्रस्थः अस्ति।\"','adjective'),(32518,'','ऋणभागः, ऋणांशः','ऋणस्य सः भागः यम् ऋणी प्रददाति।; \"मया अस्य मासस्य ऋणभागः दत्तः।\"','noun'),(32512,'','देवानीकः','सगरवंशीयः एकः राजा।; \"देवानीकस्य पुत्रः अहीनगुः आसीत्।\"','noun'),(32511,'','अहीनगुः','एकः सूर्यवंशी राजा।; \"अहीनगुः देवानीकस्य पुत्रः आसीत्।\"','noun'),(32509,'','रुद्रः','प्राचीनं वाद्यम्।; \"अधुना रुद्रः लुप्तप्रायः एव।\"','noun'),(32508,'','रुद्रः','विश्वकर्मणः पुत्रः।; \"रुद्रस्य वर्णनं प्राचीनग्रन्थेषु वर्तते।\"','noun'),(32507,'','रुद्राः, अहिर्बुध्न्याः, उग्रः, खरः, जयन्तः, वक्रः','देवतागणः।; \"रुद्राः एकादश सन्ति।\"','noun'),(32506,'','अहिर्बुध्न्यः','एकादशसु रुद्रेषु एकः।; \"अहिर्बुध्न्यस्य वर्णनं शिवपुराणे वर्तते।\"','noun'),(32505,'','सर्पसत्त्रम्','सर्पान् संहर्तुं कृतः यागः।; \"राजा जन्मेजयः सर्पसत्त्रम् अनुतस्थौ।\"','noun'),(32504,'','अहिफेनम्','सर्पस्य फेनम्।; \"व्यालिकः अहिफेनं संगृह्य विक्रीणाति।\"','noun'),(32501,'','काम्पिल्यम्','फर्रूखाबादनगरस्थं पुरातनं नगरम्।; \"काम्पिल्यम् इति नगरं दक्षिणपञ्चालस्य राजधानिका आसीत् तथा च द्रौपद्याः स्वयंवरम् अत्रैव सम्पन्नम्।\"','noun'),(32500,'','अहिक्षेत्रनगरम्','दक्षिणपाञ्चालस्य राजधानी।; \"अहिक्षेत्रनगरे पाञ्चालीभाषाम् इत्युक्ते कन्नौजीभाषां वदन्ति।\"','noun'),(32481,'','गर्भाधानम्','स्त्रियः गर्भे पुरुषस्य वीर्येण जीवस्य उत्पत्तिः।; \"ग्रन्थादिषु अभिष्टस्य सन्तानस्य प्राप्त्यर्थं गर्भाधानस्य निश्चितः समयः स्थितिः च उक्ता अस्ति।\"','noun'),(32478,'','अहिंसा','योगशास्त्रे वर्णितेषु पञ्चयमेषु प्रथमः।; \"मनसा वचनेन कर्मणा वा कस्यापि प्राणिनः अपीडनं नाम अहिंसा।\"','noun'),(32479,'','टगणः','छन्दःशास्त्रानुसारेण पञ्चसु गणेषु एकः।; \"टगणः षण्णां मात्राणाम् अस्ति यस्य त्रयोदश उपभेदाश्च सन्ति।\"','noun'),(32476,'','उदारतावाद','सा राजनैतिका विचारधारा यस्यां प्रगतिं प्राथम्यं दीयते।; \"महेशः उदारतावादेन प्रभावितः जातः।\"','noun'),(32477,'','उदारतावादी','उदारमतवादस्य अनुयायी।; \"अद्य अस्माकं प्रान्ते उदारतावादिनां चर्चासत्रम् अस्ति।\"','noun'),(32468,'','अहंवाद','स्वविषये कृता अतिशयोक्तिः।; \"अहंवादात् त्रायस्व।\"','noun'),(32473,'','निर्वासित, निष्कासित','; \"','adjective'),(32462,'','खम्भातम्','गुजराथप्रदेशे वर्तमानं खातम्।; \"माही इति नदी खम्भाते वहति।\"','noun'),(32463,'','माहेन्द्रवाणी','एका पौराणिका नदी।; \"माहेन्द्रवाण्याः वर्णनं महाभारते अस्ति।\"','noun'),(32464,'','अस्रपा','या यातुं करोति।; \"ग्रामस्थाः अस्रपाम् अताडयन्।\"','noun'),(32466,'','मित्रवान्','कृष्णस्य पुत्रः।; \"मित्रवतः वर्णनं पुराणेषु वर्तते।\"','noun'),(32454,'','भीष्मकमणिः','पीतवर्णीयः मणिः।; \"भीष्मकमणिः द्विप्रकारकः मोहिनीभीष्मकः तथा च कामदेवभीष्मकः अस्ति। \"','noun'),(32455,'','मोहिनी-भीष्मक-मणिः, अमृत-मणिः','भीष्मकमणेः प्रकारयोः एकः प्रकारः।; \"मोहिनी-भीष्मक-मणिः रत्नसदृशः अस्ति।\"','noun'),(32456,'','कामदेव-भीष्मक-मणिः','भीष्मक-मणेः प्रकारयोः एकः प्रकारः।; \"कामदेव-भीष्मक-मणिः स्वच्छः शोभनीयः च अस्ति।\"','noun'),(32457,'','उपलः','विभिन्ने वर्णे दृश्यमानः मणिविशेषः यस्मिन् श्वेतनीलपीतादीनां वर्णानां बिन्दवः भवन्ति।; \"जले दुग्धे वा निमज्जनेन उपलस्य दीप्तिः वर्धते।\"','noun'),(32467,'','मित्रवान्','द्वादशतमस्य मनोः पुत्रः।; \"मित्रवान् इत्यस्य वर्णनं पुराणे दृश्यते।\"','noun'),(32458,'','मस्तु','दध्नः जलम्।; \"दध्नः वस्त्रे बद्ध्वा स्थापयतु येन मस्तु स्रविष्यति।\"','noun'),(32459,'','माहित्थः','एकः पौराणिकः ऋषिः।; \"माहित्थस्य वर्णनं शतपथब्राह्मणेषु वर्तते।\"','noun'),(32460,'','माहिष','महिषेन सम्बद्धं महिषस्य वा।; \"सः माहिषात् दुग्धात् विनिर्मितान् पदार्थान् विक्रीणाति।\"','adjective'),(32461,'','खम्भातः','गुजराथप्रदेशस्य प्रतीच्यां वर्तमानः खम्भाताखातस्य तटे वर्तमानः प्रदेशः।; \"महेश-पटेल-महोदयः खम्भातस्य निवासी अस्ति।\"','noun'),(32443,'','माल्यवान्','एकः गन्धर्वः यः इन्द्रस्य शापेन पिशाचः बभूव।; \"जयैकादश्याः व्रतस्य अज्ञात्वा एव सम्पादनेन माल्यवान् उद्दधार।\"','noun'),(32444,'','अस्थिसञ्चयम्','अन्त्येष्ट्याः पश्चाद् अस्थिनां संचयनम्।; \"पितामहस्य अस्थिसञ्चयनार्थे जनाः आगताः।\"','noun'),(32445,'','अस्थिसन्धिः','अस्थ्नां सन्धिस्थानम्।; \"अस्यां वृद्धावस्थायाम् अस्थिसन्धिषु अतीव पीडा वर्तते।\"','noun'),(32447,'','माल्यवती','एका नदी यस्याः वर्णनं रामायणे वर्तते।; \"माल्यवती चित्रकूटस्य समीपं वहति।\"','noun'),(32449,'','अस्मिता','योगशास्त्रानुसारेण पञ्चक्लेशेषु एकः।; \"आत्माचित्तयोः भिन्नतायां तयोः एकत्वस्य ज्ञानम् एव अस्मिता अस्ति।\"','noun'),(32426,'','अस्त्रकारः','यः अस्राणि निर्माति।; \"सेनापतिना अस्रकारात् विविधानि अस्राणि क्रीतानि।\"','noun'),(32429,'','मार्जालीयः','एकः ऋषिः।; \"मार्जालीयस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(32430,'','अहल्य','हलेन अनाकृष्टम्।; \"अहल्येषु क्षेत्रेषु तृणानि वर्धन्ते।\"','adjective'),(32431,'','अस्त्रविद्','अस्त्रविद्यायां निपुणः।; \"अस्त्रविदः सेनायाम् नियुक्ताः।\"','noun'),(32432,'','साल्वाराजः','पुराणेषु वर्णितः मार्तिकावर्तस्य राजा।; \"काशीनरेशस्य पुत्री अम्बा साल्वाराजं स्वपतिं मन्यते स्म।\"','noun'),(32433,'','मार्तिकावतः','एकं प्राचीनं राज्यम्।; \"एकदा देवव्रतेन मार्तिकावतस्य राज्ञः साल्वाराजस्य पराभवः कृतः।\"','noun'),(32434,'','अस्त्रवेदः, अस्त्रविद्या','शस्त्राणाम् अस्त्राणां च प्रहरणस्य नियमाः यत्र विधीयन्ते तत् शास्त्रम्।; \"कर्णं परशुरामः अस्त्रविद्याम् अशिक्षयत्।\"','noun'),(32441,'','मालिनी','पुराणेषु वर्णिता नदी।; \"मालिन्याः तटे एव शकुन्तला अजायत।\"','noun'),(32442,'','मालिनी','रुचिदेवसावर्णि इत्याख्यस्य मनोः माता।; \"मालिन्याः वर्णनं पुराणेषु वर्तते।\"','noun'),(32439,'','मालहायनः','एकः ऋषिः।; \"मालहायनस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32440,'','अस्थिमाला','अस्थ्नां माला।; \"तान्त्रिकः कण्ठे अस्थिमालां धारयति।\"','noun'),(32438,'','अस्थिकुंड नरकम्','नरकविशेषः।; \"ये प्रयागे पितृन् न तर्पयन्ति ते अस्थिकुंडनरके पतन्ति।\"','noun'),(32437,'','अस्त्राहत','अस्त्रेण आहतः।; \"अस्त्राहतानां सैनिकानां चिकित्सायै शिबिरं प्रस्थापितम्।\"','adjective'),(32436,'','अस्त्रशिक्षा','अस्त्राणां प्रशिक्षणम्।; \"आचार्यः द्रोणः कौरवान् च पाण्डवान् च अस्त्रशिक्षां पाठयाञ्चकार।\"','noun'),(32435,'','अस्त्रागारम्','तत् स्थानं यत्र अस्त्राणि स्थापयन्ति।; \"अस्त्रागारे इदानीं युद्धाय अस्त्राणि न सन्ति।\"','noun'),(32425,'','अस्त्रम्','चिकित्सकस्य अस्त्रविशेषः येन सः शल्यक्रियां कर्तुं प्रभवति।; \"परिचारिका एकम् एकम् अस्त्रं शल्चिकित्सकस्य हस्ते स्थापयति।\"','noun'),(32424,'','अस्त्रम्','तत् वस्तु येन शत्रोः प्रहारः वारयितुं शक्यते।; \"ढालम् इति एकम् अस्त्रम्।\"','noun'),(32423,'','अस्रम्','क्षिप्यमाणं शस्त्रम्।; \"धनुः दूरवेधिन्यादीनि अस्राणि सन्ति।\"','noun'),(32422,'','जयानकी','विराटनृपस्य भ्राता।; \"जयानकी इत्यस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32419,'','अस्तेयम्','योगस्य अष्टसु अङ्गेषु नियमनामकस्य अङ्गस्य भागः यत्र अन्यस्य वस्तुनः बलात् अपहारः सर्वथा वर्ज्यः।; \"तैः अस्तेयम् आ मृत्योः आचरितम्।\"','noun'),(32421,'','जयानकी','राज्ञः द्रुपदस्य पुत्रः।; \"जयानकी इत्यस्य वर्णनं पुराणेषु वर्तते।\"','noun'),(32417,'','अस्तिः','जरासन्धस्य कन्या।; \"अस्ति इत्यस्याः वर्णनं पुराणेषु वर्तते।\"','noun'),(32418,'','अस्तेयम्','अन्यस्य वस्तुनः अनपहरणस्य क्रिया।; \"चोरस्य अस्तेयस्य आचरणस्य इच्छा न परिपूर्णा जाता।\"','noun'),(32366,'','सुनाभः','वरुणस्य मन्त्री।; \"सुनाभः पुराणेषु वर्णितः।\"','noun'),(32367,'','सुनाभः','गरुडस्य पुत्रः।; \"सुनाभः पुराणेषु वर्णितः\"','noun'),(32368,'','सुनाभ','यस्य नाभिः सुन्दरा अस्ति।; \"तस्य पुत्रः सुनाभः अस्ति।\"','adjective'),(32369,'','सुनायकः','अरुणस्य पुत्रः।; \"सुनायकः पुराणेषु वर्णितः।\"','noun'),(32370,'','सुनामा','सुकेतोः पुत्रः।; \"सुनामा पुराणेषु वर्णितः वर्तते।\"','noun'),(32371,'','सुनामन्','कार्तिकेयस्य अनुचरः।; \"सुनामा पुराणेषु वर्णितः वर्तते।\"','noun'),(32372,'','असुरसेनः','एकः राक्षसः।; \"पुराणेस्थकथानुसारेण प्रयागनगरं असुरसेनस्य शरीरस्य उपरि स्थापितं वर्तते।\"','noun'),(32373,'','असुरः','वैद्यकशास्त्रानुसारेण रोगविशेषः।; \"असुरस्य रुग्णः घर्मरहितः भवति जल्पति च।\"','noun'),(32374,'','असुरकुमारः','जैनशास्त्रानुसारेण त्रिभुवनपतिः।; \"असुरकुमारस्य वर्णनं जैनशास्त्रेषु दृश्यते।\"','noun'),(32376,'','असुरमाया','राक्षसाणाम् इन्द्रजालम्।; \"सः स्वप्ने असुरमायाम् अपश्यत्।\"','noun'),(32377,'','मर्त्य, मरिष्णु, मर्त','यः म्रियते।; \"यः जातः सः मर्त्यः अस्ति।\"','adjective'),(32378,'','पूगपुष्पिका','विवाहनिमित्ते दीयमानं पुष्पताम्बूलम्।; \"पूगपुष्पिकायाः दानेन विवाहः निश्चयेन भविष्यति इति मन्यते।\"','noun'),(32379,'','रक्तपुष्पा, परारक्ता, शिलाटिका','रक्तवर्णीया पुनर्नवा।; \"रक्तपुष्पा भेषजरूपेण उपयुज्यते।\"','noun'),(32380,'','पुष्पिका, पिप्पिका, दन्तशर्करा, रौचनिकम्, कपालकः','दन्तमलम्।; \"दन्तक्षालनेन पुष्पिका न भवति।\"','noun'),(32381,'','पुष्पिका','लिङ्गमलम्।; \"शिश्नस्य स्वच्छतया पुष्पिका न भवति।\"','noun'),(32382,'','पुष्पिका','कस्यापि अध्यायस्य अन्ते स्थितः सः भागः येन पूर्वं वर्णितस्य प्रसङ्गस्य समाप्तिः सूच्यते।; \"अस्य ग्रन्थस्य पुष्पिकया न अधिकं किमपि स्पष्टं भवति।\"','noun'),(32385,'','असूया','परेषु गुणेषु दोषाविष्करणस्य स्वभावः।; \"असूया मनुष्ये स्थितः दुर्गुणः अस्ति।\"','noun'),(32390,'','मयूरसारिणी','वर्णवृत्तविशेषः।; \"मयूरसारिण्यां त्रयोदश वर्णाः सन्ति।\"','noun'),(32391,'','वस्तिकुण्डलिका, वस्तिकुण्डलम्','मूत्राशयस्य रोगः।; \"वस्तिकुण्डलिकायां मूत्राशये ग्रन्थिः भवति।\"','noun'),(32392,'','मरुः','एकः दैत्यः।; \"मरुः नरकासुरस्य सखा आसीत्।\"','noun'),(32393,'','अवीक्षितः','एकः चंद्रवंशीयः राजा।; \"अवीक्षितः धर्मपरायणः शासकः आसीत्।\"','noun'),(32394,'','मरुत्तः','एकः चंद्रवंशीयः राजा।; \"मरुत्तः राजा अवीक्षितस्य पुत्रः आसीत्।\"','noun'),(32395,'','रक्तप्रवाहः, असृग्धारा','रक्तस्य प्रवाहः।; \"हृदयस्य रक्तप्रवाहे अवरुद्धे मृत्युः ध्रुवः।\"','noun'),(32396,'','असेव्य','यद् सेवार्थम् अयोग्यम्।; \"कुष्ठरोगस्य रुग्णः असेव्यः मन्यते स्म।\"','adjective'),(32401,'','केतुः, शिखी','नवग्रहान्तर्गतग्रहविशेषः।; \"केतुः पापग्रहः अस्ति जनाः मन्यन्ते।\"','noun'),(32403,'','कोहलः','एकः गंधर्वः।; \"कोहलः नाट्यशास्त्रे निपुणः आसीत्।\"','noun'),(32404,'','स्खलित','स्वस्य स्थानात् पतितः।; \"पर्वतात् स्खलितेन भूखण्डेन पर्वतीय मार्गः अवरुद्धः।\"','adjective'),(32410,'','परीक्षित','यस्य परीक्षणं कृतम्।; \"परीक्षिताः उत्तरपत्रिकाः अन्यत्र स्थापयतु।\"','adjective'),(32412,'','आधारद्रव्यम्','तद् द्रव्यं यस्य उपयोगः अन्यत् द्रव्यं निर्मातुं क्रियते।; \"चन्दनस्य तैलं नैकानां सुगन्धानाम् आधारद्रव्यम् अस्ति।\"','noun'),(32365,'','सुनहः','जह्नोः ऋषेः पुत्रः।; \"सुनहः पुराणेषु वर्णितः।\"','noun'),(32358,'','भर्तृहरिरागः','सङ्कररागविशेषः।; \"पुरजरागः तथा ललितरागस्य योगेन भर्तृहरिरागः जातः।\"','noun'),(32359,'','पुरजरागः','रागविशेषः।; \"पुरजरागः तथा ललितरागस्य योगेन भर्तृहरिरागः जातः।\"','noun'),(32361,'','चन्द्रसेनः','उज्जयिन्याः राजा।; \"चन्द्रसेनः भर्तृहरेः तथा च विक्रमादित्यस्य पिता आसीत्।\"','noun'),(32364,'','परिप्लवः','एकः कुरुवंशीयः राजा।; \"सुनयः परिप्लवस्य पुत्रः आसीत्।\"','noun'),(32363,'','सुनयः','परिप्लवस्य राज्ञः एकः पुत्रः।; \"सुनयः पुराणेषु वर्णितः।\"','noun'),(32357,'','भर्तृहरिः, हरिः','संस्कृतस्य सुप्रसिद्धः कविः।; \"भर्तृहरिः उज्जयिन्याः राजा आसीत् तथा च द्वितीयस्य विक्रमादित्यस्य अग्रजः आसीत्।\"','noun'),(32354,'','कर्मयोगी','यः कर्मयोगं करोति।; \"कर्मयोगी निष्कामभावेन कर्म करोति कर्मफलं न पश्यति।\"','noun'),(32355,'','सुनामन्','कंसस्य एकः अनुजः।; \"सुनामा इति कंसस्य अष्टसु भ्रातृषु एकः भ्राता।\"','noun'),(32356,'','आशीषं दा, आशास्','आशीर्वचनानुकूलव्यापारः।; \"भिक्षुकः मनोवाञ्छितां भिक्षां प्राप्य गृहिणीम् आशीषं ददाति।\"','verb'),(32353,'','कर्मयोगः','सः योगः यस्मिन् कर्मफले आसक्तिः नास्ति ईश्वरार्थे कर्म क्रियते।; \"गृहस्थस्य कृते कर्मयोगः अतीव उपयुक्तः।\"','noun'),(32352,'','असिपत्रवनम्','सः नरकः यस्मिन् निजपथादनापद्यपगतः पाखण्डञ्चोपगतः प्रवेश्य कषया प्रहरन्ति तत्रासावितस्ततो धावमानः उभयतोधारै स्तालवनासिपत्रैः छिद्यमानसर्वाङ्गो हा हतोस्मीति परमया वेदनया मूर्च्छितः पदे पदे निपतति स्वधर्महा पाखण्डानुगमनफलं भुङ्क्ते।; \"असिपत्रवनस्य विस्तारं द्विसहस्रयोजनानि अस्ति।\"','noun'),(32350,'','सुनेत्रः','धृतराष्ट्रस्य पुत्रः।; \"सुनेत्रस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(32351,'','सुनेत्रः','त्रयोदशतमस्य मनोः पुत्रः।; \"सुनेत्रस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(32331,'','निःसारता, असारता, तत्वशून्यता','निःसारस्य अवस्था भावो वा।; \"जीवनस्य निःसारता दृष्ट्वा तेन आत्महत्या कृता।\"','noun'),(32332,'','तैललेपनम्','तैलस्य लेपनस्य क्रिया।; \"रमेशः आतपे उपविश्य तैललेपनं करोति।\"','noun'),(32334,'','तोटकः','वर्णवृत्तविशेषः।; \"तोटकस्य प्रत्येकस्मिन् चरणे चत्वारः सगणाः भवन्ति।\"','noun'),(32338,'','तुर्वसुः','ययातिपुत्रः।; \"देवयान्याः गर्भात् तुर्वसुः जातः।\"','noun'),(32341,'','पिङ्गला','पुराणेषु वर्णिता एका वेश्या।; \"क्वचिद् एव पिङ्गलायाः उल्लेखः प्राप्यते।\"','noun'),(32342,'','पिङ्गला','दक्षिणदिग्गजस्य पत्नी।; \"प्राचीनकथायां पिङ्गलायाः उल्लेखः अस्ति।\"','noun'),(32343,'','पिङ्गला','खगविशेषः।; \"आम्रस्य शाखायां पिङ्गला अस्ति।\"','noun'),(32344,'','पिङ्गला','राज्ञः भर्तृहरेः पत्नी।; \"पिङ्गलायाः उल्लेखः प्राचीनासु कथासु प्राप्यते।\"','noun'),(32345,'','असिताङ्गः','एकः ऋषिः।; \"असिताङ्गस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(32346,'','असिधावकः','असिधारकर्ता।; \"असिधावकः असिं संमार्जति।\"','noun'),(32347,'','विदुः','गजस्य कुम्भद्वयस्य मध्यभागः।; \"हस्तिपकेन विदोः अधोभागे ओम् इति अक्षरं निर्मितम्।\"','noun'),(32348,'','विदुः','अश्वस्य कर्णयोः मध्यभागः।; \"अश्वपालः अवभग्ने विदौ लेपं लेपयति।\"','noun'),(32349,'','असिपत्रम्','खड्गकोषः।; \"संग्रहालये स्थापिते असिपत्रे शोभनीयं क्षदनम् अस्ति।\"','noun'),(32329,'','महोदर, लम्बजठर, प्रोदर, पिचण्डिन्','बृहद् उदरयुक्तः।; \"महोदरः पुरुषः उदरे हस्तं स्थापयति।\"','adjective'),(32330,'','शाखा','मुख्यप्रवाहे युज्यमानः अन्यः प्रवाहः।; \"प्रत्येकस्य दीर्घायाः नद्याः नैकाः शाखाः भवन्ति।\"','noun'),(32328,'','तोकः','कृष्णस्य मित्रम्।; \"तोकस्य वर्णनं हिन्दू-धर्म-ग्रन्थेषु प्राप्यते।\"','noun'),(32322,'','तोमरः','द्वादशमात्राणां छन्दोविशेषः।; \"तोमरस्य अन्ते गुरुः लघुश्च भवति।\"','noun'),(32323,'','तैलपात्रम्','तैलस्थापनार्थे पात्रम्।; \"तैलपात्रं तैलेन पूरितम्।\"','noun'),(32324,'','तिलतैलम्, तैलम्','तिलस्य तैलम्।; \"सः तिलतैलेन एव अङ्गमर्दनं करोति।\"','noun'),(32325,'','चन्दनादितैलम्','(वैद्यकम्)रक्तचन्दनस्य योगेन निर्मितं तैलम्।; \"चन्दनादितैलम् अतीव लाभदायकम् अस्ति।\"','noun'),(32318,'','असात्म्य, अनारोग्यकर','निसर्गस्य विरुद्धं यत्।; \"असात्म्यः आहारः व्याधिम् उत्पादयति।\"','adjective'),(32310,'','स्थविरः','बौद्धभिक्षूणां एकः सम्प्रदायः।; \"सः स्थविरस्य अनुयायी अस्ति।\"','noun'),(32315,'','गुरुपूर्णिमा, व्यासपूर्णिमा','आषाढमासस्य पौर्णिमा।; \"गुरुपूर्णिमायां आध्यात्मिकः गुरुः पूज्यते।\"','noun'),(32304,'','संवेदनशीलता','संवेदनशीलस्य अवस्था भावो वा।; \"शासनेन प्रजायाः समस्यानां निराकरणं संवेदनशीलतया करणीयम्।\"','noun'),(32305,'','असहकाराभियानम्','गान्धीमहोदयेन आचरितम् अभियानम्।; \"प्रजायाः असन्तोषप्रकटीकरणम् असहकाराभियानस्य मुख्यं प्रयोजनम् आसीत्।\"','noun'),(32306,'','वनिता, तिलका, डिल्ला','षड्भिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"वनितायां द्वौ सगणौ भवतः।\"','noun'),(32307,'','गाधता, गाधत्वम्, उत्तानता, उत्तानत्वम्, तनिमा','गाधस्य अवस्था भावः वा।; \"अस्मिन् तडागे अधिका गभीरता नास्ति अपि तु गाधता अस्ति।\"','noun'),(32309,'','स्थविरः, शैलेयम्','सुगन्धिता वनस्पतिः।; \"सः स्थविरम् उन्मूलयति।\"','noun'),(32296,'','स्थविर','वृद्धः तथा च पूज्यः।; \"एतद् रमेशस्य स्थविरस्य पितामहस्य चित्रम् अस्ति।\"','adjective'),(32297,'','सरित्-प्रवाहः','नद्याः प्रवाहः।; \"सरित्प्रवाहे नौका प्रवहति।\"','noun'),(32298,'','सम्प्लवनम्','वर्तमानात् स्थानात् झटिति उपरि गमनस्य क्रिया।; \"सम्प्लवनेन वानरः वृक्षे गतः।\"','noun'),(32280,'','असमाप्तिः','समाप्तेः अभावः।; \"धनस्य असमाप्तेः अनन्तरम् अपि लोभः तु अस्ति एव।\"','noun'),(32281,'','वैदर्भी','इक्ष्वाकुवंश्यस्य राज्ञः सगरस्य पत्नी।; \"वैदर्भ्याः षष्टिसहस्राः पुत्राः आसन्।\"','noun'),(32282,'','शैव्या','सगरस्य पत्नी।; \"असमंजः शैव्यायाः गर्भात् जातः।\"','noun'),(32283,'','असमः','अर्थालङ्कारविशेषः।; \"असमे उपमानम् असम्भवम् अस्ति।\"','noun'),(32291,'','मलिनीभू','अमलिनः मलिनः भवति इति तदनुकूलः व्यापारः।; \"एतत् वस्त्रं मलिन्यभवत्।\"','verb'),(32276,'','देवकः','एकः पौराणिकः राजा यः कृष्णस्य मातामहः आसीत्।; \"देवकस्य वर्णनं पुराणे दृश्यते।\"','noun'),(32277,'','देवरक्षित','राजादेवकस्य पुत्रः।; \"देवरक्षितस्य वर्णनं पुराणे दृश्यते।\"','noun'),(32275,'','असहायता, निस्सहायता, निःसहायता, निराश्रितता, निराश्रयता, अनाश्रितता, अनाश्रयता, असहायत्वम्','असहायस्य अवस्था भावो वा।; \"दीनबालकानां असहायतां नैके जनाः स्वार्थपरिपूर्त्यर्थम् उपयुञ्जन्ति।\"','noun'),(32278,'','देवरक्षिता','राज्ञः देवकस्य कन्या।; \"देवरक्षितायाः वर्णनं पुराणेषु दृश्यते।\"','noun'),(32273,'','कलहिनी','शनेः पत्नी।; \"कलहिन्याः वर्णनं पुराणे प्राप्यते।\"','noun'),(32272,'','असत्यवादः, मिथ्यावादः','असत्यभाषणस्य क्रिया।; \"केचन जनाः असत्यवादेन तावत् अभ्यस्ताः भवन्ति येन कदापि तेषां मुखात् सत्यभाषणं न भवति।\"','noun'),(32274,'','असद्भावः, असत्, असत्ता','सत्तायाः अभावः।; \"वेदानुसारेण दृश्यस्य जगतः असद्भावस्य स्वीकारः कठिनः अस्ति।\"','noun'),(32271,'','असत्संसर्गः, खलसंसर्गः, कुसङ्गः','दुष्टानां सङ्गतिः।; \"असत्संसर्गः मनुष्यस्य अधःपतनस्य कारणम् अस्ति।\"','noun'),(32263,'','संसृष्टः','पर्वतविशेषः।; \"संसृष्टस्य उल्लेखः पुराणे प्राप्यते।\"','noun'),(32264,'','अस्तुत','यः न शंसितः।; \"अस्तुतस्य देवस्य अप्रसन्नतायाः शापः तैः प्राप्तः।\"','adjective'),(32258,'','एकीकरणम्','द्वयोः अधिकानां वा वस्तूनां संयोजनस्य क्रिया।; \"रासायनिक-तत्वानाम् एकीकरणेन यौगिकपदार्थाः जायन्ते।\"','noun'),(32259,'','मेलनम्, समायोगः, योगः','समानानां पदार्थानाम् संयोजनस्य क्रिया।; \"मेलनस्य अनन्तरम् एतेषां परीक्षणं करोतु।\"','noun'),(32260,'','निर्लिप्तता, अलिप्तता, असंसक्तिः','निर्लिप्तस्य अवस्था भावो वा।; \"निर्लिप्तता इति एका महती साधना।\"','noun'),(32262,'','सुपक्व, सुसिद्ध, विपक्व, सुश्रात','यद् सम्यक् पक्वम् अस्ति (भोजनम्)।; \"सुपक्वं भोजनं सुपाच्यं भवति।\"','adjective'),(32257,'','संश्लिष्टः','मण्डपप्रकारः।; \"श्वस्तनीयस्य कार्यक्रमस्य कृते संश्लिष्टः सिद्धः।\"','noun'),(32251,'','संवृत्तः','नागविशेषः।; \"संवृत्तस्य वर्णनं पौराणिकासु कथासु दृश्यते।\"','noun'),(32252,'','वेष्टित, उपवेष्टित, अनुसंवीत','यस्य वेष्टनं जातम्।; \"प्रच्छदपटेन वेष्टितः शिशुः मात्रा शिशुदोलायां स्थापितः।\"','adjective'),(32254,'','संवृतम्','गुप्तस्थानम्।; \"शत्रुभ्यः रक्षितुं राजा संवृतम् अगच्छत्।\"','noun'),(32244,'','अतिकश, अत्यङ्कुश, दुर्ललित','व्यवस्थापयितुम् अयोग्यः।; \"अतिकशायाः सम्पत्तेः सः स्वामी।\"','adjective'),(32238,'','वितुष्ट, विसंवादित','यः आनन्दं न प्राप्नोति।; \"वितुष्टः पुरुषः सर्वदा दुःखी भवति।\"','adjective'),(32239,'','असंप्रज्ञातसमाधि','योगस्य एकः समाधिः।; \"स्वामी असंप्रज्ञातसमाधौ लीनः।\"','noun'),(32240,'','असहयोगः, असहकारः','सहकारस्य अभावः।; \"मम कार्ये कुटुम्बस्य असहयोगः सर्वदा बाधकः भवति।\"','noun'),(32242,'','असम्बधा','वर्णवृत्तविशेषः।; \"असम्बधायाः प्रत्येकस्मिन् चरणे मगणः तगणः नगणः सगणः तथा द्वौ गुरू भवतः।\"','noun'),(32243,'','असम्भवः','अर्थालङ्कारविशेषः।; \"असम्भवे अशक्यस्य शक्यता प्रदर्श्यते।\"','noun'),(32231,'','अष्टिः','वृत्तिविशेषः।; \"अष्ट्यां षोडश अक्षराणि भवन्ति।\"','noun'),(32232,'','अष्टी','रागिणीविशेषः।; \"अष्टी दीपकरागस्य रागिणी अस्ति।\"','noun'),(32235,'','असङ्ख्यता, अगणनीयता, अगण्यता, अगणितता, अनन्तता','अगण्यस्य अवस्था भावो वा।; \"अवकाशस्थ तारकानां असङ्ख्यता अनुमानेन एव ज्ञातुं शक्यते।\"','noun'),(32227,'','पञ्चाक्षर','पञ्चभिः अक्षरैः युक्तः।; \"शिवस्य अस्य पञ्चाक्षरस्य मन्त्रस्य जपनेन भवतः विवाहः शीघ्रं भविष्यति।\"','adjective'),(32228,'','पञ्चाक्षरी','सः मन्त्रः यस्मिन् पञ्च अक्षराणि सन्ति।; \"तान्त्रिकाः महाशिवरात्र्याम् आ रात्रौ पञ्चाक्षरीं जपन्ति।\"','noun'),(32229,'','अष्टाध्यायी','पाणिनिना विरचितः संस्कृतव्याकरणस्य प्रधानः ग्रन्थः।; \"अष्टाध्याय्यां अष्टाध्यायाः सन्ति।\"','noun'),(32230,'','अष्टाह','यद् अष्ट दिनानि यावत् भवति।; \"इदम् अष्टाहः ज्वरः अस्ति।\"','adjective'),(32201,'','गञ्जनतालः','अष्टासु तालेषु एकः तालः।; \"मम गुरुः गञ्जनताले प्रवीणः अस्ति।\"','noun'),(32202,'','पञ्चतालः','अष्टासु तालेषु एकः तालः।; \"दूरात् पञ्चतालस्य ध्वनिः आगच्छति।\"','noun'),(32203,'','रूपलतालः','अष्टासु तालेषु एकः तालः।; \"रुपलतालेन कक्षः मन्त्रमुग्धः जातः।\"','noun'),(32204,'','समतालः','संगीतस्य अष्टासु तालेषु एकः प्रकारः।; \"संगीते समतालः अवादयत्।\"','noun'),(32205,'','अष्टदलम्','अष्टदलयुक्तं कमलम्।; \"तडागः अष्टदलैः आच्छादितः अस्ति।\"','noun'),(32206,'','अष्टदल','अष्टाभिः दलैः युक्तम्।; \"प्रति गुरुवासरे अष्टदलेन कमलेन लक्ष्मीं पूजय।\"','adjective'),(32207,'','अष्टद्रव्यम्','अष्टानि हविर्द्रव्याणि।; \"पिप्पलन्यग्रोधादि अष्टद्रव्याणि सन्ति।\"','noun'),(32211,'','अष्टभावः','वैद्यकानुसारेण स्तम्भस्वेदरोमाञ्चस्वरभङ्गावैश्वर्यकम्पवैवर्ण्याश्रुपाताः अष्ट भावाः।; \"वैद्यः अष्टभावम् अपि व्याधेः लक्षणं मन्यते।\"','noun'),(32212,'','अष्टभुजा','अष्टभिः भुजाभिः युक्ता देवी।; \"अर्चकः अष्टभुजां पूजयति।\"','noun'),(32214,'','अष्टमङ्गल','अष्टप्रकारकं मङ्गलम्।; \"सिंहः वृषः नागः कलशः व्यञ्जनम् वैजयन्ती भेरी तथा च  दीपकः इति अष्टमङ्गलानि सन्ति।\"','noun'),(32215,'','अष्टमानम्','अष्टौ मुष्टयः परिमाणम्।; \"अष्टमानान् तण्डुलान् प्राप्य ब्राह्मणः प्रसन्नः जातः।\"','noun'),(32216,'','अष्टमिका','चतुर्णां तोलकां परिमाणविशेषः।; \"विवाहसमये प्राप्तस्य अस्य कण्ठाभरणस्य तोलम् अष्टमिका अस्ति।\"','noun'),(32217,'','अष्टमिका','अर्धपलमात्रं परिमाणम्।; \"सः अस्य समाधानं अष्टमिकायां प्रयच्छति।\"','noun'),(32218,'','अष्टमूर्तिः','शिवस्य अष्टौ मूर्तयः।; \"सर्वः भवः रुद्रः उग्रः भीमः पशुपतिः ईशानः महादेवः अथवा क्षितिः जलः तेजः वायुः आकाशः यजमानः अकः तथा च चन्द्रः इति अष्टमूर्तयः।\"','noun'),(32219,'','अष्टवर्गः','अष्टौषधीनां समूहः।; \"जीवकम् ऋषभकं मेदा महामेदा काकोली क्षीरकोकोली ऋद्धिः तथा च वृद्धिः इति अष्टवर्गः।\"','noun'),(32220,'','क्षपणकः, जीवकः','नग्नः जैनसाधुः।; \"एषा क्षपणकानां सभा।\"','noun'),(32221,'','क्षपणकः, जीवकः','बौद्धभिक्षूणाम् एकः सम्प्रदायः।; \"अस्मिन् क्षेत्रे क्षपणकानां प्रभावः अस्ति।\"','noun'),(32222,'','अष्टसिद्धिः','सिद्धेः अष्ट प्रकाराः।; \"अणिमा लघिमा महिमा प्राप्तिः प्राकाम्यम् ईशित्वं वशित्वं कामावायिता इति अष्टसिद्धयः सन्ति।\"','noun'),(32224,'','अष्टाकपालः','सः यज्ञः यस्मिन् अष्टसु कपालेषु पुरोडाशः पक्त्वा हूयते।; \"अष्टाकपालस्य समाप्त्यनन्तरं पण्डितान् भोजनम् अयच्छत्।\"','noun'),(32226,'','अष्टाक्षर','अष्टाभिः अक्षरैः युक्तः।; \"गणेशस्य अयं अष्टाक्षरः मन्त्रः प्रभावी अस्ति।\"','adjective'),(32223,'','अष्टाकपालः','अष्टसु मृद्पात्रेषु पक्वः पुरोडाशः।; \"अन्ततः यज्ञे अष्टाकपालस्य आहुतिः दत्ता।\"','noun'),(32188,'','अष्टका','अष्टम्यां तिथौ क्रियमाणं श्राद्धम्।; \"अस्मिन् समये अष्टकायाः कृते अहम् आगन्तुं न शक्नोमि।\"','noun'),(32189,'','अष्टकुलम्, अष्टवंशः','पुराणानुसारेण सर्पाणां अष्टानि कुलानि।; \"शेषः वासुकिः कुलीरः कर्कटः धृतराष्ट्रः तक्षकः अनन्तः बलाहकः एतेषां कुलानां अष्टकुले अन्तर्भावो भवति।\"','noun'),(32191,'','शेषः','छन्दोविशेषः।; \"शेषे षट्चत्वारिंशत् गुरुवर्णाः तथा षष्टिः लघुवर्णाः भवति अथवा द्विपञ्चाशताधिकैकशत मात्राः भवन्ति।\"','noun'),(32200,'','चन्द्रशेखरतालः','अष्टासु तालेषु एकः तालः।; \"मम गुरुः अस्मान् चन्द्रशेखरतालं न पाठितवान्।\"','noun'),(32199,'','ज्योतितालः','अष्टासु तालेषु एकः तालः।; \"गायकः वादकाय ज्योतितालं वादयितुं सम्प्रार्थितवान्।\"','noun'),(32198,'','दोजतालः','अष्टासु तालेषु एकः तालः।; \"संगीतकारः दोजतालं वादयति।\"','noun'),(32197,'','आडतालः','अष्टासु तालेषु एकः तालः।; \"संगीतकारः आडतालं स्पष्टीकरोति।\"','noun'),(32195,'','कामेश्वरी','एका भैरवी।; \"सः तान्त्रिकः कामेश्वरीम् उपासते।\"','noun'),(32196,'','अष्टतालः','संगीतान्तर्गताः अष्टौ तालाः।; \"अष्टताले आडतालः दोजतालः ज्योतितालः चंद्रशेखरतालः गंजनतालः पञ्चतालः रूपलतालः तथा च समतालः इत्यस्य अन्तर्भावो भवति।\"','noun'),(32194,'','अष्टतारिणी','भगवत्याः अष्टरूपाणि।; \"तारा उग्रा महोग्रा व्रजा काली सरस्वती कामेश्वरी तथा च चामुण्डा इत्येताः अष्टतारिण्यः सन्ति।\"','noun'),(32192,'','अष्टकुली','सर्पाणां अष्टकुलेषु एकस्मिन् कुले जातः।; \"भीमसेनस्य विवाहः अष्टकुल्या कन्यया सह जातः।\"','adjective'),(32193,'','गन्धाष्टकम्','अष्टाभिः सुगन्धिभिः वस्तुभिः निर्मितं सुगन्धि वस्तु।; \"गन्धाष्टकस्य प्रयोगः मसिरूपेण अपि क्रियते।\"','noun'),(32186,'','अष्टका','गौणचान्द्रपौषमाघफाल्गुनमासीया कृष्णाष्टमी।; \"अष्टकायां मातृकं श्राद्धं क्रियते।\"','noun'),(32181,'','अश्वावतारी','छन्दोविशेषः।; \"अश्वावतार्याम् एकत्रिंशत् मात्राः सन्ति।\"','noun'),(32182,'','अष्टाङ्ग','अष्टाभिः अङ्गैः युक्तः।; \"सः प्रतिदिनं अष्टाङ्गं योगं करोति।\"','adjective'),(32183,'','अष्टाङ्गी','यः अष्टाङ्गयोगम् आचरति।; \"अष्टाङ्गी नित्यं स्वसमीपे एकम् आसनं स्थापयति।\"','noun'),(32184,'','अष्टकम्','अष्टानां समूहः।; \"गङ्गायाः स्तुतिः ताम् अधिकृत्य रचिते अष्टके अस्ति।\"','noun'),(32185,'','अष्टकमलम्, अष्टचक्रम्','हठयोगानुसारेण मूलाधारात् ललाटं यावत् वर्तमानानि अष्ट कमलानि येषु दलस्य सङ्ख्या भिन्ना वर्तते।; \"मूलाधारस्वाधिष्ठानमणिपुरानहदविशुद्धाज्ञाचक्रसहस्रारचक्रसुरतिमलाः  अष्टकमलानि सन्ति।\"','noun'),(32173,'','शास्त्रार्थः','तात्त्विकः वादविवादः।; \"सर्वे शास्त्रार्थं कर्तुं न शक्नुवन्ति।\"','noun'),(32174,'','अश्वललितः, अद्रितनया','वर्णवृत्तविशेषः।; \"अश्वललिते त्रयोविंशतिः वर्णाः सन्ति।\"','noun'),(32175,'','अश्ववदनः','एकः प्राचीनः देशः।; \"अश्ववदनस्य उल्लेखः संस्कृतसाहित्ये दृश्यते।\"','noun'),(32176,'','अश्वसूक्तम्','वेदेषु तत् सूक्तं यस्मिन् अश्वस्य वर्णनम् अस्ति।; \"तम् अश्वसूक्तं रोचते।\"','noun'),(32178,'','अश्वस्तन','वर्तमानदिनसम्बन्धिमात्रम्।; \"अश्वस्तनस्य मनुष्यस्य कापि चिन्ता न भवति।\"','adjective'),(32168,'','अश्वबन्धः','चित्रकाव्यानुसारेण छन्दोविशेषः।; \"अश्वबन्धे अश्वस्य चित्रं निर्माय यद् लिख्यते तस्मात् अङ्गानां तथा आभूषणानां नामानि प्राप्यन्ते।\"','noun'),(32170,'','अश्वलः','ऋषिविशेषः।; \"राज्ञः जनकस्य सभायां शास्त्रार्थं कर्तुम् अश्वलः अपि अगच्छत्।\"','noun'),(32171,'','शास्त्रार्थः','शास्त्रस्य अर्थः।; \"गुरुणा विना शास्त्रार्थः न ज्ञायते।\"','noun'),(32172,'','शास्त्रार्थः','सः तर्कः वितर्कः च यः शास्त्रस्य सम्यक् अर्थं यावत् नयति।; \"राजा जनकः नैकान् विदुषः ऋषीन् शास्त्रार्थं कर्तुं आमन्त्रितवान्।\"','noun'),(32166,'','पुष्करद्वीपः','पुराणानुसारेण सप्तद्वीपेषु एकः दीपः।; \"स्वस्मात् द्विगुणितविस्तारवन्तेन क्षीरसागरेण पुष्करद्वीपः परिवेष्टितः।\"','noun'),(32167,'','सावित्र, सौर्य','सवित्रा सूर्येण वा सम्बद्धम्।; \"मन्दिरे पञ्चकुण्डीयं सावित्रः होमः प्रचलति।\"','adjective'),(32165,'','शाकद्वीपः','पुराणानुसारेण पृथिव्याः सप्तसु द्वीपेषु एकः।; \"शाकद्वीपः दधिसागरं परिश्रयति।\"','noun'),(32153,'','सावित्री','कश्यपस्य पत्नी।; \"सावित्र्याः उल्लेखः पौराणिकग्रन्थेषु प्राप्यते।\"','noun'),(32154,'','सावित्री','अष्टावक्रस्य कन्या।; \"सावित्र्याः उल्लेखः धर्मग्रन्थेषु प्राप्यते।\"','noun'),(32155,'','सावित्री','राज्ञः भोजस्य पत्नी।; \"सावित्र्या सह राजा भोजः नगरभ्रमणं करोति।\"','noun'),(32156,'','सावित्री','प्लक्षद्वीपे वर्तमाना नदी।; \"सावित्र्याः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32157,'','सावित्रम्','प्राचीनम् अस्त्रम्।; \"तेन सावित्रेण शत्रुम् आघातितम्।\"','noun'),(32158,'','सावित्रः','सूर्यस्य पुत्रः।; \"सः सावित्रम् उपासते।\"','noun'),(32159,'','प्लक्षद्वीपः','विष्णुपुराणानुसारेण सप्तद्वीपेषु एकः।; \"प्लक्षद्वीपः जम्बुद्वीपात् द्विगुणितः अस्ति।\"','noun'),(32161,'','प्लक्षः','एकम् तीर्थस्थानम्।; \"अस्माकं प्रतिवेशी प्लक्षस्य यात्रार्थे गतः।\"','noun'),(32162,'','जम्बूद्वीपः, सुदर्शनः','पुराणानुसारेण सप्तसु द्वीपेषु एकः।; \"सप्तसु द्वीपेषु मध्यभागे जम्बुद्वीपः स्थितः अस्ति।\"','noun'),(32163,'','शाल्मलिद्वीपः','पुराणानुसारेण पृथिव्याः सप्तसु द्वीपेषु एकः।; \"शाल्मलिद्वीपस्य विस्तारः प्लक्षद्वीपात् द्विगुणितः अस्ति।\"','noun'),(32164,'','क्रौन्चद्वीपः','पुराणानुसारेण पृथिव्याः सप्तद्वीपेषु एकः द्वीपः।; \"क्रौन्चद्वीपः घृतसागरेण परिवेष्टितः।\"','noun'),(32151,'','सावित्री-संस्कारः','सवितृसम्बन्धी संस्कारः।; \"सावित्री-संस्कारः उपनयनकाले कुर्वन्ति।\"','noun'),(32152,'','सावित्री','धर्मस्य पत्नी।; \"सावित्र्याः उल्लेखः पुराणेषु प्राप्यते।\"','noun'),(32142,'','अश्वतरः','एकः गन्धर्वः।; \"अश्वतरस्य वर्णनं हिन्दूनां धर्मग्रन्थेषु प्राप्यते।\"','noun'),(32143,'','अश्वदूतः','अश्वारूढः सन्देशवाहकः।; \"द्वारपालः अश्वदूतेन सह राजानं प्रति गच्छति।\"','noun'),(32144,'','अश्वपतिः','अश्वसेनायाः अधिकारी।; \"वलीशाहः अश्वपतिः आसीत्।\"','noun'),(32146,'','अश्वपतिः','अश्वानां पतिः।; \"अश्वपतिः पञ्चाशत् अश्वानां स्वामी अस्ति।\"','noun'),(32147,'','अश्वपतिः','भरतस्य मातुलः।; \"अश्वपतेः उल्लेखः रामायणे प्राप्यते।\"','noun'),(32148,'','अश्वपतिः','कैकयदेशस्य राजपुत्राणाम् उपाधिः।; \"राजपुत्रः अश्वपतिः इति उपाधिं दत्वा सम्मानितः।\"','noun'),(32149,'','अश्वपतिः','मद्रदेशस्य धर्मपरायणः राजा।; \"अश्वपतिः सावित्र्याः पिता आसीत्।\"','noun'),(32150,'','सावित्री, देवीसावित्री','ब्रह्मणः पत्नी।; \"राजा अश्वपतिः सावित्रेः उपासनां कृत्वा कन्यां प्राप्तवान् यस्याः नामकरणम् अपि तेन सावित्री इत्येव कृतम्।\"','noun'),(32141,'','अश्वतरः','सर्पविशेषः।; \"मार्गेः मृतः अश्वतरः आसीत्।\"','noun'),(32140,'','अश्वग्रीवः','कश्यपऋषेः पुत्रः।; \"अश्वग्रीवः कश्यपऋषेः दनु इत्याख्यायाः पत्नेः पुत्रः आसीत्।\"','noun'),(32138,'','अश्वगतिः','चित्रकाव्यस्य चक्रम्।; \"अश्वगतौ चतुष्षष्टिः कोष्टकानि सन्ति।\"','noun'),(32139,'','खड्गबन्धः','चित्रकाव्यविशेषः।; \"खड्गबन्धे पद्यस्य शब्दाः एवं लिख्यन्ते येन शब्दाः खड्गस्य आकारं प्राप्नुवन्ति।\"','noun'),(32123,'','अश्रुतः','श्रीकृष्णस्य पुत्रः।; \"भागवतकथायां अश्रुतस्य उल्लेखः अस्ति।\"','noun'),(32124,'','अश्रुतः','द्युतमतः पुत्रः।; \"अश्रुतस्य वर्णनं प्राचीनेषु ग्रन्थेषु प्राप्यते।\"','noun'),(32125,'','द्युतिधर','यः प्रकाशं धारयति।; \"द्युतिधराणां संन्यासिनां दर्शनं तोषाय भवति।\"','adjective'),(32127,'','द्युतिमत्','मद्रदेशस्य राजा।; \"द्युतिमतः कन्यायाः विवाहः सहदेवेन अभवत्।\"','noun'),(32128,'','अश्रुमुख','अश्रुयुक्तं मुखं यस्य।; \"अश्रुमुखं बालकं माता अग्रहत्।\"','adjective'),(32130,'','अश्रेष्ठ, अनुत्तम','यः श्रेष्ठः नास्ति।; \"श्रेष्ठः पुरुषः अश्रेष्ठं पुरुषं परिवर्तयति।\"','adjective'),(32131,'','अश्लीलता','काव्यस्य दोषेषु एकः।; \"तस्य रचनाः अश्लीलतायाः कृते ख्याताः।\"','noun'),(32132,'','उशीनर','एकः धर्मपरायणः राजा।; \"इन्द्रेण अग्निदेवेन च उशीनरः परीक्षितः।\"','noun'),(32133,'','अश्वकर्णः, जरणद्रुमः, तार्क्ष्यप्रसवः, शस्यसंबरणः, धन्यः, दीर्घपर्णः, कुशकः, कौशिकः','शालवृक्षस्य प्रकारः।; \"मार्गे अश्वकर्णस्य आवतिः अस्ति।\"','noun'),(32135,'','अश्वगतिः, धारा','अश्वस्य पदविक्षेपः।; \"अश्वगतिं वर्धयितुम् अश्ववाहः प्रयतते।\"','noun'),(32136,'','अश्वगतिः','छन्दोविशेषः।; \"अश्वगतेः प्रत्येकस्मिन् चरणे पञ्च भगणाः एकः गुरुश्च भवति।\"','noun'),(32137,'','चित्रकाव्यम्','सः आलङ्कारिकः काव्यप्रकारः यस्मिन् चरणानां रचना एवं क्रियते येन कमलादिसदृशानि चित्राणि दृश्यन्ते।; \"चित्रकाव्यस्य गणना अधमे काव्ये भवति।\"','noun'),(32120,'','अश्रिः, अश्री','अस्त्रस्य अग्रभागः।; \"अश्रिः तीक्ष्णा भवेत्।\"','noun'),(32122,'','अश्रुलेशः, नयनोदबिन्दुः, बाष्पबिन्दुः','अश्रुबिन्दुः।; \"सा नेत्रयोः समागतानाम् अश्रुलेशानाम् अवरोधनस्य प्रयन्तम् अकरोत्।\"','noun'),(32119,'','अश्रिः','गृहस्य कोणः।; \"दीपावल्याः उत्सवसमये प्रत्येका अश्रिः दीपैः प्रकाशिता भवति।\"','noun'),(32116,'','नेमिचक्रः','परीक्षितस्य वंशे जातः एकः राजा।; \"नेमिचक्रः असीमकृष्णस्य पुत्रः आसीत्।\"','noun'),(32117,'','असीमकृष्णः','परीक्षितस्य वंशे जातः एकः राजा।; \"असीमकृष्णः वीरः श्रेष्ठः च आसीत्।\"','noun'),(32118,'','नेमिः','एकः दैत्यः।; \"भागवते नेमेः वर्णनं प्राप्यते।\"','noun'),(32114,'','मूत्रपतनम्','मूत्रस्य पतनस्य व्याधिः।; \"मूत्रपतनस्य व्याधौ तेन नियन्त्रणं प्राप्तम्।\"','noun'),(32103,'','मूत्रमार्गः','मूत्रोत्सर्जनस्य मार्गः।; \"मूत्रमार्गे पाषाणरोगस्य जायमानत्वात् मूत्रोत्सर्जने पीडा भवति।\"','noun'),(32106,'','मूत्रविज्ञानम्','आयुर्वेदस्य एकः ग्रन्थः।; \"मूत्रविज्ञानस्य रचयिता जानुकर्णः ऋषिः अस्ति।\"','noun'),(32097,'','अश्मरी','मूत्रद्वारा प्रस्तरम् इव कठिनमांसोत्सर्गः।; \"औषधेन अश्मरी शमिता।\"','noun'),(32075,'','त्रिसामा','एका पौराणिका नदी।; \"त्रिसामा महेन्द्रपर्वतात् प्रभवति इति मन्यन्ते।\"','noun'),(32076,'','अशून्यशयनव्रतम्','श्रावणमासस्य कृष्णपक्षस्य द्वितीयायां क्रियमाणं व्रतम्।; \"भगवतः विष्णोः पूजनार्थम् अशून्यशयनव्रतं क्रियते।\"','noun'),(32112,'','देवदारुतैलम्','देवदारोः अरुक्षस्य काष्ठस्य तैलम्।; \"देवदारुतैलस्य उपयोगः वेदनां निवारयितुं क्रियते।\"','noun'),(32111,'','नृत्यप्रियः','कार्तिकेयस्य अनुचरः।; \"नृत्यप्रियस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32109,'','जानुकर्णः','एकः ऋषिः।; \"जानुकर्णेन मूत्रविज्ञानस्य रचना कृता।\"','noun'),(32110,'','नूपुरः','इक्ष्वाकुवंशीयः राजा।; \"नूपुरस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32102,'','नृगा','एका पौराणिका स्त्री या उशीनरस्य पत्नी आसीत्।; \"नृगः नृगायाः गर्भात् जातः।\"','noun'),(32101,'','नृग','उशीनरस्य पुत्रः।; \"नृगः नृगायाः गर्भात् जातः।\"','noun'),(32100,'','नृगः','मनोः पुत्रः।; \"नृगस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32098,'','मूत्रनिरोधः','मूत्रप्रतिबन्धकरोगविशेषः।; \"मूत्रनिरोधेन रुगण्स्य शरीरं श्वयति।\"','noun'),(32093,'','मूत्रक्षयः','मूत्रावरोधस्य व्याधिः।; \"सः रुग्णः मूत्रक्षयेण पीडितः अस्ति।\"','noun'),(32094,'','मूत्रनिरोधः','मूत्ररोधनस्य व्याधिः।; \"वैद्यः रुग्णाय मूत्रनिरोधस्य औषधम् अददात्।\"','noun'),(32092,'','मूत्राघातः','मूत्रावरोधकरोगविशेषः।; \"मूत्राघातस्य द्वादश प्रकाराः सन्ति।\"','noun'),(32087,'','त्रावणकोरम्, तिरुविथामकूरम्, तिरुविथान्कूरम्, अश्मकः','दक्षिणभारते वर्तमानं प्राचीनं राज्यम्।; \"त्रावणकोरं कदाचित् समृद्धं राज्यम् आसीत्।\"','noun'),(32090,'','अश्मभेदः','वृक्षविशेषः।; \"अश्मभेदः मूत्रकृच्छम् उपशमयति।\"','noun'),(32091,'','मूत्रकृच्छ्रः, मूत्रकृच्छ्रम्','वेदनया मूत्रोत्सर्गस्य व्याधिः।; \"पितामही मूत्रकृच्छेन पीडिता अस्ति।\"','noun'),(32048,'','पीतशालः, असनवृक्षः','पीतः शालवृक्षविशेषः।; \"पीतशालस्य काष्ठस्य दृढत्वात् गृहादीनां निर्माणे तस्य उपयोगः क्रियते।\"','noun'),(32049,'','भावप्रकाशः','आयुर्वेदस्य एकः मूलग्रन्थः।; \"भावप्रकाशस्य रचयिता आचार्य-भाव-मिश्रः अस्ति।\"','noun'),(32050,'','अश्रद्धेय','श्रद्धार्थे अयोग्यः।; \"कदाचित् परिवारस्थान् अश्रद्धेयान् जनान् अपि नमस्क्रिया करणीया।\"','adjective'),(32051,'','अशब्द, निस्वर','यद् शब्दैः व्यक्तं न भवति।; \"अशब्दा वृत्तिः अपि सर्वं सूचयति।\"','adjective'),(32052,'','सुकेशी','सा स्त्री यस्याः केशाः शोभनीयाः कृष्णाः दीर्घाः च सन्ति।; \"एका सुकेशी पुनःपुनः केशान् मार्जयति।\"','noun'),(32053,'','सुकेशी, सुकेशा','यस्या केशाः शोभनीयाः कृष्णाः दीर्घाः च सन्ति।; \"मञ्चे एका सुकेशी स्त्री उपस्थिता अस्ति।\"','adjective'),(32055,'','सुकेश','यस्य केशाः शोभनीयाः।; \"सुकेशः युवकः वारंवारं केशमार्जनं करोति।\"','adjective'),(32060,'','अशासावेदनीयः','जैनमतानुसारेण कर्मविशेषः।; \"अशासावेदनीयस्य प्रादुर्भावेण दुःखम् अनुभूयते।\"','noun'),(32062,'','कुस्वभावः','दुष्टः स्वभावः।; \"स्वपुत्राणां कुस्वभावः अस्माभिः एव दूरीकर्तव्यः।\"','noun'),(32063,'','नारदः','विश्वमित्रस्य पुत्रः।; \"नारदस्य वर्णनं पुराणे दृश्यते।\"','noun'),(32064,'','नारदः','एकः गन्धर्वः।; \"नारदः कश्यपऋषेः पुत्रः अस्ति।\"','noun'),(32065,'','नायकरागः','रागविशेषः।; \"नायकरागः दीपकरागस्य पुत्रः अस्ति इति मन्यते।\"','noun'),(32066,'','नित्यहोमः','सर्वकालीनः होमः।; \"पण्डितः नित्यहोमं करोति।\"','noun'),(32067,'','निदद्रु','दद्रुरोगरहितः।; \"निदद्रुः बालकः दद्रुणा पीडिताय बालकाय उद्वेजयति।\"','adjective'),(32069,'','अशुभ्र, अश्वेत, असित','यः श्वेतः नास्ति।; \"अधवानां कृते अशुभ्रं वस्त्रं वर्ज्यम् आसीत्।\"','adjective'),(32086,'','अश्मन्तकः, अम्लोटकः','तृणविशेषः।; \"प्राचीनाः ऋषयः अश्मन्तकेन मेखलां निर्मान्ति स्म।\"','noun'),(32084,'','अशौर्यम्','शौर्यस्य अभावः।; \"राज्यस्य धुरां वोढुम् अशौर्यं न योग्यम्।\"','noun'),(32085,'','पराक्रमहीन','शौर्यण रहितः।; \"पराक्रमहीनस्य राज्ञः पराजयः निश्चितः अस्ति।\"','adjective'),(32083,'','अशोकषष्ठी','चैत्रमासस्य शुक्लपक्षस्य षष्ठी तिथिः।; \"अशोकषष्ठी चैत्रस्य नवरात्रस्य षष्ठी अस्ति।\"','noun'),(32078,'','अशोकपुष्पमञ्जरी','दण्डकवृत्तभेदः।; \"अशोकपुष्पमञ्जर्याम् अष्टाविंशतिः अक्षराणि भवन्ति तथा लघुगुरुविषये कोऽपि नियमः न वर्तते।\"','noun'),(32079,'','अशोकवाटिका','अशोकवृक्षस्य उद्यानम्।; \"यात्रिणः अशोकवाटिकायां विश्राम्यन्ति।\"','noun'),(32081,'','नीलचक्रम्','अशोकमञ्जर्याः भेदविशेषः।; \"नीलचक्रे त्रिंशत् वर्णाः भवन्ति।\"','noun'),(32082,'','नीलचक्रम्, श्रीचक्रम्','जगन्नाथमन्दिरस्य शिखरे स्थितं चक्रम्।; \"नीलचक्रम् अष्टाभिः धातुभिः विनिर्मितम्।\"','noun'),(32077,'','भावमिश्रः','भावप्रकाशनाम्नः ग्रन्थस्य रचनाकारः।; \"भावमिश्रस्य अयं ग्रन्थः प्रसिद्धः अस्ति।\"','noun'),(32074,'','त्रिष्टुप्','एकं वैदिकं छन्दः।; \"त्रिष्टुप् इति छन्दसि प्रत्येके चरणे एकादशानि अक्षराणि सन्ति।\"','noun'),(32072,'','त्रिशिखः','रावणस्य पुत्रः।; \"त्रिशिखस्य वर्णनं धार्मिकग्रन्थेषु प्राप्यते।\"','noun'),(32073,'','त्रैबलिः','एकः पौराणिकः ऋषिः।; \"त्रैबालेः वर्णनं महाभारते आधिक्येन प्राप्यते।\"','noun'),(32070,'','त्रिशिरः','एकः राक्षसः।; \"त्रिशिरस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(32071,'','त्रिशीर्षः','प्रजापतेः त्वष्टुः पुत्रः।; \"त्रिशीर्षस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32046,'','शतगु','शतैः गोभिः युक्तः।; \"राज्ञः गोदानेन नैके ऋषयः शतगवः भवन्ति स्म।\"','adjective'),(32047,'','अशनाया, क्षुधा, बुभुक्षा','भोजनस्य इच्छा।; \"अहम् अशनायाः उपशमनाय प्रयत्नं करोमि स्म।\"','noun'),(32041,'','शक्तुकः','विषप्रकारः यः अत्यन्तः तीव्रः अस्ति।; \"शक्तुकस्य उल्लेखः भावप्रकाशे वर्तते।\"','noun'),(32042,'','शतकुम्भा','एका पौराणिका नदी।; \"शतकुम्भायाः वर्णनं महाभारते वर्तते।\"','noun'),(32043,'','शणकः','एकः ऋषिः।; \"शणकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(32044,'','अशत्रु','यस्य कः अपि शत्रुः नास्ति।; \"अशत्रुः राजा नैकेभ्यः वर्षेभ्यः पर्यन्तं राज्यम् अकरोत्।\"','adjective'),(32039,'','शक्तिवनम्','एकं वनं यस्य वर्णनं पुराणे वर्तते।; \"अस्मिन् ग्रन्थे शक्तिवनस्य वर्णनम् अस्ति।\"','noun'),(32037,'','पिजवनः','एकः पौराणिकः राजा।; \"पिजवनः पाञ्चालस्य राजा आसीत्।\"','noun'),(32038,'','सुदासः','एकः पौराणिकः राजा।; \"सुदासः द्रुपदात् प्राक् पाञ्चालस्य राजा आसीत्।\"','noun'),(32032,'','अव्रतम्','जैनमतानुसारेण व्रतस्य त्यागः।; \"तेन अव्रतस्य निश्चयः कृतः।\"','noun'),(32033,'','अव्रत','यः कमपि व्रतं न आचरति।; \"यात्रायाम् एकेन अव्रतेन मनुष्येण सह सम्पर्कः जातः।\"','adjective'),(32035,'','निःशङ्क','शङ्कया रहितः।; \"निःशङ्कं मनः प्रसन्नं भवति।\"','adjective'),(32036,'','असंशयः, निश्चयः, निश्चितम्, निर्धारणम्, असंदिग्धत्वम्, ध्रुवत्वम्','संशयस्य अभावः।; \"असंशयः मनः दृढीकरोति।\"','noun'),(32026,'','अव्युत्पन्न','(व्याकरणशास्त्रानुसारेण सः शब्दः)यस्य व्युत्पत्तिः न जायते।; \"एतेषु शब्देषु अव्युत्पन्नान् शब्दान् अन्यत्र लिखन्तु।\"','adjective'),(32028,'','अव्रण','व्रणरहितः।; \"अव्रणस्य मनुष्यस्य व्रणस्य पीडायाः अनुभवः कथं भवेत्।\"','adjective'),(32024,'','अव्युत्पन्न','यस्य कस्मादपि व्युत्पत्तिः न दीयते।; \"तेन स्वस्य शोधकार्यार्थम् अव्युत्पन्नानां शब्दानां सूचिः निर्मिता।\"','adjective'),(32012,'','लिप्तकः','विषजुष्टः बाणः।; \"आखेटकः व्याघ्रं लिप्तकेन प्राहरत्।\"','noun'),(32013,'','लिप्ता','ज्योतिःशास्त्रानुसारेण कालस्य परिमाणविशेषः।; \"लिप्ता प्रायः निमेषेण समानं भवति।\"','noun'),(32014,'','अव्याजः','छलाभावः।; \"महात्मनः चित्तम् अव्याजम् अस्ति।\"','noun'),(32015,'','अव्यापकता','व्यापकतायाः अभावः।; \"कल्पनायाः अव्यापकता मन्दत्वम् जनयति।\"','noun'),(32016,'','अनुद्योगिन्','उद्योगहीनः।; \"अनुद्योगिना मनुष्येण विवाहं कर्तुं सा अवमन्यते।\"','adjective'),(32017,'','अव्यापारिन्','साङ्ख्यमतानुसारेण यः प्रकृत्या क्रियाशून्यः अस्ति।; \"योगिनः अव्यापारिनः सन्ति।\"','adjective'),(32020,'','अव्याप्तिः','व्याप्तिः च तदभाववदवृत्तित्वम् व्यापकसमानाधिकरण्यम् अनौपाधिकत्वम् आधेयतादिवत् वस्तुभावविशेषः लक्ष्ये लक्षणस्याप्रवृत्तिः।; \"अव्याप्तिः इति एकः दोषः अस्ति।\"','noun'),(32018,'','अव्यापक','यः न व्याप्नोति।; \"ईश्वरः व्यापकः  जीवः अव्यापकः अस्ति।\"','adjective'),(32019,'','अव्याप्तिः','व्याप्तेः अभावः।; \"जलस्य अव्याप्तिः कष्टप्रदा अस्ति।\"','noun'),(32008,'','व्याघातः','कस्यचित् अधिकारे जायमानः आघातः।; \"व्याघातात् रक्षितुं सः विधिज्ञम् आश्रितः।\"','noun'),(32009,'','लिप्तक','विषेण लिप्तम्।; \"आखेटकः लिप्तकेन बाणेन मृगयां प्रहरति।\"','adjective'),(32010,'','व्याघातः','ज्योतिषशास्त्रे सप्तविंशतियोगान्तर्गतत्रयोदशयोगः।; \"व्याघाते शुभकार्यं वर्जितम्।\"','noun'),(32011,'','व्याघातः','काव्ये अर्थालङ्कारविशेषः।; \"व्याघाते एकेन एव उपायेन द्वयोः विरुद्धयोः कार्ययोः वर्णनं भवति।\"','noun'),(32007,'','अव्याघातः','व्याघातस्य अभावः।; \"मनसः शान्त्यर्थे अव्याघातः आवश्यकः।\"','noun'),(32005,'','पुरुजानुः','एकः पौराणिकः राजा।; \"पुरुजानुः राजा द्रुपदात् प्राक् पाञ्चालनरेशः आसीत्।\"','noun'),(32006,'','विष्वक्सेनः','चतुर्दशसु मनुषु एकः मनुः।; \"विष्वक्सेनः मत्स्यपुराणानुसारेण त्रयोदशतमः तथा च विष्णुपुराणानुसारेण चतुर्दशतमः मनुः आसीत्।\"','noun'),(32004,'','उग्रायुधः','धृतराष्ट्रस्य पुत्रः।; \"उग्रायुधस्य वर्णनं पुराणे वर्तते।\"','noun'),(32002,'','केशिनी','राज्ञः अजमेढस्य एका पत्नी।; \"केशिन्याः वर्णनं पुराणेषु दृश्यते।\"','noun'),(32003,'','जन्मेजयः','सः राजा यः महाभारतकालात् प्राक् पाञ्चालं शशास।; \"उग्रायुधेन जन्मेजयः हतः।\"','noun'),(32001,'','धूमिनी','राज्ञः अजमेढस्य एका पत्नी।; \"धूमिन्याः वर्णनं पुराणेषु दृश्यते।\"','noun'),(31995,'','संजयः','राजा भृम्यश्वस्य पञ्चसु पुत्रेषु एकः।; \"संजयस्य वर्णनं धार्मिककथासु दृश्यते।\"','noun'),(31979,'','अव्यवहार्य्य','व्यवहर्तुम् अयोग्यः।; \"अव्यवहार्याणि वस्तुनि क्षेप्तव्यानि।\"','adjective'),(31980,'','प्रहासः','कार्तिकेयस्य अनुचरः।; \"प्रहासस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(31981,'','प्रान्तरम्','निर्जनः मार्गः।; \"तं मन्दिरं प्राप्तुं वयं घण्टां यावत् प्रान्तरात् अगच्छन्।\"','noun'),(31982,'','अव्यवधानम्','व्यवधानेन विना।; \"अव्यवधानेन कार्यक्रमः सम्पन्नः।\"','noun'),(31983,'','वन्यक्षेत्रम्','वनेन परितः क्षेत्रम्।; \"अस्माकं यानं अर्धहोरां यावत् वन्यक्षेत्रे अभ्रमत्।\"','noun'),(31984,'','प्रान्तायनः','ऋषेः प्रान्तस्य गोत्रजः।; \"प्रयागराज्ये वयं प्रान्तायनम् अमिलत्।\"','noun'),(31985,'','गोत्रज','गोत्रे जातः।; \"सः कश्यपमुनेः गोत्रजः अस्ति।\"','adjective'),(31988,'','अव्याकृतधर्मः','बौद्धशास्त्रानुसारेण प्रकृतिः यया शुभाशुभकर्मणी कर्तुं शक्यते।; \"अव्याकृतधर्मस्य निरूपणं पालिभाषायाः साहित्ये प्राप्यते।\"','noun'),(31960,'','चातुर्भद्रम्','नागरातिविषामुस्ता गुडूचीति चतुष्टयम्।; \"चातुर्भद्रम् औषधिरूपेण उपयुज्यते।\"','noun'),(31961,'','चातुर्मासिक','यद् चातुर्मासे जायते।; \"अस्मिन् मन्दिरे चातुर्मासिकस्य यज्ञस्य आयोजनं कृतम् अस्ति।\"','adjective'),(31962,'','चतुर्मासम्','आषाढमासस्य शुक्लपक्षस्य एकादश्याः कार्तिकमासस्य शुक्लपक्षस्य एकादशीं यावत् चतुर्मासात्मकः समयः।; \"पुराणानुसारेण चतुर्मासे भगवान् विष्णुः निद्राति।\"','noun'),(32000,'','अलमीढः','एकः पाञ्चालनरेशः।; \"अलमीढस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(31999,'','नलिनी','एका पौराणिका स्त्री।; \"नलिनी राज्ञः अलमीढस्य पत्नी आसीत्।\"','noun'),(31998,'','कपिल, काम्पिल्य','राजा भृम्यश्वस्य पञ्चसु पुत्रेषु एकः।; \"कपिलस्य वर्णनं वायुमत्स्यादिषु पुराणेषु दृश्यते।\"','noun'),(31997,'','यवीनरः','राजा भृम्यश्वस्य पञ्चसु पुत्रेषु एकः।; \"यवनीरस्य वर्णनं वायुमत्स्यादिषु पुराणेषु दृश्यते।\"','noun'),(31996,'','बृहदिषुः','राजा भृम्यश्वस्य पञ्चसु पुत्रेषु एकः।; \"वृहदिषोः वर्णनं वायुमत्स्यादिषु पुराणेषु दृश्यते।\"','noun'),(31994,'','मुद्रलः, मुकुलः','राजा भृम्यश्वस्य पञ्चसु पुत्रेषु एकः।; \"मुद्गलेन भ्रातृभिः सह पञ्चालस्य रक्षा कृता।\"','noun'),(31993,'','भृम्यश्वः','पौराणिकः राजा।; \"कथानुसारेण भृम्यश्वस्य पञ्चभिः पुत्रैः पञ्चालस्य रक्षा कृता ।\"','noun'),(31990,'','अव्याख्येय, अनिर्वर्णनीय, निरुपाख्य, अनिर्वचनीय','यद् अधिकं वर्णयितुं न शक्यते।; \"अस्याः कथायाः पठनेन पाठकस्य अव्याख्येया चित्तवृतिः भवति।\"','adjective'),(31992,'','भृम्यश्वः','एकः ऋषिः।; \"भृम्यश्वस्य वर्णनं पुराणेषु दृश्यते।\"','noun'),(31943,'','प्रतिस्कन्धः','कार्तिकेयस्य अनुचरः।; \"प्रतिस्कन्धस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31944,'','प्रधानः','एकः राजर्षिः।; \"प्रधानस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31945,'','दीर्घमता-ऋषिः, प्रद्वेषी','पौराणिकः ऋषिः।; \"दीर्घमता-ऋषेः वर्णनं महाभारते प्राप्यते।\"','noun'),(31946,'','प्रस्कुन्दः','वर्तुलाकारा वेदिः।; \"पण्डितः प्रस्कुन्दे उपविशत्।\"','noun'),(31948,'','प्रसृतजः','व्याभिचारात् जातः संतानः।; \"वेश्यया स्वपुत्रः इव प्रसृतजः पालितः।\"','noun'),(31949,'','प्रसेनजित्','भागवतानुसारेण सत्राजितः भ्राता यः सिंहेन हतः।; \"प्रसेनजित् कृष्णेन हतः इति सत्राजित् आरोपितवान्।\"','noun'),(31950,'','सत्राजित्','एकः यादवः येन सूर्योपासनां कृत्वा स्यमन्तकमणिः प्राप्तः।; \"सत्राजितः कन्यायाः सत्यभामायाः विवाहः कृष्णेन सह जातः।\"','noun'),(31951,'','स्यमन्तकमणिः','सः पौराणिकः मणिः यः सूर्येण सत्राजितः उपासनया प्रसद्य तस्मै दत्तः।; \"एकवारं स्यमन्तकमणिः कृष्णेन हृतः इति जनाः निनिन्दुः।\"','noun'),(31952,'','प्रस्तारपङ्क्तिः','एकं वैदिकं छन्दः।; \"प्रस्तारपङ्क्त्यां प्रथमे द्वितीये च चरणे द्वादश तथा च तृतीये चतुर्थे च चरणे अष्टौ मात्राः सन्ति।\"','noun'),(31978,'','अव्यवस्थित, अमर्याद','विधानशास्त्रादीनां मर्यादया रहितः।; \"अव्यवस्थितस्य कार्यस्य परिणामाः सम्यक् न सन्ति।\"','adjective'),(31974,'','अव्यक्तानुकरण','अव्यक्तस्य पदस्य शब्दस्य वा अनुकरणम्।; \"पशूनां पक्षिणां च ध्वनेः मनुष्यैः कृतम् अनुकरणम् अव्यक्तानुकरणम् अस्ति।\"','noun'),(31975,'','अव्यथा','; \"','noun'),(31976,'','अव्ययीभावः, अव्ययीभाव-समासः','व्याकरणे सः समासः यस्मिन् समर्थं पदम् अव्ययेन समस्यते।; \"उपकृष्णम् अनुरुपम् इत्यादीनि अव्ययीभावस्य उदाहरणानि सन्ति।\"','noun'),(31977,'','अव्ययेतः','यमकानुप्रासस्य द्वयोः भेदयोः एकः।; \"अव्ययेते यमकात्मकेषु अक्षरेषु अन्यद् पदम् अक्षरं न वर्तते।\"','noun'),(31964,'','परिभ्रमी','यः व्यर्थमेव अत्र तत्र अटति।; \"परिभ्रमिणैः सह साहचर्येण भवतः पुत्रः अपि परिभ्रमी अभवत्।\"','noun'),(31959,'','चातुर्दश','यः चतुर्दश्यां जातः।; \"सीमायाः पुत्रः चातुर्दशः अस्ति।\"','adjective'),(31957,'','चातुर्दशः','एकः राक्षसः।; \"चातुर्दशस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31958,'','चातुर्दश','चतुर्दश्या सम्बद्धः।; \"सीमा चातुर्दशं व्रतं करोति।\"','adjective'),(31942,'','प्रतिविन्ध्यः','युधिष्ठिरस्य पुत्रः।; \"प्रतिविन्ध्यः द्रौपदीगर्भात् जातः।\"','noun'),(31956,'','चातुर्थक','प्रतिचतुर्थदिने यः भवति।; \"प्रतिचतुर्थदिने यः ज्वरः भवति तस्य चातुर्थकः ज्वरः इति संज्ञा।\"','adjective'),(31955,'','चातुर्जातकम्','गुडत्वगेलापत्रनागकेशररूपचतुष्टयम्।; \"चातुर्जातकस्य उपयोगः भोजने भेषजे च उपयुज्यते।\"','noun'),(31939,'','प्रतर्दनः','पौराणिकः ऋषिः।; \"प्रतर्दनस्य वर्णनं सामवेदे प्राप्यते।\"','noun'),(31938,'','प्रज्वारः','ज्वरस्य तापः।; \"ज्वरेण पीडिताः रुग्णाः प्रज्वारेण त्रस्ताः।\"','noun'),(31940,'','प्रतानः','एकः ऋषिः।; \"प्रतानस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31941,'','प्रतिवाहः','अक्रूरस्य भ्राता।; \"प्रतिवाहस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31937,'','प्रज्वारः','एकः गन्धर्वः।; \"प्रज्वारस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31936,'','प्रज्वलिया','मात्रिकः छन्दोविशेषः।; \"प्रज्वलियायाः प्रत्येकस्मिन् चरणे षोडश मात्राः सन्ति।\"','noun'),(31933,'','मानवी','मनोः कन्या।; \"मानव्याः वर्णनं पुराणे प्राप्यते।\"','noun'),(31935,'','प्रज्भटिका','प्राकृतछन्दसः एकः भेदः।; \"प्रज्भटिकायां प्रत्येके चरणे षोडशमात्राः सन्ति।\"','noun'),(31932,'','पुष्पिताग्रा','वर्णवृत्तविशेषः।; \"पुष्पिताग्रायाः प्रथमे तृतीये च चरणे द्वौ नगणौ एकः रगणः एकः यगणः च भवति तथा द्वितीये चतुर्थे च चरणे नगणः जगणौ रगणः तथा एकः गुरुः च भवति।\"','noun'),(31931,'','पुष्पदामः','वर्णवृत्तविशेषः।; \"पुष्पदामस्य प्रत्येकस्मिन् चरणे षोडश वर्णाः सन्ति।\"','noun'),(31930,'','अव्यक्तराशिः','बीजगणिते अज्ञातः अङ्कः अलक्षितं परिमाणं वा।; \"बीजगणिते अव्यक्तराशिं ज्ञात्वा प्रश्नान् समाधत्ते।\"','noun'),(31929,'','अव्यक्तगति','सर्वेषां परोक्षम् आचरतीति।; \"अव्यक्तगतिः मनुष्यः सर्वैः ज्ञातः।\"','adjective'),(31920,'','सरल','यः व्यङ्ग्यः अथवा वक्रः नास्ति।; \"कृपया भवान् मम सरलानां प्रश्नानां सरलानि उत्तराणि वदन्तु।\"','adjective'),(31922,'','लक्षणरहित','; \"','adjective'),(31926,'','पुष्पदन्तः','एकः विद्याधरः।; \"पुष्पदन्तस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31927,'','पुष्पद्रंष्टः','एकः नागः।; \"पुष्पद्रंष्टस्य वर्णनं पुराणे प्राप्यते।\"','noun'),(31928,'','अव्यक्तक्रिया','बीजगणिते वर्तमाना एका क्रिया।; \"अद्यपि अव्यक्तक्रियां ज्ञातुं न शक्नोमि।\"','noun'),(31919,'','अवोक्षणम्','हस्तं तिर्यक् कृत्वा जलप्रोक्षणम्।; \"पण्डितः यजमानेन अवोक्षणं कारयति।\"','noun'),(31917,'','सर्वसम्मत, मतभेदरहित','सर्वैः स्वीकृतम्।; \"अयं सर्वसम्मतः निर्णयः नासीत्।\"','adjective'),(31918,'','निर्वैरम्, अविद्वेषः','वैरस्य अभावः।; \"निर्वैरेण एव अस्य समाधानं भवितुम् अर्हति।\"','noun'),(31894,'','मनोहररागः','सङ्कररागविशेषः।; \"सङ्गीतज्ञः मनोहररागं गायति।\"','noun'),(31895,'','मनोहरा','त्रिशिरायाः राक्षस्याः माता।; \"मनोहरायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31896,'','अप्राप्य','यस्य प्राप्तिः अनुचिता।; \"सः सर्वदा एव अप्राप्यानि वस्तूनि इच्छति।\"','adjective'),(31897,'','मयूरगतिः','वर्णवृत्तविशेषः।; \"मयूरगतेः प्रत्येकस्मिन् चरणे क्रमेण पञ्च यगणाः मगणः भगणश्च भवति।\"','noun'),(31900,'','अवेष्टिः','यज्ञेन प्रायश्चित्तिः।; \"ऋषेः शापात् मुक्तिं प्राप्तुं राज्ञः कृते अवेष्टिः एव उपायः।\"','noun'),(31901,'','अवैदिक','वेदविरुद्धः।; \"इदानीन्तने काले अवैदिकाः प्रथाः अधिकाः प्रचलन्ति।\"','adjective'),(31909,'','निदाघः','पुलस्त्यमुनेः पुत्रः।; \"विष्णुपुराणे निदाघस्य वर्णनं प्राप्यते।\"','noun'),(31913,'','अवैदिक','यद् वैदिकं नास्ति।; \"बौद्धः धर्मः अवैदिकः धर्मः अस्ति।\"','adjective'),(31916,'','ऐकमत्यम्, एकवाक्यता, एकचित्तता','कस्मिञ्चित् विषये विचारे वा सर्वेषां जनानां समानं मतं वर्तते तादृशी अवस्था।; \"तस्य व्यक्तित्वस्य विषये विद्वत्सु ऐकमत्यं नास्ति।\"','noun'),(31892,'','मनोवती','गन्धर्वस्य चित्राङ्गदस्य पुत्री।; \"मनोवत्याः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31893,'','मनोहरः','छन्दोविशेषः।; \"मनोहरे त्रयोदश गुरुवर्णाः षड्विंशत्याधिकैकशताः लघुवर्णाः तथा द्विपञ्चाशताधिकैकशताः मात्राः सन्ति।\"','noun'),(31886,'','मनोरमा','वर्णवृत्तविशेषः।; \"मनोरमायाः प्रत्येकस्मिन् चरणे चत्वारः भगणाः तथा द्वौ गुरुवर्णौ भवतः।\"','noun'),(31887,'','मनोरमा','चतुर्दशभिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"मनोरमायाः प्रत्येकस्मिन् चरणे चत्वारः सगणाः तथा अन्ते द्वौ लघुवर्णौ भवतः।\"','noun'),(31888,'','मनोरमा','वर्णवृत्तविशेषः।; \"मनोरमायाः प्रत्येकस्मिन् चरणे त्रयः तगणाः तथा एकः गुरुश्च भवति।\"','noun'),(31889,'','अवृत्तिः, वृत्तिवैकल्यम्','उपजीविकायाः अभावः।; \"कदाचित् अवृत्तिः मनुष्यस्य अधःपतनस्य कारणं भवति।\"','noun'),(31874,'','प्रभाकरः','नागविशेषः।; \"प्रभारकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31875,'','प्रभावः','सूर्यदेवस्य पुत्रः।; \"प्रभावस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31876,'','प्रभावः','सुग्रीवस्य मन्त्री।; \"प्रभावस्य वर्णनं रामायणे प्राप्यते।\"','noun'),(31872,'','प्रबोधिता','वर्णवृत्तविशेषः।; \"प्रबोधितायाः प्रत्येकस्मिन् चरणे क्रमेण सगणः जगणः सगणः रगणः अन्ते गुरुवर्णश्च भवति।\"','noun'),(31885,'','मनोरमा','आर्याछन्दसः सप्तपञ्चाशत्सु भेदेषु एकः।; \"मनोरमायां द्वादश गुरुवर्णाः तथा त्रयस्त्रिंशत् लघुवर्णाः भवन्ति।\"','noun'),(31883,'','मनोरमा','एका गन्धर्वी।; \"मनोरमायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31882,'','अवीरा','पतिपुत्ररहिता स्त्री।; \"सर्वे अवीरायाः सहाय्यं करोति।\"','noun'),(31881,'','अबीज, निष्कल, निर्बीज','बीजरहितः।; \"अबीजानि द्राक्षाफलानि मह्यं रोचन्ते।\"','adjective'),(31879,'','अविषा, निर्विषातृणम्','हिमालयप्रदेशे लभ्यमाना औषधीया वनस्पतिः।; \"अविषया सर्पवृश्चिकादीनां विषस्य प्रभावः दूरीभवति।\"','noun'),(31873,'','प्रभद्रकः','वर्णवृत्तविशेषः।; \"प्रभद्रके पञ्चदश वर्णाः सन्ति।\"','noun'),(31870,'','प्रभाती','प्रत्यूषप्रभासयोः वस्वोः माता।; \"प्रभात्याः वर्णनं महाभारते प्राप्यते।\"','noun'),(31871,'','प्रबालकः','यक्षविशेषः।; \"प्रबालकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31869,'','पुरुमीढः','राज्ञः पुरुमीढस्य अनुजः।; \"अजमीढस्य अनुजस्य पुरुमीढस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31868,'','सुशान्तिः','राज्ञः अजमीढस्य पुत्रः।; \"सुशान्तेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31865,'','यवीनरः','राज्ञः अजमीढस्य पुत्रः।; \"यवीनरस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31866,'','नीलनी','राज्ञः अजमीढस्य पत्नी।; \"नीलः नीलन्याः गर्भात् जातः।\"','noun'),(31867,'','नीलः','राज्ञः अजमीढस्य पुत्रः।; \"नीलन्याः गर्भात् नीलः जातः।\"','noun'),(31861,'','प्रियदर्शनः','गन्धर्वविशेषः।; \"प्रियदर्शनस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31862,'','प्रियमेधः','ऋषिविशेषः।; \"प्रियमेधस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31863,'','नीलः','नागविशेषः।; \"नीलस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31864,'','अजमीढः','राज्ञः हस्तिनः पुत्रः यः पाञ्चालदेशस्य राजा आसीत्।; \"अजमीढस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31858,'','प्रातिपीयः','ऋषिविशेषः।; \"प्रातिपीयस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31856,'','प्रातरः','नागविशेषः।; \"प्रातरस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31857,'','प्रातिपेयः','पौराणिकः राजा।; \"प्रातिपेयस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31859,'','प्रातृदः','ऋषिविशेषः।; \"प्रातृदस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31855,'','प्राज्ञः','भगवतः कल्केः अग्रजः।; \"प्राज्ञस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31851,'','प्रियंवदः','गन्धर्वविशेषः।; \"प्रियंवदस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31852,'','प्रहृतः','ऋषिविशेषः।; \"प्रहृतस्य वर्णनं पुराणेषु अस्ति।\"','noun'),(31853,'','प्रान्तः','ऋषिविशेषः।; \"प्रान्तस्य वर्णनं पुराणेषु अस्ति।\"','noun'),(31854,'','प्रांशुः','वैवस्वतमनुपुत्रः।; \"प्रांशोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31849,'','अविषय','विषयरहितः।; \"समाधौ एव साधकस्य अविषयाणि इन्द्रियाणि सन्ति।\"','adjective'),(31850,'','अवीचिः','नरकविशेषः।; \"दानधनादीनां व्यवहारे असत्यं साक्ष्यं यः करोति सः अवीचिं प्राप्नोति।\"','noun'),(31830,'','तामिस्रः','नरकविशेषः।; \"तामिस्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31831,'','अन्धतामिस्रम्','नरकविशेषः यस्मिन् विश्वासघातिनः गच्छन्ति।; \"अन्धतामिस्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31832,'','रौरवः','नरकविशेषः।; \"पुराणानुसारं रौरवः पञ्चमः नरकः।\"','noun'),(31833,'','कृमिभोजनः','नरकविशेषः।; \"कृमिभोजनस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31834,'','सन्दंशः, गर्भदंशः','मनुस्मृत्यां वर्णितः नरकविशेषः।; \"सन्दंशं प्रायः चोराः गच्छन्ति।\"','noun'),(31835,'','तप्तसूर्मिः','पुराणेषु वर्णितः नरकविशेषः।; \"बलात्कारी तप्तसूर्मिं गच्छति।\"','noun'),(31836,'','वज्रकण्टकः','नरकविशेषः।; \"वज्रकण्टकस्य वर्णनम् मनुस्मृत्याम् अपि वर्तते।\"','noun'),(31837,'','वज्रः','श्रीकृष्णस्य प्रपौत्रः।; \"वज्रः अनिरुद्धस्य पुत्रः आसीत्।\"','noun'),(31838,'','शाल्मलिः','नरकविशेषः।; \"शाल्मलेः वर्णनं मनुस्मृतौ प्राप्यते।\"','noun'),(31839,'','वैतरणीनदी','उडीसाराज्यस्य नदी।; \"वैतरणीनदी पवित्रा मन्यते।\"','noun'),(31840,'','पूयोदः','नरकविशेषः।; \"पूयोदस्य वर्णनं मनुस्मृतौ अपि प्राप्यते।\"','noun'),(31841,'','विलासः','स्त्रीणां कामार्थिनी वृत्तिः।; \"आशीषस्य सहकर्मिण्याः विलासः सफलः जातः।\"','noun'),(31842,'','प्राणरोधः','नरकविशेषः।; \"प्राणिनां घातकाः प्राणरोधं गच्छन्ति।\"','noun'),(31843,'','अविलासः','विलासस्य अभावः।; \"अविलासेन जीवनस्य मार्गः परिवर्तितः।\"','noun'),(31844,'','विशसनम्','नरकविशेषः।; \"विशसनस्य वर्णनं मनुस्मृतौ प्राप्यते।\"','noun'),(31819,'','विपर्ययः, प्रत्यवायः','एकस्मिन् वस्तुनि विशिष्टे स्थाने स्थितानां परस्पराणां स्थानग्रहणम्।; \"पिटारा इति तथा टिपारा इति च इत्येतयोः शब्दयोः वर्णानां विपर्ययः अस्ति।\"','noun'),(31847,'','नीरन्ध्र','रन्ध्ररहितम्।; \"नीरन्ध्रस्य पात्रस्य आच्छादनेन दीपः अशाम्यत्।\"','adjective'),(31845,'','लालाभक्षः','नरकविशेषः।; \"यः कामेन वशीभूत्वा सगोत्रस्त्रिभिः सह समागमं करोति सः लालाभक्षं गच्छति।\"','noun'),(31846,'','सारमेयादनम्','नरकविशेषः।; \"अपहारकाः सारमेयादनं प्राप्नोति।\"','noun'),(31829,'','अविरतिः','जैनमतानुसारेण धर्मशास्त्रम् अतिक्रम्य वर्तनम्।; \"अविरतिः निन्दनीया अस्ति।\"','noun'),(31828,'','अवियोगव्रतम्','कल्किपुराणानुसारेण तद् व्रतं यस्य आचरणेन स्त्री पतिवियोगं न अनुभवति।; \"मार्गशीर्षशुक्लतृतीयायाम् अवियोगव्रतं आचरन्त्यः महिलाः चन्द्रमसः दर्शनं कृत्वा एव दुग्धं पिबन्ति।\"','noun'),(31827,'','वियोगरहित','यस्य वियोगः न जातः।; \"वियोगरहिता कामिनी विरहिण्याः दुःखं कथं ज्ञातुं शक्नोति।\"','adjective'),(31824,'','अविपित्तकः','अम्लपित्तस्य व्याधेः निवारकं चूर्णम्।; \"अविपित्तकं जले मिश्रयित्वा पिबतु इति वैद्यः असूचयत्।\"','noun'),(31823,'','मोदः','वर्णवृत्तविशेषः।; \"मोदस्य प्रत्येकस्मिन् चरणे पञ्च भगणाः मगणः सगणः एकः गुरुवर्णश्च भवति।\"','noun'),(31820,'','अविपर्ययः','विपर्ययस्य अभावः।; \"अस्मिन् शब्दे वर्णानाम् अविपर्ययः अस्ति।\"','noun'),(31821,'','मेषहृत्','गरुडपुत्रः।; \"मेषहृतः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31822,'','आमयाविन्, मन्दाग्नि, अप्रदीप्ताग्नि, अनग्नि','यः अजीर्णेन पीडितः अस्ति।; \"आमयावी मनुष्यः दुर्बलः जातः।\"','adjective'),(31809,'','अविधानम्, अविधिः, नियमविरोधः','विधानस्य अभावः।; \"अविधानस्य स्थितौ राज्यस्य कार्याणां सञ्चालनम् असम्भवं भविष्यति।\"','noun'),(31810,'','व्याप्तिः, व्याप्तिसम्बन्धः, अविनाभावः, अविनाभावसम्बन्धः','द्वयोः वस्तुनोः वर्तमानः अनिवार्यसम्बन्धः यः कदापि न बाधते अथवा यस्मिन् द्वे वस्तुनी परस्पराभ्यां विना न वर्तेते।; \"धूमाग्नयोः व्याप्तिः अस्ति।/व्याप्तिः साध्यवदन्यस्मिन्नसम्बन्ध उदाहृतः।(भाषापरिच्छेदः)\"','noun'),(31818,'','परावर्तनम्','पुनः पूर्वस्थानग्रहणस्य क्रिया।; \"ग्रहाः प्रकारद्वयेन परावर्तनं कुर्वन्ति।\"','noun'),(31817,'','अविनीता','विनयरहिता स्त्री।; \"अविनीतया सह कः अपि वार्तालापम् अपि कर्तुं न इच्छति।\"','noun'),(31816,'','गरुडः, गरुत्मान्, तार्क्ष्यः, वैनतेयः, खगेश्वरः, नागान्तकः, विष्णुरथः, सुपर्णः, पन्नगाशनः, महावीरः, पक्षिसिंहः, उरगाशनः, शाल्मली, हरिवाहनः, अमृताहरणः, नागाशनः, शाल्मलिस्थः, खगेन्द्रः, भुजगान्तकः, तरक्षी, तार्क्ष्यनायकः','पुराणेषु वर्णितं भगवतः विष्णोः वाहनम्।; \"गरुडः भगवतः विष्णोः परमः भक्तः अस्ति।\"','noun'),(31814,'','मेधावी','च्यवनमुनिपुत्रः।; \"मेधाविनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31813,'','मेधावी','कश्यपपुत्रः।; \"मेधाविनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31811,'','मेधा','दक्षप्रजापतेः कन्या।; \"मेधायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31808,'','अवैध, नियमविरुद्ध, धर्मरोधिन्','यद् विध्यनुसारेण योग्यं नास्ति।; \"अवैधेन कार्येण हानिः भवति।\"','adjective'),(31807,'','चित्रा','षोडशभिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"चित्रायाम् आदौ त्रयः नगणाः अनन्तरं द्वौ यगणौ भवतः।\"','noun'),(31806,'','चित्रारागिणी','रागिणीविशेषः।; \"चित्रारागिणीं भैरवरागस्य सहचरीं मन्यते।\"','noun'),(31803,'','मूलीनदी','पौराणिकी नदी।; \"मूलीनद्याः वर्णनं धर्मग्रन्थेषु प्राप्यते।\"','noun'),(31805,'','चित्रा','अप्सरोविशेषः।; \"चित्रायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31804,'','अविद्यमान, असत्','यस्य सत्ता न विद्यते।; \"सूर्यः अस्तं गच्छति परम् अविद्यमानः न भवति।\"','adjective'),(31795,'','व्युषिताश्वः','पौराणिकः राजा।; \"व्युषिताश्वस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31796,'','शक्ती','छन्दोविशेषः।; \"शक्त्याः प्रत्येकस्मिन् चरणे अष्टादश मात्राः सन्ति।\"','noun'),(31797,'','शक्रवापी','नागविशेषः।; \"शक्रवापिनः वर्णनं महाभारते प्राप्यते।\"','noun'),(31798,'','शक्रजानुः','पौराणिकः वानरः।; \"शक्रजानोः वर्णनं रामायणे प्राप्यते।\"','noun'),(31799,'','अवित्करणम्','पाशुपतदर्शनानुसारं तद् कर्म यद् अन्येषां मतेन निन्दनीयं भवति।; \"अवित्करणस्य कर्ता योग्यायोग्यस्य विवेकेन रहितः भवति।\"','noun'),(31800,'','अतार्किक','यद् तार्किकं नास्ति।; \"सः अतार्किकं न्यायं न अपेक्षते।\"','adjective'),(31788,'','अविक्रयणम्','विक्रयणस्य अभावस्य अवस्था।; \"अविक्रयणस्य विषये वणिजः चिन्ताग्रस्ताः सन्ति।\"','noun'),(31789,'','अविज्ञात, अज्ञात, अपरिचित, अनागत, अविदित','यत् सम्यक् प्रकारेण न ज्ञातम्।; \"प्रकृतौ नैकानि अविज्ञातानि तत्त्वानि सन्ति।\"','adjective'),(31792,'','रौद्राश्वः','पुरुवंशीयः राजा।; \"रौद्राश्वस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31793,'','धर्मेयुः','पुरुवंशीयस्य राज्ञः रौद्राश्वस्य पुत्रः।; \"धर्मेयोः वर्णनं महाभारते प्राप्यते।\"','noun'),(31794,'','व्रतेयुः','पुरुवंशीयः राज्ञः रौद्राश्वस्य पुत्रः।; \"व्रतेयोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31786,'','वैभण्डिः','ऋषिविशेषः।; \"वैभण्डेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31787,'','अविक्रीत','यद् न विक्रीतम्।; \"वणिक् अविक्रीतानि वस्तूनि न्यूनेन मूल्येन विक्रीणाति।\"','adjective'),(31766,'','अवाक्पुष्पी','वनस्पतिविशेषः यस्य पुष्पाणि अधोमुखानि सन्ति।; \"प्राङ्गणस्य अवाक्पुष्पी शुष्का जाता।\"','noun'),(31773,'','वेदश्रुतिनदी','पौराणिकी नदी।; \"वेदश्रुतिनद्याः वर्णनं महाभारते प्राप्यते।\"','noun'),(31774,'','वेदस्मृतानदी, वेदस्मृतिनदी','पौराणिकी नदी।; \"वेदस्मृतानद्याः वर्णनं महाभारते प्राप्यते।\"','noun'),(31777,'','करयोग्य','यस्मात् करं प्राप्तुं शक्यते।; \"वणिजः प्रायः करयोग्यं धनं गोपयन्ति।\"','adjective'),(31780,'','वेदाश्वानदी','पौराणिकी नदी।; \"वेदाश्वानद्याः वर्णनं महाभारते प्राप्यते।\"','noun'),(31781,'','अवावटः','प्रथमपतिं विहाय द्वितीयात् सवर्णात् पत्युः उपपतेः वा उत्पन्नः पुत्रः।; \"अवावटः इदानीं विवाहार्थं योग्यः।\"','noun'),(31782,'','मूषिकः','पौराणिकः जनपदः।; \"मूषिकस्य उल्लेखः महाभारते प्राप्यते।\"','noun'),(31783,'','वैतण्डी','ऋषिविशेषः।; \"वैतण्डिनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31784,'','अविकारः','विकारस्य अभावः।; \"भक्त्यर्थम् अविकारः आवश्यकः।\"','noun'),(31751,'','जलबिन्दुजा','यवनालस्य शर्करा।; \"जलबिन्दुजा विरेचकम् औषधम् अस्ति।\"','noun'),(31752,'','जलबुद्बुदम्, जलबिम्बम्','जलस्य बुद्बुदः।; \"समुद्रतटे बालकः जलबुद्बुदैः क्रीडति।\"','noun'),(31753,'','शतपथब्राह्मणम्','यजुर्वेदस्य ब्राह्मणम्।; \"शतपथब्राह्मणे कर्मकाण्डस्य वर्णनम् अस्ति।\"','noun'),(31755,'','शतपथिक','शतपथब्राह्मणस्य ज्ञाता अनुयायी वा।; \"शतपथिकः ब्राह्मणः शतपथब्राह्मणम् अधिकृत्य व्याख्यानं करोति।\"','adjective'),(31756,'','शतपथिक','विविधानां मतानाम् अनुसर्ता।; \"शतपथिकः मोहनः कदापि एकस्य मार्गस्य अवलम्बनं न करोति।\"','adjective'),(31757,'','शतपर्वा','भार्गवमुनिपत्नी।; \"शतपर्वायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31758,'','वहनीय, संहार्य','वोढुं योग्यम्।; \"इदं वहनीयम् उपकरणम् अस्ति।\"','adjective'),(31759,'','पुनर्प्राप्य','यद् पुनः प्राप्तुं शक्यते।; \"पुनर्प्राप्याणि भौतिकानि वस्तूनि भ्रष्टानि चेदपि दुःखं मा कुरु।\"','adjective'),(31760,'','शतबलानदी','पौराणिकी नदी।; \"शतबलानद्याः वर्णनं महाभारते प्राप्यते।\"','noun'),(31761,'','अवहित्था','आकारगोपनस्य क्रिया।; \"तस्य अवहित्था असफला जाता।\"','noun'),(31762,'','शतबलिः','वीरः वानरः यस्य वर्णनं रामायणे प्राप्यते।; \"सीतायाः अन्वेषणार्थम् उत्तरस्यां दिशि गतायाः वानरसेनायाः नायकः शतबलिः आसीत्।\"','noun'),(31765,'','सुषेणः','वानरराजस्य वालिनः श्वशुरः।; \"सीतायाः अन्वेषणार्थं प्रतीच्यां दिशि गतायाः वानरसेनायाः नायकः सुषेणः आसीत्।\"','noun'),(31745,'','अभिघातविज्ञानम्','चिकित्साविज्ञानस्य सा शाखा यस्यां दुर्घटनायां जातानां क्षतानाम् शल्यस्य उपचाराः निहिताः सन्ति।; \"अभिघातविज्ञाने दुर्घटनाग्रस्तस्य मनुष्यस्य शल्यचिकित्सायाः विषये विस्तृतं कथनं भवति।\"','noun'),(31749,'','अवहारः','कञ्चित् निश्चितं समयं यावत् युद्धविश्रामस्य क्रिया।; \"महाभारतस्य युद्धसमये अवहारे अश्वत्थामा द्रौपदीपुत्रान् जघान।\"','noun'),(31750,'','अवहारः, शस्त्र-पातः, युद्धावसानम्','युद्धरतानाम् उभययोः पक्षयोः मध्ये युद्धस्य नियतसमये विरामविषयकः ससमयः विचारः।; \"अवहारे सत्यपि शत्रूणा आक्रमणं कृतम्।\"','noun'),(31727,'','उपाङ्गम्','मुख्यभागस्य उपभागः।; \"पुराणादीनि वेदस्य उपाङ्गानि सन्ति।\"','noun'),(31728,'','गलनम्, प्रश्चोतनम्, अवस्यन्दनम्, अनुसिञ्चनम्','सिञ्चनस्य क्रिया।; \"रसस्य गलनस्य संरोधानन्तरं तालरसेन युक्तः घटः वृक्षात् अवरुह्यते।\"','noun'),(31731,'','अवाह्य','यस्य वहनं न शक्यम्।; \"अवाह्यस्य द्रव्यसम्भारस्य कृते अस्माभिः अन्यः पुरुषः प्रयोजनीयः।\"','adjective'),(31732,'','स्कन्धमणिः','मन्त्रगण्डकविशेषः।; \"मनहरः स्कन्दमणिं धारयति।\"','noun'),(31734,'','स्कन्धः','आर्याछन्दसः भेदविशेषः।; \"इदं स्कन्धस्य उदाहरणम् अस्ति।\"','noun'),(31735,'','राष्ट्रभृत्','राज्ञः भरतस्य पुत्रः।; \"राष्ट्रभृतः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31737,'','रासः','छन्दोविशेषः।; \"रासस्य प्रत्येकस्मिन् चरणे अष्ट अष्ट षट् इत्येवं द्वाविंशतिः मात्राः सन्ति तथा अन्ते च सगणः वर्तते।\"','noun'),(31738,'','हस्तपृष्ठम्','हस्तस्य पृष्ठतमः भागः।; \"मातुः हस्तपृष्ठे रामः इति अक्षरं लिखितम् अस्ति।\"','noun'),(31739,'','काण्डः, काण्डम्','पूर्णविषययुक्तः ग्रन्थस्य भागः।; \"श्रीमद्भागवतपुराणे द्वादश काण्डाः सन्ति।\"','noun'),(31740,'','रुमण्वान्','पौराणिकः ऋषिः।; \"रुमण्वतः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31741,'','ललितः','वर्णवृत्तविशेषः।; \"ललितस्य प्रथमे चरणे क्रमेण सगणः जगणः सगणः तथा लघुवर्णः द्वितीये नगणः सगणः जगणः तथा गुरुवर्णः तृतीये नगणः सगणः सगणः तथा चतुर्थे सगणः जगणः सगणः जगणः च वर्तते।\"','noun'),(31744,'','लवली','वर्णवृत्तविशेषः।; \"लवल्याः प्रत्येकस्मिन् चरणे षोडश द्वितीये द्वादश तृतीये अष्ट तथा चतुर्थे विंशतिः वर्णाः भवन्ति।\"','noun'),(31743,'','ललितपदः','अष्टाविंशतिभिः वर्णैः युक्तः छन्दोविशेषः।; \"ललितपदे षोडशे तथा द्वादशे विश्रामः भवति।\"','noun'),(31742,'','ललितरागः','रागविशेषः।; \"ललितरागः प्रातः गीयते।\"','noun'),(31726,'','अवस्तु','वस्तुनः अभावः।; \"जीवने अवस्तुनः सम्भवः नास्ति।\"','noun'),(31724,'','शशिभागा','मुचुकुन्दस्य पुत्री।; \"शशिभागायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31725,'','अमूर्त','आकाररहितः।; \"अमूर्तानां भावानां विचाराणां च प्रकटीकरणं सरलं नास्ति।\"','adjective'),(31723,'','शशबिन्दुः','गन्धर्वस्य चित्ररथस्य पुत्रः।; \"शशबिन्दोः वर्णनं पुराणेषु अस्ति।\"','noun'),(31711,'','अवसादग्रस्त','अवसादेन पीडितः।; \"अवसादग्रस्तस्य रुग्णस्य उचिताः उपचाराः कर्तव्याः।\"','adjective'),(31721,'','शशादः','इक्ष्वाकोः राजपुत्रः।; \"शशादस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31722,'','शशिखण्डः','एकः विद्याधरः।; \"शशिखण्डस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31709,'','अवसादक, पीथिन्, शोषिन्','येन म्लानता अनुभूयते।; \"औषधसेवनान्तरं रुग्णे अवसादकानि चिह्नानि दृष्टानि।\"','adjective'),(31708,'','अवसादः, अवसन्नता, विषादः, सादः, तन्द्रा, ग्लानिः, तन्द्रिता, विषण्णता','मनसः शरीरस्य वा सा स्थितिः यस्यां किमपि कार्यं कर्तुम् अनिच्छा भवति।; \"अवसादस्य स्थितौ योगासनं लाभदायकं भवति।\"','noun'),(31703,'','सभानिष्कासित','यः सभायाः निष्कासितः।; \"सभानिष्कासितः मनुष्यः अक्रुध्यत्।\"','adjective'),(31704,'','ऐच्छिक-सेवानिवृत्तिः','सर्वकालं यावत् कार्यात् अवकाशग्रहणस्य क्रिया।; \"पिता ऐच्छिक-सेवानिवृत्तेः पश्चात् रोगार्तायाः मातुः सेवां करोति।\"','noun'),(31702,'','अवसन्नता, अवसन्नत्वम्','अवसन्नस्य अवस्था भावः वा।; \"स्वास्थ्यार्थम् अवसन्नता हानिकारिका।\"','noun'),(31692,'','विरामः','पूर्णरूपेण स्थगनस्य क्रिया।; \"इदानीम् अस्याः परियोजनायाः कृते विरामः कृतः।\"','noun'),(31690,'','अवश्रयणम्','पक्वं भोजनम् अग्निसंयोगात् दूरीकरणस्य क्रिया।; \"अन्नस्य अवश्रवणार्थं सः सहाय्यताम् अयाचत।\"','noun'),(31701,'','अवसन्न','कस्यचित् वस्तुनः भारेण यद् समनिपतति।; \"कृषकः अवसन्नां भूमिं समीकृतं करोति।\"','adjective'),(31700,'','विनाशोन्मुख','यः विनाशं प्रति गच्छति।; \"विनाशोन्मुखी प्रकृतिः भवता त्यक्तव्या।\"','adjective'),(31699,'','अवसक्थिका, खट्टा, पर्यस्तिका, परिकरः','स्वनाम्ना प्रसिद्धे आसने पृष्ठस्य जानुनोः च बन्धनार्थं प्रयुक्तं वस्त्रम्।; \"अवसक्थिकायाः ग्रन्थिः शिथिला जाता।\"','noun'),(31698,'','अवसक्थिका','आसनप्रकारः।; \"अवसक्थिकायां वस्त्रादिद्वारा पृष्ठः जानुनी च बध्यते।\"','noun'),(31696,'','सुभिक्षम्','अन्नस्य प्राचुर्यम्।; \"सुभिक्षे अपि अन्नस्य दुरुपयोगः न कर्तव्यः।\"','noun'),(31695,'','पर्णशदः','वृक्षात् पर्णानाम् अवगलनस्य क्रिया।; \"इदानीं पर्णशदः अस्ति।\"','noun'),(31680,'','अवलेहः','लेहनस्य वस्तु।; \"मध्वादयः अवलेहाः सन्ति।\"','noun'),(31681,'','अवलेहन, लेहनम्, प्रलेहनम्','अवलेहस्य क्रिया।; \"वैद्यस्य अनुसारेण अस्य औषधस्य मधुना सह अवलेहनं प्रभावकारकम् अस्ति।\"','noun'),(31682,'','आश्व','अश्वेन सम्बद्धम्।; \"अस्मिन् पशुचिकित्सालये आश्वः उपचारः भवति।\"','adjective'),(31683,'','अवलेह्य','लेढुं योग्यः।; \"मधुवाणीनामकं कसनस्य अवलेह्यं भेषजम् अस्ति।\"','adjective'),(31685,'','दर्शक','यः पश्यति।; \"क्रीडासङ्कुलं दर्शकैः जनैः पूर्णम् अस्ति।\"','adjective'),(31686,'','परिलग्न, उपमित','यद् आश्लिष्यति।; \"सः भित्तौ परिलग्नं कर्गजं विदारयति।\"','adjective'),(31678,'','कारागृहाध्यक्षः, कारागाराधिपतिः','कारागृहस्य व्यवस्थापनादीनां पर्यवेक्षणं यः करोति।; \"कारागृहाध्यक्षः कारागृहे अटित्वा कार्याणां निरीक्षणं करोति।\"','noun'),(31654,'','अवलम्बनम्','ग्रहणस्य धारणस्य वा क्रिया।; \"उत्तमस्य आचारस्य अवलम्बनेन जीवनं सफलं भवति।\"','noun'),(31655,'','संयुतः','वर्णवृत्तविशेषः।; \"संयुतस्य प्रत्येकस्मिन् चरणे सगणः जगणौ तथा एकः गुरुवर्णश्च भवति।\"','noun'),(31656,'','संयमः','ध्रूमाक्षुपुत्रः।; \"संयमः राक्षसस्य मालिनः पुत्रः आसीत्।\"','noun'),(31658,'','अवलिप्त','यत् लिप्यते।; \"भस्मेन अवलिप्तान् पात्रान् सा प्रक्षालयति।\"','adjective'),(31661,'','खादित, उपभुक्त, अशित, आलीढ, परिभुक्त','यद् खाद्यते।; \"पक्षिभिः खादितैः फलैः वाटिका आच्छादिता।\"','adjective'),(31662,'','कर्षित','यस्य कर्षणं कृतम्।; \"माता अग्रजस्य कर्षिते व्रणे लेपम् अनक्ति।\"','adjective'),(31663,'','अवलुण्ठित','लुठति इति।; \"माता अवलुण्ठितं बालकं स्नानार्थं नयति।\"','adjective'),(31664,'','शयित','शयनं क्रियमाणः।; \"परिचारिका शयितं रुग्णम् उत्थापयति।\"','adjective'),(31667,'','कार्ष्णिः','गन्धर्वविशेषः।; \"कार्ष्णेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31670,'','कामरूपः','षड्विंशतिभिः मात्राभिः युक्तः छन्दोविशेषः।; \"कामरूपे सप्तमे नवमे दशमे च विरामः भवति तथा अन्ते गुरुः लघुश्च भवति।\"','noun'),(31671,'','कामिनी, कामवती','मैथुनाभिलाषिणी स्त्री।; \"तस्याः सात्विकेन वार्तालापेन कामिनी शान्ता जाता।\"','noun'),(31672,'','कान्तः','मात्रिकः छन्दोविशेषः।; \"कान्तायां षण्णां मात्राणां चत्वारः पदाः सन्ति।\"','noun'),(31677,'','कारापालः','कारागृहस्य रक्षकः।; \"कृष्णजन्मान्तरं सर्वे कारापालाः निद्रिताः जाताः।\"','noun'),(31650,'','दण्डी','धृतराष्ट्रपुत्रः।; \"दण्डिनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31648,'','गीता','षड्विंशतिभिः मात्राभिः युक्तः मात्रिकः छन्दोविशेषः।; \"गीतायां चतुर्दशमात्रायां द्वादशमात्रायां च विरामः भवति तथा अन्ते लघुवर्णः गुरुवर्णश्च भवति।\"','noun'),(31652,'','अवलम्बकः','छन्दोविशेषः।; \"किं भवान् अवलम्बकस्य विषये माम् अधिकं ज्ञापयति।\"','noun'),(31651,'','अवर्धमान','यस्य वृद्धिः न भवति।; \"अयम् अवर्धमानः उद्योगः आसीत्।\"','adjective'),(31647,'','कुण्डलः','द्वाविंशतेः मात्राणां छन्दोविशेषः।; \"कुण्डले द्वादशे दशमे च स्थाने विरामः वर्तते तथा अन्ते द्वौ गुरुवर्णौ भवतः।\"','noun'),(31644,'','वृन्दारकः','धृतराष्ट्रपुत्रः।; \"वृन्दारकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31645,'','वैराटः','धृतराष्ट्रपुत्रः।; \"वैराटस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31627,'','दुर्भिक्षम्','अन्नस्य अभावः।; \"दुर्भिक्षे सः उच्छिष्टम् एव खादित्वा जीवितः आसीत्।\"','noun'),(31634,'','उन्मूलनीय, उच्चाटनीय','उन्मूलनं कर्तुं योग्यः।; \"कृषकः क्षेत्रात् उन्मूलनीयान् क्षुपान् उन्मूलयति।\"','adjective'),(31635,'','उन्मूलित, उत्पाटित, विपाटित, उद्वृढ, समुच्छिन्न','यस्य उन्मूलनं कृतम्।; \"उन्मूलिताः वृक्षाः पुनः आरोपिताः।\"','adjective'),(31641,'','वर्गरहित, वर्गहीन','वर्गेण विना।; \"नैकैः वर्गैः युक्ते अस्मिन् देशे वर्गरहितस्य समाजस्य कल्पना अपि न क्रियते।\"','adjective'),(31643,'','सेनापतिः','धृतराष्ट्रपुत्रः।; \"सेनापतेः वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31637,'','अवरोहः','काव्यालङ्कारविशेषः यस्मिन् कस्यापि वस्तुनः रूपस्य गुणस्य च उद्धरणं प्रदर्श्यते।; \"इमाः पङ्क्तयः अवरोहस्य उत्तमम् उदाहरणम् अस्ति।\"','noun'),(31636,'','अवरोपित','यद् अवरुह्यते।; \"कृषकः अवरोपितं तालरसम् आस्वादयति।\"','adjective'),(31623,'','निकृष्टतम','अत्यधिकं निकृष्टम्।; \"मनुस्मृत्यनुसारेण मांसभक्षणे मीनस्य भक्षणं निकृष्टतमं मन्यते।\"','adjective'),(31620,'','अलोलुपः','धृतराष्ट्रस्य पुत्रः।; \"अलोलुपस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31622,'','अल्मबुषः','राक्षसविशेषः यस्य वर्णनं महाभारते प्राप्यते।; \"महाभारतस्य युद्धे अलम्बुषः कौरवाणां सहायकः आसीत्।\"','noun'),(31617,'','विकटः','धृतराष्ट्रपुत्रः।; \"विकटस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31618,'','अभयः','धृतराष्ट्रपुत्रः।; \"अभयस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31616,'','वंशवज्रा','अर्धसमवर्णवृत्तं यत् इन्द्रवज्रायाः तथा च इन्द्रवंशायाः योगेन निर्मितम्।; \"वंशवज्रायाः प्रथमे तृतीये च चरणे तगणः तगणः जगणः तथा च द्वौ गुरुवर्णौ स्तः।\"','noun'),(31615,'','आवर्तः','रत्नप्रकारः।; \"दैवज्ञः तम् आवर्तस्य मुद्रां धारयितुम् असूचयत्।\"','noun'),(31614,'','क्राथः','पौराणिकः राजा।; \"क्राथं राहुग्रहस्य अवतारं मन्यते।\"','noun'),(31610,'','माया','मयदानवस्य पुत्री।; \"मायायाः विवाहः विश्रवसा सह जातः।\"','noun'),(31611,'','माया','इन्द्रवज्रायाः उपभेदः यः इन्द्रवज्रायाः तथा च उपेन्द्रवज्रायाः योगेन निर्मीयते।; \"मायायाः द्वितीये तृतीये च चरणे प्रथमः लघुवर्णः भवति।\"','noun'),(31612,'','माया','वर्णवृत्तविशेषः।; \"मायायाः प्रत्येकस्मिन् चरणे क्रमेण भगणः तगणः मगणः भगणः एकः गुरुवर्णश्च अस्ति।\"','noun'),(31613,'','क्राथः','धृतराष्ट्रपुत्रः।; \"क्राथस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31603,'','अवरम्','गजस्य अपरसक्थि।; \"अवरस्य आघातेन गजः वेदनया पीडितः अस्ति।\"','noun'),(31604,'','अवरज','हीने वंशे जातः।; \"अवरजः रोहिदासः कर्मभिः श्रेष्ठः जातः।\"','adjective'),(31605,'','उग्रसेनः','राज्ञः परीक्षितस्य पुत्रः।; \"उग्रसेनस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31606,'','उग्रसेनः','धृतराष्ट्रपुत्रः।; \"उग्रसेनस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31608,'','दुष्कर्णः','धृतराष्ट्रपुत्रः।; \"दुष्कर्णस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31609,'','इन्द्रवज्रा','वर्णवृत्तविशेषः।; \"इन्द्रवज्रायां तगणः तगणः जगणः रगणः तथा च गुरुवर्णाः भवन्ति।\"','noun'),(31597,'','करखा','सप्तविंशतिभिः मात्राभिः युक्तः छन्दोविशेषः।; \"करखायाः अन्ते यगणः भवति।\"','noun'),(31600,'','अवयवः','न्यायशास्त्रानुसारेण वाक्यस्य पञ्चसु अङ्गेषु प्रत्येकः।; \"प्रतिज्ञाहेतूदाहरणोपनयननिगमनाः पञ्च अवयवाः सन्ति।\"','noun'),(31592,'','करपृष्ठम्, अवहस्तः, हस्तपृष्ठम्','हस्तस्य पृष्ठभागः।; \"तस्य करपृष्ठे व्रणः जातः।\"','noun'),(31593,'','अवमन्थः','रोगविशेषः यस्मिन् उपस्थे गण्डः भवति।; \"अवमन्थस्य कारणात् रुग्णः चलनसमये पीडाम् अनुभवति।\"','noun'),(31586,'','महोदरः','धृतराष्ट्रपुत्रः।; \"महोदरस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31588,'','कबूची','धृतराष्ट्रस्य पुत्रविशेषः।; \"कबूचिनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31590,'','कनरश्यामरागः','सङ्कररागविशेषः।; \"सङ्गीतज्ञः कनरश्यामरागं गायति।\"','noun'),(31591,'','सङ्गीतप्रिय','यस्मै सङ्गीतं रोचते।; \"सभागृहं सङ्गीतप्रियैः जनैः पूरितम् अस्ति।\"','adjective'),(31579,'','अवपाटिका','पुरुषेषु जायमानः लिङ्गाग्रचर्मणः रोगविशेषः।; \"सः रुग्णः अवपाटिकया पीडितः अस्ति।\"','noun'),(31580,'','भुजस्तम्भः','रोगविशेषः यस्मिन् हस्तः अकार्यशीलः भवति।; \"भुजस्तम्भस्य कारणात् पितामही हस्तः उपरि कर्तुं न शक्नोति।\"','noun'),(31581,'','हावः','स्त्रीणां श्रुङ्गारभावजाः क्रियाः।; \"साहित्यशास्त्रे एकादश हावाः सन्ति।\"','noun'),(31583,'','बोधक','यः बोधं कारयति।; \"किं भवता पञ्चतन्त्रस्य बोधिकाः कथाः पठिताः।\"','adjective'),(31564,'','कोशलः','सरयूतटस्थः प्रदेशः।; \"प्राचीनस्य भारतदेशस्य षोडशेषु महाजनपदेषु कोशलः आसीत्।\"','noun'),(31565,'','कोशलरागः','सङ्गीतशास्त्रे वर्तमानः रागविशेषः।; \"शिक्षकः अस्मान् कोशलरागं पाठयति।\"','noun'),(31566,'','कोशलजातिः','कोशलदेशे वर्तमाना जातिविशेषः।; \"कोशलजातिः वीरतायै प्रसिद्धा अस्ति।\"','noun'),(31567,'','कोशपालः','कोशस्य रक्षकः।; \"कोशगृहस्थितस्य धनस्य चौर्यकर्मणः आरोपः कोशपाले अस्ति।\"','noun'),(31570,'','नाकुलः','नकुलनाम्नः पाण्डवस्य वंशजः।; \"अस्मिन् पुस्तके नाकुलस्य अपि कथाः सन्ति।\"','noun'),(31571,'','पेषणम्, संचूर्णनम्, सम्पेषणम्','चूर्णीकरणस्य क्रिया।; \"विशिष्टानां पाषाणानां पेषणेन वज्रचूर्णं प्राप्यते।\"','noun'),(31573,'','कोकिलः','छन्दोविशेषः।; \"कोकिले शतानि वर्णाः तथा द्विपञ्चाशताधिकैकशतमात्राः भवन्ति।\"','noun'),(31574,'','सुविनीत, महाशालीन','अत्यधिकः नम्रः।; \"तस्य सुविनीतस्य मनुष्यस्य सर्वे सम्मानं कुर्वन्ति।\"','adjective'),(31560,'','पण्डितकः','धृतराष्ट्रपुत्रः।; \"पण्डितकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31562,'','अनुधावनम्','कमपि अनुसृत्य धावनस्य क्रिया।; \"भवतः अनुधावनेन कः अपि लाभः न भविष्यति।\"','noun'),(31563,'','अवधिज्ञानम्','जैनधर्मानुसारेण दृष्टिपथात् अपि उत्तरत्र वर्तमानानां वस्तूनां प्रत्यक्षज्ञानम्।; \"अवधिज्ञानात् पूर्वं सामान्यायाः सत्तायाः भ्रमः जायते।\"','noun'),(31557,'','अवधः','वधस्य अभावः।; \"तस्य कार्यकाले राज्ये अवधः आसीत्।\"','noun'),(31558,'','प्रमार्थी','धृतराष्ट्रस्य पुत्रविशेषः।; \"प्रमार्थिनः वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31559,'','विरजाः','धृतराष्ट्रस्य पुत्रविशेषः।; \"विरजसः वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31542,'','साधर्म्यम्','समानस्य धर्मस्य अवस्था।; \"साधर्म्ये सत्यपि अस्माकं धार्मिकेषु विचारेषु भिन्नता अस्ति।\"','noun'),(31534,'','विजयः','विष्णोः अनुचरः।; \"ब्रह्मणः मानसपुत्राः राक्षसरूपं धारयित्वा पृथिव्यां जनिं लभताम् इत्येवंरूपेण जयाय विजयाय च अशपत्।\"','noun'),(31535,'','नैयायिकः, न्यायवेत्ता, न्यायाध्येता','यः न्यायं तर्कशास्त्रं वा विशेषम् अधीते।; \"नैयायिकस्य तर्केण सर्वे जोषं स्थिताः।\"','noun'),(31556,'','पाशिन्','धृतराष्ट्रपुत्रः।; \"पाशिनः वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31555,'','हिङ्गु, सहस्त्रवेधि, जतुकम्, वाल्हिकम्, वाल्हीकम्, रामठम्, जन्तुघ्नम्, वाल्ही, गृहिणी, मधुरा, सूपधूपनम्, जतु, केशरम्, उग्रगन्धम्, भूतारिः, जन्तुनाशनम्, सूपाङ्गम्, उग्रवीर्यम्, अगूढगन्धम्, भेदनम्','शतपुष्पाविशेषः।; \"हिङ्गुनाम्ना एव द्रव्यम् उपलभ्यते यस्य उपयोगः व्यञ्जनरूपेण औषधरूपेण वा क्रियते।\"','noun'),(31554,'','अवदीर्ण, आयुत, गालित, द्रवमाण, द्रावित, द्रुत, निर्गलित','यद् द्रवरूपे परिवर्तितम्।; \"माता अवदीर्णेन घृतेन मिष्टान्नं पचति।\"','adjective'),(31552,'','पृथक्करणम्','बहुषु वस्तुषु प्रत्येकस्य वस्तुनः सम्भेदं कृत्वा स्थापनस्य क्रिया।; \"माता वस्त्राणां पृथक्करणं करोति।\"','noun'),(31551,'','विशसनम्, व्यवच्छेदः, विदारणः','छेदनस्य क्रिया।; \"एते वैद्याः शवस्य विशसनस्य तथा च तस्य परीक्षणस्य कार्यं कुर्वन्ति।\"','noun'),(31546,'','नागरथः','धृतराष्ट्रपुत्रः।; \"नागरथस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31547,'','सुजातः','धृतराष्ट्रपुत्रः।; \"सुजातस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31544,'','अनुर्यायी','धृतराष्ट्रस्य पुत्रः।; \"अनुर्यायिनः वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31545,'','जयत्सेनः','धृतराष्ट्रपुत्रः।; \"जयत्सेनस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31541,'','सहधर्मिन्, अपृथग्धर्मशील','समानस्य धर्मस्य।; \"मोहनसोहनौ सहधर्मिणौ स्तः।\"','adjective'),(31540,'','तार्किक','तर्कसम्बन्धी।; \"तस्य तार्किकानां वचनानां सत्यत्वम् अद्य प्रतीयते।\"','adjective'),(31539,'','भूगर्भस्थ','भूगर्भे वर्तमानम्।; \"नैकानि प्राकृतिकानि वस्तूनि भूगर्भस्थानि सन्ति।\"','adjective'),(31538,'','वक्रोक्तिः, काकूक्तिः','अन्यस्यान्यार्थं सूचयन्ती उक्तिः।; \"भूरि चिन्तनेन तस्य वक्रोक्तेः अर्थः मया ज्ञातः।\"','noun'),(31537,'','वक्रोक्तिः','अप्रत्यक्षरूपेण कथनम्।; \"तस्य वक्रोक्तिं ज्ञात्वा अहं क्रोधिता जाता।\"','noun'),(31533,'','जयः','विष्णोः अनुचरः।; \"ब्रह्मणः मानसपुत्राः राक्षसरूपं धारयित्वा पृथिव्यां जनिं लभताम् इत्येवंरूपेण जयाय विजयाय च अशपत्।\"','noun'),(31530,'','सुहस्तः','धृतराष्ट्रपुत्रः।; \"सुहस्तस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31532,'','उपचित्रः','वर्णवृत्तविशेषः।; \"उपचित्रस्य विषमेषु चरणेषु त्रयः सगणाः लघुः गुरुश्च भवति तथा समचरणेषु त्रयः भगणाः द्वौ गुरू च भवतः।\"','noun'),(31524,'','विमलाद्रिः, शत्रुञ्जयः','भारतदेशस्थितः पर्वतविशेषः।; \"विमलाद्रिः काठियावाडराज्ये अस्ति।\"','noun'),(31525,'','शत्रुसहः','धृतराष्ट्रपुत्रः।; \"शत्रुसहस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31526,'','महाबाहुः','धृतराष्ट्रपुत्रः।; \"महाबाहोः वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31527,'','अयोभुजः','धृतराष्ट्रपुत्रः।; \"अयोभुजस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31528,'','श्रुतान्तः','धृतराष्ट्रपुत्रः।; \"श्रुतान्तस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31529,'','उत्तरार्धम्','कालस्य वस्तुनः वा द्वयोः अर्धभागयोः अपरः भागः।; \"ब्रासीलदेशे अष्टादशतमस्य शतकस्य उत्तरार्धे एकोनविंशतिततमस्य शतकस्य उत्तरार्धे मोदिन्या इति नामकं प्रेमगीतं लोकप्रियम् आसीत्।\"','noun'),(31523,'','शत्रुञ्जयः','धृतराष्ट्रपुत्रः।; \"शत्रुञ्जयस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31514,'','वास्तुवित्, वास्तुविद्, स्थपतिः','वास्तुशास्त्रस्य ज्ञाता।; \"तेजोमहालयस्य भित्तिषु मुख्यस्य वास्तुविदः नाम नैकेषु स्थानेषु अभिलिखितम् अस्ति।\"','noun'),(31515,'','सुकेतुः','कश्यपवंशीयः राजा।; \"सुकेतोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31516,'','धर्मकेतुः','राज्ञः सुकेतोः पुत्रः।; \"धर्मकेतोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31517,'','जयः','धृतराष्ट्रपुत्रः।; \"जयस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31518,'','रौद्रकर्मा','धृतराष्ट्रपुत्रः।; \"रौद्रकर्मणः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31519,'','दुर्जयः','धृतराष्ट्रपुत्रः।; \"दुर्जयस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31520,'','दुःशलः','धृतराष्ट्रपुत्रः।; \"दुःशलस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31521,'','दुःसहः','धृतराष्ट्रपुत्रः।; \"दुःसहस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31522,'','चारुचित्रः','धृतराष्ट्रपुत्रः।; \"चारुचित्रस्य वर्णनं धार्मिकेषु ग्रन्थेषु प्राप्यते।\"','noun'),(31513,'','वर्णफलकः, वर्णफलकम्','यस्मिन् फलके चित्रं निर्माय तस्मिन् चित्रे वर्णं पूरयते।; \"चित्रकारः वर्णफलके चित्रम् लिखति।\"','noun'),(31511,'','लोककला','विशिष्टस्य प्रदेशस्य परम्परया आगता कला।; \"भारतदेशे नैकाः लोककलाः सन्ति।\"','noun'),(31512,'','चित्रायुधः','धृतराष्ट्रपुत्रः।; \"चित्रायुधस्य वर्णनं धार्मिकेषु ग्रन्थेषु अस्ति।\"','noun'),(31510,'','आदिलशाहः','बीजापूरस्य यवनः शासकः।; \"आदिलशाहस्य अस्वास्थस्य समये शिवाजीमहाराजः बीजापूरगमनस्य निश्चयम् अकरोत्।\"','noun'),(31507,'','उपचित्रः','धृतराष्ट्रपुत्रः।; \"उपचित्रस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31505,'','आजादहिन्दसेना','भारतदेशस्य स्वातन्त्र्यार्थं सुभाषचन्द्रबोसमहोदयैः निर्मिता सेना।; \"भारतदेशस्य स्वतन्त्रतायाम् आजादहिन्दसेनायाः महत्वपूर्णं योगदानम् आसीत्।\"','noun'),(31504,'','द्रोणपुष्पी, कुम्भयोनिः, कुरुम्बिका, चित्राक्षुपः, कुरुम्बा, सुपुष्पा, चित्रपत्रिका, द्रोणा, फलेपुष्पा','श्वेतपुष्पयुक्तः औषधीयः क्षुपः।; \"द्रोणपुष्प्याः उपयोगः अर्शादीनां व्याधीनां निवारणे भवति।\"','noun'),(31502,'','स्कम्भः, स्तम्भः, अवष्टम्भः, यष्टिः, धारिका','आधारार्थं कस्यापि वस्तुनः अधः स्थाप्यमाना काचित् रचना।; \"अयं सेतुः सप्तसु स्तम्भेषु आधारितः अस्ति।\"','noun'),(31503,'','भाषासमूहः','भाषाविज्ञानस्य अनुसारेण कृतः भाषाणां विभागः।; \"हिन्दीभाषा हिन्द-आर्य इति भाषासमूहे अन्तर्भूता अस्ति।\"','noun'),(31498,'','रत्नासुरः','एकः राक्षसः।; \"रत्नासुरस्य वधाय ब्रह्माविष्णुशिवाः ज्योतिबारूपम् अधारयन्।\"','noun'),(31499,'','कलरीचिकित्सा','केरलराज्यस्य चिकित्साप्रकारः।; \"कलरीचिकित्सायाः उपचारकेन्द्रम् इदम्।\"','noun'),(31500,'','ग्राममः, ग्रामम-उत्सवः','केरलराज्ये निर्वर्त्यमानः उत्सवः।; \"ग्राममस्य आयोजनं जानेवरीमासस्य 14 दिनाङ्कतः 23 दिनाङ्कपर्यन्तं भवति।\"','noun'),(31490,'','अनुविन्दः','धृतराष्ट्रपुत्रः।; \"अनुविन्दस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31491,'','अनाधृष्टिः','धृतराष्ट्रपुत्रः।; \"अनाधृष्टेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31492,'','धनुर्गहः','धृतराष्ट्रस्य पुत्रः।; \"धनुर्गहस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31493,'','विवित्सुः','धृतराष्ट्रपुत्रः।; \"विवित्सोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31494,'','निषङ्गी','धृतराष्ट्रपुत्रः।; \"निषङ्गिनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31495,'','प्ररोपित, विरोपित, संरोपित','यस्य आरोपणं कृतम्।; \"सर्वे प्ररोपिताः क्षुपाः उत्तमाः सन्ति।\"','adjective'),(31496,'','सन्ततिः','दक्षकन्या।; \"सन्ततेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31497,'','सन्तः','छन्दोविशेषः।; \"सन्ते एकविंशतिः मात्राः सन्ति।\"','noun'),(31489,'','अनुकरणम्, अनुक्रिया, अनुकृतिः, अनुवृत्तिः, अनुकर्म','कस्यचित् वर्तनं सम्भाषणशैलीं वा सम्यक् अवलोक्य तदनुसारम् एव कृतम् आचरणम्।; \"ज्येष्ठानाम् अनुकरणं न योग्यम्।\"','noun'),(31487,'','अवतारणम्','उपरिष्टात् अधोदिशम् आहरणम्।; \"धूमिकायाः कारणात् विमानस्य अवतारणे काठिन्यम् अनुभूयते।\"','noun'),(31488,'','कुण्डधारः','धृतराष्ट्रपुत्रः।; \"कुण्डधारस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31485,'','अवतीर्ण','उपरिष्टात् अधोदिशम् आगतः।; \"इदानीम् एव अवतीर्णात् विमानयानात् यात्रिणः बहिः आगच्छन्ति।\"','adjective'),(31486,'','कृत्या','तन्त्रानुसारेण एका राक्षसी।; \"तान्त्रिकाः कार्यसिद्ध्यर्थम् अनुष्ठानद्वारा कृत्याम् आहूय शत्रोः नाशं कुर्वन्ति।\"','noun'),(31477,'','दुर्मदः','धृतराष्ट्रपुत्रः।; \"दुर्मदस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31478,'','कुण्डभेदी','धृतराष्ट्रपुत्रः।; \"कुण्डभेदिनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31484,'','उद्धृत','अन्यस्मात् स्थानात् कस्यचित् भागस्य उद्धरणरूपेण ग्रहणम्।(लेखः वचनं वा); \"रामायणात् उद्धृताः इमाः पङ्क्तयः।\"','adjective'),(31472,'','अग्रायुधः','धृतराष्ट्रपुत्रः।; \"अग्रायुधस्य वर्णनं महाभारते अस्ति।\"','noun'),(31473,'','सुवर्चाः','धृतराष्ट्रस्य पुत्रः।; \"सुवर्चसः वर्णनं महाभारते प्राप्यते।\"','noun'),(31474,'','चित्राक्षः','धृतराष्ट्रपुत्रः।; \"चित्राक्षस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31456,'','सुषेणः','परीक्षितस्य पुत्रः।; \"सुषेणस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31414,'','सुभटः, महारथः, महाभटः, अतिरथः, महावीरः','महान् वीरः।; \"रावणस्य सेनायां नैके सुभटाः आसन्।\"','noun'),(31415,'','गुम्फित, रचित, ग्रथित','यद् सूत्रे रच्यते।; \"सा प्रतिदिनं भगवतः मूर्त्यै गुम्फितं पुष्पहारम् अर्पयति।\"','adjective'),(31416,'','अवगीत','यद् असाधुरित्या गीतम्।; \"तस्य अवगीतं गानं श्रुत्वा सर्वे पलायिताः।\"','adjective'),(31422,'','अवघर्षणम्, अभिघर्षणम्, अवमर्दनम्, आघर्षणम्, घर्षणम्, निघर्षणम्','आघर्षस्य क्रिया।; \"ऊषा पात्रस्य दग्धं भागं अवघर्षणेन मार्ष्टुं प्रयतते।\"','noun'),(31423,'','कुसुमस्तबकः','छन्दोविशेषः।; \"कुसुमस्तबकस्य प्रत्येकस्मिन् चरणे नव नवाधिकाः वा सगणाः भवन्ति।\"','noun'),(31424,'','कुसुमितलतावेल्लिका','वर्णवृत्तविशेषः।; \"कुसुमितलतावेल्लिकायाम् अष्टादश वर्णाः सन्ति।\"','noun'),(31470,'','तिरस्कृतः','तन्त्रोक्तः मन्त्रविशेषः।; \"सः तिरस्कृतस्य साधनां करोति।\"','noun'),(31471,'','चित्रबाणः','धृतराष्ट्रपुत्रः।; \"चित्रबाणस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31468,'','आच्छादक','येन आच्छाद्यते।; \"शवस्य आच्छादकानि वस्त्राणि प्रायः श्वेतवर्णीयानि भवन्ति।\"','adjective'),(31469,'','तिरस्करिणी','सा विद्या यया मनुष्यः अदृश्यः भवितुम् अर्हति।; \"शिक्षकः तिरस्करिणीम् अपि जानाति।\"','noun'),(31465,'','दुर्विरोचनः','धृतराष्ट्रपुत्रः।; \"दुर्विरोचनस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31466,'','अवज्ञेय','यस्य अवज्ञा क्रियते।; \"अवज्ञेयः अधिकारी उद्विग्नः भवति।\"','adjective'),(31467,'','आदित्यकेतुः','धृतराष्ट्रपुत्रः।; \"आदित्यकेतोः वर्णनं महाभारते अस्ति।\"','noun'),(31464,'','अवज्ञा','अलङ्कारविशेषः।; \"अवज्ञायां एकस्य वस्तुनः गुणेन दोषेण वा अन्यस्य वस्तुनः गुणस्य दोषस्य वा अकथनं वर्णितम् अस्ति।\"','noun'),(31461,'','उपनन्दः','धृतराष्ट्रपुत्रः।; \"उपनन्दस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31462,'','भूरिबलः','धृतराष्ट्रपुत्रः।; \"भूरिबलस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31463,'','कनकध्वजः','धृतराष्ट्रपुत्रः।; \"कृत्यानाम्नां विद्यां प्राप्य पाण्डवान् जिघांसिता कनकध्वजः स्वयमेव एव तया विद्यया उपहतः।\"','noun'),(31460,'','सुनामः','धृतराष्ट्रपुत्रः।; \"सुनामस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31459,'','सुलोचनः','धृतराष्ट्रपुत्रः।; \"सुलोचनस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31458,'','अवच्छेद्य','अवच्छेत्तुं योग्यः।; \"अवच्छेद्यानां वस्तूनां पुनः परीक्षणं करोतु।\"','adjective'),(31457,'','सुषेणः','कृष्णस्य पुत्रः।; \"सुषेणस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31452,'','सुषेणः','धृतराष्ट्रपुत्रः।; \"सुषेणस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31453,'','अवच्छेदक','द्वे वस्तुनी येन पृथक्क्रियते।; \"अस्य भवनस्य अवच्छेदिकां भित्तिम् अवलङ्घ्य चोरः प्राविशत्।\"','adjective'),(31454,'','निर्णायक, निश्चायक, अवच्छेदक, अवधारक','कस्यापि विषस्य निश्चितिः येन भवति।; \"अपराधस्य निर्णायकानि प्रमाणानि एतानि।\"','adjective'),(31455,'','सुषेणः','द्वितीयस्य मनोः पुत्रः।; \"सुषेणस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31449,'','दुर्विषहः','धृतराष्ट्रपुत्रः।; \"दुर्विषहस्य वर्णनं महाभारते अस्ति।\"','noun'),(31450,'','जलसन्धः','धृतराष्ट्रपुत्रः।; \"जलसन्धस्य वर्णनं महाभारते अस्ति।\"','noun'),(31448,'','दुर्विमोचनः','धृतराष्ट्रपुत्रः।; \"दुर्विमोचनस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31447,'','श्रुतवर्मा','धृतराष्ट्रपुत्रः।; \"श्रुतवर्मणः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31444,'','अवच्छिन्न, परिच्छिन्न, असक्त','यद् पृथक्क्रियते।; \"कर्मकरः यन्त्रस्य अवच्छिन्नान् भागान् योजयति।\"','adjective'),(31445,'','दुष्प्रधर्षः','धृतराष्ट्रपुत्रः।; \"दुष्प्रधर्षस्य वर्णनं महाभारते अस्ति।\"','noun'),(31434,'','यतिरागः','शालकरागभेदः।; \"गायकः यतिरागं गायति।\"','noun'),(31435,'','यतिः','मृदङ्गस्य प्रबन्धविशेषः।; \"यतिम् अनुसृत्य नर्तकः नृत्यति।\"','noun'),(31437,'','जलहरणम्','द्वात्रिंशद्भिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"जलहरणे षोडशे वर्णे यतिः भवति।\"','noun'),(31438,'','जलोद्धतिगतिः','द्वादशवर्णैः युक्तः वर्णवृत्तविशेषः।; \"जलोद्धतिगतेः प्रत्येकस्मिन् चरणे जगणः सगणः जगणः सगणः च भवति।\"','noun'),(31442,'','अवच्छिन्न','यत् अवच्छिद्यते।; \"युद्धभूमौ सर्वत्र शत्रूणाम् अवच्छिन्नानि शरीराणि आसन्।\"','adjective'),(31441,'','दुष्प्रहर्षः','धृतराष्ट्रपुत्रः।; \"दुष्प्रहर्षस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31439,'','जह्नुः','एकः राजर्षिः येन गङ्गां पीत्वा अनन्तरं पुनः कर्णाभ्यां स्राविता।; \"जह्नोः कारणात् एव गङ्गायाः नाम जाह्नवी इति अस्ति।\"','noun'),(31433,'','यतिः','छन्दोविशेषः।; \"केषाञ्चन मतानुसारेण यतौ पञ्च गुरुमात्राः द्विचत्वारिंशत्याधिकैकशतलघुमात्राः च सन्ति केचन पञ्च गुरुमात्राः षट्त्रिंशत्याधिकैकशतलघुमात्राः च सन्ति इति मन्यन्ते।\"','noun'),(31430,'','यतिः','ब्रह्मणः पुत्रः।; \"यतेः उल्लेखः भागवते अस्ति।\"','noun'),(31431,'','जम्बुमाली','एकः राक्षसः।; \"जम्बुमालिनः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31432,'','यतिः','नहुषस्य पुत्रः।; \"यतेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31427,'','विच्छेदनम्','छित्त्वा विलगीकरणस्य क्रिया।; \"रोगस्य प्रसारणम् अवरोद्धुं पादस्य विच्छेदनम् आवश्यकम् अस्ति।\"','noun'),(31428,'','यतिः','छन्दःशास्त्रानुसारेण काव्यगानसमये चरणेषु वर्तमानं तत् स्थानं यत्र लयं रक्षितुं किञ्चित् कालं विश्राम्यते।; \"काव्यगानसमये यतौ अवधानं ददातु।\"','noun'),(31429,'','गरुडरुतम्','वर्णवृत्तविशेषः।; \"गरुडरुते षोडश वर्णाः भवन्ति।\"','noun'),(31425,'','चयनम्','पुष्पादीनां ग्रहणस्य क्रिया।; \"माता पूजायै पुष्पाणां चयनं करोति।\"','noun'),(31426,'','विच्छेदः','कस्यापि शृङ्खलितस्य वस्तुनः मध्ये एव खण्डस्य अवस्था भावः वा।; \"विच्छेदं रक्षितुं सर्वे प्रयतन्ते।\"','noun'),(31404,'','प्रतिष्ठा','वर्णवृत्तविशेषः।; \"प्रतिष्ठायां चत्वारः वर्णाः भवन्ति।\"','noun'),(31405,'','प्रमाणी','अष्टभिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"प्रमाण्याः प्रत्येकस्मिन् चरणे जगणः रगणः तथा एकः गुरुवर्णः च भवति।\"','noun'),(31406,'','प्रमाथः','शिवस्य गणः।; \"प्रमाथस्य वर्णनं स्कन्दपुराणे प्राप्यते।\"','noun'),(31407,'','प्रमाथः','स्कन्दस्य अनुचरः।; \"प्रमाथस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31408,'','प्रमाथी','रामस्य सेनायाम् उपस्थितः वानरः।; \"प्रमाथिनः वर्णनं रामायणे प्राप्यते।\"','noun'),(31387,'','अनुसंधा, अनुसन्धा, विमृश्, वीक्ष्, अवेक्ष्, परीक्ष्, समीक्ष्','वृत्तस्य वा विषयस्य वा मूलकारणानाम् अन्वेषणानुकूलः व्यापारः।; \"आरक्षकाः तथ्यान् अनुसन्दधति।\"','verb'),(31381,'','शम्भुः','वर्णवृत्तविशेषः।; \"शम्भोः प्रत्येकस्मिन् चरणे सगणः तगणः यगणः भगणः मगणौ तथा गुरुश्च अस्ति।\"','noun'),(31383,'','क्षत्रिया, क्षत्रियाणी','क्षत्रियस्त्री।; \"भारतीये इतिहासे नैकाभिः क्षत्रियाभिः वीरतापूर्णं कार्यं कृतम्।\"','noun'),(31384,'','क्षत्रियी, क्षत्रियाणी','क्षत्रियस्य पत्नी।; \"ऐतिहासिकेन प्रमाणेन नैकाः क्षत्रय्यः सहगामिन्यः आसन् इति ज्ञायते।\"','noun'),(31411,'','प्रमादिनी','हिन्दोलरागस्य रागिणी।; \"सङ्गीतज्ञः प्रमादिनीं पाठयति।\"','noun'),(31413,'','प्रमिताक्षरा','वर्णवृत्तविशेषः।; \"प्रमिताक्षरायाः प्रत्येकस्मिन् चरणे द्वादश वर्णाः भवन्ति।\"','noun'),(31409,'','प्रमाथी','खरनाम्नः राक्षसस्य सहचरः।; \"प्रमाथिनः वर्णनं रामायणे प्राप्यते।\"','noun'),(31402,'','प्रतिबाहुः','अक्रूरस्य भ्राता।; \"प्रतिबाहोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31399,'','पोतकः','पौराणिकः नागः।; \"पोतकस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31400,'','पुष्करसद्','ऋषिविशेषः।; \"पुष्करसदः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31401,'','ग्रन्थनम्, अवगुम्फनम्','सूत्रे तन्तौ वा सूत्रणस्य क्रिया।; \"पुष्पाणां ग्रन्थनं समाप्य सीमा पूजायाः स्थालीम् अलङ्करोति।\"','noun'),(31395,'','यौधेयाः','प्राचीने भारते वर्तमानः वीराणां जातिविशेषः।; \"यौधेयानां निवासः इदानीन्तनीये हरियाणाराज्यस्य समीपे आसीत्।\"','noun'),(31397,'','रथोद्धता','एकादशभिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"रथोद्धतायाः प्रत्येकस्मिन् चरणे क्रमेण रगणः नगणः रगणः तथा लघुः गुरुश्च भवतः।\"','noun'),(31394,'','अवगुण्ठनम्, अवगुण्ठितमुद्रा','स्त्रीमुखाच्छादकवस्त्रं तर्जन्या गृहित्वा निर्मिता आकर्षिका मुद्रा।; \"अस्मिन् चित्रे राधायाः अवगुण्ठनं मनोहारी अस्ति।\"','noun'),(31393,'','यौधेयः','युधिष्ठिरस्य पुत्रः।; \"यौधेयस्य वर्णनं महाभारते अस्ति।\"','noun'),(31392,'','आच्छादनम्, समाच्छादनम्, संवरणम्, गुहनम्, निगुहनम्, आवरणम्, अपवारणम्','सहेतुकगोपनस्य क्रिया।; \"स्वभावस्य आच्छादनं सरलं नास्ति।\"','noun'),(31388,'','युद्धाजित्','कृष्णपुत्रः।; \"युद्धाजितः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31389,'','युद्धाजित्','राज्ञः क्रोष्टोः पुत्रः।; \"युद्धाजितः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31390,'','क्रोष्टुः','यदुवंशीयः राजा।; \"क्रोष्टोः वर्णनं पुराणेषु अस्ति।\"','noun'),(31391,'','अवगाहित','यस्मिन् स्नानं क्रियते।; \"अवगाहितं जलं दूषितम् अस्ति इति आशङ्का वर्तते।\"','adjective'),(31379,'','अवगाहनम्','जले निमज्य स्नानस्य क्रिया।; \"ऋषयः प्रातःकाले अवगाहनस्य कृते नदीं गच्छन्ति स्म।\"','noun'),(31373,'','शङ्खचूडः','एकः यक्षः।; \"शङ्खचूडस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31374,'','शङ्खचूडः','कुबेरस्य सखा।; \"शङ्खचूडः कुबेरस्य अनुचरः अपि आसीत्।\"','noun'),(31375,'','वज्रनाभः','दानवविशेषः यः सुमेरुपर्वतस्य गुहायां तपम् आचरत्।; \"वज्रनाभस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31378,'','वज्रनाभः','कृष्णस्य प्रपौत्रः।; \"अर्जुनः वज्रनाभाय व्रजक्षेत्रस्य राज्यम् अददात्।\"','noun'),(31370,'','शङ्कुशिरः','असुरविशेषः।; \"शङ्कुशिरस्य वर्णनं भागवते प्राप्यते।\"','noun'),(31371,'','शङ्खः','छप्पयछन्दसः एकसप्ततौ भेदेषु एकः।; \"शङ्खे द्विपञ्चाशताधिकैशतमात्राः अथवा नवचत्वारिंशत् वर्णाः भवन्ति।\"','noun'),(31369,'','शङ्कुमती','वैदिकवर्णवृत्तविशेषः।; \"शङ्कुमत्याः प्रथमे चरणे पञ्च तथा अन्येषु चरणेषु षडधिकाः न्यूनाः वा वर्णाः सन्ति।\"','noun'),(31367,'','शङ्करः','मात्रिकः छन्दोविशेषः।; \"शङ्करस्य प्रत्येकस्मिन् चरणे षोडशे तथा दशमे स्थाने विश्रामेण सह आहत्य षड्विंशतिः मात्राः सन्ति अन्ते लघुः गुरुश्च भवति।\"','noun'),(31366,'','गणित, अङ्कित','यस्य गणनं कृतम्।; \"गणितेषु जनेषु केचन जनाः बहिः अगच्छन्।\"','adjective'),(31363,'','अवक्षेपणम्','मिथ्या दोषारोपणस्य क्रिया।; \"अवक्षेपणात् रक्षितव्यम्।\"','noun'),(31361,'','संयुक्तता, संयुक्तत्वम्, सम्बद्धता, सम्बद्धत्वम्','संयुक्तस्य अवस्था भावः वा।; \"संयुक्तता भारतीयानां कुटुम्बानां वैशिष्ट्यम् अस्ति।\"','noun'),(31353,'','अवगीतम्, अवक्वणः','अशोभनं गीतम्।; \"एतादृशम् अवगीतं कस्मै रोचते।\"','noun'),(31356,'','चिन्तामणिः','कल्पितरत्नविशेषः।; \"चिन्तामणिः इच्छापूर्तिं करोति इति मन्यते।\"','noun'),(31357,'','अधःपातनम्','रासायनिकी प्रक्रिया।; \"अधःपातनेन द्रव्ये घनं वस्तु विभज्यते।\"','noun'),(31360,'','अवक्षुत','यस्मिन् छिक्कितम्।; \"अवक्षुतं खाद्यं न खादितव्यम्।\"','adjective'),(31343,'','बलाकः','राक्षसविशेषः।; \"बलाकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31344,'','नीचकेश','लघुकेशयुक्तः।; \"नीचकेशः भिक्षुः तस्य दृष्टिपथे आगतः।\"','adjective'),(31345,'','बलाकः','पुरोः पुत्रः।; \"बलाकस्य वर्णनं भागवते प्राप्यते।\"','noun'),(31346,'','बलाकाश्वः','पौराणिकः राजा।; \"बलाकाश्वस्य वर्णनं हरिवंशपुराणे प्राप्यते।\"','noun'),(31347,'','बलाहकः','नागविशेषः।; \"बलाहकस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31348,'','बल्वलः','दैत्यविशेषः।; \"बल्वलः इल्वलनाम्नः दैत्यस्य पुत्रः आसीत्।\"','noun'),(31349,'','कतः','पौराणिकः ऋषिः।; \"कतः कात्यस्य पिता आसीत्।\"','noun'),(31350,'','कात्यः','पौराणिकः ऋषिः।; \"महर्षिः कात्यायनः कात्यस्य वंशजः आसीत्।\"','noun'),(31351,'','अवक्रोशः','कर्णकटुः ध्वनिः।; \"काकशब्दः इव अवक्रोशः कस्मै अपि न रोचते।\"','noun'),(31352,'','आक्रोशनम्, अवभर्त्सनम्, आक्रोशः, तर्जनम्','भर्त्सनस्य क्रिया।; \"इदानीं तस्य आक्रोशनेन किं लाभः।\"','noun'),(31342,'','बला','दक्षकन्या।; \"बलायाः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31330,'','अवकीर्णिन्','यस्य ब्रह्मचर्यं खण्डितम्।; \"अवकीर्णी ब्रह्मचारी आश्रमात् निष्कासितः।\"','adjective'),(31331,'','समाहरणम्, सङ्ग्रहणम्, चयनम्, अवचयः','एकत्रीकरणस्य क्रिया।; \"वणिक् आजीवनं धनस्य समाहरणे एव व्यस्तः भवति।\"','noun'),(31332,'','अवकृष्ट, बहिष्कृत, दूरीकृत, निष्कासित, निःसारित','यद् दूरे क्रियते।; \"अवकृष्टानां मनुष्याणाम् इयं संस्था अस्ति।\"','adjective'),(31333,'','अवकृष्ट','अधोभागे आनीतम्।; \"प्रक्षालनस्य अनन्तरम् अवकृष्टानि वस्तूनि यथास्थाने स्थापितानि।\"','adjective'),(31337,'','पत्रिकाख्यः','कर्पूरभेदः।; \"महेशः पत्रिकाख्यं प्रज्वालयति।\"','noun'),(31338,'','पथ्या','आर्याछन्दसः भेदः।; \"पथ्यायाः अपि नैके उपभेदाः सन्ति।\"','noun'),(31340,'','वैराटी','भैरवरागस्य रागिणी।; \"वैराट्याः गानसमयः अस्ति दिने पञ्चविंशतिदण्डतः अष्टाविंशतिदण्डपर्यन्तम्।\"','noun'),(31312,'','हरी','क्रोधावशकश्यपयोः दशसु कन्यासु एका।; \"हर्याः एव सिंहवानरादीनाम् उत्पत्तिः मन्यते।\"','noun'),(31307,'','आकर्षणम्','कस्यचित् पदार्थस्य बलात् कर्षणस्य क्रिया।; \"सागरतरङ्गाणाम् आकर्षणं नौजीविकं भीषयते।\"','noun'),(31308,'','अवकर्षणम्','अधोभागे कर्षणस्य क्रिया।; \"बरमुदात्रिकोण इति स्थानस्य अवकर्षणम् अद्यापि रहस्यमयम् अस्ति।\"','noun'),(31329,'','चूर्णित, चूर्णीकृत','यस्य चूर्णं कृतम्।; \"चूर्णिते औषधे मधु योजयित्वा खादितुं वैद्यः असूचयत्।\"','adjective'),(31327,'','उत्कीर्ण, आस्तीर्ण, अवकीर्ण','सर्वत्र विस्तृणोति इति।; \"सूर्यस्य उत्कीर्णैः किरणैः निसर्गस्य शोभा वर्धते।\"','adjective'),(31326,'','पटेलजातिः','वणिजा सम्बद्धः जातिविशेषः।; \"महाराष्ट्रियः अपि सः पुत्रस्य विवाहः पटेलजातौ अकरोत्।\"','noun'),(31325,'','आवपनम्, निर्वपणम्, प्रकिरणम्, कीर्णिः, आवापः, निर्वापः','सर्वत्र व्याप्तेः क्रिया भावः वा।; \"सूर्यप्रकाशस्य आवपनेन भूमिः शोभते।\"','noun'),(31322,'','अवकाशः','छन्दोविशेषः।; \"इयं रचना अवकाशस्य उत्तमम् उदाहरणम् अस्ति।\"','noun'),(31320,'','रोधः','जलम् अवरोद्धुं दृढतायै वा भित्तेः समीपे व्यवस्थितं इष्टिकामृत्तिकादीनां समुदायः।; \"जलप्लावने रोधः अपि अवासीदत्।\"','noun'),(31318,'','सङ्कल्पनाकोशः','सङ्कल्पनायाम् आधारितः शब्दकोशः।; \"हिन्दीशब्दतन्त्रः सङ्कल्पनाकोशः अस्ति।\"','noun'),(31317,'','अवकलित, अवलोकित','यस्य अवलोकनं कृतम्।; \"इदम् अवकलितं यन्त्रम् अस्ति।\"','adjective'),(31316,'','अवबोधनम्','बोधस्य क्रिया।; \"नूतनानाम् आविष्काराणाम् अवबोधनम् आवश्यकम् अस्ति।\"','noun'),(31315,'','मृदङ्गकः','वर्णवृत्तविशेषः।; \"मृदङ्गके पञ्चदश वर्णाः सन्ति।\"','noun'),(31314,'','मृगेन्द्रमुखः','वर्णवृत्तविशेषः।; \"मृगेन्द्रमुखे त्रयोदशवर्णाः सन्ति।\"','noun'),(31313,'','हरिः','चतुर्दशभिः वर्णैः युक्तः वर्णवृत्तविशेषः।; \"हरेः प्रत्येकस्मिन् चरणे जगणः, रगणः, जगणः, रगणः अन्ते लघु गुरुश्च भवति।\"','noun'),(31309,'','मृगी','वर्णवृत्तविशेषः।; \"मृग्याः प्रत्येकस्मिन् चरणे रगणः भवति।\"','noun'),(31310,'','मृगी','कश्यपपुत्री या क्रोधवशायाः गर्भात् उत्पन्ना।; \"मृग्याः विवाहः पुलहमुनिना सह जातः।\"','noun'),(31311,'','क्रोधवशा','कश्यपस्य पत्नी यस्य दश कन्याः आसन्।; \"क्रोधवशायाः गर्भात् आदौ नैकै जन्तवः जाताः।\"','noun'),(31301,'','वंशहीन, निर्वंश','यस्य वंशः अवशिष्टः नास्ति।; \"वंशहीनः राजा अतीव दुःखी आसीत्।\"','adjective'),(31302,'','नीचकुलम्, दुष्कुलम्','निम्नं कुलम्।; \"नीचकुले जाते अपि सः साधुः अस्ति।\"','noun'),(31303,'','मुक्तिमतीनदी','पौराणिकी नदी।; \"मुक्तिमतीनद्याः वर्णनं महाभारते प्राप्यते।\"','noun'),(31304,'','मुदावसुः','प्रजापतिपुत्रः।; \"मुदावसोः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31295,'','न्यूनीकरणम्, अल्पीकरणम्','कस्यापि वस्तुनः क्षयस्य क्रिया।; \"आरक्षकाः अपराधानां न्यूनीकरणम् इच्छन्ति।\"','noun'),(31296,'','उपनाम','वंशस्य नाम।; \"प्रपत्रस्य अस्मिन् भागे स्वस्य उपनाम लिखन्तु।\"','noun'),(31305,'','मुष्टिकः','कंसस्य राजसभायाः मल्लः।; \"कृष्णबलरामाभ्यां सह जाते मल्लयुद्धे मुष्टिकः मृतः जातः।\"','noun'),(31299,'','अल्पवयस्कता, अल्पवयस्कत्वम्, कुमारता, कुमारत्वम्','अल्पवयस्कस्य अवस्था।; \"अल्पवयस्कतायां जातः विवाहः विध्यनुसारेण अपराधः अस्ति।\"','noun'),(31293,'','अल्पसंख्यकवर्गः','अल्पसङ्ख्यायुक्तानां जनानां समूहः।; \"मध्यप्रदेशराज्यस्य सर्वकारेण जैनवर्गः अपि अल्पसंख्यकवर्गे समाविष्टः कृतः।\"','noun'),(31294,'','अल्पिष्ठ, न्यूनतम','न्यूनातिन्यूनम्।; \"अल्पिष्ठं धनं प्राप्य अपि सः सन्तुष्टः अस्ति।\"','adjective'),(31289,'','काव्यः','रोलाछन्दसः प्रकारः।; \"काव्ये प्रत्येकस्मिन् चरणे एकादशमी मात्रा लघ्वी भवति।\"','noun'),(31290,'','अल्पमध्यम','कृशया कट्या युक्तः।; \"अल्पमध्यमः नर्तकः सर्वेषां मनांसि आकर्षति।\"','adjective'),(31291,'','कासारः','दण्डकवृत्तभेदः।; \"कासारे विंशतिः रगणाः भवन्ति।\"','noun'),(31292,'','कुजम्भः','प्रल्हादस्य पुत्रविशेषः।; \"कुजम्भस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31288,'','कावेरी','सम्पूर्णयाः जातेः रागिणीविशेषः।; \"सङ्गीतज्ञः कावेरीं गायति।\"','noun'),(31255,'','भद्रकायः','कृष्णस्य पुत्रः।; \"भद्रकायस्य वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31256,'','अलोकः','जगतः अभावः।; \"अलोके सर्वम् अदृश्यं भवति।\"','noun'),(31257,'','अलोकः','जैनशास्त्रानुसारेण तद् स्थानं यत्र केवलम् आकाशम् एव भवति नान्यद् किमपि।; \"मोक्षप्रापकः एव अलोकं गच्छति।\"','noun'),(31258,'','अलोला','छन्दोविशेषः।; \"अलोलायाः प्रत्येकस्मिन् चरणे चतुर्दश वर्णाः सन्ति।\"','noun'),(31260,'','कालरात्रिः','प्रलयस्य रात्रिः।; \"धर्मग्रन्थानुसारेण कालरात्रौ जगतः नाशः भविष्यति।\"','noun'),(31261,'','सर्पगन्धा, सर्पाक्षी, गन्धनाकुली, गण्डाली, नाडीकलापकः','औषधीया वनस्पतिः यस्य क्षेत्रेषु आरोपणं क्रियते।; \"सर्पगन्धायाः मूलस्य उपयोगः ह्रद्रोगादीनां निवारणे क्रियते।\"','noun'),(31265,'','चन्द्रशूरः','सर्षपः इव एका औषधीया वनस्पतिः यद् 30-60 सेन्टीमीटरं यावत् उन्नतः भवति।; \"चन्द्रशूरस्य आरोपणम् आक्टोबरमासे नोव्हेम्बरमासे च क्रियते।\"','noun'),(31254,'','भद्रकः','वर्णवृत्तविशेषः।; \"भद्रकस्य प्रत्येकस्मिन् चरणे क्रमेण भगणः रगणः नगणः रगणः तथा गुरुश्च भवति।\"','noun'),(31287,'','बृहद्रथः','देवराजस्य पुत्रः।; \"बृहद्रथस्य उल्लेखः धर्मग्रन्थेषु प्राप्यते।\"','noun'),(31285,'','अल्पज्ञता','ज्ञानस्य अपूर्णता।; \"अल्पज्ञतायाः पश्चात्तापस्य अपेक्षया भवान् ज्ञानवर्धनस्य प्रयत्नं करोतु।\"','noun'),(31286,'','काहला','एका अप्सराः।; \"काहलायाः वर्णनं पुराणेषु अस्ति।\"','noun'),(31284,'','अल्पज्ञता','अल्पज्ञस्य अवस्था भावः वा।; \"सः स्वस्य अल्पज्ञतायाः कृते अपि अभिमानी अस्ति।\"','noun'),(31283,'','कालीयम्','कृष्णचन्दनकाष्ठम्।; \"सीमा कालीयं श्लक्ष्णीकरोति।\"','noun'),(31282,'','अबुध, अपण्डित','यः सर्वं न जानाति।; \"अबुधाय मनुष्याय एतादृशं कूटं प्रश्नं पृच्छनेन कः लाभः भविष्यति।\"','adjective'),(31281,'','अल्पज्ञ, अल्पधी, भौततुल्य, भौतप्राय, जड, मूर्ख','न्यूनया धारणया युक्तः।; \"अल्पज्ञान् छात्रान् पाठयितुम् अध्यापकैः अधिकाः प्रयत्नाः कर्तव्याः।\"','adjective'),(31279,'','अल्पज्ञ','यः अल्पं जानाति।; \"अल्पज्ञः मनुष्यः पण्डितमूर्खयोः मध्यः भवति।\"','adjective'),(31276,'','कालीनदी','भारतीयानदी।; \"कालीनदी हिमालयात् प्रभवति।\"','noun'),(31275,'','अल्पच्छद','अल्पवस्त्राच्छादितः।; \"अल्पच्छदं भिक्षुकं दृष्ट्वा सः दुःखी जातः।\"','adjective'),(31271,'',' ',' ; \"\"','noun'),(31274,'','आधेय','न्यासरूपेण स्थापयितुं योग्यः।; \"तस्य समीपे इदानीम् आधेयं धनं नास्ति।\"','adjective'),(31270,'','अल्पः','अलङ्कारविशेषः।; \"अल्पे आधेयस्य अपेक्षया आधारस्य अल्पता प्रदर्श्यते।\"','noun'),(31268,'','वत्सनाभः, विषम्, उग्रम्, महौषधम्, गरलम्, मारणम्, स्तौङ्ककम्','विषवृक्षविशेषः।; \"वत्सनाभस्य मूलेभ्यः विषं प्राप्यते।\"','noun'),(31266,'','अलोहित, रक्तहीन, विशोणित','रक्तरहितः।; \"मृत्योः पश्चात् इमम् अलोहितं शरीरं ज्वाल्यते भूमौ निधीयते वा।\"','adjective'),(31249,'','बाह्यकर्णः','नागविशेषः।; \"बाह्यकर्णस्य वर्णनं महाभारते प्राप्यते।\"','noun'),(31250,'','बृहत्कीर्तिः','एकः राक्षसः।; \"बृहत्कीर्तेः वर्णनं पुराणेषु प्राप्यते।\"','noun'),(31251,'','बृहद्रथः','शतधन्वनः पुत्रः।; \"बृहद्रथस्य वर्णनं पुराणेषु अस्ति।\"','noun'),(31252,'','शतधन्वा','कृष्णस्य समकालीनः पौराणिकः वीरः।; \"शतधन्वा कृष्णेन हतः।\"','noun'),(31253,'','भक्तिः','वर्णवृत्तविशेषः।; \"भक्तेः प्रत्येकस्मिन् चरणे तगणः यगणः तथा अन्ते द्वौ गुरू भवतः।\"','noun'),(31240,'','सन्नतिः','दक्षकन्या।; \"सन्नतेः विवाहः क्रतुना सह जातः।\"','noun'),(31241,'','अलवणाशिन्','येन लवणं न खाद्यते।; \"सः अलवणाशी उपासकः अस्ति।\"','adjective'),(31242,'','अ