INSERT INTO `tbl_all_synset` VALUES (2478,'','अजगरः, शयुः, वाहसः','सर्पविशेषः बृहत्सर्पः।; \"भारते विविधप्रकारकाः अजगराः सन्ति।\"','noun'),(2493,'','गुप्त, अज्ञात, प्रच्छन्न, आच्छन्न, गूढ, पिहित','यद् न ज्ञातम्।; \"तेन अस्मिन् विषये गुप्ता वार्ता कथिता।\"','adjective'),(2491,'','तटवासिन्','यः तटे वसति।; \"जलप्लवात् नैके तटवासिनः जनाः गृहहीनाः अभवन्।\"','adjective'),(2492,'','अमापित, अपरिमापित','यः न मापितः।; \"अमापितस्य क्षेत्रस्य विभाजनस्य विषये बहुविवादः जातः।\"','adjective'),(2485,'','शारीरिक-पीडा, शारीरिक क्लेशः','शरीरे जाता पीडा।; \"मोहनः शारीरिक-पीडया त्रस्तः अस्ति।\"','noun'),(2486,'','अजा, छागी, पयस्विनी, भीरुः, मेध्या, गलेस्तनी, छागिका, मज्जा, सर्वभक्ष्या, गलस्तनी, चुलुम्पा, सज्जा, मुखविलुण्ठिका','पशुविशेषः, या अप्रशस्ता खरतुल्यनादा प्रदीप्तपुच्छा कुनखा विवर्णा निकृत्तकर्णा द्विपमस्तका तथा च  यस्याः दुग्धं पानार्थंम् उपयुज्यते ।; \"अजायाः दुग्धं शीतलं मधुरं च।\"','noun'),(2487,'','मेषा, उरभा, मेढ्रा, मेण्डा, मेण्ढा, मेठा, भेडा, सम्फाला','स्त्रीत्वविशिष्टः मेषः।; \"मेषा बालकं दुग्धं पाययति।\"','noun'),(2488,'','माया','तत् किमपि यद् वस्तुतः नास्ति किन्तु सत्यं भासते।; \"वयं सर्वे सांसारिकया मायया अवरुद्धाः।\"','noun'),(2489,'','अज्ञातः, अज्ञाता, अज्ञातम्, अविदितः, अविदिता, अविदितम्, अननुभूतः, अननुभूता, अननुभूतम्, अपरिचितः, अपरिचितम्, अपरिचिता, अगोचरः, अगोचरा, अगोचरम्','यद् न ज्ञातम्।; \"एषः अज्ञातः प्रदेशः अस्ति।\"','adjective'),(2490,'','अज्ञात, अनभिज्ञ, अनागत, अविज्ञात, अविदित','यः ज्ञातः नास्ति।; \"यात्राकाले अज्ञातेन व्यक्तिना दत्तं किमपि खाद्यं न स्वीकरणीयम्।\"','adjective'),(2473,'','प्रासङ्गिक,  प्रासङ्गिहः, प्रसङ्गोपात्तः','प्रसङ्गसम्बन्धी।; \"साम्प्रदायिकी समानता इति सद्यकालीनः एकः प्रासङ्गिकः विषयः अभवत्।\"','adjective'),(2474,'','अस्पृश्य','स्प्रष्टुम् अयोग्यः।; \"शिक्षायाः अभावात् ग्रामेषु अधुना अपि कांश्चन वर्णान् अस्पृश्यान् मन्यन्ते।\"','adjective'),(2471,'','अनुमुद्, अभिनन्द्, रोच्, प्रशस्, अनुमन्, अनुरज्','मनसि आनन्दोत्पादनात्मकः व्यापारः।; \"अनेन दृश्येन मम मनः अनुमोदते। \"','verb'),(2472,'','कृष्णः, नारायणः, दामोदरः, हृषीकेशः, केशवः, माधवः, अच्युतः, गोविन्दः, जनार्दनः, गिरिधरः, दैवकीनन्दनः, माधवः, शौरिः, अहिजितः, योगीश्वरः, वंशीधरः, वासुदेवः, कंसारातिः, वनमाली, पुराणपुरुषः, मुकुन्दः, कंसारिः, वासुः, मुरलीधरः, जगदीशः, गदाधरः, नन्दात्मजः, गोपालः, नन्दनन्दनः, यादवः, पूतनारिः, मथुरेशः, द्वारकेशः, पाण्डवायनः, देवकीसूनुः, गोपेन्द्रः, गोवर्धनधरः, यदुनाथः, चक्रपाणिः, चतुर्भुजः, त्रिविक्रमः, पुण्डरीकाक्षः, गरुडध्वजः, पीताम्बरः, विश्वम्भरः, विश्वरुजः, सनातनः, विभुः, कान्तः, पुरुषः, प्रभुः, जितामित्रः, सहस्रवदनः','यदुवंशीय वसुदेवस्य पुत्रः यः विष्णोः अवतारः इति मन्यते।; \"सूरदासः कृष्णस्य परमो भक्तः।\"','noun'),(2470,'','शुभ्, भूष्, अलङ्कृ, विभूष्, समलंकृ, अतिभूष्, अभिभूष्, मण्ड्, मङ्क्, संशुभ्, उपशुभ्','मण्डनानुकूलः व्यापारः।; \"हिमालयः भारतदेशस्य मुकुट इव शोभते। /विद्या विनयेन शोभते।\"','verb'),(2469,'','निस्तोदनम्, संतोदी','तोदनेन या पीडा भवति।; \"सर्वस्मिन् शरीरे निस्तोदनं भवति।\"','noun'),(2468,'','रुच्, अभिरुच्, स्वद्, जुष्, प्री','आस्वादनानुकूलः व्यापारः।; \"मह्यम् इदं कार्यं नैव रोचते।\"','verb'),(2467,'','द्युतिः, आभा, दीप्तिः, रत्नद्युतिः, रत्नदीप्तिः, रत्नप्रभा, रत्नकिरणः, प्रकाशः','रत्नस्य शोभा प्रकाशः च।; \"सः चौरः तस्य सुवर्णकारस्य आपणाद् प्राप्तानाम् रत्नानां द्युतिं दृष्ट्वा हर्षभरितः अभवत्।\"','noun'),(2466,'','रहस्यगोपनम्','रहस्यस्य गुप्ततायाः क्रिया भावो वा।; \"ग्रामप्रमुखस्य आदेशः अस्ति यद् अस्मिन् विषये रहस्यगोपनम् एव योग्यम्।\"','noun'),(2465,'','विशुद्धता, शुद्धता, विशुद्धिः','विशुद्धस्य अवस्था भावो वा।; \"सुवर्णस्य विशुद्धतां अवलोकनाद् एव जानाति सुवर्णकारः। / हेम्नः संलक्ष्यते ह्यग्नौ विशुद्धिः श्यामिकापि वा।\"','noun'),(2464,'','माहात्म्यम्, महात्मता, महिमा, महत्वम्, उदारता, औदार्यम्, चित्तोदारता, महेच्छा, महानुभावः','महात्मनो भावः।; \"हिन्दीसाहित्ये प्रेमचन्दस्य माहात्म्यं न अन्यथा कर्तुं शक्यते।\"','noun'),(2463,'','उत्तमता, उत्कृष्टता','उत्तमस्य अवस्था भावो वा।; \"चरित्रस्य उत्तमता सर्वश्रेष्ठा।\"','noun'),(2462,'','षडङ्गुल','सः यस्य करजे षड् अङ्गुलयः सन्ति।\"; \"बालकः वारं वारं षडङ्गुलस्य पुरुषस्य अङ्गुलीः गणयति।\"','adjective'),(2461,'','सद्गुणिन्, गुणवत्, गुणशालिन्','सद्गुणैः युक्तः।; \"गुणवान् व्यक्तिः प्रशंसनीयः भवति।\"','adjective'),(2460,'','विनोदक, हृदयङ्गम, मनोरञ्जक, चित्तवेधक, मनोहर, हृदयग्राहिन्, विनोदद, अनुरागजनक, कौतुकवत्','यद् विनोदेन परिपूर्णम्।; \"तस्य पार्श्वे नैकाः विनोदकाः ग्रन्थाः सन्ति।\"','adjective'),(2459,'','मृत','यस्य उपयोगिताक्रियाशीलतादयः अधुना नष्टाः।; \"काश्चन प्राचीनाः भाषाः अद्य मृताः सन्ति ।\"','adjective'),(2458,'','महात्मा, विश्रुतः, महायशस्कः, प्रसिद्धः, उत्कृष्टः, श्रेष्ठः, महाभागः, प्रतिष्ठः','उत्तम-स्वभाव-युक्तः।; \"मोहनदास करमचन्द गान्धी महात्मा आसन्।\"','adjective'),(2457,'','प्रिय, अभिमत, अभीष्ट, अभीप्सित, अर्य, परिप्री, दयित, मनःप्रिय, मनःप्रणीत, मनस्कान्त','यद् रोचते।; \"एतत् मम अतीव प्रियं पुस्तकम् अस्ति। \"','adjective'),(2455,'','अभीष्ट','यद् इष्टम् अस्ति।; \"एतद् मम अभीष्टं भोजनम्।\"','adjective'),(2456,'','प्रशंसनीय, प्रशंस्य, श्लाघ्य, श्लाघनीय, स्तुत्य, अभिनन्दनीय','यः प्रशंसितुं योग्यः।; \"ये अन्यान् कृते जीवन्ति ते प्रशंसनीयाः सन्ति।\"','adjective'),(2454,'','गुणवत्, गुणयुक्त, गुणान्वित','यद् गुणैः युक्तम्।; \"यद्यपि गुणवन्ति उपकरणानि महार्हाणि तथापि तानि दीर्घकालपर्यन्तं उपायोक्तुं शक्यन्ते।\"','adjective'),(2453,'','हितकारिन्, हितकारक, इष्टकर, हितकर, कल्याणकारिन्, मङ्गलकारिन्, कल्याणप्रद, मङ्गलकारक, मङ्गलदायक, मङ्गलप्रद, शङ्कर','यः कल्याणं करोति।; \"सज्जनानाम् उपदेशः हितकारी अस्ति।\"','adjective'),(2452,'','कलात्मक, कलामय','यद् कलया युक्तम् अस्ति।; \"भवता आलेखितं चित्रं कलात्मकम्।\"','adjective'),(2451,'','उपयोगिन्, उपकारक, उपकारिन्, सोपकार, महोपकार, प्रयोगिन्, सार्थक, सार्थ, अर्थकर, अर्थद, अर्थवत्','उपयुक्तद्रव्यादिः।; \"बालकानां कृते एषः ग्रन्थः उपयोगी अस्ति।\"','adjective'),(2449,'','विनोदनपूर्ण, आमोद-प्रमोदपूर्ण, आमोद-प्रमोदात्मक','यः विनोदनेन परिपूर्णः।; \"एतद् स्थानं  विनोदनपूर्णम् अस्ति।\"','adjective'),(2450,'','विकसित, उन्नत','यस्य वर्धनं जातं वा उन्नतिः जाता।; \"अमेरिका विकसितं राष्ट्रम्।\"','adjective'),(2446,'','अचेतनता, अचेतना, चेतनाहीनता, चेतनाशून्यता','चेतनाहीनस्य अवस्था भावो वा।; \"कुष्ठेन पीडिते अङ्गे अचेतनता आगच्छति।\"','noun'),(2447,'','अचेतनता, चेतनहीनता, चेतनाहीनता','अचेतनस्य अवस्था भावो वा।; \"जडपदार्थेषु अचेतनता दृश्यते।\"','noun'),(2448,'','स्थापनीय, स्थाप्य, संस्थापनीय, निधेय','स्थापयितुं योग्यम्।; \"एषा नग्नमूर्तिः स्थापनीया न वर्तते।\"','adjective'),(2445,'','सङ्कल्पपूर्वकम्, निश्चयपूर्वकम्','सङ्कल्पेन सह।; \"सङ्कल्पपूर्वकम् कथयामि एतद् कार्यं कृत्वा एव विरमामि।\"','adverb'),(2441,'','मूर्च्छित, निश्चेष्ट, अचेष्ट, प्रमुग्ध, अचेत, चेतनाहीन, चेतनाशुन्य, अचेतन, चेतनारहित','किञ्चित् कालार्थे यस्य चेतना लुप्ता।; \"सुहृदस्य मृत्योः वार्ता श्रुत्वा सः मुर्च्छितः। \"','adjective'),(2442,'','निर्जीव, निष्प्राण','यस्मिन् जीवनं नास्ति।; \"निर्जीवेषु वस्तुषु संवेदना नास्ति।\"','adjective'),(2443,'','अचेतन, जड','यस्मिन् चेतना नास्ति।; \"मोहनः अचेतनानां पदार्थानां अध्ययनं करोति।\"','adjective'),(2444,'','लक्ष्यवेधिन्, लक्ष्यानुगामिन्','यः लक्ष्यं प्राप्नोति।; \"व्याधस्य शरव्यकं लक्ष्यवेधि आसीत्।\"','adjective'),(2440,'','प्रमत्तवत्, अनवधान, प्रमद्वर','अवधानहीनः।; \"प्रमत्तवान् व्यक्तिः व्यसनैः ग्रसति।\"','adjective'),(2439,'','शान्त, प्रशान्त, निरुद्विग्न, अविकल, अव्याकुल, अव्यग्र, विश्रब्ध, निराकुल, अनाकुल, शमित, विश्रान्त, शान्तचेतस्','यद् उद्विग्नं नास्ति।; \"मोहनस्य जीवनं शान्तम् अस्ति।\"','adjective'),(2437,'','अचिन्तित','यद्विषयकं चिन्तनं न कृतम्।; \"एषा अचिन्तिता समस्या।\"','adjective'),(2438,'','उपेक्षित','ज्ञात्वा अकृतावधानम्।; \"एषः ग्रामः शासनेन उपेक्षितः अस्ति।\"','adjective'),(2435,'','निश्चिन्त, चिन्ताहीन, चिन्तामुक्त, निःशङ्क','यस्य कापि चिन्ता नास्ति।; \"यावत् कन्यायाः विवाहः न भवति तावत् पितरौ निश्चिन्तौ न भवतः।\"','adjective'),(2436,'','अविचारणीय, अचिंतनीय, अविचार्य','यस्य चिन्तनं न आवश्यकम्।; \"एषा वार्ता अविचारणीया।/आज्ञा गुरूणां हि अविचारणीया।\"','adjective'),(2421,'','धीर, अनाकुल, धीरप्रशान्त, धीरशान्त, धृतात्मन्, धृतिमत्','अविचलचित्तः।; \"विपत्तौ अपि धैर्यस्य अत्यागात् धीरः अन्ततो गत्वा यशस्वी भवति।\"','adjective'),(2422,'','स्थिर, अचल, अविचल, निश्चल','यस्मिन् गतिः नास्ति।; \"पर्वताः स्थिराः सन्ति।\"','adjective'),(2423,'','संयमिन्, नियमिन्, संयमशील','यः संयमेन जीवति।; \"संयमी व्याधिग्रस्तः न भवति।\"','adjective'),(2424,'','मन्द, अबल, अल्पशक्ति, निर्बल, निर्माय, फल्ग्व, कुण्ठित','यः प्रबलः नास्ति।; \"मन्दा बुद्धिः अपि प्रयत्नेन प्रबला भवति।\"','adjective'),(2425,'','अतीव्र, अतेजा, निस्तेजा, तेजोहीन, धाराहीन, अतीक्ष्ण, निर्व्याकुल, प्रशान्त, प्रशान्तचित्त, शान्तचेतस्, शान्तात्मन्','यद् न तीक्ष्णम्।; \"किम् भवान् अनया अतीव्रया छुरिकया एव युद्धं करिष्यति।\"','adjective'),(2426,'','विस्मयः, आश्चर्यम्, चमत्करणम्, चमत्कारः, चमत्कृतिः, चोद्यम्','मनसः सः भावः यः किञ्चित् अभूतपूर्वं दृष्ट्वा श्रुत्वा ज्ञात्वा वा जायते।; \"माम् अकस्मात् दृष्ट्वा तस्य विस्मयः अभूत्।\"','noun'),(2427,'','जिज्ञासा, कौतूहलम्, कौतुकम्, कुतुकम्, कुतूहलम्, पिपृच्छिषा, अनुसन्धानेच्छा','ज्ञातुमिच्छा।; \"बालकस्य मनसि जिज्ञासा वर्तते।\"','noun'),(2428,'','विशिष्टता, विशिष्टत्वम्, विलक्षणता, अद्भुतता, अनन्यता, अनन्यत्वम्, अपूर्वता, अपूर्वत्वम्','विलक्षणस्य अवस्था भावो वा।; \"तस्य विशिष्टता दृष्ट्वा अहं विस्मितः।\"','noun'),(2429,'','विस्मि, स्मि, कुह्','अद्भुतं दृष्ट्वा श्रुत्वा वा मनसि उत्पन्नः आश्चर्यानुकूलः व्यापारः।; \"उपक्रीडायां क्रीडापटूनां कौशल्यं दृष्ट्वा बालकाः विस्मयन्ते।\"','verb'),(2430,'','क्षुभ्, विक्षुभ्, संक्षुभ्, अकस्मात् क्षुभ्, आकस्मिकत्रासं कृ, बीभत्सं जन्','भयोपजनितः कम्पनानुकूलः आकस्मिकः व्यापारः।; \"क्वचित्  रात्रौ दुःस्वप्नं दृष्ट्वा बालाः क्षुभ्यन्ति।\"','verb'),(2431,'','जोषम् आस्, जोषम् अस्, जोषम् स्था','कस्यापि प्रश्नस्य उत्तरं दातुम् असमर्थानुकूलः व्यापारः।; \"सम्यक् सज्जतायाः अभावात् साक्षात्कारे अहं जोषम् आसम्।\"','verb'),(2432,'','अनुसरणम्, अनुगमनम्, अनुवर्तनम्','कस्यापि पछ्चाद् धावनस्य क्रिया।; \"श्यामः स्वपितुः अनुसरणम् करोति।\"','noun'),(2433,'','दृढ, स्थर, निश्चल, अचल, अविचलित, धीर, धृतिमत्, धैर्यवत्','यः निर्णयम् अन्यथा न करोति।; \"सः स्वनिर्णये दृढः आसीत्।\"','adjective'),(2434,'','अनपेक्षित, अवाञ्छित, अनभिलषित, अनीप्सित','यद् अपेक्षितं नास्ति।; \"अनपेक्षितस्य वस्तुनः प्रापणं सुखकारकम्।\"','adjective'),(2420,'','गम्भीर, शान्त, सौम्य, अटल, दृढ, स्थिरधी, स्थिरमति, स्थिरमनस्, स्थिरात्मन्, स्थितिमत्, स्थितमति, स्थितप्रजा, स्थितधी, सुस्थिर, सुधीर, प्रस्थ, धृतात्मन्','यः चञ्चलः नास्ति।; \"सः प्रकृत्या गम्भीरः अस्ति।\"','adjective'),(2414,'','असम्भव, असम्भाव्य, अशक्य','यद् सम्भवं नास्ति।; \"रामेण असम्भवं कार्यं कृतम्।\"','adjective'),(2415,'','विरल','यद् घनं नास्ति।; \"विरलस्य वनस्य मार्गेण अगच्छाम।\"','adjective'),(2416,'','सन्तुष्ट, तृप्त, तुष्ट, परितुष्ट, सन्तोषित, धृतिमत्','यस्य इच्छा तोषिता।; \"भवतां दर्शनेन अहं सन्तुष्टः।\"','adjective'),(2417,'','पापिन्, अघिन्, अधम, अनाचारिन्, पतित, पातकिन्, नीच, पापकर्मन्, पापात्मन्, अधर्मिन्, पापाचारिन्, अवर','यः पापं करोति।; \"धार्मिकग्रन्थानुसारेण यदा पृथिव्यां पापं वर्धते तदा प्रभुः अवतारं गृहीत्वा पापीनां संहरति।\"','adjective'),(2418,'','घृणित, अवद्य, जुगुप्स्य, कुत्सित, वीभत्स, जघन्य, घृणास्पद, अपकृष्ट','घृणार्थे योग्यः।; \"भ्रूणहत्या एकः घृणितः अपराधः।\"','adjective'),(2419,'','मलिन, समल, मलदूषित, पङ्कदूषित, मलीमस','न अच्छः।; \"पाठशालायां मलिनं वासं परिधृत्य न आगन्तव्यम्।\"','adjective'),(2408,'','पुरःसरः, अग्रदूतः, अग्रेसरः, पुरोगामी, पुरोगः, प्राग्गामी','यः अग्रे गत्वा अन्यस्य आगमनं सूचयति।; \"लङ्काविजयात् अनन्तरं प्रभुः रामचन्द्रः हनुमन्तं पुरःसरः इति रूपेण अयोध्यां प्रेषयति।\"','noun'),(2409,'','प्रगतिशील, उन्नतशील, विकासशील, उन्नतिशील, उत्थानशील, अभ्युत्थायी','यः उन्नतिं करोति।; \"भारतदेशः प्रगतिशीलः देशः।\"','adjective'),(2410,'','अग्रेप्रेषित, अग्रप्रेषित, अग्रेषित, अग्रेसारित','कस्यापि निवेदनम् अग्रिमे कार्यार्थे उचिते आज्ञार्थे वा उच्चाधिकारिणः समीपे प्रेषितम्।; \"प्रान्ताधिकारी अग्रेप्रेषितं पत्रं श्वः चिन्तयिष्यति।\"','adjective'),(2411,'','अविश्वसनीय','यः विश्वसितुं न अर्हति।; \"अविश्वसनीया वार्ता एषा।\"','adjective'),(2412,'','अतर्क्य, तर्कहीन, तर्करहित, अयुक्त, युक्तिहीन','तर्केण विना।; \"किमर्थं अतर्क्यां वार्तां करोषि।\"','adjective'),(2413,'','न्यासः, स्थाप्यः, स्थाप्यम्, स्थाप्या, उपनिधानम्','पारिश्रमिकस्य अंशः यः क्रीणनाद् प्राक् कस्मादपि कार्याद् प्राक् वा अन्तिमनिर्णयस्य लक्षणरूपेण दीयते।; \"तेन वस्तुक्रयणार्थे वणिजे न्यासः दत्तः।\"','noun'),(2403,'','अतीव, बहु, अधिक, अतिशय, अति, अनल्प','सङ्ख्यामात्रादीनां बाहुल्यम्।; \"तस्य दुर्दशां वीक्ष्य अतीव दुःखितः अहम्।\"','adjective'),(2404,'','द्विभुज, द्विबाहु, द्विभुजा','यस्य द्वौ भुजौ स्तः।; \"अत्र पञ्च फुटपरिमाणं यावत् द्विभुजस्य सूर्यस्य मूर्तिः अस्ति।\"','adjective'),(2405,'','अग्रगामिन्, पुरोगामिन्','यः नियतम् उन्नतिं कुर्वन् अग्रे गच्छति।; \"अग्रगामी व्यक्तिः समाजं नूतनं मार्गं दर्शयति।\"','adjective'),(2406,'','प्रगतिशील','यः प्रगतिं करोति।; \"प्रगतिशीलः व्यक्तिः सङ्कटान् अपाक्राम्यन् प्रगतिपथे अग्रे सरति। \"','adjective'),(2407,'','महापुरुषः','महान् पुरुषः।; \"भारतदेशः महापुरुषाणां देशः।\"','noun'),(2402,'','अग्न्याशयम्, अग्निदम्','एका दीर्घा ग्रन्थिः या आमाशयस्य पृष्ठभागे अनुप्रस्थरूपेण वा स्थिता अस्ति तथा च यस्याः पाचकरसादयः निर्वहन्ति।; \"अग्न्याशयात् निर्गतः पाचकरसः पाचने साहाय्यकः भवति।\"','noun'),(2396,'','शवदाहः, दाह-संस्कारः, दाहक्रिया, दाहकर्म, अग्निकर्म, अग्निदाहः','शवस्य ज्वलनम्।; \"अधुना शवदाहस्य कृते नगरेषु विद्युत् शवदाहगृहस्य निर्माणं कृतम्।\"','noun'),(2397,'','नैऋति','दक्षिणपश्चिमा दिक्।; \"सः नैऋतौ दिशि गतः।\"','noun'),(2398,'','अग्निपरीक्षा','प्राचीनकालीना परीक्षा यस्यां कोऽपि हस्ते अग्निं गृहीत्वा अग्नौ उपविश्य वा स्वस्य निर्दोषत्वं सिद्ध्यति।; \"सीतया स्वस्य पवित्रतासिद्ध्यर्थे अग्निपरीक्षा दत्ता।\"','noun'),(2399,'','कृत्रिम-उपग्रहः','मानवेन निर्मितः उपग्रहः।; \"भारतदेशेन नैके कृत्रिम-उपग्रहाः अन्तरीक्षे प्रेषिताः।\"','noun'),(2401,'','आग्नेयास्त्रम्, अग्न्यस्त्रम्','तद् अस्त्रं यस्माद् अग्निः निर्गच्छति।; \"प्राचीने काले अधिकानि आग्नेयास्त्रणि उपायुञ्जन्।\"','noun'),(2400,'','अग्निहोत्रम्','यज्ञविशेषः,मन्त्रैः सह अग्नये होत्रम्।; \"सायंकाले प्रातःकाले च अग्निहोत्रः कर्तव्यः।\"','noun'),(2394,'','मुखाग्निः','शवमुखे दत्तवह्निः।; \"तेन पितुः मुखाग्निः दत्तः।\"','noun'),(2395,'','पित्तम्, मायुः, पलज्वलः, तेजः, तिक्तधातुः, उष्मा, अग्निः, अनलः,शाण्डिलीपुत्रः','शरीरस्थधातुविशेषः यः पित्ताशये जायते तथा च यः  पचनक्रियायां साहाय्यं करोति।; \"पित्तं अन्नस्य पचनक्रियायां सहायकम्।\"','noun'),(2392,'','चरणम्, पादम्','पद्यस्य चतुर्थांशः।; \"अस्य दोहा इति काव्य प्रकारस्य प्रथमं चरणं स्पष्टीकरोतु।\"','noun'),(2393,'','आतपः, तापः, अभितापः, उपतापः, उष्णता, औष्ण्यम्, उष्मः, औष्म्यम्, निदाघः, चण्डता, तिग्मता, तैग्म्यम्, तिग्मम्','उष्मस्य भावः।; \"ग्रीष्मे आतपः वर्धते।\"','noun'),(2391,'','गौरवहीनता, अगौरवता, निस्तेजता','गौरवहीनस्य अवस्था भावो वा।; \"राष्ट्रस्य गौरवहीनतायाः कारणं वयम् एव।\"','noun'),(2390,'','कृष्ण, श्याम, नील, अश्वेत','कज्जलस्य अङ्गारस्य वा वर्णम्।; \"एतद् श्रुत्वा सोहनस्य मुखं कृष्णम् अभवत्।\"','adjective'),(2388,'','ग्रह्','बलपूर्वकग्रहणम्।; \"यांस्तत्र चारान् गृह्णीयात् ।\"','verb'),(2389,'','कृष्णवर्णीय, श्वेतेतर, कृष्ण','यः मानवः श्वेतवर्णीयः नास्ति ।; \"आङ्ग्लाः कृष्णवर्णीयैः सह दुर्वर्तनं कृतवन्तः।\"','adjective'),(2385,'','परिव्राजकः, परिव्राट्, संन्यासी','यः सन्यस्तवृत्त्या जीवति।; \"चित्रकूटे एकः महान् परिव्राजकः माम् मिलितवान्।\"','noun'),(2386,'','इन्द्रियातीत, अतीन्द्रिय, अगोचर, अप्रत्यक्ष, परोक्ष, अभौतिक, अविषय, अव्यक्त','यस्य अनुभूतिः ज्ञानेन्द्रियैः न जायते।; \"ईश्वरः इन्द्रियातीतः अस्ति।\"','adjective'),(2387,'','परिश्रि, परिबृंह्, परिबन्ध्, उपलिख्, पर्यङ्ख्','कम् अपि चतुर्भिः दिग्भिः निरोधनात्मकः व्यापारः।; \"अस्माकं सैनिकैः शत्रुसैनिकाः पर्यश्रीयन्त।\"','verb'),(2384,'','आवासहीन, आश्रयहीन, गृहहीन, अनिकेत, अकेतन, अगृह, निर्गृह','यः गृहविहीनः अस्ति।; \"शरयुनद्यां आगतेन आप्लावेन नैकाः जनाः आवासहीनाः जाताः।\"','adjective'),(2381,'','स्वशिक्षित','येन गुरुं विना विद्या अधिगता।; \"एकलव्यः धनुर्विद्यायां स्वशिक्षितः आसीत् किन्तु सः द्रोणाचार्यं गुरुम् अमन्यत।\"','adjective'),(2363,'','पूर्वजः','पितामहप्रपितामहादिभ्यः पूर्वः जातः।; \"रामकृष्णादयः अस्माकं पूर्वजाः।\"','noun'),(2364,'','सन्धाता','यः सन्धानं करोति।; \"अस्य दुर्गस्य सन्धानं कर्तुं चत्वारः सन्धातारः आवश्यकाः।\"','noun'),(2365,'','खण्डनीय','खण्डितुं योग्यः।; \"भवतः कथनं खण्डनीयम् वर्तते।\"','adjective'),(2366,'','पुरोगामिन्, अग्रगामिन्','यः अग्रे गच्छति।; \"पुरोगामी पुरुषः एव अस्य दलस्य नायकः अस्ति।\"','adjective'),(2367,'','अग्रे, अग्रतः, पुरतः, पुरः','अग्रे गच्छति।; \"सः सावकाशम् अग्रे गच्छति।\"','adverb'),(2368,'','अग्रतः, अग्रम्, पुरतः, पुरः','अग्रे सरति।; \"मार्गदर्शकः अग्रे गच्छति।\"','adverb'),(2369,'','बाष्पीयनौका, बाष्पीयनौः, बाष्पीयतरी, आग्नेयनौ, आग्नेयनौका','बाष्पसञ्चालिता नौका।; \"वयं बाष्पीयनौकया गङ्गापारं गताः।\"','noun'),(2370,'','गृहपतिः, गृहस्वामी','गृहस्य स्वामी।; \"गृहपतिः कुटुम्बं पालयति।\"','noun'),(2371,'','नेता','यः कस्यापि क्षेत्रे विषये वा नेतृत्वं करोति।; \"वाजपेयी महोदयः कुशलः नेता अस्ति।\"','noun'),(2372,'','मार्गदर्शकः, दिग्दर्शकः','यः मार्गं प्रदर्शयति।; \"अधुना मार्गदर्शकाणां अल्पसंख्यत्वात् युवकाः मार्गात् अन्यत्र गच्छन्ति।\"','noun'),(2373,'','प्रमुखः, प्रधानः','यः गृहस्य दलस्य समाजस्य वा मुख्यः अस्ति।; \"अटलमहोदयः भारतीयजनतापक्षस्य प्रमुखः अस्ति।\"','noun'),(2374,'','नेतृत्वम्, नायकत्वम्, मुख्यता, मुख्यत्वम्, अधिष्ठातृत्वम्, प्रमुखता','नेतुः कार्यम्।; \"भारतीयसैनिकैः कुशलसेनापतेः नेतृत्वे शत्रवः परास्ताः।\"','noun'),(2375,'','लेपः, अवलेपः','येन लिप्यते।; \"माता मृद्भित्तिकायां मृदादेः लेपेन लिम्पनं करोति।\"','noun'),(2333,'','ब्राह्मणः, द्विजः, विप्रः, द्विजोत्तमः, द्विजातिः, द्विजन्मा, अग्रजन्मा, भूदेवः, अग्रजातकः, सूत्रकण्ठः, ज्येष्ठवर्णः, वक्त्रजः, मैत्रः, वेदवासः, नयः, षट्कर्मा, गुरूः, ब्रह्मा','हिन्दूधर्मशास्त्रानुसारेण चातुर्वर्ण्यव्यवस्थायां प्रथमो  वर्णः यस्य शास्त्रनिरूपितधर्माः अध्ययनं यजनं दानञ्च सन्ति।; \"ब्राह्मण्यां ब्राह्मणात् जातो ब्राह्मणः न संशयः। क्षत्रियायां तथैव वैश्यायाम् अपि चैव हि।\"','noun'),(2383,'','वानप्रस्थाश्रमिन्','यः वानप्रस्थाश्रमे प्रविष्टः।; \"वानप्रस्थिनः राज्ञः पुनरागमनार्थे प्रयतते।\"','adjective'),(2382,'','अगुरु','यस्य भारः अल्पः अस्ति।; \"पक्षम् अगुरु खलु।\"','adjective'),(2380,'','अगुरु, वंशिकम्, राजार्हम्, लोहम्, कृमिजम्, जोङ्गकम्, कृष्णम्, तोहाख्यम्, लघु, पीतकम्, वर्णप्रसादनम्, अनार्थकम्, असारम्, कृमिजग्धम्, काष्ठकम्','काष्ठविशेषः, सुगन्धिकाष्ठविशेषः, आयुर्वेदे अस्य गुणाः तिक्तत्वं, लेपे रूक्षत्वम्,व्रणकफवायुवान्तिमुखरोगनासित्वादि; \"अगुरू प्रवणं लोहं राजार्हं योगजम् तथा वंशिकं कृमिजञ्चापि कृमिजग्धमनार्यकम्।\"','noun'),(2376,'','स्वागतम्','कस्यापि मान्यवरस्य प्रियस्य वा आगमनावसरे कृतं सादरम् अभिनन्दनम्।; \"रामस्य अयोध्यागमनावसरे अयोध्यावासिनः तस्य भव्यं स्वागतं कृतवन्तः।\"','noun'),(2377,'','दुर्गुणः, अवगुणः, दोषः, अपगुणः','सः गुणः यः असाधुः।; \"दुर्गुणः सदा परिहर्तव्यः।\"','noun'),(2378,'','अगुप्त, अनिभृत','यत् गुप्तं नास्ति।; \"एषा अगुप्ता वार्ता ज्ञातुं शक्यते भवान्।\"','adjective'),(2379,'','अगूढ, रहस्यहीन','यस्मिन् रहस्यं नास्ति।; \"एषा तु अगूढा वार्ता व्यर्थमेव रहस्यमया इति भणसि।\"','adjective'),(2358,'','अग्रम्','यत् अग्रिमे/ प्रथमे स्थाने वर्तते।; \"सूचेः अग्रं तीक्ष्णम् अस्ति\"','adjective'),(2359,'','आगामिन्, आगन्तव्य, उपस्थायिन्','आगच्छति कालः तत्सम्बन्धी वा।; \"अहम् आगामिन्यै परीक्षायै  अध्ययनं करोमि।\"','adjective'),(2360,'','उत्तम, उत्कृष्ट, श्रेष्ठ, प्रधान, प्रमुख, प्रवेक, मुख्य, वर्यः, वरेण्य, प्रवर्ह, अनवरार्ध्य, परार्ध्य, अग्र, प्रग्रबर, प्राग्रा, अग्रा, अग्रीय, अग्रिय, अनुत्तम','अत्यन्तम् श्रेयान्।; \"रामचरितमानस इति गोस्वामी तुलसीदासस्य एका उत्तमा कृतिः।\"','adjective'),(2361,'','उत्तरकालीनः','उत्तरकालेन सम्बन्धितम्।; \"तस्मै उत्तरकालीने साहित्ये रुचिः नास्ति।\"','adjective'),(2362,'','प्राचीनः, पूर्वकालीनः, पूर्वकालिकः','भूतकालेन सम्बन्धितः।; \"सः प्राचीनस्य मानववंशस्य संस्कृतेः अध्ययनं करोति।\"','adjective'),(2357,'','अग्रगामी, अग्रेसरः','यः अग्रे गच्छति।; \"सङ्कटान् प्रथमतः अग्रगामी पराङ्मुखीकरोति।\"','noun'),(2351,'','अज्ञेयः, अज्ञेया, अज्ञेयम्, अगम्यः, अगम्यम्, अगम्या, ज्ञानातीतः, ज्ञानातीता, ज्ञानातीतम्, बोधातीतः, बोधातीता, बोधातीतम्','यद् ज्ञानात् परे अस्ति।; \"ईश्वरः अज्ञेयः अस्ति।\"','adjective'),(2352,'','अप्राप्य, अलभ्य, अनुपलब्ध','यद् प्राप्यम् नास्ति।; \"बालकः क्वचित् अप्राप्यम् अपि याचते।\"','adjective'),(2353,'','अपारम्','नास्ति पारम् यस्य तत्।; \"अधुना वैज्ञानिकाः अपारं किमपि नास्ति इति मन्यन्ते।\"','adjective'),(2354,'','धूपवर्तिका','सुगन्धार्थे प्रज्वलिता वर्तिका।; \"मोहनः पूजाकाले धूपवर्तिकां प्रज्वालयति।\"','noun'),(2355,'','वैयाजम्, मेषयितृत्वम्','अभिप्रायगोपनम्।; \"बालकाः पाठशालां न गन्तुं वैयाजम् कुर्वन्ति।\"','noun'),(2356,'','प्रतिष्ठित, अग्रगण्य, गणमान्य, मान्य, माननीय, गौरवान्वित','येन प्रतिष्ठा लब्धा।; \"पण्डित महेशः स्वस्य क्षेत्रे प्रतिष्ठितः व्यक्तिः अस्ति।\"','adjective'),(2350,'','अगाध','यस्य गाधो नास्ति।; \"पण्डित सुनीलस्य ज्ञानम् अगाधम्।\"','adjective'),(2345,'','विकल्पहीनता, उपायहीनता','विकल्पहीनस्य अवस्था भावो वा।; \"विकल्पहीनतायाः कारणात् सः निर्णेतुं न शक्नुयात्।\"','noun'),(2347,'','दुर्गमः','दुःखेन गमनीयस्थानादि।; \"सः पर्वतारोहणार्थे दुर्गमं मार्गम् अवलम्बितवान्।\"','adjective'),(2348,'','अप्रवेश्यम्, अप्रवेश्यः, अप्रवेश्या','प्रवेशाय प्रतिबन्धितः।; \"एतद् अप्रवेश्यं द्वारम्।\"','adjective'),(2349,'','वृक्षः, तरुः, द्रुमः, पादपः, द्रुः, महीरुहः, शाखी, विटपी, अमोकहः, कुटः, सालः, पलाशी, आगमः, अगच्छः, विष्टरः, महीरुट्, कुचिः, स्थिरः, कारस्करः, नगः, अगः, कुटारः, विटपः, कुजः, अद्रिः, शिखरी, कुठः, कुञ्जः, क्षितिरुहः, अङ्गघ्रिपः, भूरुहः, भूजः, महीजः, धरणीरुहः, क्षितिजः, शालः','शाखा-पर्ण-स्कन्ध-मूलादि-युक्ता दीर्घजीवीनी वनस्पतिः।; \"वृक्षाणां रक्षणं कर्तव्यम्।\"','noun'),(2344,'','अव्यतीत, अगत, अविगत','यद् व्यतीतं नास्ति।; \"भवताम् अधिकांशं जीवनम् अव्यतीतम्।\"','adjective'),(2343,'','स्थैर्यम्, स्थिरता, निश्चलता','स्थिरस्य अवस्था भावो वा।; \"मनसाः स्थैर्यम् शान्तिं प्रयच्छति।\"','noun'),(2342,'','अपचितः, व्ययितः, व्ययीकृतः, व्ययीभूतः','भग्नानि उपयोगशून्यानि च वस्तूनि।; \"अस्मिन् पण्ये अपचितानि क्रीयन्ते।\"','noun'),(2341,'','अचर, अचल, क्षोण, स्थावर','यः न चलति।; \"वृक्षाः सजीवाः किन्तु अचराः।\"','adjective'),(2334,'','अभक्ष्य, अनाहार्य, अभोज्य','भक्षणार्थे अयोग्यः।; \"एतद् अभक्ष्यं वस्तु अस्ति।\"','adjective'),(2335,'','दलसदस्यः','यः कस्यापि दलस्य समुदायस्य वा सदस्यः अस्ति।; \"दलसदस्ययोः कलहेन दलः दुर्बलं भवति।\"','noun'),(2336,'','सार्वभौमिक, सार्वलौकिक, लौक्य','सर्वेषां देशानां स्तरीयः।; \"भारतदेशः सार्वभौमिकी प्रतिस्पर्धायाः प्रतिनिधित्वं करोति।\"','adjective'),(2337,'','प्रधानाचार्य','प्रधानाचार्यस्य पदम्।; \"प्रधानाचार्यस्य पदस्य कृते साक्षात्कारार्थे गच्छामि।\"','noun'),(2338,'','ब्रह्माण्डम्, विश्वः','तारकाग्रहनक्षत्रैः युक्तम् अखिलं जगत्।; \"ब्रह्माण्डं रहस्यैः परिपूर्णम् अस्ति।\"','noun'),(2339,'','अप्रतिष्ठित','यः प्रतिष्ठितः नास्ति।; \"मोहनः अप्रतिष्ठितः अस्ति।\"','adjective'),(2340,'','पर्वतः, महीध्रः, शिखरी, क्ष्माभृत्, अबार्यः, धरः, अद्रिः, गोत्रः, गिरिः, ग्रावा, अचलः, शैलः, शिलोच्चयः, स्थावरः, स